<template>
  <ProgrammerLoadingEffect :visible="isPageLoading" message="AUTHENTICATING" :theme="userDepartment ? userDepartment.label : ''" />
  <ProgrammerLoadingEffect :visible="loggingOut" message="LOGGING OUT" :theme="userDepartment ? userDepartment.label : ''" />
  <SessionExpiredModal :visible="showSessionExpiredModal" @logout="confirmLogout" />

  <!-- Welcome + T&C Modal (shown on every login) -->
  <WelcomeModal :visible="showWelcomeModal" :user-name="displayName" @agreed="onWelcomeAgreed" />


  <transition name="dev-modal">
    <div v-if="showDevelopersPopup" class="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center z-50 p-0 sm:p-4" @click.self="showDevelopersPopup = false">
      <div class="dev-modal-card bg-white rounded-t-3xl sm:rounded-3xl shadow-2xl max-w-2xl w-full max-h-[88vh] sm:max-h-[85vh] overflow-hidden flex flex-col">

        <!-- Header -->
        <div class="bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light px-4 sm:px-6 py-4 sm:py-5 flex-shrink-0 relative overflow-hidden">
          <div class="light-sweep"></div>
          <div class="relative z-10 flex items-center justify-between">
            <div class="flex items-center gap-2.5 sm:gap-3">
              <div class="w-9 h-9 sm:w-10 sm:h-10 bg-white/20 rounded-2xl flex items-center justify-center flex-shrink-0">
                <svg class="w-4.5 h-4.5 sm:w-5 sm:h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
              </div>
              <div>
                <h3 class="text-base sm:text-lg font-bold text-white leading-tight">Meet Our Developers</h3>
                <p class="text-blue-100/80 text-[10px] sm:text-xs">CCS &middot; Creatives Committee</p>
              </div>
            </div>
            <button @click="showDevelopersPopup = false" class="w-8 h-8 rounded-full bg-white/15 hover:bg-white/25 flex items-center justify-center text-white transition flex-shrink-0">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
            </button>
          </div>
        </div>

        <!-- Scrollable content -->
        <div class="px-3 sm:px-5 py-3 sm:py-5 overflow-y-auto dev-modal-scroll flex-1">
          <div class="grid grid-cols-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2.5 sm:gap-4">
            <div
              v-for="(dev, index) in developers"
              :key="dev.name"
              class="flex flex-col items-center bg-blue-50/60 hover:bg-blue-50 rounded-2xl p-2.5 sm:p-3 transition-all duration-200 hover:shadow-sm hover:scale-[1.02] active:scale-[0.98] cursor-pointer"
              :style="{ transitionDelay: `${index * 40}ms` }"
            >
              <div class="w-14 h-14 sm:w-16 sm:h-16 rounded-full overflow-hidden flex-shrink-0 ring-2 ring-blue-200 shadow-md bg-gradient-to-br from-ssaam-dark to-ssaam-light mb-2 flex items-center justify-center text-white">
                <img v-if="dev.image" :src="dev.image" :alt="dev.name" class="w-full h-full object-cover rounded-full" />
                <span v-else class="text-sm font-bold">{{ dev.initials }}</span>
              </div>
              <p class="text-[10px] sm:text-xs font-bold text-center leading-tight text-blue-700 hover:text-blue-900 mb-0.5 line-clamp-2">
                <a :href="dev.facebook" target="_blank" rel="noopener noreferrer" class="underline underline-offset-1">{{ dev.name }}</a>
              </p>
              <p class="text-[9px] sm:text-[10px] text-gray-500 text-center line-clamp-1 font-medium">{{ dev.year_level }} - {{ dev.program }}</p>
              <p class="text-[9px] sm:text-[10px] text-blue-400 text-center font-semibold line-clamp-1 mt-0.5">{{ dev.role }}</p>
            </div>
          </div>
        </div>

        <!-- Sticky Footer -->
        <div class="px-4 sm:px-6 py-3 sm:py-4 border-t border-gray-100 flex-shrink-0 bg-white">
          <button @click="showDevelopersPopup = false" class="w-full bg-gradient-to-r from-ssaam-dark via-blue-700 to-ssaam-light text-white py-2.5 sm:py-3 rounded-2xl font-bold text-sm hover:opacity-90 active:scale-[0.98] transition shadow-md shadow-blue-200">Done</button>
        </div>
      </div>
    </div>
  </transition>


  <!-- Delete Duplicate Student Confirmation Modal -->
  <div v-if="showDeleteDuplicateConfirm" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" @click.self="cancelDeleteDuplicateStudent">
    <div class="bg-white rounded-2xl shadow-2xl p-6 md:p-8 max-w-sm w-full mx-4">
      <div class="text-center mb-6">
        <div class="w-16 h-16 mx-auto mb-4 bg-red-100 rounded-full flex items-center justify-center">
          <svg class="w-8 h-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path>
          </svg>
        </div>
        <h3 class="text-xl font-bold text-gray-900 mb-2">Delete Student</h3>
        <p class="text-gray-600 text-sm">Are you sure you want to delete <span class="font-semibold">{{ duplicateStudentToDelete?.name }}</span> ({{ duplicateStudentToDelete?.id }})?</p>
        <p class="text-red-600 text-xs mt-2 font-medium">This action cannot be undone.</p>
      </div>
      <div class="flex gap-3">
        <button @click="cancelDeleteDuplicateStudent" class="flex-1 bg-gray-200 text-gray-800 py-2.5 px-4 rounded-lg font-medium hover:bg-gray-300 transition" :disabled="deletingDuplicateStudent">
          Cancel
        </button>
        <button @click="confirmDeleteDuplicateStudent" class="flex-1 bg-red-600 text-white py-2.5 px-4 rounded-lg font-medium hover:bg-red-700 transition flex items-center justify-center gap-2" :disabled="deletingDuplicateStudent">
          <svg v-if="deletingDuplicateStudent" class="animate-spin h-5 w-5" fill="none" viewBox="0 0 24 24">
            <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
            <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
          </svg>
          <span>{{ deletingDuplicateStudent ? 'Deleting...' : 'Delete' }}</span>
        </button>
      </div>
    </div>
  </div>

  <!-- Clear Sessions Confirmation Modal -->
  <div v-if="showClearSessionsConfirm" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" @click.self="showClearSessionsConfirm = false">
    <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-md w-full mx-4">
      <div class="flex justify-between items-center mb-6">
        <h3 class="text-2xl font-bold text-red-900">Clear All Sessions</h3>
        <button @click="showClearSessionsConfirm = false" class="text-gray-500 hover:text-gray-700 text-2xl">&times;</button>
      </div>
      <!-- Sessions loading bar -->
      <div v-if="sessionsLoading" class="w-full mb-4">
        <div class="w-full bg-gray-200 rounded-full h-2 overflow-hidden">
          <div :class="[isCOE ? 'from-orange-600 to-red-500' : isSOM ? 'from-green-600 to-yellow-500' : isCNAHS ? 'from-green-700 to-green-600' : 'from-ssaam-dark to-ssaam-light','h-2','rounded-full','animate-pulse','bg-gradient-to-r']" style="width:60%"></div>
        </div>
      </div>
      
      <div class="mb-6">
        <div class="bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg mb-4">
          <div class="flex items-start gap-3">
            <svg class="w-6 h-6 text-red-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path>
            </svg>
            <div>
              <p class="text-sm text-red-800 font-medium">Are you sure you want to clear all session tokens?</p>
              <p class="text-xs text-red-700 mt-1">This will force logout ALL users from the system immediately. They will need to log in again.</p>
            </div>
          </div>
        </div>
        <p class="text-sm text-gray-600">Your current session will remain active.</p>
      </div>
      
      <div class="flex gap-3">
        <button 
          @click="showClearSessionsConfirm = false" 
          class="flex-1 bg-gray-200 text-gray-800 py-3 px-4 rounded-lg font-medium hover:bg-gray-300 transition"
        >
          Cancel
        </button>
        <button 
          @click="clearAllSessionTokens" 
          class="flex-1 bg-red-600 text-white py-3 px-4 rounded-lg font-medium hover:bg-red-700 transition flex items-center justify-center gap-2"
          :disabled="clearingSessionTokens"
        >
          <svg v-if="clearingSessionTokens" class="animate-spin h-5 w-5" fill="none" viewBox="0 0 24 24">
            <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
            <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
            </svg>
            Clear All Sessions
          </button>
        </div>
      </div>
    </div>

    <!-- RFID Scanner Fullscreen Modal - Enhanced Kiosk Layout -->
    <div v-if="rfidFullscreenMode" class="fixed inset-0 z-[70] overflow-hidden bg-gradient-to-b from-[#080e2e] to-[#0f1f6e]">
    <!-- Glowing particle canvas -->
    <canvas ref="particleCanvas" class="absolute inset-0 w-full h-full pointer-events-none z-0" style="opacity:0.85"></canvas>
    <!-- Offline badge -->
    <Transition name="fade">
      <div v-if="!rfidIsOnline" class="absolute top-5 left-1/2 -translate-x-1/2 z-30 flex items-center gap-2 bg-red-600/90 backdrop-blur-sm text-white text-xs font-semibold px-4 py-2 rounded-full border border-red-400/60 shadow-lg">
        <svg class="w-3.5 h-3.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18.364 5.636a9 9 0 010 12.728M15.536 8.464a5 5 0 010 7.072M12 12h.01M8.464 15.536a5 5 0 010-7.072M5.636 5.636a9 9 0 000 12.728"/></svg>
        Offline — scans will be queued ({{ rfidOfflineQueue.length }} queued)
      </div>
    </Transition>
    <button @click="rfidFullscreenMode = false" :class="['absolute top-5 right-5 z-20 w-10 h-10 flex items-center justify-center rounded-full bg-white/10 backdrop-blur-sm border border-white/20 text-white transition-all hover:bg-white/25 hover:scale-110 active:scale-95', isCOE ? 'hover:border-red-300 hover:text-red-200' : isSOM ? 'hover:border-yellow-300 hover:text-yellow-200' : isCNAHS ? 'hover:border-green-300 hover:text-green-200' : 'hover:border-blue-300 hover:text-blue-200']" title="Close (ESC)">
      <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"></path></svg>
    </button>
    
    <div class="h-full flex flex-col lg:flex-row overflow-hidden relative z-10">
      <!-- Left Panel - Scanner (Kiosk Style) -->
      <div class="lg:w-[460px] xl:w-1/2 flex-shrink-0 min-h-max lg:h-full flex flex-col items-center justify-center px-5 py-8 lg:py-10 border-b lg:border-b-0 lg:border-r border-white/20">

        <!-- SSAAM Logo + Title -->
        <div class="flex items-center gap-3 mb-5">
          <div class="relative w-10 h-10 lg:w-14 lg:h-14 flex-shrink-0 overflow-hidden">
            <img
              :src="isCOE ? '/icons/coe.svg' : isSOM ? '/icons/som.svg' : jrmsuLogoUrl"
              :alt="isCOE ? 'COE Logo' : isSOM ? 'SOM Logo' : 'JRMSU Logo'"
              class="w-full h-full object-contain drop-shadow-xl"
            />
            <!-- Shine layer:
                 We render a SECOND copy of the exact same logo image, but
                 turn every visible pixel pure white via `filter: brightness(0) invert(1)`.
                 Because this is a real <img>, the transparent pixels around
                 the logo stay transparent — there is literally nothing to
                 paint outside the silhouette, so the shine cannot bleed.
                 A horizontal linear-gradient mask sweeps a narrow bright
                 band across the white silhouette to create the shimmer.
                 `mix-blend-mode: plus-lighter` makes the bright band ADD
                 light to the underlying logo instead of replacing it. -->
            <img
              :src="isCOE ? '/icons/coe.svg' : isSOM ? '/icons/som.svg' : jrmsuLogoUrl"
              alt=""
              aria-hidden="true"
              class="logo-shine absolute inset-0 w-full h-full object-contain pointer-events-none"
            />
          </div>
          <h1 class="text-2xl lg:text-4xl font-extrabold italic text-white drop-shadow tracking-wide">SSAAM</h1>
        </div>

        <!-- Event Info Card -->
        <div class="w-full max-w-sm bg-white/10 border border-white/20 rounded-2xl px-5 py-4 mb-4 text-center backdrop-blur-sm shadow-lg">
          <p class="text-white font-bold text-lg lg:text-xl leading-tight truncate">{{ selectedEvent?.title || 'No Event Selected' }}</p>
          <p class="text-white/60 text-xs lg:text-sm mt-0.5">{{ formatEventDate(selectedEvent?.date || selectedEvent?.event_date) }}</p>
          <div v-if="selectedSession" class="mt-2 flex flex-wrap justify-center items-center gap-2">
            <span :class="['px-3 py-1 rounded-full text-xs font-semibold', isCOE ? 'bg-orange-500/30 text-orange-200' : isSOM ? 'bg-green-500/30 text-green-200' : isCNAHS ? 'bg-green-500/30 text-green-200' : 'bg-blue-500/30 text-blue-200']">
              {{ selectedSession.label }} Session
            </span>
            <span class="text-white/50 text-xs">{{ formatDisplayTime(selectedSession.start_time) }} – {{ formatDisplayTime(selectedSession.end_time) }}</span>
          </div>
          <p class="text-white/35 text-xs mt-2 font-mono tracking-widest">{{ fsLiveClock }}</p>
        </div>

        <!-- Active Mode Display (read-only in fullscreen kiosk).
             Mode is controlled from the regular Admin panel; in fullscreen
             we show it as a clear, non-interactive banner so a kiosk
             attendant can never accidentally toggle it mid-event. Three
             possible states: Check-In Only, Check-In, Check-Out. -->
        <div class="w-full max-w-sm mb-4">
          <!-- 1. Check-In Only Session -->
          <div
            v-if="selectedSession && selectedSession.check_in_only"
            class="flex items-center gap-3 py-3 px-4 rounded-2xl bg-gradient-to-r from-blue-500/25 via-blue-500/20 to-indigo-500/25 border-2 border-blue-400/50 shadow-lg shadow-blue-500/20 cursor-default select-none"
          >
            <div class="w-10 h-10 flex-shrink-0 flex items-center justify-center rounded-xl bg-blue-500/40 border border-blue-300/50">
              <svg class="w-5 h-5 text-blue-50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
            </div>
            <div class="flex-1 min-w-0">
              <p class="text-blue-200/70 text-[10px] uppercase tracking-widest font-semibold leading-none">Active Mode</p>
              <p class="text-blue-50 text-base font-extrabold leading-tight mt-1">Check-In Only</p>
            </div>
            <div class="w-2.5 h-2.5 rounded-full bg-blue-300 animate-pulse flex-shrink-0 shadow-[0_0_8px_rgba(147,197,253,0.8)]"></div>
          </div>

          <!-- 2. Check-In Mode -->
          <div
            v-else-if="rfidOperationType === 'in'"
            class="flex items-center gap-3 py-3 px-4 rounded-2xl bg-gradient-to-r from-green-500/25 via-emerald-500/20 to-green-500/25 border-2 border-green-400/55 shadow-lg shadow-green-500/20 cursor-default select-none"
          >
            <div class="w-10 h-10 flex-shrink-0 flex items-center justify-center rounded-xl bg-green-500/40 border border-green-300/50">
              <svg class="w-5 h-5 text-green-50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M11 16l-4-4m0 0l4-4m-4 4h14M3 12a9 9 0 1118 0 9 9 0 01-18 0z" transform="rotate(180 12 12)" />
              </svg>
            </div>
            <div class="flex-1 min-w-0">
              <p class="text-green-200/70 text-[10px] uppercase tracking-widest font-semibold leading-none">Active Mode</p>
              <p class="text-green-50 text-base font-extrabold leading-tight mt-1">Check-In</p>
            </div>
            <div class="w-2.5 h-2.5 rounded-full bg-green-300 animate-pulse flex-shrink-0 shadow-[0_0_8px_rgba(134,239,172,0.8)]"></div>
          </div>

          <!-- 3. Check-Out Mode (themed per college) -->
          <div
            v-else
            :class="['flex items-center gap-3 py-3 px-4 rounded-2xl border-2 shadow-lg cursor-default select-none bg-gradient-to-r',
              isCOE ? 'from-red-500/25 via-rose-500/20 to-red-500/25 border-red-400/55 shadow-red-500/20'
              : isSOM ? 'from-yellow-500/25 via-amber-500/20 to-yellow-500/25 border-yellow-400/55 shadow-yellow-500/20'
              : isCNAHS ? 'from-teal-500/25 via-cyan-500/20 to-teal-500/25 border-teal-400/55 shadow-teal-500/20'
              : 'from-orange-500/25 via-amber-500/20 to-orange-500/25 border-orange-400/55 shadow-orange-500/20']"
          >
            <div :class="['w-10 h-10 flex-shrink-0 flex items-center justify-center rounded-xl border',
              isCOE ? 'bg-red-500/40 border-red-300/50'
              : isSOM ? 'bg-yellow-500/40 border-yellow-300/50'
              : isCNAHS ? 'bg-teal-500/40 border-teal-300/50'
              : 'bg-orange-500/40 border-orange-300/50']">
              <svg :class="['w-5 h-5', isCOE ? 'text-red-50' : isSOM ? 'text-yellow-50' : isCNAHS ? 'text-teal-50' : 'text-orange-50']" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2" d="M11 16l-4-4m0 0l4-4m-4 4h14M3 12a9 9 0 1118 0 9 9 0 01-18 0z" />
              </svg>
            </div>
            <div class="flex-1 min-w-0">
              <p :class="['text-[10px] uppercase tracking-widest font-semibold leading-none',
                isCOE ? 'text-red-200/70' : isSOM ? 'text-yellow-200/70' : isCNAHS ? 'text-teal-200/70' : 'text-orange-200/70']">Active Mode</p>
              <p :class="['text-base font-extrabold leading-tight mt-1',
                isCOE ? 'text-red-50' : isSOM ? 'text-yellow-50' : isCNAHS ? 'text-teal-50' : 'text-orange-50']">Check-Out</p>
            </div>
            <div :class="['w-2.5 h-2.5 rounded-full animate-pulse flex-shrink-0',
              isCOE ? 'bg-red-300 shadow-[0_0_8px_rgba(252,165,165,0.8)]'
              : isSOM ? 'bg-yellow-300 shadow-[0_0_8px_rgba(253,224,71,0.8)]'
              : isCNAHS ? 'bg-teal-300 shadow-[0_0_8px_rgba(94,234,212,0.8)]'
              : 'bg-orange-300 shadow-[0_0_8px_rgba(253,186,116,0.8)]']"></div>
          </div>
        </div>

        <!-- Scanner Box -->
        <div class="w-full max-w-sm bg-white/10 backdrop-blur-lg rounded-2xl p-5 lg:p-7 border border-white/20 shadow-2xl mb-4">
          <!-- Animated RFID pulse rings + icon -->
          <div class="relative flex justify-center items-center mb-4 h-16">
            <div class="absolute w-16 h-16 rounded-full border border-white/20 animate-[ping_2.4s_ease-in-out_infinite]"></div>
            <div class="absolute w-12 h-12 rounded-full border border-white/30 animate-[ping_2.4s_ease-in-out_infinite_0.6s]"></div>
            <div class="absolute w-8 h-8 rounded-full bg-white/10 animate-[ping_2.4s_ease-in-out_infinite_1.2s]"></div>
            <div class="relative z-10 w-10 h-10 flex items-center justify-center rounded-full bg-white/15 border border-white/30">
              <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M5 3v4M19 3v4M3 9h18M4 21h16a1 1 0 001-1V9H3v11a1 1 0 001 1zM8 13a2 2 0 100-4 2 2 0 000 4zm8 6v-2a3 3 0 00-3-3H11a3 3 0 00-3 3v2"/>
              </svg>
            </div>
          </div>

          <p class="text-center text-sm lg:text-base font-semibold text-white mb-0.5">Ready for RFID or Student ID</p>
          <p class="text-center text-white/55 text-xs mb-4">Scan card or type Student ID (both accepted)</p>

          <div class="flex items-center gap-2">
            <input 
              ref="rfidFullscreenInputRef"
              v-model="rfidInput"
              @input="onRfidInput"
              @keydown.enter="manualRfidSubmit"
              @keydown="handleRfidKeydown"
              type="text"
              placeholder="Scan RFID or enter Student ID..."
              :class="['flex-1 min-w-0 px-3 py-3 text-center text-sm bg-white/15 border-2 rounded-xl outline-none text-white placeholder-white/50 transition-all',
                isCOE ? 'border-orange-400/60 focus:border-orange-300 focus:ring-4 focus:ring-orange-300/20'
                : isSOM ? 'border-green-400/60 focus:border-green-300 focus:ring-4 focus:ring-green-300/20'
                : isCNAHS ? 'border-teal-400/60 focus:border-teal-300 focus:ring-4 focus:ring-teal-300/20'
                : 'border-white/25 focus:border-blue-300 focus:ring-4 focus:ring-blue-300/20']"
              :disabled="rfidProcessing"
              autofocus
            />
            <button 
              @click="manualRfidSubmit"
              :disabled="rfidProcessing || !rfidInput.trim()"
              :class="['w-12 h-12 flex-shrink-0 flex items-center justify-center rounded-xl border-2 text-white transition-all disabled:opacity-40 disabled:cursor-not-allowed active:scale-95',
                rfidInput.trim()
                  ? 'bg-white/25 border-white/40 hover:bg-white/35 hover:scale-105 shadow-lg'
                  : 'bg-white/10 border-white/20']"
            >
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
            </button>
          </div>
        </div>

        <!-- Stats Row — Active Mode moved up into the dedicated banner,
             so this row now focuses on the live scan count alone. -->
        <div class="w-full max-w-sm mb-4">
          <div class="bg-white/10 border border-white/15 rounded-xl px-4 py-3 text-center backdrop-blur-sm flex items-center justify-center gap-4">
            <div class="w-10 h-10 flex-shrink-0 rounded-xl bg-white/10 border border-white/20 flex items-center justify-center">
              <svg class="w-5 h-5 text-white/80" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z" />
              </svg>
            </div>
            <div class="text-left">
              <p class="text-white/50 text-[10px] uppercase tracking-widest font-semibold leading-none">Total Scanned</p>
              <p class="text-2xl font-extrabold text-white leading-tight mt-1">{{ sortedAttendanceLogs.length }}</p>
            </div>
          </div>
        </div>

        <p class="text-white/30 text-xs">Press ESC or click X to exit</p>
      </div>

      <!-- Right Panel - Results + Recent Logs -->
      <div class="flex-1 min-h-0 flex flex-col p-4 lg:p-6 overflow-hidden">
        <!-- Success Card -->
        <transition name="slide-down">
          <div v-if="rfidResult && rfidResult.success && rfidResult.action !== 'already_checked_in' && (rfidResult.student || rfidResult.student_name)" class="mb-4">
            <div class="bg-green-500/15 backdrop-blur-lg rounded-2xl p-5 lg:p-6 border-2 border-green-400/60 shadow-2xl">
              <div class="flex items-center gap-4">
                <div class="relative flex-shrink-0">
                  <div class="relative w-16 h-16 lg:w-20 lg:h-20 rounded-full overflow-hidden border-2 border-green-300/60 shadow-lg">
                    <div :class="['absolute inset-0 flex items-center justify-center font-bold text-lg text-white', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                      {{ (rfidResult.student?.full_name || rfidResult.student_name || '?').charAt(0) }}
                    </div>
                    <img v-if="rfidResult.student_image || rfidResult.student?.photo || rfidResult.student?.image || rfidResult.student?.avatar" :src="rfidResult.student_image || rfidResult.student?.photo || rfidResult.student?.image || rfidResult.student?.avatar" class="absolute inset-0 w-full h-full object-cover" @error="$event.target.style.display='none'" />
                  </div>
                  <div class="absolute -bottom-1 -right-1 w-7 h-7 bg-green-500 rounded-full flex items-center justify-center border-2 border-white/30 shadow">
                    <svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                  </div>
                </div>
                <div class="flex-1 min-w-0">
                  <p class="text-green-300 font-bold text-sm lg:text-base mb-0.5">
                    {{ rfidResult.action === 'check_in' ? 'Check-in Successful!' : rfidResult.action === 'check_out' ? 'Check-out Successful!' : 'Success!' }}
                  </p>
                  <p class="text-white font-bold text-lg lg:text-xl truncate">{{ rfidResult.student?.full_name || rfidResult.student_name }}</p>
                  <div v-if="rfidResult.student?.program || rfidResult.student?.year_level" class="text-white/70 text-sm mt-0.5">
                    <span v-if="rfidResult.student?.program">{{ rfidResult.student.program }}</span>
                    <span v-if="rfidResult.student?.program && rfidResult.student?.year_level"> • </span>
                    <span v-if="rfidResult.student?.year_level">{{ rfidResult.student.year_level }}</span>
                  </div>
                  <div class="flex flex-wrap gap-2 mt-2">
                    <span v-if="rfidResult.student?.student_id" class="px-3 py-1 bg-white/15 rounded-full text-xs text-white/80">ID: {{ rfidResult.student.student_id }}</span>
                    <span v-if="rfidResult.time" class="px-3 py-1 bg-white/15 rounded-full text-xs text-white/70">{{ new Date(rfidResult.time).toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }) }}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </transition>

        <!-- Duplicate / Already Checked In Card -->
        <transition name="slide-down">
          <div v-if="rfidResult && selectedSession && (rfidResult.action === 'already_checked_in' || (rfidResult.message && /already/i.test(rfidResult.message)))" class="mb-4">
            <div class="bg-yellow-500/15 backdrop-blur-lg rounded-2xl p-5 lg:p-6 border-2 border-yellow-400/60 shadow-2xl">
              <div class="flex items-center gap-4">
                <div class="relative flex-shrink-0">
                  <div class="relative w-16 h-16 lg:w-20 lg:h-20 rounded-full overflow-hidden border-2 border-yellow-300/60 shadow-lg">
                    <div :class="['absolute inset-0 flex items-center justify-center font-bold text-lg text-white', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                      {{ (rfidResult.student?.full_name || rfidResult.student_name || '?').charAt(0) }}
                    </div>
                    <img v-if="rfidResult.student_image || rfidResult.student?.photo || rfidResult.student?.image || rfidResult.student?.avatar" :src="rfidResult.student_image || rfidResult.student?.photo || rfidResult.student?.image || rfidResult.student?.avatar" class="absolute inset-0 w-full h-full object-cover" @error="$event.target.style.display='none'" />
                  </div>
                  <div class="absolute -bottom-1 -right-1 w-7 h-7 bg-yellow-500 rounded-full flex items-center justify-center border-2 border-white/30 shadow">
                    <svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                  </div>
                </div>
                <div class="flex-1 min-w-0">
                  <p class="text-yellow-300 font-bold text-sm lg:text-base mb-0.5">
                    {{ (rfidResult.action === 'check_out' || rfidResult.action === 'already_checked_out' || (rfidResult.action === 'already_completed' && rfidOperationType === 'out')) ? 'Already Logged Out' : 'Already Logged In' }}
                  </p>
                  <p class="text-white font-bold text-lg lg:text-xl truncate">{{ rfidResult.student?.full_name || rfidResult.student_name }}</p>
                  <div v-if="rfidResult.student?.program || rfidResult.student?.year_level" class="text-white/70 text-sm mt-0.5">
                    <span v-if="rfidResult.student?.program">{{ rfidResult.student.program }}</span>
                    <span v-if="rfidResult.student?.program && rfidResult.student?.year_level"> • </span>
                    <span v-if="rfidResult.student?.year_level">{{ rfidResult.student.year_level }}</span>
                  </div>
                  <div class="flex flex-wrap gap-2 mt-2">
                    <span v-if="rfidResult.student?.student_id" class="px-3 py-1 bg-white/15 rounded-full text-xs text-white/80">ID: {{ rfidResult.student.student_id }}</span>
                    <span v-if="rfidResult.time" class="px-3 py-1 bg-white/15 rounded-full text-xs text-white/70">{{ new Date(rfidResult.time).toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }) }}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </transition>

        <!-- Generic Warning Card -->
        <transition name="slide-down">
          <div v-if="rfidResult && rfidResult.warning && !(rfidResult.action === 'already_checked_in' || (rfidResult.message && /already/i.test(rfidResult.message)))" class="mb-4">
            <div class="bg-yellow-500/15 backdrop-blur-lg rounded-2xl p-5 border-2 border-yellow-400/50 shadow-xl">
              <div class="flex items-center gap-4">
                <div class="w-12 h-12 rounded-full flex items-center justify-center shrink-0 bg-yellow-400/25 border border-yellow-400/40">
                  <svg class="w-6 h-6 text-yellow-300" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clip-rule="evenodd"/></svg>
                </div>
                <div class="flex-1">
                  <p class="text-yellow-200 font-bold text-sm mb-0.5">Warning</p>
                  <p class="text-white/85 text-sm leading-snug">{{ rfidResult.message }}</p>
                </div>
              </div>
            </div>
          </div>
        </transition>
        
        <!-- Error / Scan Failed Card -->
        <transition name="slide-down">
          <div v-if="rfidResult && rfidResult.error" class="mb-4">
            <div class="bg-red-900/50 backdrop-blur-lg rounded-2xl p-5 border-2 border-red-400/60 shadow-xl">
              <div class="flex items-center gap-4">
                <div class="w-14 h-14 rounded-full flex-shrink-0 flex items-center justify-center bg-red-500/30 border border-red-400/50">
                  <svg class="w-7 h-7 text-red-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                </div>
                <div class="flex-1 min-w-0">
                  <p class="text-red-300 font-bold text-sm mb-0.5">Scan Failed</p>
                  <p class="text-white font-semibold text-sm lg:text-base">{{ rfidResult.message }}</p>
                </div>
              </div>
            </div>
          </div>
        </transition>
        
        <!-- Recent Logs (desktop) -->
        <div class="hidden lg:flex flex-col flex-1 min-h-0">
          <div class="flex items-center justify-between mb-3">
            <h2 :class="['text-base lg:text-lg font-bold flex items-center gap-2', isCOE ? 'text-orange-300' : isSOM ? 'text-green-300' : isCNAHS ? 'text-teal-300' : 'text-blue-300']">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
              Recent Logs
            </h2>
            <span v-if="sortedAttendanceLogs.length > 0" :class="['px-2.5 py-1 rounded-full text-xs font-bold', isCOE ? 'bg-orange-500/30 text-orange-200' : isSOM ? 'bg-green-500/30 text-green-200' : isCNAHS ? 'bg-teal-500/30 text-teal-200' : 'bg-blue-500/30 text-blue-200']">
              {{ sortedAttendanceLogs.length }}
            </span>
          </div>
          
          <div class="flex-1 overflow-hidden">
            <div v-if="sortedAttendanceLogs.length === 0" class="flex flex-col items-center justify-center h-full text-white/50">
              <svg class="w-14 h-14 mb-3 opacity-40" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
              <p class="text-sm font-medium">No attendance records yet</p>
              <p class="text-xs mt-1 opacity-60">Scan an RFID card to begin</p>
            </div>
            <div v-else class="space-y-2 overflow-y-auto h-full pr-1 fullscreen-scroll">
              <div 
                v-for="(log, index) in sortedAttendanceLogs.slice(0, 20)" 
                :key="log._id" 
                :class="['rounded-xl p-3 border transition-all duration-300',
                  isCOE ? 'bg-orange-500/10 border-orange-400/25 hover:bg-orange-500/15' : isSOM ? 'bg-green-500/10 border-green-400/25 hover:bg-green-500/15' : isCNAHS ? 'bg-teal-500/10 border-teal-400/25 hover:bg-teal-500/15' : 'bg-blue-500/10 border-blue-400/25 hover:bg-blue-500/15',
                  index === 0 && isRecentCheckIn(log) ? 'ring-1 ring-inset ' + (isCOE ? 'ring-orange-400/60' : isSOM ? 'ring-green-400/60' : isCNAHS ? 'ring-teal-400/60' : 'ring-blue-400/60') : '']"
              >
                <div class="flex items-center gap-3">
                  <!-- Avatar -->
                  <div class="relative w-9 h-9 rounded-full flex-shrink-0">
                    <div :class="['absolute inset-0 rounded-full flex items-center justify-center text-white text-xs font-bold', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                      {{ getInitials(log.student?.full_name || log.student_name) }}
                    </div>
                    <img v-if="log.student_image || log.student?.photo" :src="log.student_image || log.student?.photo" class="absolute inset-0 w-full h-full rounded-full object-cover" @error="$event.target.style.display='none'" />
                  </div>
                  
                  <!-- Name & Details -->
                  <div class="flex-1 min-w-0">
                    <p class="font-semibold text-white text-sm truncate">{{ log.student?.full_name || log.student_name }}</p>
                    <p class="text-white/50 text-xs truncate">{{ log.program || log.student?.program || '' }}</p>
                  </div>
                  
                  <!-- Times + Status -->
                  <div class="flex-shrink-0 flex flex-col items-end gap-1">
                    <span :class="['px-2 py-0.5 rounded-full text-xs font-semibold',
                      log.is_late ? 'bg-orange-500/30 text-orange-200'
                      : (log.check_out_at || log.check_out_time) ? 'bg-green-500/30 text-green-200'
                      : 'bg-yellow-500/30 text-yellow-200']">
                      {{ log.is_late ? ((log.check_out_at || log.check_out_time) ? 'Late' : 'Late (In)') : ((log.check_out_at || log.check_out_time) ? 'Present' : 'In') }}
                    </span>
                    <span class="text-white/45 text-xs font-mono">
                      {{ (log.check_in_at || log.check_in_time) ? new Date(log.check_in_at || log.check_in_time).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--:--' }}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>


    <!-- RFID Loading Effect (Fullscreen with Flipping Logo) -->
    <RFIDLoadingEffect :visible="rfidFullscreenMode && rfidProcessing" :is-coe="isCOE" />

    <!-- Mobile Fullscreen Slide-Down Notification (Top, Above Everything) -->
    <transition name="slide-down">
      <div v-if="rfidFullscreenMode && rfidResult && rfidResult.success && rfidResult.action !== 'already_checked_in' && (rfidResult.student || rfidResult.student_name) && window.innerWidth < 1024" class="fixed inset-x-0 top-0 z-50 p-2 sm:p-4">
        <div class="bg-white bg-opacity-15 backdrop-blur-lg rounded-2xl p-4 sm:p-6 border-2 border-green-400 border-opacity-50 shadow-2xl mx-auto max-w-sm mt-2">
          <div class="flex items-center gap-3 sm:gap-4">
            <div class="relative w-12 h-12 sm:w-16 sm:h-16 rounded-full flex-shrink-0 ring-4 ring-green-400 ring-opacity-60">
              <div :class="['absolute inset-0 rounded-full flex items-center justify-center text-xl sm:text-2xl font-bold text-white', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                {{ getInitials(rfidResult.student?.full_name || rfidResult.student_name) }}
              </div>
            </div>
            <div class="flex-1 min-w-0">
              <div class="flex items-center gap-2 mb-1">
                <svg class="w-4 h-4 sm:w-5 sm:h-5 text-green-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                <span class="text-sm sm:text-lg font-bold text-green-400">{{ rfidResult.action === 'check_in' ? 'Check-in!' : 'Check-out!' }}</span>
              </div>
              <p class="text-white font-semibold text-xs sm:text-sm truncate">{{ rfidResult.student?.full_name || rfidResult.student_name }}</p>
            </div>
          </div>
        </div>
      </div>
    </transition>
  </div>

  <!-- Admin Key Modal - Always on top -->
  <div v-if="isPageLoading" :class="pageLoadingBgClass" :style="pageLoadingBgStyle">
    <div class="text-center text-white">
      <svg class="animate-spin h-16 w-16 mx-auto mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
        <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
        <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
      </svg>
      <p class="text-xl font-semibold">Loading Dashboard...</p>
      <p class="text-sm opacity-75 mt-2">Please wait while we fetch your data</p>
    </div>
  </div>

  <!-- Logout Confirmation Modal -->
  <transition name="fade">
    <div v-if="showLogoutConfirmation" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" @click.self="showLogoutConfirmation = false">
      <transition name="modal-bounce" appear>
        <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-sm w-full mx-4 text-center">
          <div class="w-16 h-16 mx-auto mb-4 bg-red-100 rounded-full flex items-center justify-center">
            <svg class="w-8 h-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path>
            </svg>
          </div>
          <h3 class="text-2xl font-bold text-gray-900 mb-2">Confirm Logout</h3>
          <p class="text-gray-600 mb-6">Are you sure you want to logout?</p>
          
          <div class="flex gap-3">
            <button @click="showLogoutConfirmation = false" class="flex-1 px-6 py-2 bg-gray-200 text-gray-800 rounded-lg font-medium hover:bg-gray-300 transition duration-300">
              Cancel
            </button>
            <button @click="confirmLogout" class="flex-1 px-6 py-2 bg-gradient-to-r from-red-600 to-red-500 text-white rounded-lg font-medium hover:from-red-700 hover:to-red-600 transition duration-300 flex items-center justify-center gap-2">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
              Logout
            </button>
          </div>
        </div>
      </transition>
    </div>
  </transition>

  <!-- Logout Animation -->
  <transition name="fade">
    <div v-if="showLogoutAnimation" :class="logoutBgClass" :style="logoutBgStyle" class="fixed inset-0 z-[9999] flex items-center justify-center overflow-hidden">
      <!-- Particle background -->
      <div class="absolute inset-0 pointer-events-none">
        <span v-for="p in logoutParticles" :key="p.id" class="absolute rounded-full logout-particle" :style="p.style"></span>
      </div>
      <div class="text-center text-white flex flex-col items-center gap-4 relative z-10">
        <div class="flex items-center gap-4">
          <img src="/ccs.png" alt="JRMSU Logo" class="w-20 h-20 object-contain drop-shadow-2xl flex-shrink-0" />
          <div class="leading-tight text-left">
            <h1 class="text-6xl font-extrabold italic tracking-wide drop-shadow-lg">SSAAM</h1>
          </div>
        </div>
        <p class="text-lg font-semibold opacity-90">Logging Out</p>
        <svg class="animate-spin h-10 w-10 text-white opacity-80" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
          <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      </div>
    </div>
  </transition>

  <!-- Edit Attendance (Excuse) Modal -->
  <transition name="fade">
    <div v-if="showEditAttendanceModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[100] overflow-hidden" @click.self="showEditAttendanceModal = false">
      <div class="bg-white rounded-lg p-4 w-full max-w-md mx-4 my-8 shadow-2xl max-h-[90vh] overflow-y-auto">
        <div class="flex items-center justify-between mb-3">
          <h3 class="font-semibold">Edit Attendance (Excuse)</h3>
          <button @click="showEditAttendanceModal = false" class="text-gray-500 hover:text-gray-700">&times;</button>
        </div>
          <div class="space-y-3">
          <div>
            <label class="flex items-center gap-2">
              <input type="checkbox" v-model="editExcused" class="form-checkbox" />
              <span class="text-sm">Mark as Excused</span>
            </label>
          </div>
          <div>
            <label class="text-sm block mb-1">Excused by (student name or admin)</label>
            <div class="flex gap-2">
              <input v-model="editExcusedBy" type="text" class="flex-1 border rounded-md px-3 py-2 text-sm" placeholder="Name who provided the excuse (optional)" />
              <button type="button" @click="fetchExcuseStudentOptions" class="px-3 py-2 bg-gray-100 rounded text-sm">Choose...</button>
            </div>
            <div v-if="excuseStudentOptionsVisible" class="mt-2">
              <select v-model="editExcusedById" @change="onExcuseStudentSelected" class="w-full border rounded-md px-3 py-2 text-sm">
                <option :value="null">-- Select student (or leave blank) --</option>
                <option v-for="s in excuseStudentOptions" :key="s._id" :value="s._id">{{ s.full_name }} — {{ s.student_id }}</option>
              </select>
              <div class="text-xs text-gray-500 mt-1">Selecting a student will set the excused-by reference; you can still type a manual name.</div>
            </div>
          </div>
          <div>
            <label class="text-sm block mb-1">Reason (optional)</label>
            <textarea v-model="editExcuseReason" rows="3" class="w-full border rounded-md px-3 py-2 text-sm" placeholder="Enter reason for excuse"></textarea>
          </div>
          <div class="flex justify-end gap-2">
            <button @click="showEditAttendanceModal = false" class="px-4 py-2 rounded-lg border text-sm">Cancel</button>
            <button @click="saveEditAttendance" class="px-4 py-2 rounded-lg bg-green-600 text-white text-sm">Save</button>
          </div>
        </div>
      </div>
    </div>
  </transition>

  <!-- Mobile Menu Overlay with Animation -->
  <transition name="fade">
    <div v-if="showMobileMenu" class="fixed inset-0 bg-black bg-opacity-50 z-30 md:hidden" @click="showMobileMenu = false"></div>
  </transition>

  <div class="md:flex md:h-screen md:overflow-hidden">
    <!-- Sidebar (Hidden on mobile, visible on desktop) -->
    <div :class="[ 'hidden md:flex w-64 bg-gradient-to-b text-white flex-col order-1 border-r border-white/10 h-screen shadow-2xl sticky top-0 self-start', sidebarGradient ]">
      <div class="px-5 py-5 border-b border-white/15 flex-shrink-0 bg-white/5 backdrop-blur-sm">
        <div class="flex items-center gap-3">
          <img src="/src/assets/ccs-logo.png" alt="JRMSU Logo" class="w-11 h-11 object-contain drop-shadow-xl flex-shrink-0" :class="{ 'logo-flip-animation': sidebarLogoFlipping }" />
          <div class="flex flex-col leading-tight">
            <h1 class="text-2xl font-extrabold italic text-white tracking-wide drop-shadow-sm">SSAAM</h1>
            <p class="text-white/50 text-[9px] uppercase tracking-widest">JRMSU</p>
          </div>
        </div>
      </div>

      <div class="px-3 py-3 border-b border-white/10 flex-shrink-0">
        <!-- Admin (master) keeps the original centered card -->
        <div v-if="currentUser.isMaster || currentUser.role === 'admin'" class="flex flex-col items-center bg-white/[0.06] rounded-2xl px-3 py-4 border border-white/10">
          <p class="text-sm mb-2 opacity-90 text-white">Welcome back,</p>
          <span class="relative inline-flex items-center gap-1.5 px-4 py-1.5 bg-gradient-to-r from-yellow-400 via-amber-500 to-yellow-600 text-white text-sm font-black rounded-full shadow-[0_0_25px_rgba(245,158,11,0.8)] border border-yellow-300/40 overflow-hidden">
            <div class="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent skew-x-[-20deg] translate-x-[-150%] animate-sweep-4s"></div>
            <img src="/crown.svg" alt="Admin" class="w-5 h-5 drop-shadow-[0_0_3px_rgba(255,255,255,0.8)] brightness-0 invert" />
            <span class="tracking-widest uppercase text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.3)]">Admin</span>
          </span>
        </div>
        <!-- Compact card for co-admin / treasurer / student -->
        <div v-else class="bg-white/[0.06] rounded-xl px-2.5 py-2.5 border border-white/10">
          <div class="flex items-center gap-2.5">
            <div :class="['relative w-10 h-10 aspect-square rounded-full flex items-center justify-center overflow-hidden flex-shrink-0 ring-2 ring-white/20', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']" :style="{ background: profileGradient }">
              <img v-if="!sidebarImageFailed && (currentUser.image || currentUser.photo)" :src="currentUser.image || currentUser.photo" alt="Profile" class="w-full h-full object-cover" @error="sidebarImageFailed = true" />
              <span v-else class="text-white font-bold text-sm tracking-wide select-none">{{ getInitials(displayName) }}</span>
            </div>
            <div class="flex-1 min-w-0">
              <p class="text-white text-[13px] font-semibold leading-tight truncate" :title="displayName">{{ displayName }}</p>
              <div class="mt-1 flex items-center gap-1 flex-wrap">
                <span v-if="isTreasurer" class="inline-flex items-center gap-1 pl-0.5 pr-1.5 py-0.5 bg-gradient-to-r from-cyan-500 to-teal-500 text-white text-[9px] font-black uppercase tracking-wider rounded-full" :title="userCollegeCode || 'Treasurer'">
                  <span v-if="userCollegeCode" class="inline-flex items-center justify-center w-4 h-4 bg-white rounded-full"><img :src="userCollegeIcon" alt="College" class="w-3 h-3" /></span>
                  <span>Treasurer</span>
                </span>
                <span v-else-if="isCoAdmin" class="inline-flex items-center gap-1 pl-0.5 pr-1.5 py-0.5 bg-gradient-to-r from-violet-500 to-purple-600 text-white text-[9px] font-black uppercase tracking-wider rounded-full" :title="userCollegeCode || 'Co-Admin'">
                  <span v-if="userCollegeCode" class="inline-flex items-center justify-center w-4 h-4 bg-white rounded-full"><img :src="userCollegeIcon" alt="College" class="w-3 h-3" /></span>
                  <span>Co-Admin</span>
                </span>
                <span v-else class="inline-flex items-center gap-1 pl-0.5 pr-1.5 py-0.5 bg-white/10 text-white/80 text-[9px] font-bold uppercase tracking-wider rounded-full border border-white/10" :title="userCollegeCode || 'Student'">
                  <span v-if="userCollegeCode" class="inline-flex items-center justify-center w-4 h-4 bg-white rounded-full"><img :src="userCollegeIcon" alt="College" class="w-3 h-3" /></span>
                  <span>Student</span>
                </span>
                <span v-if="currentUser.rfid_status === 'verified'" class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-emerald-500/90 text-white text-[9px] font-bold rounded-full" title="Verified">
                  <img src="/verified.svg" alt="Verified" class="w-2 h-2" style="filter: brightness(0) invert(1);" />
                  Verified
                </span>
                <span v-else-if="currentUser.rfid_status === 'Unreadable' || (currentUser.rfid_code && currentUser.rfid_code.toUpperCase().startsWith('UNREADABLE'))" class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-slate-500/90 text-white text-[9px] font-bold rounded-full" title="Unreadable">Unreadable</span>
                <span v-else class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-amber-500/90 text-white text-[9px] font-bold rounded-full" title="Unverified">Unverified</span>
              </div>
            </div>
          </div>
          <div v-if="canSwitchView" class="mt-2.5 flex bg-white/10 rounded-full p-0.5 border border-white/15 text-[10px] font-bold">
            <button @click="roleViewMode = 'role'" :class="['flex-1 px-2 py-1 rounded-full transition-all', roleViewMode === 'role' ? 'bg-white text-gray-800 shadow' : 'text-white/70 hover:text-white']">Tools</button>
            <button @click="roleViewMode = 'user'" :class="['flex-1 px-2 py-1 rounded-full transition-all', roleViewMode === 'user' ? 'bg-white text-gray-800 shadow' : 'text-white/70 hover:text-white']">User View</button>
          </div>
        </div>
      </div>

      <nav class="flex-1 px-3 py-4 overflow-y-auto min-h-0 sidebar-scroll">
        <p class="text-white/30 text-[9px] uppercase tracking-widest font-semibold px-4 mb-2">Menu</p>
        <button @click="currentPage = 'dashboard'" :class="[sidebarItemBase, currentPage === 'dashboard' ? sidebarItemActive : sidebarItemHover]">
          <svg v-if="(isAdminLike) && inRoleView" class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
          <img v-else src="/home.svg" alt="Dashboard" class="w-5 h-5" style="filter: brightness(0) invert(1);" />
          <span>{{ ((isAdminLike) && inRoleView) ? 'Statistics' : 'Dashboard' }}</span>
        </button>

        <button v-if="(isAdminLike) && !isTreasurer && inRoleView" @click="currentPage = 'manage'; showMobileMenu = false; handleManageClick()" :class="[sidebarItemBase, 'mt-2', currentPage === 'manage' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
          <span>Manage</span>
        </button>
        <button v-if="(isAdminLike) && inRoleView" @click="currentPage = 'pending'; fetchPendingStudents()" :class="[sidebarItemBase, 'mt-2', currentPage === 'pending' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
          <span class="flex items-center gap-2">Pending <span v-if="pendingCount > 0" class="bg-red-500 text-white text-xs px-2 py-0.5 rounded-full">{{ pendingCount }}</span></span>
        </button>
        <button v-if="(isAdminLike) && !isTreasurer && inRoleView" @click="currentPage = 'admin-requests'; fetchAdminRequests()" :class="[sidebarItemBase, 'mt-2', currentPage === 'admin-requests' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
          <span class="flex items-center gap-2">Requests <span v-if="pendingRequestsCount > 0" class="bg-amber-500 text-white text-xs px-2 py-0.5 rounded-full">{{ pendingRequestsCount }}</span></span>
        </button>
        <button v-if="(isAdminLike) && !isTreasurer && !isCoAdmin && inRoleView" @click="currentPage = 'settings'; fetchSettings(); fetchAvailablePayments()" :class="[sidebarItemBase, 'mt-2', currentPage === 'settings' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          <span>Settings</span>
        </button>
        <button v-if="isSuperAdmin" @click="currentPage = 'co-admins'; fetchCoAdmins()" :class="[sidebarItemBase, 'mt-2', currentPage === 'co-admins' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z"></path></svg>
          <span>Assign</span>
        </button>
        <button v-if="(!currentUser.isMaster || inRoleView) && !isTreasurer" @click="currentPage = 'attendance'; fetchAttendanceData()" :class="[sidebarItemBase, 'mt-2', currentPage === 'attendance' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"></path></svg>
          <span>Attendance</span>
        </button>
        <button v-if="(isAdminLike) && inRoleView" @click="currentPage = 'contributions'" :class="[sidebarItemBase, 'mt-2', currentPage === 'contributions' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>
          <span>Contributions</span>
        </button>
        <button v-if="(isAdminLike) && inRoleView" @click="currentPage = 'raffle-tickets'" :class="[sidebarItemBase, 'mt-2', currentPage === 'raffle-tickets' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 5v2m0 4v2m0 4v2M5 5a2 2 0 00-2 2v3a2 2 0 110 4v3a2 2 0 002 2h14a2 2 0 002-2v-3a2 2 0 110-4V7a2 2 0 00-2-2H5z"></path></svg>
          <span>Raffle Ticket</span>
        </button>
        <button v-if="(isTreasurer || isCoAdmin) && inRoleView" @click="currentPage = 'audit-trail'" :class="[sidebarItemBase, 'mt-2', currentPage === 'audit-trail' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"></path></svg>
          <span>Audit Trail</span>
        </button>
        <button v-if="inUserView || (!isAdminLike && !canSwitchView)" @click="currentPage = 'request'; fetchStudentRequests()" :class="[sidebarItemBase, 'mt-2', currentPage === 'request' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
          <span>Request</span>
        </button>
        <button v-if="!isAdminLike || inUserView" @click="currentPage = 'my-contributions'; fetchMyPayments()" :class="[sidebarItemBase, 'mt-2', currentPage === 'my-contributions' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>
          <span>Contributions</span>
        </button>
        <button v-if="!isAdminLike || inUserView" @click="currentPage = 'my-raffle'" :class="[sidebarItemBase, 'mt-2', currentPage === 'my-raffle' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 5v2m0 4v2m0 4v2M5 5a2 2 0 00-2 2v3a2 2 0 110 4v3a2 2 0 002 2h14a2 2 0 002-2v-3a2 2 0 110-4V7a2 2 0 00-2-2H5z"></path></svg>
          <span>My Raffle</span>
        </button>
        <!-- Location: live geofence preview for any active event the student can attend -->
        <button v-if="!isAdminLike || inUserView" @click="currentPage = 'location'; fetchAttendanceData()" :class="[sidebarItemBase, 'mt-2', currentPage === 'location' ? sidebarItemActive : sidebarItemHover]">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          <span>Location</span>
        </button>

        <div class="mt-3 border-t border-white/10 pt-3">
          <p class="text-white/30 text-[9px] uppercase tracking-widest font-semibold px-4 mb-2">Account</p>
          <button v-if="false" @click="currentPage = 'admin-profile'; fetchAdminProfile()" :class="[sidebarItemBase, 'mb-1', currentPage === 'admin-profile' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg>
            <span>My Profile</span>
          </button>
          <button 
            @click="handleLogoutWithAnimation"
            :class="[
              'flex items-center space-x-3 px-4 py-2.5 rounded-xl w-full text-left text-sm font-medium transition-all duration-200 border-l-4 border-transparent text-white/80',
              isLoggingOut ? 'scale-95 opacity-60' : 'hover:bg-red-500/20 hover:border-red-400/60 hover:text-white hover:translate-x-0.5'
            ]"
          >
            <img src="/logout.svg" alt="Log Out" :class="['w-4 h-4 transition-transform duration-300', isLoggingOut ? 'rotate-180' : '']" style="filter: brightness(0) invert(1); opacity:0.85;" />
            <span>{{ isLoggingOut ? 'Signing out…' : 'Log Out' }}</span>
          </button>
        </div>
      </nav>

      <div class="px-5 py-3 border-t border-white/10 flex-shrink-0">
        <p class="text-white/30 text-[10px]">Powered by</p>
        <button @click="showDevelopersPopup = true" class="text-yellow-400/80 hover:text-yellow-300 text-[10px] font-medium transition-colors cursor-pointer">CCS - Creatives Committee</button>
      </div>
    </div>

    <!-- Mobile Sidebar (Slide-in menu for mobile) with Animation -->
    <transition name="slide-in">
      <div v-if="showMobileMenu" :class="[ 'fixed left-0 top-0 h-screen w-72 bg-gradient-to-b text-white flex flex-col z-40 md:hidden shadow-2xl', sidebarGradient ]">
        <div class="flex items-center justify-between px-4 py-4 border-b border-white/15 bg-white/5 flex-shrink-0">
          <div class="flex items-center gap-2.5">
            <img src="/src/assets/ccs-logo.png" alt="JRMSU Logo" class="w-9 h-9 object-contain drop-shadow-lg flex-shrink-0" />
            <div class="flex flex-col leading-tight">
              <h1 class="text-xl font-extrabold italic text-white tracking-wide drop-shadow-sm">SSAAM</h1>
              <p class="text-[9px] uppercase tracking-widest font-semibold text-white/50">JRMSU</p>
            </div>
          </div>
          <button @click="showMobileMenu = false" class="text-2xl text-white/80 hover:text-white leading-none">×</button>
        </div>
        
        <div class="px-4 py-4 border-b border-white/10 flex-shrink-0">
          <div v-if="currentUser.isMaster || currentUser.role === 'admin'" class="flex flex-col items-center bg-white/[0.06] rounded-2xl px-3 py-4 border border-white/10">
            <p class="text-sm mb-2 opacity-90 text-white">Welcome back,</p>
            <span class="relative inline-flex items-center gap-1.5 px-4 py-1.5 bg-gradient-to-r from-yellow-400 via-amber-500 to-yellow-600 text-white text-sm font-black rounded-full shadow-[0_0_25px_rgba(245,158,11,0.8)] border border-yellow-300/40 overflow-hidden">
              <div class="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent skew-x-[-20deg] translate-x-[-150%] animate-sweep-4s"></div>
              <img src="/crown.svg" alt="Admin" class="w-5 h-5 drop-shadow-[0_0_3px_rgba(255,255,255,0.8)] brightness-0 invert" />
              <span class="tracking-widest uppercase text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.3)]">Admin</span>
            </span>
          </div>
          <div v-else class="bg-white/[0.06] rounded-xl px-2.5 py-2.5 border border-white/10">
            <div class="flex items-center gap-2.5">
              <div :class="['relative w-10 h-10 aspect-square rounded-full flex items-center justify-center overflow-hidden flex-shrink-0 ring-2 ring-white/20', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']" :style="{ background: profileGradient }">
                <img v-if="!sidebarImageFailed && (currentUser.image || currentUser.photo)" :src="currentUser.image || currentUser.photo" alt="Profile" class="w-full h-full object-cover" @error="sidebarImageFailed = true" />
                <span v-else class="text-white font-bold text-sm tracking-wide select-none">{{ getInitials(displayName) }}</span>
              </div>
              <div class="flex-1 min-w-0">
                <p class="text-white text-[13px] font-semibold leading-tight truncate" :title="displayName">{{ displayName }}</p>
                <div class="mt-1 flex items-center gap-1 flex-wrap">
                  <span v-if="isTreasurer" class="inline-flex items-center gap-1 pl-0.5 pr-1.5 py-0.5 bg-gradient-to-r from-cyan-500 to-teal-500 text-white text-[9px] font-black uppercase tracking-wider rounded-full" :title="userCollegeCode || 'Treasurer'">
                    <span v-if="userCollegeCode" class="inline-flex items-center justify-center w-4 h-4 bg-white rounded-full"><img :src="userCollegeIcon" alt="College" class="w-3 h-3" /></span>
                    <span>Treasurer</span>
                  </span>
                  <span v-else-if="isCoAdmin" class="inline-flex items-center gap-1 pl-0.5 pr-1.5 py-0.5 bg-gradient-to-r from-violet-500 to-purple-600 text-white text-[9px] font-black uppercase tracking-wider rounded-full" :title="userCollegeCode || 'Co-Admin'">
                    <span v-if="userCollegeCode" class="inline-flex items-center justify-center w-4 h-4 bg-white rounded-full"><img :src="userCollegeIcon" alt="College" class="w-3 h-3" /></span>
                    <span>Co-Admin</span>
                  </span>
                  <span v-else class="inline-flex items-center gap-1 pl-0.5 pr-1.5 py-0.5 bg-white/10 text-white/80 text-[9px] font-bold uppercase tracking-wider rounded-full border border-white/10" :title="userCollegeCode || 'Student'">
                    <span v-if="userCollegeCode" class="inline-flex items-center justify-center w-4 h-4 bg-white rounded-full"><img :src="userCollegeIcon" alt="College" class="w-3 h-3" /></span>
                    <span>Student</span>
                  </span>
                  <span v-if="currentUser.rfid_status === 'verified'" class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-emerald-500/90 text-white text-[9px] font-bold rounded-full">
                    <img src="/verified.svg" alt="Verified" class="w-2 h-2" style="filter: brightness(0) invert(1);" />
                    Verified
                  </span>
                  <span v-else-if="currentUser.rfid_status === 'Unreadable' || (currentUser.rfid_code && currentUser.rfid_code.toUpperCase().startsWith('UNREADABLE'))" class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-slate-500/90 text-white text-[9px] font-bold rounded-full">Unreadable</span>
                  <span v-else class="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-amber-500/90 text-white text-[9px] font-bold rounded-full">Unverified</span>
                </div>
              </div>
            </div>
            <div v-if="canSwitchView" class="mt-2.5 flex bg-white/10 rounded-full p-0.5 border border-white/15 text-[10px] font-bold">
              <button @click="roleViewMode = 'role'" :class="['flex-1 px-2 py-1 rounded-full transition-all', roleViewMode === 'role' ? 'bg-white text-gray-800 shadow' : 'text-white/70 hover:text-white']">Tools</button>
              <button @click="roleViewMode = 'user'" :class="['flex-1 px-2 py-1 rounded-full transition-all', roleViewMode === 'user' ? 'bg-white text-gray-800 shadow' : 'text-white/70 hover:text-white']">User View</button>
            </div>
          </div>
        </div>

        <nav class="flex-1 px-3 py-4 overflow-y-auto min-h-0 sidebar-scroll">
          <p class="text-white/30 text-[9px] uppercase tracking-widest font-semibold px-4 mb-2">Menu</p>
          <button @click="currentPage = 'dashboard'; showMobileMenu = false" :class="[sidebarItemBase, currentPage === 'dashboard' ? sidebarItemActive : sidebarItemHover]">
            <svg v-if="(isAdminLike) && inRoleView" class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
            <img v-else src="/home.svg" alt="Dashboard" class="w-5 h-5" style="filter: brightness(0) invert(1);" />
            <span>{{ ((isAdminLike) && inRoleView) ? 'Statistics' : 'Dashboard' }}</span>
          </button>

          <button v-if="(isAdminLike) && !isTreasurer && inRoleView" @click="currentPage = 'manage'; showMobileMenu = false; handleManageClick()" :class="[sidebarItemBase, 'mt-2', currentPage === 'manage' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
            <span>Manage</span>
          </button>
          <button v-if="(isAdminLike) && inRoleView" @click="currentPage = 'pending'; showMobileMenu = false; fetchPendingStudents()" :class="[sidebarItemBase, 'mt-2', currentPage === 'pending' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            <span class="flex items-center gap-2">Pending <span v-if="pendingCount > 0" class="bg-red-500 text-white text-xs px-2 py-0.5 rounded-full">{{ pendingCount }}</span></span>
          </button>
          <button v-if="(isAdminLike) && !isTreasurer && inRoleView" @click="currentPage = 'admin-requests'; showMobileMenu = false; fetchAdminRequests()" :class="[sidebarItemBase, 'mt-2', currentPage === 'admin-requests' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
            <span class="flex items-center gap-2">Requests <span v-if="pendingRequestsCount > 0" class="bg-amber-500 text-white text-xs px-2 py-0.5 rounded-full">{{ pendingRequestsCount }}</span></span>
          </button>
          <button v-if="(currentUser.role === 'admin' || isSuperAdmin) && inRoleView" @click="currentPage = 'settings'; showMobileMenu = false; fetchSettings(); fetchAvailablePayments()" :class="[sidebarItemBase, 'mt-2', currentPage === 'settings' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
            <span>Settings</span>
          </button>
          <button v-if="isSuperAdmin" @click="currentPage = 'co-admins'; showMobileMenu = false; fetchCoAdmins()" :class="[sidebarItemBase, 'mt-2', currentPage === 'co-admins' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z"></path></svg>
            <span>Assign</span>
          </button>
          <button v-if="(!currentUser.isMaster || inRoleView) && !isTreasurer" @click="currentPage = 'attendance'; showMobileMenu = false; fetchAttendanceData()" :class="[sidebarItemBase, 'mt-2', currentPage === 'attendance' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"></path></svg>
            <span>Attendance</span>
          </button>
          <button v-if="(isAdminLike) && inRoleView" @click="currentPage = 'contributions'; showMobileMenu = false" :class="[sidebarItemBase, 'mt-2', currentPage === 'contributions' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>
            <span>Contributions</span>
          </button>
          <button v-if="(isAdminLike) && inRoleView" @click="currentPage = 'raffle-tickets'; showMobileMenu = false" :class="[sidebarItemBase, 'mt-2', currentPage === 'raffle-tickets' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 5v2m0 4v2m0 4v2M5 5a2 2 0 00-2 2v3a2 2 0 110 4v3a2 2 0 002 2h14a2 2 0 002-2v-3a2 2 0 110-4V7a2 2 0 00-2-2H5z"></path></svg>
            <span>Raffle Ticket</span>
          </button>
          <button v-if="(isTreasurer || isCoAdmin) && inRoleView" @click="currentPage = 'audit-trail'; showMobileMenu = false" :class="[sidebarItemBase, 'mt-2', currentPage === 'audit-trail' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"></path></svg>
            <span>Audit Trail</span>
          </button>
          <button v-if="inUserView || (!isAdminLike && !canSwitchView)" @click="currentPage = 'request'; showMobileMenu = false; fetchStudentRequests()" :class="[sidebarItemBase, 'mt-2', currentPage === 'request' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
            <span>Request</span>
          </button>
          <button v-if="!isAdminLike || inUserView" @click="currentPage = 'my-contributions'; showMobileMenu = false; fetchMyPayments()" :class="[sidebarItemBase, 'mt-2', currentPage === 'my-contributions' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>
            <span>Contributions</span>
          </button>
          <button v-if="!isAdminLike || inUserView" @click="currentPage = 'my-raffle'; showMobileMenu = false" :class="[sidebarItemBase, 'mt-2', currentPage === 'my-raffle' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 5v2m0 4v2m0 4v2M5 5a2 2 0 00-2 2v3a2 2 0 110 4v3a2 2 0 002 2h14a2 2 0 002-2v-3a2 2 0 110-4V7a2 2 0 00-2-2H5z"></path></svg>
            <span>My Raffle</span>
          </button>
          <button v-if="!isAdminLike || inUserView" @click="currentPage = 'location'; showMobileMenu = false; fetchAttendanceData()" :class="[sidebarItemBase, 'mt-2', currentPage === 'location' ? sidebarItemActive : sidebarItemHover]">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
            <span>Location</span>
          </button>

          <button 
            @click="refreshCurrentUser(); showMobileMenu = false"
            :class="['md:flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-white hover:bg-opacity-10 w-full text-left mt-2 transition-all duration-300 hidden', refreshingUserData ? 'opacity-70' : '']"
          >
            <svg class="w-5 h-5 transition-transform duration-700" :class="{ 'animate-spin': refreshingUserData }" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path>
            </svg>
            <span>Refresh Data</span>
          </button>
          <div class="mt-3 border-t border-white/10 pt-3">
            <p class="text-white/30 text-[9px] uppercase tracking-widest font-semibold px-4 mb-2">Account</p>
            <button v-if="false" @click="currentPage = 'admin-profile'; showMobileMenu = false; fetchAdminProfile()" :class="[sidebarItemBase, 'mb-1', currentPage === 'admin-profile' ? sidebarItemActive : sidebarItemHover]">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" style="filter: brightness(0) invert(1);"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg>
              <span>My Profile</span>
            </button>
            <button 
              @click="handleLogoutWithAnimation"
              :class="[
                'flex items-center space-x-3 px-4 py-2.5 rounded-xl w-full text-left text-sm font-medium transition-all duration-200 border-l-4 border-transparent text-white/80',
                isLoggingOut ? 'scale-95 opacity-60' : 'hover:bg-red-500/20 hover:border-red-400/60 hover:text-white hover:translate-x-0.5'
              ]"
            >
              <img src="/logout.svg" alt="Log Out" :class="['w-4 h-4 transition-transform duration-300', isLoggingOut ? 'rotate-180' : '']" style="filter: brightness(0) invert(1); opacity:0.85;" />
              <span>{{ isLoggingOut ? 'Signing out…' : 'Log Out' }}</span>
            </button>
          </div>
        </nav>

        <div class="px-5 py-3 border-t border-white/10 flex-shrink-0">
          <p class="text-white/30 text-[10px]">Powered by</p>
          <button @click="showDevelopersPopup = true" class="text-yellow-400/80 hover:text-yellow-300 text-[10px] font-medium transition-colors cursor-pointer">CCS - Creatives Committee</button>
        </div>
      </div>
    </transition>

    <!-- Main Content Area -->
    <div ref="mainContentEl" tabindex="-1" class="bg-slate-50 md:flex-1 md:order-2 min-w-0 min-h-screen md:min-h-0 md:overflow-y-auto outline-none">
      <!-- Mobile Header with Hamburger Menu -->
      <div class="md:hidden sticky top-0 bg-white border-b border-gray-200 p-3 flex items-center justify-between z-20 shadow">
        <div class="flex items-center gap-2">
          <img src="/src/assets/ccs-logo.png" alt="JRMSU Logo" class="w-8 h-8 object-contain drop-shadow" style="filter: invert(1);" />
          <div class="flex flex-col leading-tight">
            <h1 :class="['text-xl font-extrabold italic', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">SSAAM</h1>
            <p :class="['text-[9px] uppercase tracking-widest font-semibold', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : isCNAHS ? 'text-green-400' : 'text-blue-400']">JRMSU</p>
          </div>
        </div>
        <div class="flex items-center gap-2">
          <button @click="showContactModal = true" :class="['p-2 rounded-lg transition', isCOE ? 'hover:bg-orange-100' : isSOM ? 'hover:bg-green-100' : isCNAHS ? 'hover:bg-green-100' : 'hover:bg-blue-100']">
            <img src="/help.svg" alt="Help" :class="['w-5 h-5', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" />
          </button>
          <button @click="showMobileMenu = true" :class="['text-2xl', isCOE ? 'text-orange-900 hover:text-orange-700' : isSOM ? 'text-green-900 hover:text-green-700' : isCNAHS ? 'text-green-900 hover:text-green-700' : 'text-blue-900 hover:text-blue-700']">☰</button>
        </div>
      </div>

      <!-- Floating Help Button (visible on mobile and desktop) -->
      <div class="fixed bottom-4 right-4 md:bottom-8 md:right-8 z-20">
        <button @click="showContactModal = true" :class="['text-white rounded-full w-12 h-12 md:w-14 md:h-14 flex items-center justify-center transition-all duration-300 shadow-lg hover:scale-110 active:scale-95 hover:shadow-xl bg-gradient-to-r', isCOE ? 'from-orange-600 to-red-500 hover:from-orange-700 hover:to-red-600' : isSOM ? 'from-green-600 to-yellow-500 hover:from-green-700 hover:to-yellow-600' : isCNAHS ? 'from-green-700 to-green-600 hover:from-green-800 hover:to-green-700' : 'from-ssaam-dark to-ssaam-light hover:from-ssaam-dark hover:to-ssaam-light']">
          <img src="/help.svg" alt="Help" class="w-5 h-5 md:w-6 md:h-6" style="filter: brightness(0) invert(1);" />
        </button>
      </div>

      <Transition name="section-fade" mode="out-in">
      <div :key="currentPage" class="p-4 md:p-8">
        <h1 :class="['hidden md:block text-xl md:text-3xl font-bold mb-4 pb-3 border-b', isCOE ? 'text-orange-900 border-orange-200' : isSOM ? 'text-green-900 border-green-200' : isCNAHS ? 'text-green-900 border-green-200' : 'text-blue-900 border-blue-200']">{{ currentPage === 'users' ? 'Manage Users' : currentPage === 'roles' ? 'Manage Roles' : currentPage === 'settings' ? 'Settings' : currentPage === 'pending' ? 'Pending Approvals' : currentPage === 'admin-requests' ? 'Student Requests' : currentPage === 'attendance' ? 'Attendance' : currentPage === 'payments' ? 'Payments' : currentPage === 'contributions' ? 'Contributions' : currentPage === 'raffle-tickets' ? 'Raffle Ticket' : currentPage === 'my-contributions' ? 'My Contributions' : currentPage === 'my-raffle' ? 'My Raffle Results' : currentPage === 'admin-profile' ? 'My Profile' : currentPage === 'co-admins' ? 'Promote Co-Admins' : currentPage === 'request' ? 'Request' : currentPage === 'location' ? 'Location' : currentPage === 'audit-trail' ? (isTreasurer ? 'My Audit Trail' : 'College Audit Trail') : currentPage === 'dashboard' && (isAdminLike) && inRoleView ? 'Statistics' : 'Dashboard' }}</h1>

        <!-- Password Update Warning Banner -->
        <div v-if="showPasswordUpdateWarning && !currentUser.isMaster && currentUser.role !== 'admin'" class="mb-4 bg-yellow-50 border border-yellow-200 px-4 py-3 rounded-xl flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3">
          <div class="flex items-center gap-2 flex-1 min-w-0">
            <svg class="w-4 h-4 text-yellow-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path>
            </svg>
            <p class="text-xs text-yellow-800">Your password is still set to your last name. Please change it for better security.</p>
          </div>
          <div class="flex items-center gap-2 flex-shrink-0 self-end sm:self-auto">
            <button @click="showPasswordChangeModal = true; showPasswordUpdateWarning = false" class="bg-yellow-500 hover:bg-yellow-600 text-white text-xs px-3 py-1.5 rounded-lg font-medium transition">Change Password</button>
            <button @click="showPasswordUpdateWarning = false" class="text-yellow-600 hover:text-yellow-800 text-xs font-medium transition">Dismiss</button>
          </div>
        </div>

        <!-- ── Face ID Setup Required Banner ──────────────────────────────────── -->
        <!-- Shown to co-admin / treasurer who have NOT enrolled a face yet.      -->
        <!-- Non-dismissable — disappears only once they set up Face ID.          -->
        <transition name="fade">
          <div v-if="isRestrictedMasterRole && faceIdEnrolledCount === 0" class="mb-5">
            <!-- Main urgent banner -->
            <div class="relative overflow-hidden rounded-2xl border border-red-300/60 bg-gradient-to-br from-red-50 via-orange-50 to-amber-50 shadow-lg shadow-red-100/60 px-4 py-4 sm:px-5 sm:py-4">
              <!-- Pulsing left accent stripe -->
              <div class="absolute left-0 inset-y-0 w-1.5 rounded-l-2xl bg-gradient-to-b from-red-500 to-orange-500 animate-pulse"></div>

              <div class="pl-3 flex flex-col sm:flex-row sm:items-start gap-4">
                <!-- Icon block -->
                <div class="flex-shrink-0 flex items-start gap-3">
                  <div class="relative">
                    <div class="absolute inset-0 rounded-xl bg-red-400/30 blur-md animate-pulse"></div>
                    <div class="relative w-11 h-11 rounded-xl bg-gradient-to-br from-red-500 to-orange-500 flex items-center justify-center shadow-md">
                      <svg class="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2">
                        <path stroke-linecap="round" stroke-linejoin="round" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/>
                      </svg>
                    </div>
                  </div>
                  <!-- Role badge (mobile inline) -->
                  <div class="sm:hidden flex items-center">
                    <span class="px-2.5 py-1 rounded-full text-[11px] font-black uppercase tracking-wider bg-red-100 border border-red-300 text-red-700">
                      {{ restrictedRoleLabel }} · Action Required
                    </span>
                  </div>
                </div>

                <!-- Text block -->
                <div class="flex-1 min-w-0">
                  <!-- Role badge (desktop) -->
                  <div class="hidden sm:inline-flex items-center mb-1.5">
                    <span class="px-2.5 py-0.5 rounded-full text-[11px] font-black uppercase tracking-wider bg-red-100 border border-red-300 text-red-700">
                      {{ restrictedRoleLabel }} · Action Required
                    </span>
                  </div>
                  <h4 class="text-sm font-bold text-red-900 leading-snug">Face ID Not Set Up</h4>
                  <p class="mt-0.5 text-xs text-red-700/90 leading-relaxed max-w-lg">
                    As a <strong>{{ restrictedRoleLabel }}</strong>, you are required to enroll your Face ID for account security. You currently have <strong>no biometric on file</strong>. Set it up now from Settings to secure your access.
                  </p>

                  <!-- Steps hint -->
                  <div class="mt-3 flex flex-wrap gap-2">
                    <div v-for="(step, i) in ['Go to Settings', 'Open Face ID section', 'Capture your face']" :key="i"
                      class="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-white/80 border border-red-200 text-xs text-red-800 font-medium shadow-sm">
                      <span class="w-4 h-4 rounded-full bg-gradient-to-br from-red-500 to-orange-400 text-white text-[10px] font-black flex items-center justify-center flex-shrink-0">{{ i + 1 }}</span>
                      {{ step }}
                    </div>
                  </div>
                </div>

                <!-- CTA button -->
                <div class="flex-shrink-0 self-start sm:self-center">
                  <button
                    @click="currentPage = 'settings'"
                    class="relative inline-flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-red-500 to-orange-500 hover:from-red-600 hover:to-orange-600 shadow-md hover:shadow-lg hover:shadow-red-200/60 transition-all duration-200 hover:scale-[1.03] active:scale-95 whitespace-nowrap"
                  >
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2.5">
                      <path stroke-linecap="round" stroke-linejoin="round" d="M15 10a3 3 0 11-6 0 3 3 0 016 0z"/>
                      <path stroke-linecap="round" stroke-linejoin="round" d="M3 8V6a2 2 0 012-2h2M3 16v2a2 2 0 002 2h2m10-16h2a2 2 0 012 2v2m-4 12h2a2 2 0 002-2v-2"/>
                    </svg>
                    Set Up Face ID
                  </button>
                </div>
              </div>
            </div>
          </div>
        </transition>


        <div v-if="currentPage === 'settings' && (isAdminLike)" class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
          <div :class="['relative h-24 sm:h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
            <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
            <div class="light-sweep"></div>
            <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
              <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white/20 flex items-center justify-center flex-shrink-0">
                <svg class="w-5 h-5 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              </div>
              <div class="flex-1 min-w-0">
                <h2 class="text-lg sm:text-xl font-extrabold text-white tracking-tight">Access Control Settings</h2>
                <p class="text-white/70 text-xs sm:text-sm mt-0.5">Manage registration, login, and system configurations</p>
              </div>
              <button @click="refreshSettingsSection" :disabled="settingsLoading" class="px-3 sm:px-4 py-2 rounded-xl text-white text-sm font-semibold bg-white/20 hover:bg-white/30 border border-white/20 transition flex items-center gap-2 disabled:opacity-60 flex-shrink-0">
                <svg :class="['w-4 h-4', settingsLoading ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                <span class="hidden sm:inline">{{ settingsLoading ? 'Loading...' : 'Refresh' }}</span>
              </button>
            </div>
          </div>
          <div class="p-3 sm:p-4 md:p-6">

          <div v-if="settingsLoading" class="flex items-center justify-center py-12">
            <svg :class="['animate-spin h-10 w-10', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          </div>

          <div v-else class="space-y-8">
            <!-- User Registration Toggle -->
            <div class="border border-gray-200 rounded-xl p-6">
              <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
                <div>
                  <h3 :class="['text-lg font-semibold flex items-center gap-2', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">
                    <svg :class="['w-5 h-5', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"></path></svg>
                    User Registration
                  </h3>
                  <p class="text-sm text-gray-500 mt-1">Allow new students to create accounts</p>
                </div>
                <button 
                  @click="appSettings.userRegister.register = !appSettings.userRegister.register" 
                  :class="['relative inline-flex h-8 w-14 items-center rounded-full transition-colors duration-300', appSettings.userRegister.register ? 'bg-green-500' : 'bg-gray-300']"
                >
                  <span :class="['inline-block h-6 w-6 transform rounded-full bg-white shadow-lg transition-transform duration-300', appSettings.userRegister.register ? 'translate-x-7' : 'translate-x-1']"></span>
                </button>
              </div>
              <div class="flex items-center gap-2 mb-2">
                <span :class="['text-sm font-medium px-3 py-1 rounded-full', appSettings.userRegister.register ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700']">
                  {{ appSettings.userRegister.register ? 'Enabled' : 'Disabled' }}
                </span>
              </div>
                <div v-if="!appSettings.userRegister.register" class="mt-4">
                <label class="block text-sm font-medium text-gray-700 mb-2">Message to display when registration is disabled:</label>
                <textarea 
                  v-model="appSettings.userRegister.message" 
                  placeholder="Enter a message to show users when registration is disabled..."
                  :class="['w-full px-4 py-3 border rounded-lg outline-none resize-none', isCOE ? 'border-orange-300 focus:ring-2 focus:ring-orange-200 focus:border-transparent' : isSOM ? 'border-green-300 focus:ring-2 focus:ring-green-600 focus:border-transparent' : 'border-gray-300 focus:ring-2 focus:ring-blue-600 focus:border-transparent']"
                  rows="3"
                ></textarea>
              </div>
            </div>

            <!-- User Login Toggle -->
            <div class="border border-gray-200 rounded-xl p-6">
              <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
                <div>
                  <h3 :class="['text-lg font-semibold flex items-center gap-2', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">
                    <svg :class="['w-5 h-5', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1"></path></svg>
                    User Login
                  </h3>
                  <p class="text-sm text-gray-500 mt-1">Allow students to log into their accounts</p>
                </div>
                <button 
                  @click="appSettings.userLogin.login = !appSettings.userLogin.login" 
                  :class="['relative inline-flex h-8 w-14 items-center rounded-full transition-colors duration-300', appSettings.userLogin.login ? 'bg-green-500' : 'bg-gray-300']"
                >
                  <span :class="['inline-block h-6 w-6 transform rounded-full bg-white shadow-lg transition-transform duration-300', appSettings.userLogin.login ? 'translate-x-7' : 'translate-x-1']"></span>
                </button>
              </div>
              <div class="flex items-center gap-2 mb-2">
                <span :class="['text-sm font-medium px-3 py-1 rounded-full', appSettings.userLogin.login ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700']">
                  {{ appSettings.userLogin.login ? 'Enabled' : 'Disabled' }}
                </span>
              </div>
              <div v-if="!appSettings.userLogin.login" class="mt-4">
                <label class="block text-sm font-medium text-gray-700 mb-2">Message to display when login is disabled:</label>
                <textarea 
                  v-model="appSettings.userLogin.message" 
                  placeholder="Enter a message to show users when login is disabled..."
                  :class="['w-full px-4 py-3 border rounded-lg outline-none resize-none', isCOE ? 'border-orange-300 focus:ring-2 focus:ring-orange-200 focus:border-transparent' : isSOM ? 'border-green-300 focus:ring-2 focus:ring-green-600 focus:border-transparent' : 'border-gray-300 focus:ring-2 focus:ring-blue-600 focus:border-transparent']"
                  rows="3"
                ></textarea>
              </div>
            </div>

            <!-- Academic Term Settings -->
            <div :class="['border border-gray-200 rounded-xl p-6', isCOE ? 'bg-orange-50/30' : isSOM ? 'bg-green-50/30' : isCNAHS ? 'bg-green-50/30' : 'bg-blue-50/30']">
              <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <div>
                  <h3 :class="['text-lg font-semibold flex items-center gap-2', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">
                    <svg :class="['w-5 h-5', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                    Academic Term Settings
                  </h3>
                  <p class="text-sm text-gray-500 mt-1">Global semester and school year configuration</p>
                </div>
              </div>
              <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label class="block text-sm font-medium text-gray-700 mb-2">Semester</label>
                  <select 
                    v-model="appSettings.semester"
                    :class="['w-full px-4 py-2 bg-white rounded-lg outline-none transition-all', isCOE ? 'border-orange-300 focus:ring-2 focus:ring-orange-200' : 'border-gray-300 focus:ring-2 focus:ring-blue-600']"
                  >
                    <option value="1st Sem">1st Semester</option>
                    <option value="2nd Sem">2nd Semester</option>
                  </select>
                </div>
                <div>
                  <label class="block text-sm font-medium text-gray-700 mb-2">School Year</label>
                  <input 
                    v-model="appSettings.schoolYear"
                    type="text"
                    placeholder="e.g. 2023-2024"
                    :class="['w-full px-4 py-2 bg-white rounded-lg outline-none transition-all', isCOE ? 'border-orange-300 focus:ring-2 focus:ring-orange-200' : 'border-gray-300 focus:ring-2 focus:ring-blue-600']"
                  />
                </div>
              </div>
            </div>

            <!-- Search for Duplicates Section -->
            <div class="border border-blue-200 rounded-xl p-6 bg-blue-50">
              <div class="mb-4">
                <h3 class="text-lg font-semibold text-blue-900 flex items-center gap-2">
                  <svg class="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                  Search for Duplicate Records
                </h3>
                <p class="text-sm text-blue-700 mt-1">Find students with duplicate RFID codes, Student IDs, or Gmail addresses</p>
              </div>
              <div class="bg-white rounded-lg p-4 border border-blue-200 space-y-4">
                <!-- Auto Scan Button -->
                <div class="flex flex-col sm:flex-row gap-3">
                  <button 
                    @click="scanAllForDuplicates" 
                    :disabled="autoScanLoading"
                    class="flex-1 bg-gradient-to-r from-orange-500 to-red-500 text-white px-6 py-3 rounded-lg font-medium hover:from-orange-600 hover:to-red-600 transition flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    <svg v-if="autoScanLoading" class="w-5 h-5 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                    <svg v-else class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"></path></svg>
                    {{ autoScanLoading ? 'Scanning All Records...' : 'Auto Scan All for Duplicates' }}
                  </button>
                </div>
                
                <!-- Auto Scan Results -->
                <div v-if="autoScanResults.length > 0" class="mt-4">
                  <div class="bg-red-50 border border-red-200 rounded-lg p-3 mb-3">
                    <h4 class="text-sm font-bold text-red-800 flex items-center gap-2">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                      Found {{ autoScanResults.length }} duplicate issue(s)!
                    </h4>
                  </div>
                  <div class="space-y-2 max-h-80 overflow-y-auto">
                    <div v-for="(group, index) in autoScanResults" :key="index" class="bg-red-50 p-3 rounded-lg border border-red-200">
                      <p class="text-xs font-bold text-red-700 mb-2">{{ group.type }} Duplicate: "{{ group.value }}"</p>
                      <div class="space-y-2">
                        <div v-for="student in group.students" :key="student.student_id" class="bg-white p-2 rounded border border-gray-200 flex items-center gap-3">
                          <div class="w-8 h-8 rounded-full bg-gradient-to-r from-ssaam-dark to-ssaam-light flex items-center justify-center text-white text-xs font-bold overflow-hidden flex-shrink-0">
                            <img v-if="student.photo" :src="student.photo" class="w-full h-full object-cover rounded-full" />
                            <span v-else>{{ (student.first_name || '?').charAt(0) }}</span>
                          </div>
                          <div class="flex-1 min-w-0">
                            <p class="font-medium text-gray-900 text-sm truncate">{{ student.first_name }} {{ student.last_name }}</p>
                            <p class="text-xs text-gray-500">ID: {{ student.student_id }} | {{ student.email }}</p>
                            <p v-if="student.rfid_code" class="text-xs text-blue-600">RFID: {{ student.rfid_code }}</p>
                          </div>
                          <div class="flex gap-1 flex-shrink-0">
                            <button 
                              @click="openEditDuplicateStudent(student)" 
                              class="p-1.5 bg-yellow-100 text-yellow-700 rounded hover:bg-yellow-200 transition"
                              title="Edit Student"
                            >
                              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg>
                            </button>
                            <button 
                              @click="deleteDuplicateStudent(student)" 
                              class="p-1.5 bg-red-100 text-red-700 rounded hover:bg-red-200 transition"
                              title="Delete Student"
                            >
                              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
                
                <div v-else-if="autoScanPerformed && autoScanResults.length === 0" class="mt-4 text-center py-4 bg-green-50 rounded-lg border border-green-200">
                  <svg class="w-12 h-12 mx-auto text-green-500 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                  <p class="text-green-700 font-medium">No duplicates found!</p>
                  <p class="text-sm text-gray-500">All records are unique. Your database is clean!</p>
                </div>

                <!-- Divider -->
                <div class="border-t border-gray-200 pt-4 mt-4">
                  <p class="text-xs text-gray-500 mb-3">Or search for a specific value:</p>
                </div>

                <div class="flex flex-col md:flex-row gap-3">
                  <input 
                    v-model="duplicateSearchQuery" 
                    type="text" 
                    placeholder="Enter RFID, Student ID, or Email to search..." 
                    class="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                  />
                  <button 
                    @click="searchForDuplicates" 
                    :disabled="duplicateSearchLoading || !duplicateSearchQuery.trim()"
                    class="bg-blue-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-blue-700 transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    <svg v-if="duplicateSearchLoading" class="w-4 h-4 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                    <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                    {{ duplicateSearchLoading ? 'Searching...' : 'Search' }}
                  </button>
                </div>
                
                <div v-if="duplicateSearchResults.length > 0" class="mt-4">
                  <h4 class="text-sm font-semibold text-gray-700 mb-2">Found {{ duplicateSearchResults.length }} matching record(s):</h4>
                  <div class="space-y-2 max-h-60 overflow-y-auto">
                    <div v-for="result in duplicateSearchResults" :key="result.student_id" class="bg-gray-50 p-3 rounded-lg border border-gray-200">
                      <div class="flex items-center gap-3">
                        <div class="w-10 h-10 rounded-full bg-gradient-to-r from-ssaam-dark to-ssaam-light flex items-center justify-center text-white text-sm font-bold overflow-hidden">
                          <img v-if="result.photo" :src="result.photo" class="w-full h-full object-cover rounded-full" />
                          <span v-else>{{ (result.first_name || '?').charAt(0) }}</span>
                        </div>
                        <div class="flex-1 min-w-0">
                          <p class="font-medium text-gray-900 truncate">{{ result.first_name }} {{ result.last_name }}</p>
                          <p class="text-xs text-gray-500">ID: {{ result.student_id }} | {{ result.program }} - {{ result.year_level }}</p>
                          <p class="text-xs text-gray-500">Email: {{ result.email }}</p>
                          <p v-if="result.rfid_code" class="text-xs text-blue-600">RFID: {{ result.rfid_code }}</p>
                        </div>
                        <div class="flex flex-col items-end gap-1">
                          <span :class="['text-xs px-2 py-1 rounded-full', result.match_type === 'rfid' ? 'bg-orange-100 text-orange-700' : result.match_type === 'email' ? 'bg-blue-100 text-blue-700' : result.match_type === 'id' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700']">
                            {{ result.match_type === 'rfid' ? 'RFID Match' : result.match_type === 'email' ? 'Email Match' : result.match_type === 'id' ? 'ID Match' : 'Name Match' }}
                          </span>
                          <span v-if="result.is_duplicate" class="text-xs px-2 py-1 rounded-full bg-red-100 text-red-700 font-semibold">
                            DUPLICATE!
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
                
                <div v-else-if="duplicateSearchPerformed && duplicateSearchResults.length === 0" class="mt-4 text-center py-4">
                  <svg class="w-12 h-12 mx-auto text-green-500 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                  <p class="text-green-700 font-medium">No duplicates found!</p>
                  <p class="text-sm text-gray-500">The searched value is unique in the database.</p>
                </div>
              </div>
            </div>

            <!-- Database Migration Section -->
            <div class="border border-indigo-200 rounded-xl p-6 bg-indigo-50">
              <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
                <div>
                  <h3 class="text-lg font-semibold text-indigo-900 flex items-center gap-2">
                    <svg class="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M9 19l3 3m0 0l3-3m-3 3v-6"></path></svg>
                    Database Migration
                  </h3>
                  <p class="text-sm text-indigo-700 mt-1">Copy all data to another MongoDB instance</p>
                </div>
              </div>
              <div class="bg-white rounded-lg p-4 border border-indigo-200 space-y-4">
                <div>
                  <label class="block text-sm font-medium text-gray-700 mb-2">Destination MongoDB URI</label>
                  <input 
                    v-model="migrationDestinationUri"
                    type="text"
                    placeholder="mongodb+srv://user:password@cluster.mongodb.net/?appName=..."
                    class="w-full px-4 py-2 bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 outline-none transition-all font-mono text-xs"
                  />
                  <p class="text-xs text-gray-500 mt-1">Must be different from the current database URI</p>
                </div>
                <div class="bg-indigo-50 rounded p-3 border border-indigo-200">
                  <p class="text-xs text-indigo-700"><strong>Note:</strong> This will copy ALL collections from the current database to the destination. The destination collections will be cleared first.</p>
                </div>
                <button 
                  @click="migrateDatabaseConfirm" 
                  :disabled="migratingDatabase || !migrationDestinationUri.trim()"
                  class="w-full bg-gradient-to-r from-indigo-600 to-indigo-700 text-white px-6 py-3 rounded-lg font-medium hover:from-indigo-700 hover:to-indigo-800 transition flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <svg v-if="migratingDatabase" class="w-4 h-4 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                  <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M9 19l3 3m0 0l3-3m-3 3v-6"></path></svg>
                  {{ migratingDatabase ? 'Migrating...' : 'Start Migration' }}
                </button>
              </div>
            </div>

            <!-- Clean Up Unused Fields Section -->
            <div class="border border-orange-200 rounded-xl p-6 bg-orange-50">
              <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
                <div>
                  <h3 class="text-lg font-semibold text-orange-900 flex items-center gap-2">
                    <svg class="w-5 h-5 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                    Clean Up Unused Fields
                  </h3>
                  <p class="text-sm text-orange-700 mt-1">Remove unused fields and free up database storage</p>
                </div>
              </div>
              <div class="bg-white rounded-lg p-4 border border-orange-200 space-y-4">
                <div class="bg-orange-50 rounded p-3 border border-orange-200">
                  <p class="text-xs text-orange-700"><strong>⚠️ Warning:</strong> This will permanently remove contributions, semester, full_name, and school_year fields from all student records. Student data (ID, name parts, program, etc.) will remain intact. This action cannot be undone.</p>
                </div>
                <button 
                  @click="cleanupUnusedFieldsConfirm" 
                  :disabled="cleaningUpFields"
                  class="w-full bg-gradient-to-r from-orange-600 to-orange-700 text-white px-6 py-3 rounded-lg font-medium hover:from-orange-700 hover:to-orange-800 transition flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <svg v-if="cleaningUpFields" class="w-4 h-4 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                  <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                  {{ cleaningUpFields ? 'Cleaning up...' : 'Start Cleanup' }}
                </button>
              </div>
            </div>



            <!-- Clear Session Tokens Section -->
            <div class="border border-red-200 rounded-xl p-6 bg-red-50">
              <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
                <div>
                  <h3 class="text-lg font-semibold text-red-900 flex items-center gap-2">
                    <svg class="w-5 h-5 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                    Clear All Session Tokens
                  </h3>
                  <p class="text-sm text-red-700 mt-1">Force logout all users from the system (except your current session)</p>
                </div>
                <button 
                  @click="showClearSessionsConfirm = true" 
                  :disabled="clearingSessionTokens"
                  class="bg-red-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-red-700 transition-all duration-200 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed whitespace-nowrap"
                >
                  <svg v-if="clearingSessionTokens" class="w-4 h-4 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                  <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                  {{ clearingSessionTokens ? 'Clearing...' : 'Clear All Sessions' }}
                </button>
              </div>
              <div class="bg-white rounded-lg p-3 border border-red-200">
                <p class="text-xs text-red-600"><strong>Warning:</strong> This action will log out all users from the system immediately. They will need to log in again. Your current session will remain active.</p>
              </div>
            </div>

            <!-- Face ID 3rd Verification Enrollment -->
            <FaceRecognitionSettings />

            <!-- Save Button -->
            <div class="flex justify-end pt-4">
              <button 
                @click="saveSettings" 
                :disabled="settingsSaving"
                :class="['px-8 py-3 rounded-lg font-medium transition-all duration-300 flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed text-white bg-gradient-to-r', primaryButtonGradient, primaryButtonHover]"
              >
                <svg v-if="settingsSaving" class="w-5 h-5 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                <svg v-else class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg>
                {{ settingsSaving ? 'Saving...' : 'Save Settings' }}
              </button>
            </div>
          </div>
          </div>
        </div>

        <!-- Attendance Page -->

        <!-- Transparency Board Page (Admin View) -->
        <div v-if="currentPage === 'transparency' && (currentUser.role === 'admin' || currentUser.role === 'administrator' || currentUser.isMaster)" class="bg-white rounded-lg shadow-lg p-4 md:p-8">
          <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
            <div>
              <h2 class="text-2xl font-bold text-blue-900">Transparency Board</h2>
              <p class="text-sm text-gray-500">View all students who have fulfilled their contributions.</p>
            </div>
            <button @click="fetchTransparencyBoard" :disabled="transparencyLoading" class="px-4 py-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200 transition flex items-center gap-2">
              <svg :class="['w-4 h-4', transparencyLoading ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
              Refresh Board
            </button>
          </div>

          <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            <div v-for="student in transparencyList" :key="student.name" class="bg-gray-50 rounded-2xl p-6 border border-gray-100 hover:border-blue-200 transition-all shadow-sm">
              <div class="flex items-center gap-4 mb-4">
                <div class="w-12 h-12 rounded-full bg-gradient-to-br from-ssaam-dark to-ssaam-light flex items-center justify-center text-white font-bold">
                  {{ getInitials(student.name) }}
                </div>
                <div>
                  <p class="font-bold text-gray-900 leading-tight">{{ student.name }}</p>
                  <p class="text-xs text-blue-600 font-medium">{{ student.program }} | {{ student.year_level }}</p>
                </div>
              </div>
              <div class="space-y-3">
                <div v-for="payment in student.payments" :key="payment.date" class="bg-white rounded-xl p-3 border border-gray-100">
                  <div class="flex justify-between items-start">
                    <p class="text-xs font-bold text-gray-400 uppercase tracking-wider">{{ new Date(payment.date).toLocaleDateString() }}</p>
                    <span class="text-sm font-black text-green-600">₱{{ payment.amount.toFixed(2) }}</span>
                  </div>
                  <p class="text-sm text-gray-700 mt-1 line-clamp-1">{{ payment.description }}</p>
                </div>
              </div>
            </div>
          </div>

          <div v-if="transparencyList.length === 0 && !transparencyLoading" class="text-center py-20">
            <div class="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg class="w-10 h-10 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
            </div>
            <p class="text-gray-500">No payment records found yet.</p>
          </div>
        </div>

        <div v-if="currentPage === 'attendance'" class="space-y-6">
          <!-- Admin Attendance Management -->
          <div v-if="isAdminLike && inRoleView" class="relative bg-white rounded-3xl shadow-xl border border-gray-100 overflow-visible">
            <div :class="['relative h-24 sm:h-28 overflow-hidden rounded-t-3xl', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
              <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
              <div class="light-sweep"></div>
              <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
                <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white/20 flex items-center justify-center flex-shrink-0">
                  <svg class="w-5 h-5 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
                </div>
                <div class="flex-1 min-w-0">
                  <h2 class="text-lg sm:text-xl font-extrabold text-white tracking-tight">Attendance Events</h2>
                  <p class="text-white/70 text-xs sm:text-sm mt-0.5">Manage events, sessions, and RFID scanner</p>
                </div>
              </div>
              <!-- Info button sits inside the hero visually, but tooltip escapes via outer overflow-visible -->
              <div class="absolute top-3 right-3 group z-10">
                <button class="w-8 h-8 rounded-full bg-white/20 hover:bg-white/30 flex items-center justify-center transition-all" title="About Attendance Events">
                  <svg class="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clip-rule="evenodd"></path></svg>
                </button>
              </div>
            </div>
            <!-- Tooltip rendered OUTSIDE the overflow-hidden hero, anchored top-right of card -->
            <div class="absolute top-3 right-3 group z-50 pointer-events-none">
              <div class="w-8 h-8 pointer-events-auto"></div>
              <div :class="['invisible group-hover:visible absolute right-0 top-full mt-1 w-64 p-3 rounded-xl shadow-xl border text-xs space-y-2 pointer-events-none', isCOE ? 'bg-orange-50 border-orange-200 text-orange-900' : isSOM ? 'bg-green-50 border-green-200 text-green-900' : isCNAHS ? 'bg-emerald-50 border-emerald-200 text-emerald-900' : 'bg-blue-50 border-blue-200 text-blue-900']">
                <div class="font-bold flex items-center gap-1">
                  <svg class="w-4 h-4 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zM8 7a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zM14 4a1 1 0 011-1h2a1 1 0 011 1v12a1 1 0 01-1 1h-2a1 1 0 01-1-1V4z"></path></svg>
                  Attendance Events
                </div>
                <p>Browse active and upcoming events. Click an event to view and manage its sessions.</p>
                <div class="pt-2 border-t" :class="isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : isCNAHS ? 'border-emerald-200' : 'border-blue-200'">
                  <p class="font-semibold mb-1">What you can do:</p>
                  <ul class="space-y-1">
                    <li class="flex gap-1"><span class="font-bold">✓</span><span>Auto-select session (1 active) or choose manually</span></li>
                    <li class="flex gap-1"><span class="font-bold">✓</span><span>View session details and times</span></li>
                    <li class="flex gap-1"><span class="font-bold">✓</span><span>Manage attendance with RFID Scanner</span></li>
                  </ul>
                </div>
              </div>
            </div>
            <div class="p-3 sm:p-4 md:p-6 flex flex-col gap-3">
              <h2 class="sr-only">Attendance Events</h2>
              <!-- Action buttons row -->
              <div class="flex gap-2">
                <button @click="refreshAttendanceSection" :disabled="attendanceLoading" :class="['flex-1 px-4 py-2.5 rounded-xl transition flex items-center justify-center gap-2 text-sm font-semibold disabled:opacity-70 text-white bg-gradient-to-r', primaryButtonGradient, primaryButtonHover]" title="Refresh">
                  <svg :class="['w-4 h-4', attendanceLoading ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                  <span>Refresh</span>
                </button>
                <button @click="openCreateEventModal" :class="['flex-1 px-3 py-2.5 rounded-xl transition flex items-center justify-center gap-2 text-sm font-semibold text-white bg-gradient-to-r', primaryButtonGradient, primaryButtonHover]" title="Create Event">
                  <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"></path></svg>
                  <span>Create Event</span>
                </button>
              </div>
              <!-- Tab switcher -->
              <div class="flex gap-2">
                <button @click="attendanceTab = 'events'" :class="['flex-1 px-4 py-2 rounded-xl text-sm font-semibold transition whitespace-nowrap', attendanceTab === 'events' ? ['bg-gradient-to-r', primaryButtonGradient, 'text-white shadow-md'] : 'bg-gray-100 text-gray-600 hover:bg-gray-200']">Events</button>
                <button @click="switchToScannerTab" :class="['flex-1 px-4 py-2 rounded-xl text-sm font-semibold transition whitespace-nowrap', attendanceTab === 'scanner' ? ['bg-gradient-to-r', primaryButtonGradient, 'text-white shadow-md'] : 'bg-gray-100 text-gray-600 hover:bg-gray-200']">Scanner</button>
              </div>
            </div>

            <!-- Events List Tab -->
            <div v-if="attendanceTab === 'events'" class="px-3 sm:px-4 md:px-6 pb-4 sm:pb-6 space-y-3">
              <!-- Search + Compact Pagination Row -->
              <div class="space-y-2.5">
                <!-- Search Input -->
                <div class="relative">
                  <svg class="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                  <input
                    v-model="attendanceSearchQuery"
                    type="text"
                    placeholder="Search events by title..."
                    :class="['w-full pl-9 pr-4 py-2.5 rounded-xl border-2 bg-gray-50 focus:bg-white transition-all outline-none text-sm', isCOE ? 'border-gray-200 focus:border-orange-400 focus:ring-2 focus:ring-orange-100' : isSOM ? 'border-gray-200 focus:border-green-400 focus:ring-2 focus:ring-green-100' : isCNAHS ? 'border-gray-200 focus:border-emerald-400 focus:ring-2 focus:ring-emerald-100' : 'border-gray-200 focus:border-blue-400 focus:ring-2 focus:ring-blue-100']"
                  />
                </div>
                <!-- Count + Pagination inline -->
                <div class="flex items-center justify-between gap-2">
                  <span :class="['text-xs font-semibold', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-emerald-600' : 'text-blue-600']">
                    {{ filteredAttendanceEvents.length }} of {{ attendanceEvents.length }} events
                    <span v-if="attendanceTotalPages > 1" class="text-gray-400 font-normal"> · Page {{ attendanceCurrentPage }}/{{ attendanceTotalPages }}</span>
                  </span>
                  <div class="flex gap-1.5">
                    <button
                      @click="prevAttendancePage"
                      :disabled="attendanceCurrentPage === 1"
                      :class="['px-3 py-1.5 rounded-lg font-semibold transition-all text-xs flex items-center gap-1', attendanceCurrentPage === 1 ? 'opacity-40 cursor-not-allowed bg-gray-100 text-gray-500' : isCOE ? 'bg-orange-100 text-orange-700 hover:bg-orange-200 active:scale-95' : isSOM ? 'bg-green-100 text-green-700 hover:bg-green-200 active:scale-95' : isCNAHS ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200 active:scale-95' : 'bg-blue-100 text-blue-700 hover:bg-blue-200 active:scale-95']"
                    >
                      <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
                      Prev
                    </button>
                    <button
                      @click="nextAttendancePage"
                      :disabled="attendanceCurrentPage === attendanceTotalPages"
                      :class="['px-3 py-1.5 rounded-lg font-semibold transition-all text-xs flex items-center gap-1', attendanceCurrentPage === attendanceTotalPages ? 'opacity-40 cursor-not-allowed bg-gray-100 text-gray-500' : isCOE ? 'bg-orange-600 text-white hover:bg-orange-700 active:scale-95' : isSOM ? 'bg-green-600 text-white hover:bg-green-700 active:scale-95' : isCNAHS ? 'bg-emerald-600 text-white hover:bg-emerald-700 active:scale-95' : 'bg-blue-600 text-white hover:bg-blue-700 active:scale-95']"
                    >
                      Next
                      <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
                    </button>
                  </div>
                </div>
              </div>

              <!-- Loading -->
              <div v-if="attendanceLoading" class="flex items-center justify-center py-12">
                <svg :class="['animate-spin h-8 w-8', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : isCNAHS ? 'text-emerald-500' : 'text-blue-500']" fill="none" viewBox="0 0 24 24">
                  <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                  <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              </div>

              <!-- Empty -->
              <div v-else-if="paginatedAttendanceEvents.length === 0" class="flex flex-col items-center justify-center py-14 text-center">
                <img src="/events.svg" alt="No Events" class="w-14 h-14 mb-3 opacity-30" />
                <p class="text-gray-500 text-sm font-medium">{{ attendanceSearchQuery ? 'No events match your search.' : 'No attendance events yet.' }}</p>
                <p v-if="!attendanceSearchQuery" class="text-gray-400 text-xs mt-1">Click "Create Event" above to get started.</p>
              </div>

              <!-- Event Cards -->
              <transition-group v-else name="event-slide-in" tag="div" class="space-y-2.5 relative" appear>
                <div v-for="event in paginatedAttendanceEvents" :key="event._id" :class="['bg-white rounded-2xl border overflow-hidden shadow-sm hover:shadow-md transition-shadow', isCOE ? 'border-orange-100' : isSOM ? 'border-green-100' : isCNAHS ? 'border-emerald-100' : 'border-blue-100']">
                  <!-- Clickable Header -->
                  <div class="p-3 sm:p-4 cursor-pointer select-none" @click="toggleEventExpansion(event._id)">
                    <!-- Title row -->
                    <div class="flex items-start gap-2 mb-2">
                      <svg :class="['w-4 h-4 mt-0.5 transition-transform flex-shrink-0', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : isCNAHS ? 'text-emerald-500' : 'text-blue-500', expandedEvents[event._id] ? 'rotate-90' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"></path></svg>
                      <div class="flex-1 min-w-0">
                        <h3 :class="['font-bold text-sm sm:text-base leading-snug', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-emerald-900' : 'text-blue-900']">{{ event.title }}</h3>
                        <p v-if="event.description" class="text-gray-500 text-xs mt-0.5 leading-relaxed line-clamp-2">{{ event.description }}</p>
                      </div>
                    </div>
                    <!-- Badges row -->
                    <div class="flex flex-wrap gap-1.5 mb-2.5 pl-6">
                      <span :class="['px-2 py-0.5 rounded-full text-[11px] font-semibold whitespace-nowrap', getStatusBadgeClass(getEventDisplayStatus(event).status)]">{{ getEventDisplayStatus(event).label }}</span>
                      <span v-if="event.status === 'active' && getEventTimeRemaining(event._id) && getEventTimeRemaining(event._id) !== 'Ended'" class="px-2 py-0.5 rounded-full text-[11px] font-semibold whitespace-nowrap bg-orange-100 text-orange-700">
                        {{ getEventTimeRemaining(event._id) }}
                      </span>
                    </div>
                    <!-- Meta chips -->
                    <div class="flex flex-wrap gap-1.5 pl-6">
                      <span class="inline-flex items-center gap-1 px-2 py-1 bg-gray-50 rounded-lg text-[11px] text-gray-600 font-medium">
                        <svg class="w-3 h-3 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>
                        {{ formatEventDate(event.date || event.event_date) }}
                      </span>
                      <span class="inline-flex items-center gap-1 px-2 py-1 bg-gray-50 rounded-lg text-[11px] text-gray-600 font-medium">
                        <svg class="w-3 h-3 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                        {{ formatEventTime(event.start_time || event.startTime || '07:00') }} – {{ formatEventTime(event.end_time || event.endTime || '17:00') }}
                      </span>
                      <span v-if="event.location" class="inline-flex items-center gap-1 px-2 py-1 bg-gray-50 rounded-lg text-[11px] text-gray-600 font-medium">
                        <svg class="w-3 h-3 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                        {{ event.location }}
                      </span>
                    </div>
                  </div>

                  <!-- Action buttons row — stop propagation so click doesn't toggle expand -->
                  <div :class="['flex items-center gap-1.5 px-3 sm:px-4 py-2.5 border-t', isCOE ? 'border-orange-50 bg-orange-50/40' : isSOM ? 'border-green-50 bg-green-50/40' : isCNAHS ? 'border-emerald-50 bg-emerald-50/40' : 'border-blue-50 bg-blue-50/40']" @click.stop>
                    <button @click="duplicateEvent(event)" class="flex-1 flex items-center justify-center gap-1.5 py-2 px-2 rounded-xl bg-blue-50 text-blue-700 hover:bg-blue-100 active:scale-95 transition text-xs font-semibold" title="Duplicate">
                      <svg class="w-3.5 h-3.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"></path></svg>
                      <span>Duplicate</span>
                    </button>
                    <button @click="openEditEvent(event)" class="flex-1 flex items-center justify-center gap-1.5 py-2 px-2 rounded-xl bg-amber-50 text-amber-700 hover:bg-amber-100 active:scale-95 transition text-xs font-semibold" title="Edit">
                      <svg class="w-3.5 h-3.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg>
                      <span>Edit</span>
                    </button>
                    <button @click="requestDeleteEvent(event)" class="flex-1 flex items-center justify-center gap-1.5 py-2 px-2 rounded-xl bg-red-50 text-red-600 hover:bg-red-100 active:scale-95 transition text-xs font-semibold" title="Delete">
                      <svg class="w-3.5 h-3.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                      <span>Delete</span>
                    </button>
                  </div>

                  <!-- Sessions Panel - Expandable -->
                  <transition name="slide-down">
                    <div v-if="expandedEvents[event._id]" :class="['border-t px-3 sm:px-4 py-3', isCOE ? 'bg-orange-50/60 border-orange-100' : isSOM ? 'bg-green-50/60 border-green-100' : isCNAHS ? 'bg-emerald-50/60 border-emerald-100' : 'bg-blue-50/60 border-blue-100']">
                      <h4 :class="['text-xs font-bold uppercase tracking-wider mb-2.5 flex items-center gap-1.5', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-emerald-600' : 'text-blue-600']">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"></path></svg>
                        Sessions
                      </h4>
                      <div v-if="!expandedEventSessions[event._id] || expandedEventSessions[event._id].length === 0" class="text-xs text-gray-500 py-2 italic">
                        No sessions added yet — click Edit to add sessions.
                      </div>
                      <div v-else class="space-y-2">
                        <div v-for="session in expandedEventSessions[event._id]" :key="session._id" @click="selectSession(session, event, $event)" class="bg-white rounded-xl px-3 py-2.5 border border-gray-200 cursor-pointer hover:shadow-sm active:scale-[0.99] transition flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                          <div class="flex flex-wrap items-center gap-1.5">
                            <span class="font-semibold text-gray-800 text-sm">{{ session.label }}</span>
                            <span class="text-xs text-gray-400 font-medium">{{ formatEventTime(session.start_time) }} – {{ formatEventTime(session.end_time) }}</span>
                            <span :class="['px-2 py-0.5 rounded-full text-[11px] font-semibold', getSessionDisplayStatus(session, event) === 'active' ? 'bg-green-100 text-green-700' : getSessionDisplayStatus(session, event) === 'draft' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-500']">
                              {{ getSessionDisplayStatus(session, event) === 'active' ? 'Active' : getSessionDisplayStatus(session, event) === 'draft' ? 'Upcoming' : 'Closed' }}
                            </span>
                            <span v-if="session.check_in_locked" class="text-[10px] text-red-500 font-medium">Check-in locked</span>
                            <span v-if="session.check_out_locked" class="text-[10px] text-red-500 font-medium">Check-out locked</span>
                          </div>
                          <button @click.stop="openSessionLogs(session, event)" :class="['flex-shrink-0 flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold transition', isCOE ? 'bg-orange-100 text-orange-700 hover:bg-orange-200' : isSOM ? 'bg-green-100 text-green-700 hover:bg-green-200' : isCNAHS ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200' : 'bg-blue-100 text-blue-700 hover:bg-blue-200']">
                            <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
                            Logs
                          </button>
                        </div>
                      </div>
                    </div>
                  </transition>
                </div>
              </transition-group>

              <!-- Bottom Pagination -->
              <div v-if="attendanceTotalPages > 1" class="flex items-center justify-between gap-2 pt-2 border-t border-gray-100">
                <span :class="['text-xs font-semibold', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-emerald-600' : 'text-blue-600']">
                  Page {{ attendanceCurrentPage }} of {{ attendanceTotalPages }}
                </span>
                <div class="flex gap-2">
                  <button
                    @click="prevAttendancePage"
                    :disabled="attendanceCurrentPage === 1"
                    :class="['px-4 py-2 rounded-xl font-semibold transition-all text-xs', attendanceCurrentPage === 1 ? 'opacity-40 cursor-not-allowed bg-gray-100 text-gray-500' : isCOE ? 'bg-orange-600 text-white hover:bg-orange-700 active:scale-95' : isSOM ? 'bg-green-600 text-white hover:bg-green-700 active:scale-95' : isCNAHS ? 'bg-emerald-600 text-white hover:bg-emerald-700 active:scale-95' : 'bg-blue-600 text-white hover:bg-blue-700 active:scale-95']"
                  >← Previous</button>
                  <button
                    @click="nextAttendancePage"
                    :disabled="attendanceCurrentPage === attendanceTotalPages"
                    :class="['px-4 py-2 rounded-xl font-semibold transition-all text-xs', attendanceCurrentPage === attendanceTotalPages ? 'opacity-40 cursor-not-allowed bg-gray-100 text-gray-500' : isCOE ? 'bg-orange-600 text-white hover:bg-orange-700 active:scale-95' : isSOM ? 'bg-green-600 text-white hover:bg-green-700 active:scale-95' : isCNAHS ? 'bg-emerald-600 text-white hover:bg-emerald-700 active:scale-95' : 'bg-blue-600 text-white hover:bg-blue-700 active:scale-95']"
                  >Next →</button>
                </div>
              </div>
            </div>

            <!-- RFID Scanner Tab -->
            <div v-if="attendanceTab === 'scanner'" class="px-3 sm:px-4 md:px-6 pb-4 sm:pb-6 space-y-3">
              <!-- RFID Scanner Lock Controls -->
              <div v-if="selectedEvent || selectedSession" :class="['bg-gradient-to-r border rounded-xl p-3 sm:p-4', isCOE ? 'from-orange-50 to-red-50 border-orange-200' : isSOM ? 'from-green-50 to-teal-50 border-green-200' : isCNAHS ? 'from-green-50 to-teal-50 border-green-200' : 'from-blue-50 to-blue-50 border-blue-200']">
                <h3 :class="['font-semibold mb-3 sm:mb-4 flex items-center gap-2 text-sm sm:text-base', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">
                  <svg class="w-4 h-4 sm:w-5 sm:h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
                  Attendance Mode (Select One)
                </h3>
                
                <!-- Active Mode Indicator -->
                <div class="mb-4 p-3 rounded-lg" :class="[
                  effectiveRfid.checkInEnabled ? 'bg-green-100 border border-green-300' :
                  effectiveRfid.checkOutEnabled ? 'bg-blue-100 border border-blue-300' :
                  'bg-gray-100 border border-gray-300'
                ]">
                  <div class="flex items-center gap-2">
                    <svg v-if="effectiveRfid.checkInEnabled" class="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1"></path></svg>
                    <svg v-else-if="effectiveRfid.checkOutEnabled" class="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
                    <svg v-else class="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636m12.728 12.728L5.636 5.636"></path></svg>
                    <span class="font-semibold" :class="[
                       effectiveRfid.checkInEnabled ? 'text-green-700' :
                       effectiveRfid.checkOutEnabled ? 'text-blue-700' :
                      'text-gray-600'
                    ]">
                       {{ effectiveRfid.checkInEnabled ? 'CHECK-IN MODE ACTIVE' : 
                         effectiveRfid.checkOutEnabled ? 'CHECK-OUT MODE ACTIVE' : 
                         'NO MODE SELECTED - SCANNING DISABLED' }}
                    </span>
                  </div>
                  <p class="text-xs mt-1" :class="[
                    effectiveRfid.checkInEnabled ? 'text-green-600' :
                    effectiveRfid.checkOutEnabled ? 'text-blue-600' :
                    'text-gray-500'
                  ]">
                    {{ effectiveRfid.checkInEnabled ? 'Students will be marked as checked in when scanning. Late threshold applies.' : 
                       effectiveRfid.checkOutEnabled ? 'Students will be marked as checked out when scanning.' : 
                       'Select a mode below to enable RFID scanning.' }}
                  </p>
                </div>
                
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
                  <!-- Check-In Control -->
                  <div :class="['rounded-lg p-4 shadow-sm transition-all', effectiveRfid.checkInEnabled ? 'bg-green-50 ring-2 ring-green-400' : 'bg-white']">
                    <div class="flex items-center justify-between mb-3">
                      <span class="font-medium text-gray-700 flex items-center gap-2">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1"></path></svg>
                        Check-In
                      </span>
                      <button 
                        @click="toggleCheckIn" 
                        :disabled="rfidScannerSaving || checkToggleCooldown || (!selectedEvent && !selectedSession)"
                        :class="['relative inline-flex h-8 w-14 items-center rounded-full transition-colors duration-300', effectiveRfid.checkInEnabled ? 'bg-green-500' : 'bg-gray-300']"
                      >
                        <span :class="['inline-block h-6 w-6 transform rounded-full bg-white shadow-lg transition-transform duration-300', effectiveRfid.checkInEnabled ? 'translate-x-7' : 'translate-x-1']"></span>
                      </button>
                    </div>
                    <span :class="['text-sm font-medium px-3 py-1 rounded-full', effectiveRfid.checkInEnabled ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700']">
                      {{ effectiveRfid.checkInEnabled ? 'Active' : 'Inactive' }}
                    </span>
                  </div>
                  
                  <!-- Check-Out Control -->
                  <div :class="['rounded-lg p-4 shadow-sm transition-all', effectiveRfid.checkOutEnabled ? 'bg-blue-50 ring-2 ring-blue-400' : 'bg-white']">
                    <div class="flex items-center justify-between mb-3">
                      <span class="font-medium text-gray-700 flex items-center gap-2">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
                        Check-Out
                      </span>
                      <button 
                        @click="toggleCheckOut" 
                        :disabled="rfidScannerSaving || checkToggleCooldown || (!selectedEvent && !selectedSession)"
                        :class="['relative inline-flex h-8 w-14 items-center rounded-full transition-colors duration-300', effectiveRfid.checkOutEnabled ? 'bg-blue-500' : 'bg-gray-300']"
                      >
                        <span :class="['inline-block h-6 w-6 transform rounded-full bg-white shadow-lg transition-transform duration-300', effectiveRfid.checkOutEnabled ? 'translate-x-7' : 'translate-x-1']"></span>
                      </button>
                    </div>
                    <span :class="['text-sm font-medium px-3 py-1 rounded-full', effectiveRfid.checkOutEnabled ? 'bg-blue-100 text-blue-700' : 'bg-red-100 text-red-700']">
                      {{ effectiveRfid.checkOutEnabled ? 'Active' : 'Inactive' }}
                    </span>
                  </div>
                </div>
                
                <!-- Auto-switch notice & cooldown UI -->
                <div class="mt-4">
                  <p v-if="lastAutoSwitchedFromCheckIn" class="text-sm text-blue-800 bg-blue-50 border border-blue-100 px-3 py-2 rounded-lg">Check-In was turned off — automatically switched to Check-Out.</p>
                  <p v-if="checkToggleCooldown" class="text-xs text-gray-500 mt-2">Switch cooldown: {{ cooldownSeconds }}s</p>
                </div>
                
                <p class="text-xs text-gray-500 mt-3 text-center">⚙️ Settings apply only to the selected event/session. Select an event or session to configure.</p>
              </div>

              <!-- Step 1: No event selected -->
              <div v-if="!selectedEvent" :class="['rounded-2xl border-2 border-dashed p-6 flex flex-col items-center gap-4', isCOE ? 'border-orange-200 bg-orange-50/40' : isSOM ? 'border-green-200 bg-green-50/40' : isCNAHS ? 'border-emerald-200 bg-emerald-50/40' : 'border-blue-200 bg-blue-50/40']">
                <!-- Icon -->
                <div :class="['w-14 h-14 rounded-2xl flex items-center justify-center', isCOE ? 'bg-orange-100' : isSOM ? 'bg-green-100' : isCNAHS ? 'bg-emerald-100' : 'bg-blue-100']">
                  <svg :class="['w-7 h-7', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : isCNAHS ? 'text-emerald-500' : 'text-blue-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 4h4v4H3V4zm0 8h4v4H3v-4zm0 8h4v4H3v-4zm8-16h4v4h-4V4zm0 8h4v4h-4v-4zm0 8h4v4h-4v-4zm8-16h4v4h-4V4zm0 8h4v4h-4v-4zm0 8h4v4h-4v-4z"></path></svg>
                </div>
                <!-- Label -->
                <div class="text-center">
                  <p :class="['font-bold text-sm', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-emerald-800' : 'text-blue-800']">Select an Event</p>
                  <p class="text-gray-500 text-xs mt-0.5">Choose an active event to start scanning RFID cards</p>
                </div>
                <!-- Dropdown -->
                <div class="w-full relative">
                  <select v-model="selectedEvent" @change="onEventSelectForScanner" :class="['w-full px-4 py-3 pr-10 border-2 rounded-xl bg-white focus:ring-2 outline-none text-sm font-medium appearance-none cursor-pointer', isCOE ? 'border-orange-200 focus:border-orange-400 focus:ring-orange-100 text-orange-900' : isSOM ? 'border-green-200 focus:border-green-400 focus:ring-green-100 text-green-900' : isCNAHS ? 'border-emerald-200 focus:border-emerald-400 focus:ring-emerald-100 text-emerald-900' : 'border-blue-200 focus:border-blue-400 focus:ring-blue-100 text-blue-900']">
                    <option :value="null">-- Select Event --</option>
                    <option v-for="event in attendanceEvents.filter(e => getEventDisplayStatus(e).status === 'active')" :key="event._id" :value="event">{{ event.title }} ({{ formatEventDate(event.date || event.event_date) }})</option>
                  </select>
                  <!-- Custom chevron -->
                  <svg class="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M19 9l-7 7-7-7"/></svg>
                </div>
              </div>

              <!-- Step 2: Event selected, no session yet -->
              <div v-else-if="!selectedSession" :class="['rounded-2xl border overflow-hidden', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : isCNAHS ? 'border-emerald-200' : 'border-blue-200']">
                <!-- Event summary header -->
                <div :class="['px-4 py-3 flex items-start justify-between gap-3', isCOE ? 'bg-orange-50' : isSOM ? 'bg-green-50' : isCNAHS ? 'bg-emerald-50' : 'bg-blue-50']">
                  <div class="min-w-0">
                    <p class="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-0.5">Event selected</p>
                    <p :class="['font-bold text-sm truncate', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-emerald-900' : 'text-blue-900']">{{ selectedEvent.title }}</p>
                    <p class="text-xs text-gray-500 mt-0.5">{{ formatEventDate(selectedEvent.date || selectedEvent.event_date) }}</p>
                  </div>
                  <button @click="selectedEvent = null; selectedSession = null" :class="['flex-shrink-0 p-1.5 rounded-lg transition mt-0.5', isCOE ? 'text-orange-400 hover:text-orange-700 hover:bg-orange-100' : isSOM ? 'text-green-400 hover:text-green-700 hover:bg-green-100' : isCNAHS ? 'text-emerald-400 hover:text-emerald-700 hover:bg-emerald-100' : 'text-blue-400 hover:text-blue-700 hover:bg-blue-100']" title="Change event">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
                  </button>
                </div>
                <!-- Sessions body -->
                <div class="px-4 py-4 bg-white space-y-2">
                  <p class="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3">Pick a Session</p>
                  <!-- Loading -->
                  <div v-if="sessionsLoading" class="flex flex-col items-center gap-3 py-6">
                    <svg :class="['animate-spin h-6 w-6', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : isCNAHS ? 'text-emerald-500' : 'text-blue-500']" fill="none" viewBox="0 0 24 24">
                      <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                      <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
                    </svg>
                    <span class="text-sm text-gray-500 font-medium">Loading sessions…</span>
                    <div class="w-full bg-gray-200 rounded-full h-1.5 overflow-hidden">
                      <div :class="['h-1.5 rounded-full animate-pulse bg-gradient-to-r', isCOE ? 'from-orange-500 to-red-500' : 'from-ssaam-dark to-ssaam-light']" style="width: 70%"></div>
                    </div>
                  </div>
                  <!-- No sessions -->
                  <div v-else-if="eventSessions.length === 0" class="text-center py-6">
                    <p class="text-sm font-semibold text-orange-600 mb-1">No sessions found</p>
                    <p class="text-xs text-gray-500 mb-3">Add sessions to this event from the Events tab first.</p>
                    <button @click="selectedEvent = null; selectedSession = null" :class="['text-xs font-semibold underline', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-emerald-600' : 'text-blue-600']">Choose a different event</button>
                  </div>
                  <!-- Session list -->
                  <button
                    v-else
                    v-for="session in eventSessions.filter(s => getSessionDisplayStatus(s, selectedEvent) === 'active')"
                    :key="session._id"
                    @click="selectedSession = session"
                    :class="['w-full flex items-center justify-between p-3 rounded-xl border-2 transition text-left active:scale-[0.98]', isCOE ? 'border-orange-100 hover:border-orange-300 hover:bg-orange-50' : isSOM ? 'border-green-100 hover:border-green-300 hover:bg-green-50' : isCNAHS ? 'border-emerald-100 hover:border-emerald-300 hover:bg-emerald-50' : 'border-blue-100 hover:border-blue-300 hover:bg-blue-50']"
                  >
                    <div class="min-w-0">
                      <p :class="['font-semibold text-sm', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-emerald-900' : 'text-blue-900']">{{ session.label }}</p>
                      <p class="text-xs text-gray-500 mt-0.5">{{ formatDisplayTime(session.start_time) }} – {{ formatDisplayTime(session.end_time) }}</p>
                    </div>
                    <div class="flex items-center gap-2 flex-shrink-0 ml-3">
                      <span class="px-2 py-0.5 rounded-full text-[11px] font-semibold bg-green-100 text-green-700">Active</span>
                      <svg :class="['w-4 h-4', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : isCNAHS ? 'text-emerald-400' : 'text-blue-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
                    </div>
                  </button>
                  <button v-if="!sessionsLoading && eventSessions.length > 0" @click="selectedEvent = null; selectedSession = null; eventSessions = []" :class="['w-full text-xs font-semibold underline pt-1 text-center', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : isCNAHS ? 'text-emerald-500' : 'text-blue-500']">Choose a different event</button>
                </div>
              </div>
              <div v-else class="space-y-4">
                <div :class="['bg-gradient-to-r border rounded-lg p-3 sm:p-4', isCOE ? 'from-orange-50 to-red-50 border-orange-200' : 'from-blue-50 to-blue-50 border-blue-200']">
                  <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 sm:gap-4">
                    <div class="flex-1 text-left sm:text-left">
                      <h3 :class="['font-semibold text-sm sm:text-base', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">{{ selectedEvent.title }}</h3>
                      <p :class="['text-xs sm:text-sm', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']">{{ formatEventDate(selectedEvent.date || selectedEvent.event_date) }}</p>
                      <div class="flex flex-wrap items-center gap-2 mt-1">
                        <span :class="['px-2 py-0.5 rounded-full text-xs font-medium', isCOE ? 'bg-orange-100 text-orange-700' : isSOM ? 'bg-green-100 text-green-700' : isCNAHS ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700']">{{ selectedSession.label }}</span>
                        <span class="text-xs text-gray-500 truncate">{{ formatDisplayTime(selectedSession.start_time) }} - {{ formatDisplayTime(selectedSession.end_time) }}</span>
                      </div>
                    </div>
                    <div class="flex items-center gap-2 w-full sm:w-auto">
                      <!-- Open the RFID scanner kiosk in fullscreen. -->
                      <button @click="enterFullscreenMode()" title="Open RFID Scanner Fullscreen" :class="['text-white px-3 sm:px-4 py-2 rounded-lg transition flex items-center justify-center gap-2 bg-gradient-to-r flex-1 sm:flex-none text-sm sm:text-base', primaryButtonGradient, primaryButtonHover]">
                        <svg class="w-4 sm:w-5 h-4 sm:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4"></path></svg>
                        <span class="hidden sm:inline">Fullscreen</span>
                      </button>
                      <button @click="selectedEvent = null; selectedSession = null; eventSessions = []" :class="['p-2 rounded-lg transition', isCOE ? 'text-orange-600 hover:text-orange-800 hover:bg-orange-100' : isSOM ? 'text-green-600 hover:text-green-800 hover:bg-green-50' : isCNAHS ? 'text-green-600 hover:text-green-800 hover:bg-green-50' : 'text-blue-600 hover:text-blue-800 hover:bg-blue-100']">
                        <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                      </button>
                    </div>
                  </div>
                </div>

                <!-- ============================================================
                     Geofence pre-verification banner.
                     Shown only when the active event has a geofence. The admin
                     must complete the Location Gate once before the RFID input
                     becomes usable. After that, the gate's cached coords are
                     re-used for every scan (no per-scan GPS prompt).
                     ============================================================ -->
                <div v-if="scannerNeedsLocation" class="rounded-2xl overflow-hidden border-2 shadow-sm"
                     :class="scannerLocationVerified ? 'border-emerald-200' : 'border-amber-300'">
                  <!-- NOT verified — prominent CTA -->
                  <div v-if="!scannerLocationVerified"
                       class="bg-gradient-to-r from-amber-50 to-orange-50 px-4 py-3 sm:px-5 sm:py-4 flex flex-col sm:flex-row sm:items-center gap-3">
                    <div class="flex items-start sm:items-center gap-3 flex-1 min-w-0">
                      <div class="w-10 h-10 rounded-full bg-amber-100 flex items-center justify-center flex-shrink-0">
                        <svg class="w-5 h-5 text-amber-700" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"/>
                          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"/>
                        </svg>
                      </div>
                      <div class="min-w-0">
                        <p class="text-sm font-semibold text-amber-900 leading-tight">Verify your location to start scanning</p>
                        <p class="text-xs text-amber-700/80 mt-0.5 leading-snug">This event is geofenced — we check once, then every RFID scan uses that fix automatically.</p>
                      </div>
                    </div>
                    <button @click="openScannerLocationGate"
                            :class="['px-4 py-2.5 rounded-xl text-white font-semibold text-sm shadow-md flex items-center justify-center gap-2 bg-gradient-to-r flex-shrink-0', primaryButtonGradient, primaryButtonHover]">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"/>
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"/>
                      </svg>
                      <span>Verify Location</span>
                    </button>
                  </div>
                  <!-- Verified — green status with re-verify link -->
                  <div v-else
                       class="bg-gradient-to-r from-emerald-50 to-green-50 px-4 py-3 sm:px-5 sm:py-3 flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3">
                    <div class="flex items-center gap-3 flex-1 min-w-0">
                      <div class="w-9 h-9 rounded-full bg-emerald-100 flex items-center justify-center flex-shrink-0">
                        <svg class="w-5 h-5 text-emerald-700" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/>
                        </svg>
                      </div>
                      <div class="min-w-0">
                        <p class="text-sm font-semibold text-emerald-900 leading-tight">Location verified — scanner unlocked</p>
                        <p class="text-xs text-emerald-700/80 mt-0.5 leading-snug">
                          Cached fix
                          <span v-if="scannerLocationVerified.accuracy != null">(±{{ Math.round(scannerLocationVerified.accuracy) }}m)</span>
                          will be re-used for every scan in this session.
                        </p>
                      </div>
                    </div>
                    <button @click="reverifyScannerLocation"
                            class="text-xs font-semibold text-emerald-700 hover:text-emerald-900 underline underline-offset-2 self-start sm:self-auto flex-shrink-0">
                      Re-verify
                    </button>
                  </div>
                </div>

                <!-- RFID Scanner Card - Redesigned -->
                <div :class="['rounded-2xl overflow-hidden shadow-lg border', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : isCNAHS ? 'border-green-200' : 'border-blue-200']">
                  <!-- Scanner Header -->
                  <div :class="['px-4 py-3 sm:px-6 sm:py-4 flex items-center justify-between bg-gradient-to-r', isCOE ? 'from-orange-600 to-red-700' : isSOM ? 'from-green-600 to-teal-700' : isCNAHS ? 'from-emerald-600 to-green-700' : 'from-ssaam-dark to-ssaam-light']">
                    <div class="flex items-center gap-3">
                      <!-- Animated pulse rings -->
                      <div class="relative w-9 h-9 sm:w-10 sm:h-10 flex items-center justify-center flex-shrink-0">
                        <div class="absolute inset-0 rounded-full border border-white/30 animate-ping"></div>
                        <div class="absolute inset-0 rounded-full border border-white/20 animate-ping" style="animation-delay:0.4s"></div>
                        <div class="w-full h-full rounded-full bg-white/20 flex items-center justify-center">
                          <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M5 3v4M19 3v4M3 9h18M4 21h16a1 1 0 001-1V9H3v11a1 1 0 001 1z"/></svg>
                        </div>
                      </div>
                      <div>
                        <p class="text-white font-bold text-sm sm:text-base leading-tight">RFID Scanner</p>
                        <p class="text-white/70 text-xs">Scan card or enter Student ID</p>
                      </div>
                    </div>
                    <!-- Check-In Only badge or Mode indicator -->
                    <div v-if="selectedSession && selectedSession.check_in_only" class="flex items-center gap-1.5 bg-white/20 rounded-full px-3 py-1.5">
                      <div class="w-1.5 h-1.5 rounded-full bg-blue-200 animate-pulse"></div>
                      <span class="text-white text-xs font-semibold">Check-In Only</span>
                    </div>
                    <div v-else-if="effectiveRfid.checkInEnabled" class="flex items-center gap-1.5 bg-white/20 rounded-full px-3 py-1.5">
                      <div class="w-1.5 h-1.5 rounded-full bg-green-300 animate-pulse"></div>
                      <span class="text-white text-xs font-semibold">Check-In</span>
                    </div>
                    <div v-else-if="effectiveRfid.checkOutEnabled" class="flex items-center gap-1.5 bg-white/20 rounded-full px-3 py-1.5">
                      <div class="w-1.5 h-1.5 rounded-full bg-yellow-300 animate-pulse"></div>
                      <span class="text-white text-xs font-semibold">Check-Out</span>
                    </div>
                  </div>
                  <!-- Scanner Body -->
                  <div class="bg-white px-4 py-5 sm:px-6 sm:py-6">
                    <div class="flex flex-col sm:flex-row gap-3 items-stretch">
                      <div class="flex-1 relative">
                        <input 
                          ref="rfidInputRef"
                          v-model="rfidInput"
                          @input="onRfidInput"
                          @keydown="handleRfidKeydown"
                          type="text"
                          :placeholder="scannerGeoBlocked ? 'Verify your location first to enable scanning' : 'Scan RFID card or type Student ID...'"
                          :class="['w-full pl-10 pr-4 py-3 text-sm sm:text-base border-2 rounded-xl focus:ring-2 outline-none transition-all', scannerGeoBlocked ? 'border-amber-300 bg-amber-50 placeholder-amber-700 focus:border-amber-500 focus:ring-amber-100' : isCOE ? 'border-orange-200 focus:border-orange-500 focus:ring-orange-100' : isSOM ? 'border-green-200 focus:border-green-500 focus:ring-green-100' : isCNAHS ? 'border-green-200 focus:border-green-500 focus:ring-green-100' : 'border-blue-200 focus:border-blue-500 focus:ring-blue-100']"
                          :disabled="rfidProcessing || scannerGeoBlocked"
                        />
                        <svg class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
                      </div>
                      <button 
                        @click="manualRfidSubmit"
                        :disabled="rfidProcessing || !rfidInput.trim() || scannerGeoBlocked"
                        :class="['flex items-center justify-center gap-2 px-5 py-3 text-white rounded-xl font-semibold text-sm transition-all disabled:opacity-50 disabled:cursor-not-allowed bg-gradient-to-r active:scale-95 hover:scale-[1.02] shadow-md', primaryButtonGradient, primaryButtonHover]"
                      >
                        <svg v-if="rfidProcessing" class="animate-spin w-4 h-4" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                        <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                        <span>{{ rfidProcessing ? 'Processing...' : 'Submit' }}</span>
                      </button>
                    </div>
                    <p v-if="scannerGeoBlocked" class="text-xs text-amber-700 font-semibold mt-2 text-center flex items-center justify-center gap-1.5">
                      <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                      Tap “Verify Location” above to unlock the scanner for this geofenced event.
                    </p>
                    <p v-else class="text-xs text-gray-400 mt-2 text-center">Press Enter to submit automatically after scanning</p>
                  </div>
                </div>

                <!-- Live geofence preview — only when the event requires GPS.
                     Rendered in compact mode so the map stays a small status
                     panel instead of dominating the scanner view.
                     `relative z-0 isolate` creates a new stacking context so
                     Leaflet's internal high-z overlays (z-[400]/z-[500]) can't
                     bleed in front of the fullscreen kiosk modal (z-[70]).
                     Also hidden entirely while the kiosk OR the Location
                     Gate modal is on screen — the gate has its own radar
                     visual, so two map panels at once is just noisy. -->
                <div v-if="selectedEvent && selectedEvent.geofence_enabled && !rfidFullscreenMode && !scannerLocationGateOpen"
                     class="mt-4 relative z-0 isolate">
                  <GeofenceMap
                    readonly
                    compact
                    :enabled="true"
                    :latitude="Number(selectedEvent.geofence_lat)"
                    :longitude="Number(selectedEvent.geofence_lng)"
                    :radius="Number(selectedEvent.geofence_radius_meters) || 80"
                    :isCOE="isCOE"
                    :isSOM="isSOM"
                    @update:insideZone="scannerInsideZone = $event"
                    @update:distanceMeters="scannerDistanceMeters = $event"
                  />
                </div>

                <!-- Recent Logs -->
                <div class="mt-6">
                  <h4 class="font-medium text-gray-700 mb-3 flex flex-wrap items-center gap-x-2 gap-y-1">
                    <svg :class="['w-5 h-5 flex-shrink-0', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"></path></svg>
                    <span>Recent Attendance Logs</span>
                    <span v-if="selectedEvent?.title" :class="['text-sm font-normal truncate max-w-[180px] sm:max-w-none', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']">— {{ selectedEvent.title }}</span>
                  </h4>
                  <div v-if="attendanceLogs.length === 0" class="text-center py-4 text-gray-500">
                    No attendance records yet for this event.
                  </div>
                  <!-- Mobile Card View -->
                  <div v-else class="block sm:hidden space-y-3">
                    <div v-for="(log, index) in sortedAttendanceLogs.slice(0, 10)" :key="log._id" :class="['rounded-lg border p-4 transition-all duration-300 flex flex-col gap-3', index === 0 && isRecentCheckIn(log) ? (isCOE ? 'bg-gradient-to-r from-orange-50 to-red-50 border-orange-200 ring-2 ring-orange-200 ring-inset animate-pulse' : 'bg-gradient-to-r from-blue-50 to-blue-50 border-blue-300 ring-2 ring-blue-300 ring-inset animate-pulse') : 'bg-white border-gray-200']">
                      <div class="flex items-center justify-between gap-2">
                        <div class="flex items-center gap-3 min-w-0 flex-1">
                          <div :class="['w-10 h-10 rounded-full flex items-center justify-center text-white text-sm font-semibold overflow-hidden flex-shrink-0', isCOE ? 'bg-gradient-to-r from-orange-400 to-red-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']">
                            <img v-if="log.student_image || log.student?.photo" :src="log.student_image || log.student?.photo" class="w-full h-full object-cover" />
                            <span v-else>{{ (log.student?.full_name || log.student_name)?.charAt(0) || '?' }}</span>
                          </div>
                          <div class="min-w-0 flex-1">
                            <p class="font-semibold text-sm text-gray-900 truncate">{{ log.student?.full_name || log.student_name }}</p>
                            <p class="text-xs text-gray-500 truncate">{{ log.program || log.student?.program || '-' }}</p>
                          </div>
                        </div>
                        <span :class="['px-2 py-1 rounded-full text-xs font-semibold flex-shrink-0 whitespace-nowrap', getAttendanceLogStatusClass(log)]">
                          {{ getAttendanceLogStatusLabel(log) }}
                        </span>
                      </div>
                      <div :class="['gap-2 text-xs text-gray-600 bg-gray-50 rounded p-2', selectedSession?.check_in_only ? 'grid grid-cols-1' : 'grid grid-cols-2']">
                        <div>
                          <span class="text-gray-500 font-medium block">In:</span>
                          <span class="font-semibold">{{ (log.check_in_at || log.check_in_time) ? new Date(log.check_in_at || log.check_in_time).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '-' }}</span>
                        </div>
                        <div v-if="!selectedSession?.check_in_only">
                          <span class="text-gray-500 font-medium block">Out:</span>
                          <span class="font-semibold">{{ (log.check_out_at || log.check_out_time) ? new Date(log.check_out_at || log.check_out_time).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '-' }}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                  <!-- Desktop Table View -->
                  <div class="hidden sm:block overflow-x-auto">
                    <table class="w-full text-sm">
                      <thead class="bg-gray-50">
                        <tr>
                          <th :class="['px-3 py-2 text-left text-xs font-semibold', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-green-800' : 'text-blue-800']">Student</th>
                          <th :class="['px-3 py-2 text-left text-xs font-semibold', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-green-800' : 'text-blue-800']">Program</th>
                          <th :class="['px-3 py-2 text-left text-xs font-semibold', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-green-800' : 'text-blue-800']">Check-in</th>
                          <th v-if="!selectedSession?.check_in_only" :class="['px-3 py-2 text-left text-xs font-semibold', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-green-800' : 'text-blue-800']">Check-out</th>
                          <th :class="['px-3 py-2 text-left text-xs font-semibold', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-green-800' : 'text-blue-800']">Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr v-for="(log, index) in sortedAttendanceLogs.slice(0, 10)" :key="log._id" :class="['border-b transition-all duration-300', index === 0 && isRecentCheckIn(log) ? (isCOE ? 'bg-gradient-to-r from-orange-50 to-red-50 ring-2 ring-orange-200 ring-inset animate-pulse' : 'bg-gradient-to-r from-blue-50 to-blue-50 ring-2 ring-blue-300 ring-inset animate-pulse') : 'hover:bg-gray-50']">
                          <td class="px-3 py-2">
                            <div class="flex items-center gap-2">
                              <div :class="['w-7 h-7 rounded-full flex items-center justify-center text-white text-xs overflow-hidden flex-shrink-0', isCOE ? 'bg-gradient-to-r from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-r from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-r from-green-500 to-green-700' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']">
                                <img v-if="log.student_image || log.student?.photo" :src="log.student_image || log.student?.photo" class="w-full h-full object-cover rounded-full" />
                                <span v-else>{{ (log.student?.full_name || log.student_name)?.charAt(0) || '?' }}</span>
                              </div>
                              <span class="font-medium text-xs">{{ log.student?.full_name || log.student_name }}</span>
                            </div>
                          </td>
                          <td class="px-3 py-2 text-xs">{{ log.program || log.student?.program || '-' }}</td>
                          <td class="px-3 py-2 text-xs">{{ (log.check_in_at || log.check_in_time) ? new Date(log.check_in_at || log.check_in_time).toLocaleTimeString() : '-' }}</td>
                          <td v-if="!selectedSession?.check_in_only" class="px-3 py-2 text-xs">{{ (log.check_out_at || log.check_out_time) ? new Date(log.check_out_at || log.check_out_time).toLocaleTimeString() : '-' }}</td>
                          <td class="px-3 py-2">
                            <span :class="['px-2 py-0.5 rounded-full text-xs font-medium', getAttendanceLogStatusClass(log)]">
                              {{ getAttendanceLogStatusLabel(log) }}
                            </span>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Student Attendance View -->
          <div v-else class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <!-- Header Banner -->
            <div :class="['relative h-24 sm:h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-900 via-orange-600 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-900 via-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-800 via-green-700 to-green-600' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
              <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
              <div class="light-sweep"></div>
              <div class="relative z-10 px-4 sm:px-6 h-full flex items-center justify-between">
                <div class="flex items-center gap-3">
                  <div class="w-9 h-9 sm:w-10 sm:h-10 rounded-xl sm:rounded-2xl bg-white/20 backdrop-blur flex items-center justify-center flex-shrink-0">
                    <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"></path></svg>
                  </div>
                  <div>
                    <h2 class="text-base sm:text-lg font-bold text-white leading-tight">My Attendance</h2>
                    <p class="text-white/65 text-[10px] sm:text-xs">Events &amp; sessions</p>
                  </div>
                </div>
                <button @click="refreshAttendanceData" :disabled="attendanceLoading" class="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-white/15 hover:bg-white/25 border border-white/20 text-white text-xs font-semibold transition disabled:opacity-50">
                  <svg :class="['w-3.5 h-3.5', attendanceLoading ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                  Refresh
                </button>
              </div>
            </div>

            <!-- Content -->
            <div class="p-3 sm:p-4 md:p-5">

            <div v-if="attendanceLoading" class="flex items-center justify-center py-12">
              <svg :class="['animate-spin h-10 w-10', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
            </div>
            <div v-else-if="attendanceEvents.length === 0 && myAttendanceRecords.length === 0" class="text-center py-12 text-gray-500">
              <svg class="w-16 h-16 mx-auto mb-4 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"></path></svg>
              <p>No attendance events or records yet.</p>
            </div>
            <div v-else class="space-y-6">
              <!-- Active Events Section - Social Media Style -->
              <div v-if="activeNonEndedEvents.length > 0">
                <h3 class="font-semibold text-gray-700 mb-2 sm:mb-3 flex items-center gap-2 text-xs sm:text-sm uppercase tracking-widest">
                  <span class="w-2 h-2 bg-green-500 rounded-full animate-pulse flex-shrink-0"></span>
                  Active Events
                </h3>
                <!-- ============================================================
                     Animated face / scanner notification card.
                     Wrapped in a <Transition> so the message slides + scales
                     in on appear and slides out on dismiss. The :key forces
                     a re-mount on every new notification so the intro
                     animation (and the progress bar) restart cleanly even
                     when the same message text fires twice in a row.
                     The progress bar uses an inline animation-duration so
                     it always stays in sync with the dismiss timeout.
                     ============================================================ -->
                <Transition name="dash-notif">
                  <div v-if="dashFaceCheckInNotif.show"
                       :key="dashFaceCheckInNotifKey"
                       class="dash-notif-card relative overflow-hidden rounded-2xl mb-3 border shadow-sm backdrop-blur-sm"
                       :class="dashFaceCheckInNotif.type === 'success'
                         ? 'bg-gradient-to-br from-emerald-50 to-green-50/80 border-emerald-200/80'
                         : dashFaceCheckInNotif.type === 'locked'
                           ? 'bg-gradient-to-br from-amber-50 to-orange-50/80 border-amber-200/80'
                           : 'bg-gradient-to-br from-rose-50 to-red-50/80 border-rose-200/80'">
                    <div class="flex items-start gap-3 px-4 py-3.5 sm:px-5 sm:py-4">
                      <!-- Bouncy icon badge -->
                      <div class="dash-notif-icon flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center text-white shadow-md"
                           :class="dashFaceCheckInNotif.type === 'success'
                             ? 'bg-gradient-to-br from-emerald-400 to-emerald-600 shadow-emerald-500/30'
                             : dashFaceCheckInNotif.type === 'locked'
                               ? 'bg-gradient-to-br from-amber-400 to-orange-500 shadow-amber-500/30'
                               : 'bg-gradient-to-br from-rose-400 to-rose-600 shadow-rose-500/30'">
                        <svg v-if="dashFaceCheckInNotif.type === 'success'" class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                        <svg v-else-if="dashFaceCheckInNotif.type === 'locked'" class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
                        <svg v-else class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                      </div>
                      <!-- Message body -->
                      <div class="flex-1 min-w-0 pt-1">
                        <p class="text-sm font-semibold leading-snug"
                           :class="dashFaceCheckInNotif.type === 'success'
                             ? 'text-emerald-900'
                             : dashFaceCheckInNotif.type === 'locked'
                               ? 'text-amber-900'
                               : 'text-rose-900'">
                          {{ dashFaceCheckInNotif.message }}
                        </p>
                      </div>
                      <!-- Manual dismiss -->
                      <button @click="dismissDashNotif"
                              class="dash-notif-close flex-shrink-0 w-7 h-7 rounded-full flex items-center justify-center transition hover:bg-black/5 text-gray-500 hover:text-gray-800"
                              aria-label="Dismiss">
                        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                      </button>
                    </div>
                    <!-- Auto-dismiss progress bar -->
                    <div class="absolute left-0 right-0 bottom-0 h-1 overflow-hidden">
                      <div class="dash-notif-progress h-full origin-left"
                           :class="dashFaceCheckInNotif.type === 'success'
                             ? 'bg-gradient-to-r from-emerald-400 to-emerald-600'
                             : dashFaceCheckInNotif.type === 'locked'
                               ? 'bg-gradient-to-r from-amber-400 to-orange-500'
                               : 'bg-gradient-to-r from-rose-400 to-rose-600'"
                           :style="{ animationDuration: (dashFaceCheckInNotif.duration || 4000) + 'ms' }"></div>
                    </div>
                  </div>
                </Transition>
                <div class="space-y-4">
                  <div v-for="event in activeNonEndedEvents" :key="event._id || event.event_id" :class="['rounded-2xl shadow-sm border overflow-hidden bg-gradient-to-br', isCOE ? 'from-white to-orange-50 border-orange-100' : isSOM ? 'from-white to-green-50 border-green-100' : 'from-white to-blue-50 border-blue-100']">
                    <!-- Header row: clickable text on the left, scanner button on the right -->
                    <div class="px-4 pt-4 pb-2 flex items-stretch gap-3">
                      <div class="flex-1 min-w-0 cursor-pointer" @click="toggleEventExpansion(event._id || event.event_id)">
                        <div class="flex flex-wrap items-center gap-2 mb-3">
                          <svg :class="['w-4 h-4 transition-transform', isCOE ? 'text-orange-600' : 'text-blue-600', expandedEvents[event._id || event.event_id] ? 'rotate-90' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
                          <span :class="['px-3 py-1 rounded-full text-xs font-semibold', getOverallStatusClass(getSmartRecordStatus((myAttendanceRecords.value && myAttendanceRecords.value.find(r => r.event_id === (event._id || event.event_id))) || { event_id: event._id || event.event_id, event, overall_status: 'ongoing' }))]">
                            {{ getOverallStatusLabel(getSmartRecordStatus((myAttendanceRecords.value && myAttendanceRecords.value.find(r => r.event_id === (event._id || event.event_id))) || { event_id: event._id || event.event_id, event, overall_status: 'ongoing' })) }}
                          </span>
                          <span v-if="event.status === 'active' && getEventTimeRemaining(event._id || event.event_id)" :class="['px-3 py-1 rounded-full text-xs font-semibold', getEventTimeRemaining(event._id || event.event_id) === 'Ended' ? 'bg-red-100 text-red-700' : 'bg-orange-100 text-orange-700']">
                            {{ getEventTimeRemaining(event._id || event.event_id) }}
                          </span>
                        </div>
                        <!-- Event Title -->
                        <h3 :class="['font-bold text-base md:text-lg leading-tight mb-2', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">{{ event.title }}</h3>
                        <!-- Description -->
                        <p v-if="event.description" class="text-gray-600 text-sm leading-relaxed mb-3 line-clamp-2">{{ event.description }}</p>
                      </div>

                      <!-- Face ID Scanner button (always visible on the right) -->
                      <div class="flex-shrink-0 self-start">
                        <button
                          @click.stop="openEventScanner(event)"
                          :disabled="getEventScannerInfo(event).state === 'loading' || getEventScannerInfo(event).state === 'done' || dashFaceCheckInLoading"
                          :class="['ssaam-event-scanner-btn group relative flex flex-col items-center justify-center rounded-2xl text-white font-bold tracking-wide overflow-hidden transition-all duration-300', getEventScannerBtnSize, getEventScannerBtnClass(event)]"
                          :title="getEventScannerTooltip(event)"
                        >
                          <!-- Pulsing scan ring (only when ready) -->
                          <span v-if="getEventScannerInfo(event).state === 'ready'" class="absolute inset-0 rounded-2xl pointer-events-none">
                            <span class="absolute inset-0 rounded-2xl ssaam-scanner-pulse"></span>
                            <span class="absolute inset-0 rounded-2xl ssaam-scanner-sweep"></span>
                          </span>
                          <!-- Icon -->
                          <span class="relative z-10 flex items-center justify-center">
                            <!-- Loading spinner -->
                            <svg v-if="getEventScannerInfo(event).state === 'loading'" class="w-6 h-6 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                            <!-- Lock icon -->
                            <svg v-else-if="getEventScannerInfo(event).state === 'locked'" class="w-6 h-6 ssaam-scanner-lock-shake" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
                            <!-- Done check -->
                            <svg v-else-if="getEventScannerInfo(event).state === 'done'" class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                            <!-- No active -->
                            <svg v-else-if="getEventScannerInfo(event).state === 'no_active'" class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                            <!-- Ready: face scan icon -->
                            <svg v-else class="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 8V6a2 2 0 012-2h2M4 16v2a2 2 0 002 2h2m8-16h2a2 2 0 012 2v2m-4 12h2a2 2 0 002-2v-2M9 10h.01M15 10h.01M9 16c.85.63 1.885 1 3 1s2.15-.37 3-1"/></svg>
                          </span>
                          <span class="relative z-10 mt-1 text-[10px] sm:text-xs leading-none">
                            {{ getEventScannerLabel(event) }}
                          </span>
                        </button>
                      </div>
                    </div>
                    <!-- Event Details Footer -->
                    <div :class="['bg-white bg-opacity-60 px-3 sm:px-4 py-2 sm:py-3 border-t', isCOE ? 'border-orange-100' : isSOM ? 'border-green-100' : 'border-blue-100']">
                      <div class="flex flex-wrap gap-x-4 gap-y-1 text-xs text-gray-600">
                        <div class="flex items-center gap-1.5">
                          <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-500' : 'text-blue-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>
                          <span class="font-medium">{{ formatEventDate(event.date || event.event_date) }}</span>
                        </div>
                        <div class="flex items-center gap-1.5">
                          <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-500' : 'text-blue-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                          <span class="font-medium">{{ formatEventTime(event.start_time || event.startTime || '07:00') }} – {{ formatEventTime(event.end_time || event.endTime || '17:00') }}</span>
                        </div>
                        <div v-if="event.location" class="flex items-center gap-1.5">
                          <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-500' : 'text-blue-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                          <span class="font-medium">{{ event.location }}</span>
                        </div>
                      </div>
                    </div>
                    <!-- Sessions Panel - Expandable with Slide Animation -->
                    <transition name="slide-down">
                      <div v-if="expandedEvents[event._id || event.event_id]" :class="['border-t px-3 sm:px-4 py-3', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
                        <h4 :class="['text-xs sm:text-sm font-semibold mb-2 flex items-center gap-2', isCOE ? 'text-orange-700' : 'text-blue-700']"]>
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"></path></svg>
                        Sessions
                      </h4>
                      <div v-if="!expandedEventSessions[event._id || event.event_id] || expandedEventSessions[event._id || event.event_id].length === 0" class="text-sm text-gray-500 py-2">
                        No sessions available for this event.
                      </div>
                      <div v-else class="space-y-2">
                        <div v-for="session in expandedEventSessions[event._id || event.event_id]" :key="session._id" :class="['flex items-center justify-between bg-white rounded-lg px-3 py-2 border', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : 'border-blue-200']">
                          <div class="flex items-center gap-3 min-w-0">
                            <span class="font-medium text-gray-800 truncate">{{ session.label }}</span>
                            <span class="text-xs text-gray-500 whitespace-nowrap">{{ formatEventTime(session.start_time) }} - {{ formatEventTime(session.end_time) }}</span>
                          </div>
                          <div class="flex items-center gap-2 flex-shrink-0">
                            <span :class="['px-2 py-0.5 rounded-full text-xs font-medium', getSessionDisplayStatus(session, event) === 'active' ? 'bg-green-100 text-green-700' : getSessionDisplayStatus(session, event) === 'draft' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-600']">
                              {{ getSessionDisplayStatus(session, event) === 'active' ? 'Active' : getSessionDisplayStatus(session, event) === 'draft' ? 'Upcoming' : 'Closed' }}
                            </span>
                            <button
                              v-if="getSessionDisplayStatus(session, event) === 'active' && getSessionCheckAction(session, event)"
                              @click.stop="handleSessionButtonClick(session, event)"
                              :title="getSessionLockReason(session, event) || ''"
                              :class="['ssaam-checkin-btn px-3 py-1.5 rounded-xl text-xs font-bold tracking-wide transition-all duration-200 active:scale-95 shadow-md text-white', getSessionLockReason(session, event) ? 'bg-gradient-to-r from-amber-500 to-orange-600 ring-2 ring-amber-300/60 cursor-not-allowed' : (getSessionCheckAction(session, event) === 'Check In' ? (isCOE ? 'bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 shadow-orange-500/30' : isSOM ? 'bg-gradient-to-r from-green-500 to-green-600 hover:from-green-600 hover:to-green-700 shadow-green-500/30' : 'bg-gradient-to-r from-[#1e3bdb] to-[#4f62ff] hover:from-[#1730c0] hover:to-[#3d52e8] shadow-blue-600/30') : 'bg-gradient-to-r from-emerald-500 to-green-600 hover:from-emerald-600 hover:to-green-700 shadow-emerald-500/30')]"
                            >
                              <span class="flex items-center gap-1.5">
                                <!-- Locked icon overrides the action icon when scanner is closed -->
                                <svg v-if="getSessionLockReason(session, event)" class="w-3 h-3 ssaam-scanner-lock-shake" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
                                <svg v-else-if="getSessionCheckAction(session, event) === 'Check In'" class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5.121 17.804A13.937 13.937 0 0112 16c2.5 0 4.847.655 6.879 1.804M15 10a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                                <svg v-else class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M17 16l4-4m0 0l-4-4m4 4H7"/></svg>
                                {{ getSessionLockReason(session, event) ? 'Locked' : getSessionCheckAction(session, event) }}
                              </span>
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                    </transition>
                  </div>
                </div>
              </div>

              <!-- Upcoming Events Section -->
              <div v-if="upcomingEvents.length > 0">
                <h3 class="font-semibold text-gray-700 mb-2 sm:mb-3 flex items-center gap-2 text-xs sm:text-sm uppercase tracking-widest">
                  <span class="w-2 h-2 bg-blue-500 rounded-full flex-shrink-0"></span>
                  Upcoming Events
                </h3>
                <div class="space-y-4">
                  <div v-for="event in upcomingEvents" :key="event._id || event.event_id" :class="['rounded-2xl shadow-sm overflow-hidden', isCOE ? 'bg-gradient-to-br from-white to-orange-50 border border-orange-100' : isSOM ? 'bg-gradient-to-br from-white to-green-50 border border-green-100' : 'bg-gradient-to-br from-white to-blue-50 border border-blue-100']">
                    <!-- Header with status badge - Clickable to expand -->
                    <div class="px-4 pt-4 pb-2 cursor-pointer" @click="toggleEventExpansion(event._id || event.event_id)">
                      <div class="flex flex-wrap items-center gap-2 mb-3">
                        <svg :class="['w-4 h-4 transition-transform', expandedEvents[event._id || event.event_id] ? 'rotate-90' : '', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
                        <span :class="['px-3 py-1 rounded-full text-xs font-semibold', isCOE ? 'bg-orange-100 text-orange-700' : isSOM ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700']">
                          Upcoming
                        </span>
                      </div>
                      <!-- Event Title -->
                      <h3 :class="['font-bold text-base md:text-lg leading-tight mb-2', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-blue-900']">{{ event.title }}</h3>
                      <!-- Description -->
                      <p v-if="event.description" class="text-gray-600 text-sm leading-relaxed mb-3">{{ event.description }}</p>
                    </div>
                    <!-- Event Details Footer -->
                    <div :class="['bg-white bg-opacity-60 px-3 sm:px-4 py-2 sm:py-3 border-t', isCOE ? 'border-orange-100' : isSOM ? 'border-green-100' : 'border-blue-100']">
                      <div class="flex flex-wrap gap-x-4 gap-y-1 text-xs text-gray-600">
                        <div class="flex items-center gap-1.5">
                          <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>
                          <span class="font-medium">{{ formatEventDate(event.date || event.event_date) }}</span>
                        </div>
                        <div class="flex items-center gap-1.5">
                          <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                          <span class="font-medium">{{ formatEventTime(event.start_time || event.startTime || '07:00') }} – {{ formatEventTime(event.end_time || event.endTime || '17:00') }}</span>
                        </div>
                        <div v-if="event.location" class="flex items-center gap-1.5">
                          <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                          <span class="font-medium">{{ event.location }}</span>
                        </div>
                      </div>
                    </div>
                    <!-- Sessions Panel - Expandable with Slide Animation -->
                    <transition name="slide-down">
                      <div v-if="expandedEvents[event._id || event.event_id]" :class="['border-t px-3 sm:px-4 py-3', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
                        <h4 :class="['text-xs sm:text-sm font-semibold mb-2 flex items-center gap-2', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"></path></svg>
                        Sessions
                      </h4>
                      <div v-if="!expandedEventSessions[event._id || event.event_id] || expandedEventSessions[event._id || event.event_id].length === 0" class="text-sm text-gray-500 py-2">
                        No sessions available for this event.
                      </div>
                      <div v-else class="space-y-2">
                        <div v-for="session in expandedEventSessions[event._id || event.event_id]" :key="session._id" @click="selectSession(session, event, $event)" :class="['flex items-center justify-between bg-white rounded-lg px-3 py-2 border cursor-pointer hover:shadow', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : 'border-blue-200']">
                          <div class="flex items-center gap-3">
                            <span class="font-medium text-gray-800">{{ session.label }}</span>
                            <span class="text-xs text-gray-500">{{ formatEventTime(session.start_time) }} - {{ formatEventTime(session.end_time) }}</span>
                          </div>
                          <span :class="['px-2 py-0.5 rounded-full text-xs font-medium', session.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700']">
                            {{ session.status === 'active' ? 'Active' : 'Upcoming' }}
                          </span>
                        </div>
                      </div>
                    </div>
                    </transition>
                  </div>
                </div>
              </div>

              <!-- My Attendance Records Section - Enhanced with Expandable Event Folders -->
              <div v-if="myAttendanceRecords.length > 0">
                <h3 class="font-semibold text-gray-700 mb-2 sm:mb-3 flex items-center gap-2 text-xs sm:text-sm uppercase tracking-widest">
                  <img src="/events.svg" alt="History" class="w-4 h-4 flex-shrink-0" style="filter: invert(0.3) sepia(1) hue-rotate(270deg) saturate(1.5);" />
                  My Attendance History
                </h3>
                <div class="space-y-3">
                  <div 
                    v-for="record in myAttendanceRecords" 
                    :key="record._id || record.event_id" 
                    class="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm"
                  >
                    <!-- Event Folder Header - Clickable with press animation -->
                    <div 
                      @click="expandedAttendanceRecords[record.event_id] = !expandedAttendanceRecords[record.event_id]"
                      class="attendance-event-card px-4 py-3 cursor-pointer flex items-center justify-between gap-3 hover:bg-gray-50 transition-all duration-200"
                      :class="{ 'bg-gray-50': expandedAttendanceRecords[record.event_id] }"
                    >
                      <div class="flex items-center gap-3 flex-1 min-w-0">
                        <!-- Folder Icon with expand indicator -->
                        <div class="flex-shrink-0 relative">
                          <svg :class="['w-8 h-8 transition-all duration-200', expandedAttendanceRecords[record.event_id] ? (isCOE ? 'text-orange-500' : isSOM ? 'text-green-600' : isCNAHS ? 'text-emerald-600' : 'text-blue-600') : 'text-gray-400']" fill="currentColor" viewBox="0 0 24 24">
                            <path d="M10 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2h-8l-2-2z"/>
                          </svg>
                          <svg :class="['w-3 h-3 absolute -right-0.5 -bottom-0.5 transition-transform duration-200', expandedAttendanceRecords[record.event_id] ? ('rotate-90 ' + (isCOE ? 'text-orange-500' : isSOM ? 'text-green-600' : isCNAHS ? 'text-emerald-600' : 'text-blue-600')) : 'text-gray-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"></path>
                          </svg>
                        </div>
                        <!-- Event Info -->
                        <div class="flex-1 min-w-0">
                          <h4 class="font-semibold text-gray-900 truncate">{{ record.event?.title || record.event_title || 'Event' }}</h4>
                          <div class="flex flex-wrap items-center gap-2 mt-1 text-xs text-gray-500">
                            <span class="flex items-center gap-1">
                              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>
                              {{ record.event?.event_date ? formatEventDate(record.event.event_date) : '-' }}
                            </span>
                            <span v-if="record.sessions && record.sessions.length > 0" class="text-gray-400">|</span>
                            <span v-if="record.sessions && record.sessions.length > 0" class="text-gray-500">
                              {{ record.sessions.length }} session{{ record.sessions.length > 1 ? 's' : '' }}
                            </span>
                          </div>
                        </div>
                      </div>
                      <!-- Overall Status Badge -->
                      <div class="flex-shrink-0 flex flex-col items-end gap-1">
                        <span :class="['px-3 py-1 rounded-full text-xs font-semibold', getOverallStatusClass(getSmartRecordStatus(record))]">
                          {{ getOverallStatusLabel(getSmartRecordStatus(record)) }}
                        </span>
                        <!-- Show excuse reason if applicable -->
                        <span v-if="record.overall_status === 'excused' && record.excuse_reason" class="text-xs text-gray-600 italic max-w-xs text-right">
                          Reason: {{ record.excuse_reason }}
                        </span>
                      </div>
                    </div>
                    
                    <!-- Expanded Sessions Panel -->
                    <transition name="slide-fade">
                      <div v-if="expandedAttendanceRecords[record.event_id]" :class="['border-t bg-gradient-to-b', isCOE ? 'border-orange-100 from-orange-50 to-white' : 'border-gray-100 from-blue-50 to-white']">
                        <!-- Event Description if available -->
                        <div v-if="record.event?.description" class="px-4 py-2 text-sm text-gray-600 border-b border-gray-100">
                          {{ record.event.description }}
                        </div>
                        
                        <!-- Sessions List -->
                        <div v-if="record.sessions && record.sessions.length > 0" class="p-4 space-y-3">
                          <div 
                            v-for="(sessionData, idx) in record.sessions" 
                            :key="sessionData.session_id || idx"
                            class="bg-gradient-to-br from-white to-gray-50 rounded-xl border-2 border-gray-100 p-4 shadow-sm hover:shadow-md transition-all"
                          >
                            <div class="flex flex-col gap-3">
                              <!-- Session Header with Badge -->
                              <div class="flex flex-col sm:flex-row sm:items-start justify-between gap-3">
                                <!-- Session Badge and Info -->
                                <div class="flex items-start gap-3 flex-1">
                                  <div :class="['w-14 h-14 rounded-xl flex items-center justify-center flex-shrink-0 shadow-md overflow-hidden', getSessionBadgeStyle(sessionData.session?.label).bgGradient]">
                                    <img 
                                      :src="getSessionBadgeStyle(sessionData.session?.label).icon" 
                                      :alt="getSessionBadgeStyle(sessionData.session?.label).displayText"
                                      :class="['w-11 h-11 object-contain', (sessionData.session?.label?.toLowerCase().includes('night') || sessionData.session?.label?.toLowerCase().includes('whole day')) ? 'mt-1' : '']"
                                      style="filter: brightness(0) invert(1) drop-shadow(0 0 1px rgba(0,0,0,0.1)); mix-blend-mode: lighten;"
                                    />
                                  </div>
                                  <div class="flex-1 min-w-0">
                                    <div class="flex flex-wrap items-center gap-2 mb-1">
                                      <h5 class="font-bold text-gray-900 text-sm">{{ getSessionBadgeStyle(sessionData.session?.label).displayText }}</h5>
                                      <span :class="['px-2 py-0.5 rounded-full text-xs font-semibold', getSessionAttendanceClass(sessionData.attendance, sessionData.session, record.event)]">
                                        {{ getSessionAttendanceLabel(sessionData.attendance, sessionData.session, record.event) }}
                                      </span>
                                    </div>
                                    <p class="text-xs text-gray-600 font-medium">
                                      {{ formatEventTime(sessionData.session?.start_time) }} - {{ formatEventTime(sessionData.session?.end_time) }}
                                    </p>
                                    <p v-if="sessionData.session?.start_time" class="text-xs text-orange-600 flex items-center gap-1 mt-1.5">
                                      <svg class="w-3 h-3 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                                      <span>Late after {{ calculateLateThreshold(sessionData.session.start_time, sessionData.session.late_timer_minutes || 60) }}</span>
                                    </p>
                                  </div>
                                </div>
                              </div>
                              
                              <!-- Check-in/Check-out Times Grid -->
                              <div class="grid grid-cols-2 gap-3 text-sm">
                                <div class="bg-gradient-to-br from-green-50 to-emerald-50 rounded-lg p-3 border border-green-100">
                                  <div class="flex items-center gap-2 text-green-700 mb-2">
                                    <svg class="w-4 h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1"></path></svg>
                                    <span class="font-semibold text-xs">Check-in</span>
                                  </div>
                                  <p class="font-bold text-lg text-green-800 tabular-nums">
                                    {{ sessionData.attendance?.check_in_at ? new Date(sessionData.attendance.check_in_at).toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' }) : '--:--' }}
                                  </p>
                                </div>
                                <div class="bg-gradient-to-br from-blue-50 to-cyan-50 rounded-lg p-3 border border-blue-100">
                                  <div class="flex items-center gap-2 text-blue-700 mb-2">
                                    <svg class="w-4 h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
                                    <span class="font-semibold text-xs">Check-out</span>
                                  </div>
                                  <p class="font-bold text-lg text-blue-800 tabular-nums">
                                    {{ sessionData.attendance?.check_out_at ? new Date(sessionData.attendance.check_out_at).toLocaleTimeString('en-PH', { hour: '2-digit', minute: '2-digit' }) : '--:--' }}
                                  </p>
                                </div>
                              </div>
                            </div>
                          </div>
                        </div>
                        
                        <!-- No Sessions Message -->
                        <div v-else class="p-4 text-center text-sm text-gray-500">
                          <svg class="w-8 h-8 mx-auto mb-2 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"></path></svg>
                          No session data available for this event.
                        </div>
                      </div>
                    </transition>
                  </div>
                </div>
              </div>
            </div>

            </div><!-- /content wrapper -->
          </div>
        </div>

        <!-- Payments Page -->
        <div v-if="currentPage === 'payments'" class="space-y-6">
          <div v-if="isAdminLike" class="space-y-6">
            <!-- Header -->
            <div class="flex flex-col md:flex-row md:items-end md:justify-between gap-4">
              <div>
                <h1 :class="['text-3xl md:text-4xl font-bold bg-gradient-to-r bg-clip-text text-transparent', isCOE ? 'from-orange-600 to-red-600' : 'from-ssaam-dark to-ssaam-light']">Payment Management</h1>
                <p class="text-gray-600 mt-1">Create and manage payment campaigns for students</p>
              </div>
              <button 
                @click="refreshAllData()"
                :disabled="paymentsLoading"
                class="px-4 py-2 bg-white border border-gray-300 rounded-xl text-sm font-medium text-gray-700 hover:bg-gray-50 transition disabled:opacity-50 flex items-center gap-2 self-start md:self-auto"
              >
                <svg class="w-4 h-4" :class="paymentsLoading && 'animate-spin'" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                {{ paymentsLoading ? 'Refreshing...' : 'Refresh' }}
              </button>
            </div>

            <!-- Create Payment Section -->
            <div :class="['bg-gradient-to-br rounded-2xl p-6 border shadow-sm', isCOE ? 'from-orange-50 to-red-50 border-orange-100' : isSOM ? 'from-green-50 to-yellow-50 border-green-100' : 'from-blue-50 to-blue-50 border-blue-100']">
              <div class="flex items-center gap-3 mb-5">
                <div :class="['w-10 h-10 rounded-lg flex items-center justify-center', isCOE ? 'bg-gradient-to-br from-orange-500 to-red-500' : isSOM ? 'bg-gradient-to-br from-green-600 to-yellow-500' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                  <svg class="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"></path></svg>
                </div>
                <h2 class="text-xl font-bold text-gray-900">Create New Payment Campaign</h2>
              </div>
              
              <div class="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6">
                <!-- Left Column: Form Fields -->
                <div class="md:col-span-1 space-y-4">
                  <div>
                    <label class="block text-xs font-semibold text-gray-700 mb-2 uppercase tracking-wide">Campaign Title</label>
                    <input v-model="newPaymentData.title" type="text" placeholder="e.g., Membership Fee Q1 2026" :class="['w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl focus:ring-2 focus:border-transparent outline-none transition', isCOE ? 'focus:ring-orange-500' : isSOM ? 'focus:ring-green-500' : 'focus:ring-blue-500']" />
                  </div>
                  <div>
                    <label class="block text-xs font-semibold text-gray-700 mb-2 uppercase tracking-wide">Type</label>
                    <select v-model="newPaymentData.type" :class="['w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl focus:ring-2 focus:border-transparent outline-none transition', isCOE ? 'focus:ring-orange-500' : isSOM ? 'focus:ring-green-500' : 'focus:ring-blue-500']">
                      <option value="fee">Fee</option>
                      <option value="membership">Membership</option>
                      <option value="donation">Donation</option>
                      <option value="other">Other</option>
                    </select>
                  </div>
                  <div>
                    <label class="block text-xs font-semibold text-gray-700 mb-2 uppercase tracking-wide">Amount Due (₱)</label>
                    <input v-model.number="newPaymentData.amount_due" type="number" placeholder="0.00" :class="['w-full px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl focus:ring-2 focus:border-transparent outline-none transition', isCOE ? 'focus:ring-orange-500' : isSOM ? 'focus:ring-green-500' : 'focus:ring-blue-500']" />
                  </div>
                  <button 
                    @click="createPayment" 
                    :disabled="creatingPayment || !newPaymentData.title.trim()"
                    :class="['w-full px-4 py-2.5 text-sm font-semibold text-white rounded-xl transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 bg-gradient-to-r', primaryButtonGradient, primaryButtonHover]"
                  >
                    <svg v-if="creatingPayment" class="animate-spin h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                    {{ creatingPayment ? 'Creating...' : 'Create Payment' }}
                  </button>
                </div>

                <!-- Right Column: Description -->
                <div class="md:col-span-2">
                  <label class="block text-xs font-semibold text-gray-700 mb-2 uppercase tracking-wide">Description (Optional)</label>
                  <textarea v-model="newPaymentData.description" placeholder="Add notes, details, or instructions..." :class="['w-full h-full min-h-48 px-4 py-2.5 text-sm bg-white border border-gray-200 rounded-xl focus:ring-2 focus:border-transparent outline-none transition resize-none', isCOE ? 'focus:ring-orange-500' : isSOM ? 'focus:ring-green-500' : 'focus:ring-blue-500']" rows="4"></textarea>
                </div>
              </div>
            </div>

            <!-- Payments List -->
            <div>
              <h3 class="text-lg font-bold text-gray-900 mb-4">Active Campaigns</h3>

              <div v-if="paymentsList.length === 0" class="text-center py-12">
                <div class="w-16 h-16 rounded-2xl bg-gray-100 flex items-center justify-center mx-auto mb-4">
                  <svg class="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                </div>
                <p class="text-gray-600 font-medium">No payment campaigns yet</p>
                <p class="text-gray-500 text-sm mt-1">Create your first payment campaign above</p>
              </div>

              <div v-else class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                <div v-for="payment in paymentsList.filter(p => p.status === 'active')" :key="payment._id" class="relative bg-white rounded-2xl border border-gray-200 hover:border-blue-300 hover:shadow-lg transition-all duration-300 overflow-hidden group">
                  <!-- Gradient accent bar -->
                  <div class="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-ssaam-dark to-ssaam-light"></div>
                  
                  <!-- Loading overlay -->
                  <transition name="card-overlay">
                    <div v-if="activeCardLoadingId === payment._id" class="absolute inset-0 z-30 flex items-center justify-center">
                      <div class="absolute inset-0 bg-black bg-opacity-20 backdrop-blur-sm"></div>
                      <div class="relative z-40 bg-white rounded-xl px-5 py-4 shadow-2xl flex items-center gap-3">
                        <svg class="animate-spin h-5 w-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                        <span class="text-sm font-medium text-gray-700">Loading...</span>
                      </div>
                    </div>
                  </transition>

                  <div class="p-5">
                    <!-- Header -->
                    <div class="flex items-start justify-between gap-3 mb-4">
                      <div class="flex-1 min-w-0">
                        <h4 class="font-bold text-gray-900 line-clamp-2">{{ payment.title }}</h4>
                        <p class="text-sm text-gray-600 line-clamp-1 mt-0.5">{{ payment.description }}</p>
                      </div>
                      <span :class="[
                        'text-xs font-bold px-3 py-1 rounded-lg whitespace-nowrap',
                        payment.type === 'fee' && 'bg-blue-100 text-blue-700',
                        payment.type === 'membership' && 'bg-blue-100 text-blue-700',
                        payment.type === 'donation' && 'bg-green-100 text-green-700',
                        !['fee', 'membership', 'donation'].includes(payment.type) && 'bg-gray-100 text-gray-700'
                      ]">{{ (payment.type || 'fee').charAt(0).toUpperCase() + (payment.type || 'fee').slice(1) }}</span>
                    </div>

                    <!-- Stats Grid -->
                    <div class="grid grid-cols-2 gap-3 mb-4">
                      <div class="bg-gradient-to-br from-blue-50 to-blue-100 rounded-xl p-3 border border-blue-200">
                        <div class="text-xs text-blue-600 font-semibold uppercase">Total Students</div>
                        <div class="text-2xl font-bold text-blue-900 mt-1">{{ payment.stats.total_students }}</div>
                      </div>
                      <div :class="['bg-gradient-to-br rounded-xl p-3 border', isCOE ? 'from-orange-50 to-orange-100 border-orange-200' : isSOM ? 'from-green-50 to-green-100 border-green-200' : isCNAHS ? 'from-green-50 to-green-100 border-green-200' : 'from-blue-50 to-blue-100 border-blue-200']">
                        <div :class="['text-xs font-semibold uppercase', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']">Progress</div>
                        <div :class="['text-2xl font-bold mt-1', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">{{ payment.stats.completion_percentage }}%</div>
                      </div>
                    </div>

                    <!-- Stats Details -->
                    <div class="space-y-2 mb-4 pb-4 border-b border-gray-100">
                      <div class="flex items-center justify-between text-sm">
                        <span class="text-gray-600">Paid</span>
                        <span class="font-bold text-green-600">{{ payment.stats.paid_count }}</span>
                      </div>
                      <div class="flex items-center justify-between text-sm">
                        <span class="text-gray-600">Unpaid</span>
                        <span class="font-bold text-red-600">{{ Math.max(0, (payment.stats?.total_students || 0) - (payment.stats?.paid_count || 0)) }}</span>
                      </div>
                    </div>

                    <!-- Progress Bar -->
                    <div class="mb-4">
                      <div class="w-full bg-gray-200 rounded-full h-2 overflow-hidden">
                        <div class="h-full bg-gradient-to-r from-ssaam-dark to-ssaam-light transition-all duration-300" :style="{ width: payment.stats.completion_percentage + '%' }"></div>
                      </div>
                    </div>

                    <!-- Action Button -->
                    <button 
                      @click="handleManagePaymentFromCard(payment)"
                      class="w-full px-4 py-2.5 bg-gradient-to-r from-blue-50 to-blue-50 border border-blue-200 text-blue-700 rounded-xl text-sm font-semibold hover:from-blue-100 hover:to-blue-100 hover:border-blue-400 transition group-hover:shadow-md"
                    >
                      Manage Campaign
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Full Screen Payment Loading Modal (teleported to body to ensure full-page coverage) -->
          <teleport to="body">
            <transition name="fade">
              <div v-if="activeCardLoadingId" class="fixed inset-0 z-[9999] flex items-center justify-center p-4">
                <div :class="['absolute rounded-2xl w-full max-w-sm inset-0 m-auto backdrop-blur-sm',
                                       isCOE ? 'bg-orange-700 bg-opacity-30' : isSOM ? 'bg-green-700 bg-opacity-30' : 'bg-blue-700 bg-opacity-30']"></div>
                <div :class="['bg-white rounded-2xl shadow-2xl px-6 py-8 sm:px-8 sm:py-10 flex flex-col items-center gap-4 max-w-sm w-full mx-2 transition-all duration-200 relative z-10',
                                         isCOE ? 'border-2 border-orange-200' : isSOM ? 'border-2 border-green-200' : 'border-2 border-blue-200']">
                  <div :class="['w-16 h-16 rounded-full flex items-center justify-center',
                                    isCOE ? 'bg-gradient-to-br from-orange-700 to-red-600' : isSOM ? 'bg-gradient-to-br from-som-green to-som-yellow' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                    <svg class="animate-spin h-8 w-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                      <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
                    </svg>
                  </div>
                  <div class="text-center">
                    <h3 :class="['text-lg sm:text-xl font-bold mb-2',
                                  isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-gray-900']">
                      Loading {{ collegeName }} Payment Details
                    </h3>
                    <p :class="['text-sm',
                                isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : 'text-gray-600']">
                      Please wait while we fetch the payment information...
                    </p>
                  </div>
                </div>
              </div>
            </transition>
          </teleport>

          <!-- Payment Download Confirmation Modal -->
  <transition name="fade">
    <div v-if="showPaymentDownloadConfirm" class="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
      <div class="absolute inset-0 bg-black bg-opacity-40" @click="(showPaymentDownloadConfirm = false, paymentToExport = null)"></div>
      <div class="relative z-60 w-full max-w-2xl bg-white rounded-2xl shadow-2xl overflow-hidden">
        <div class="p-5 sm:p-6 lg:p-8">
          <div class="flex items-start justify-between gap-4">
            <div>
              <h3 class="text-lg sm:text-xl font-bold text-gray-900">Confirm Download</h3>
              <p class="text-sm text-gray-600 mt-1">You are exporting payment records using the filters currently applied. Review summary and confirm.</p>
            </div>
            <button @click="(showPaymentDownloadConfirm = false, paymentToExport = null)" class="text-gray-400 hover:text-gray-600">✕</button>
          </div>

          <div class="mt-4 grid grid-cols-1 sm:grid-cols-4 gap-3 items-center">
            <div class="bg-gray-50 rounded-lg p-3 text-sm">
              <div class="text-xs text-gray-500">Status</div>
              <div class="font-semibold text-gray-900">{{ paymentRecordsFilter.status || 'All' }}</div>
            </div>
            <div class="bg-gray-50 rounded-lg p-3 text-sm">
              <div class="text-xs text-gray-500">Year</div>
              <div class="font-semibold text-gray-900">{{ paymentRecordsFilter.yearLevel || 'All' }}</div>
            </div>
            <div class="bg-gray-50 rounded-lg p-3 text-sm">
              <div class="text-xs text-gray-500">Program</div>
              <div class="font-semibold text-gray-900">{{ paymentRecordsFilter.program || 'All' }}</div>
            </div>
            <div class="bg-gray-50 rounded-lg p-3 text-sm flex flex-col">
              <div class="text-xs text-gray-500">Format</div>
              <div class="mt-1 flex items-center gap-3">
                <label class="inline-flex items-center text-sm">
                  <input type="radio" v-model="paymentExportFormat" value="xlsx" class="mr-2" /> XLSX
                </label>
                <label class="inline-flex items-center text-sm">
                  <input type="radio" v-model="paymentExportFormat" value="csv" class="mr-2" /> CSV
                </label>
              </div>
            </div>
          </div>

          <div class="mt-4">
            <div class="text-sm text-gray-500">Preview (first {{ paymentDownloadPreviewLimit }} records)</div>
            <div class="mt-2 bg-white border rounded-lg overflow-auto max-h-48">
              <table class="w-full text-sm">
                <thead class="bg-gray-100">
                  <tr>
                    <th class="px-3 py-2 text-left">Student</th>
                    <th class="px-3 py-2 text-left">ID</th>
                    <th class="hidden sm:table-cell px-3 py-2 text-left">Program</th>
                    <th class="hidden lg:table-cell px-3 py-2 text-left">Year</th>
                    <th class="px-3 py-2 text-left">Amount</th>
                    <th class="px-3 py-2 text-left">Paid By</th>
                    <th class="px-3 py-2 text-left">Date</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(r, idx) in getFilteredPaymentRecords(paymentToExport).slice(0, paymentDownloadPreviewLimit)" :key="r._id || idx" class="border-t">
                    <td class="px-3 py-2">{{ r.student_name }}</td>
                    <td class="px-3 py-2 text-xs font-mono">{{ r.student_id }}</td>
                    <td class="hidden sm:table-cell px-3 py-2">{{ r.program || 'N/A' }}</td>
                    <td class="hidden lg:table-cell px-3 py-2">{{ r.year_level || 'N/A' }}</td>
                    <td class="px-3 py-2">{{ (r.amount_paid || r.amount || paymentToExport.amount_due || '') ? `₱${(r.amount_paid || r.amount || paymentToExport.amount_due).toLocaleString('en-PH', { minimumFractionDigits: 2 })}` : '-' }}</td>
                    <td class="px-3 py-2">{{ r.paid_by_treasurer ? (typeof r.paid_by_treasurer === 'string' ? r.paid_by_treasurer : (r.paid_by_treasurer?.first_name || '') + ' ' + (r.paid_by_treasurer?.last_name || '') ) : formatPaidByName(r) }}</td>
                    <td class="px-3 py-2">{{ r.payment_status === 'paid' && r.paid_date ? new Date(r.paid_date).toLocaleString() : 'N/A' }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          <div class="mt-5 flex items-center gap-3 justify-end">
            <button @click="(showPaymentDownloadConfirm = false, paymentToExport = null)" class="px-4 py-2 bg-gray-100 rounded-lg text-sm hover:bg-gray-200">Cancel</button>
            <button @click="confirmAndExportPaymentRecords" class="px-4 py-2 bg-green-600 text-white rounded-lg text-sm hover:bg-green-700 flex items-center gap-2">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
              <span>Export {{ getFilteredPaymentRecordCount(paymentToExport) }} records</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  </transition>

  <!-- Payment Scanner -->
          <div v-if="selectedPayment" class="bg-white rounded-lg shadow-lg p-4 md:p-8">
            <div class="flex justify-between items-center mb-6">
              <h3 class="text-xl font-bold text-gray-900">{{ selectedPayment.title }} - Student Scanner</h3>
              <button @click="selectedPayment = null" class="text-gray-500 hover:text-gray-700 text-2xl">&times;</button>
            </div>

            <div class="grid grid-cols-1 md:grid-cols-2 gap-8">
              <!-- Scanner Input -->
              <div class="space-y-4">
                <div class="bg-blue-50 rounded-lg p-6 border-2 border-blue-200">
                  <div class="text-center mb-4">
                    <div class="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-3">
                      <svg class="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V8a2 2 0 00-2-2h-5m-4 0V5a2 2 0 114 0v1m-4 0a2 2 0 104 0m-5 8a2 2 0 100-4 2 2 0 000 4zm0 0c1.306 0 2.417.835 2.83 2M9 14a3.001 3.001 0 00-2.83 2"></path>
                      </svg>
                    </div>
                    <h4 class="font-bold text-blue-900">Scan Student ID or RFID</h4>
                  </div>
                  
                  <input 
                    v-model="paymentSearchQuery" 
                    type="text" 
                    placeholder="Enter Student ID or scan RFID"
                    @keydown.enter="markPaymentAsPaid(selectedPayment._id)"
                    class="w-full px-4 py-3 bg-white border-2 border-blue-200 rounded-lg text-center font-mono focus:border-blue-500 outline-none"
                  />
                </div>

                <button 
                  @click="markPaymentAsPaid(selectedPayment._id)"
                  :disabled="!paymentSearchQuery.trim()"
                  class="w-full py-3 bg-gradient-to-r from-ssaam-dark to-ssaam-light text-white rounded-lg font-bold hover:from-ssaam-dark hover:to-ssaam-light transition disabled:opacity-50"
                >
                 Mark as Paid
                </button>
              </div>

              <!-- Payment Stats -->
              <div class="space-y-4">
                <div class="bg-gradient-to-br from-green-50 to-emerald-50 rounded-lg p-4 border border-green-200">
                  <p class="text-sm text-green-800 mb-1">Total Students</p>
                  <p class="text-3xl font-bold text-green-600">{{ selectedPayment.stats.total_students }}</p>
                </div>

                <div class="bg-gradient-to-br from-blue-50 to-cyan-50 rounded-lg p-4 border border-blue-200">
                  <p class="text-sm text-blue-800 mb-1">Paid</p>
                  <p class="text-3xl font-bold text-blue-600">{{ selectedPayment.stats.paid_count }}</p>
                </div>

                <div class="bg-gradient-to-br from-red-50 to-blue-50 rounded-lg p-4 border border-red-200">
                  <p class="text-sm text-red-800 mb-1">Still Unpaid</p>
                  <p class="text-3xl font-bold text-red-600">{{ Math.max(0, (selectedPayment.stats?.total_students || 0) - (selectedPayment.stats?.paid_count || 0)) }}</p>
                </div>

                <div class="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-lg p-4 border border-blue-200">
                  <p class="text-sm text-blue-800 mb-1">Completion Rate</p>
                  <p class="text-3xl font-bold text-blue-600">{{ selectedPayment.stats.completion_percentage }}%</p>
                  <div class="w-full bg-gray-200 rounded-full h-2 mt-2">
                    <div class="bg-blue-600 h-2 rounded-full transition-all" :style="{ width: selectedPayment.stats.completion_percentage + '%' }"></div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Pending Approvals Page -->
        <div v-if="currentPage === 'pending' && (isAdminLike)" class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
          <div :class="['relative h-24 sm:h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
            <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
            <div class="light-sweep"></div>
            <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
              <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white/20 flex items-center justify-center flex-shrink-0">
                <svg class="w-5 h-5 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              </div>
              <div class="flex-1 min-w-0">
                <h2 class="text-lg sm:text-xl font-extrabold text-white tracking-tight">Pending Approvals</h2>
                <p class="text-white/70 text-xs sm:text-sm mt-0.5">Review and approve or reject student registrations</p>
              </div>
              <button @click="refreshPendingSection" :disabled="pendingLoading" class="px-3 sm:px-4 py-2 rounded-xl text-white text-sm font-semibold bg-white/20 hover:bg-white/30 border border-white/20 transition flex items-center gap-2 disabled:opacity-60 flex-shrink-0">
                <svg :class="['w-4 h-4', pendingLoading ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                <span class="hidden sm:inline">Refresh</span>
              </button>
            </div>
          </div>
          <div class="p-3 sm:p-4 md:p-6">

          <!-- Search Input for Pending Students -->
          <div class="mb-4">
            <div class="relative">
              <svg class="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
              <input v-model="pendingSearchQuery" @input="filterPendingStudents" type="text" placeholder="Search by name, email, student ID, or RFID..." :class="['w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 outline-none', isCOE ? 'focus:ring-orange-600 focus:border-transparent' : isSOM ? 'focus:ring-green-600 focus:border-transparent' : 'focus:ring-blue-600 focus:border-transparent']" />
            </div>
            <p class="text-xs text-gray-500 mt-1">Search across name, email, student ID, and RFID code</p>
          </div>

          <div v-if="pendingLoading" class="flex items-center justify-center py-12">
            <svg :class="['animate-spin h-10 w-10', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          </div>

          <div v-else-if="filteredPendingStudents.length === 0 && pendingSearchQuery" class="text-center py-12">
            <div class="w-20 h-20 mx-auto mb-4 bg-gray-100 rounded-full flex items-center justify-center">
              <svg class="w-10 h-10 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
            </div>
            <h3 class="text-lg font-semibold text-gray-700 mb-2">No results found</h3>
            <p class="text-gray-500">No pending students match "{{ pendingSearchQuery }}"</p>
          </div>

          <div v-else-if="pendingStudents.length === 0" class="text-center py-12">
            <div class="w-20 h-20 mx-auto mb-4 bg-green-100 rounded-full flex items-center justify-center">
              <svg class="w-10 h-10 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h3 class="text-lg font-semibold text-gray-700 mb-2">All caught up!</h3>
            <p class="text-gray-500">No pending student registrations to review.</p>
          </div>

          <div v-else class="space-y-4">
            <div class="flex items-center justify-between text-sm text-gray-500 mb-2">
              <span>Showing {{ paginatedPendingStudents.length }} of {{ filteredPendingStudents.length }} pending student{{ filteredPendingStudents.length === 1 ? '' : 's' }}</span>
            </div>
            <div v-for="student in paginatedPendingStudents" :key="student.student_id" :class="['border rounded-xl p-4 md:p-6 hover:shadow-md transition-shadow', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : isCNAHS ? 'border-green-200' : 'border-gray-200']">
              <div class="flex flex-col md:flex-row gap-4">
                <div class="flex-shrink-0">
                  <div :class="['w-20 h-20 rounded-full flex items-center justify-center overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-yellow-600' : isCNAHS ? 'bg-gradient-to-br from-green-600 to-green-800' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']" :style="{ background: profileGradient }">
                    <img v-if="student.photo" :src="student.photo" alt="Student Photo" class="w-full h-full object-cover rounded-full" />
                    <img v-else src="/user.svg" alt="No Photo" class="w-10 h-10 brightness-0 invert" />
                  </div>
                </div>
                <div class="flex-1">
                  <div class="flex flex-col md:flex-row md:items-center justify-between gap-2 mb-3">
                    <div>
                      <h3 :class="['text-lg font-semibold', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">{{ student.first_name }} {{ student.middle_name || '' }} {{ student.last_name }} {{ student.suffix || '' }}</h3>
                      <p class="text-sm text-gray-500">{{ student.student_id }}</p>
                    </div>
                    <span class="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800 w-fit">
                      <svg class="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clip-rule="evenodd" /></svg>
                      Pending Review
                    </span>
                  </div>
                  <div class="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm mb-4">
                    <div>
                      <p class="text-gray-500">Program</p>
                      <p class="font-medium text-gray-800">{{ student.program }}</p>
                    </div>
                    <div>
                      <p class="text-gray-500">Year Level</p>
                      <p class="font-medium text-gray-800">{{ student.year_level }}</p>
                    </div>
                    <div>
                      <p class="text-gray-500">Email</p>
                      <p class="font-medium text-gray-800 truncate">{{ student.email || 'N/A' }}</p>
                    </div>
                    <div>
                      <p class="text-gray-500">Registered</p>
                      <p class="font-medium text-gray-800">{{ formatDate(student.created_date) }}</p>
                    </div>
                  </div>
                  <div class="flex flex-wrap gap-2">
                    <button @click="approveStudent(student)" :disabled="approvingStudent === student.student_id" :class="['bg-green-500 text-white px-4 py-2 rounded-lg hover:bg-green-600 transition-all duration-200 font-medium text-sm flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed']">
                      <svg v-if="approvingStudent === student.student_id" class="w-4 h-4 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                      <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg>
                      {{ approvingStudent === student.student_id ? 'Approving...' : 'Approve' }}
                    </button>
                    <button @click="openRejectModal(student)" :class="['bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition-all duration-200 font-medium text-sm flex items-center gap-2']">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                      Reject
                    </button>
                  </div>
                </div>
              </div>
            </div>
            
            <!-- Pagination Controls for Pending Students -->
            <div v-if="pendingTotalPages > 1" class="flex items-center justify-center gap-2 mt-6 pt-4 border-t border-gray-200">
              <button @click="pendingCurrentPage = 1" :disabled="pendingCurrentPage === 1" class="px-3 py-2 rounded-lg border border-gray-300 text-sm font-medium hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition">
                First
              </button>
              <button @click="pendingCurrentPage--" :disabled="pendingCurrentPage === 1" class="px-3 py-2 rounded-lg border border-gray-300 text-sm font-medium hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"></path></svg>
              </button>
              <span class="px-4 py-2 text-sm font-medium text-gray-700">
                Page {{ pendingCurrentPage }} of {{ pendingTotalPages }}
              </span>
              <button @click="pendingCurrentPage++" :disabled="pendingCurrentPage === pendingTotalPages" class="px-3 py-2 rounded-lg border border-gray-300 text-sm font-medium hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition">
                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
              </button>
              <button @click="pendingCurrentPage = pendingTotalPages" :disabled="pendingCurrentPage === pendingTotalPages" class="px-3 py-2 rounded-lg border border-gray-300 text-sm font-medium hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition">
                Last
              </button>
            </div>
          </div>
          </div>
        </div>

        <!-- Reject Modal -->
        <div v-if="showRejectModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" @click.self="showRejectModal = false">
          <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-md w-full mx-4">
            <h3 class="text-xl font-bold text-red-600 mb-4">Reject Student Registration</h3>
            <p class="text-gray-600 mb-4">Are you sure you want to reject <span class="font-semibold">{{ studentToReject?.first_name }} {{ studentToReject?.last_name }}</span>'s registration?</p>
            <div class="mb-4">
              <label class="block text-sm font-medium text-gray-700 mb-2">Reason for rejection (optional)</label>
              <textarea v-model="rejectReason" placeholder="Enter a reason to include in the notification email..." class="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none resize-none" rows="3"></textarea>
            </div>
            <div class="flex gap-3">
              <button @click="showRejectModal = false" class="flex-1 bg-gray-200 text-gray-800 py-2 px-4 rounded-lg font-medium hover:bg-gray-300 transition">Cancel</button>
              <button @click="confirmRejectStudent" :disabled="rejectingStudent" class="flex-1 bg-red-500 text-white py-2 px-4 rounded-lg font-medium hover:bg-red-600 transition flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed">
                <svg v-if="rejectingStudent" class="w-4 h-4 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                {{ rejectingStudent ? 'Rejecting...' : 'Reject' }}
              </button>
            </div>
          </div>
        </div>

        <!-- User Management Page -->
        <div v-if="currentPage === 'users' && (isAdminLike)" class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
          <div :class="['relative h-24 sm:h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
            <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
            <div class="light-sweep"></div>
            <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
              <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white/20 flex items-center justify-center flex-shrink-0">
                <svg class="w-5 h-5 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              </div>
              <div class="flex-1 min-w-0">
                <h2 class="text-lg sm:text-xl font-extrabold text-white tracking-tight">Manage Users</h2>
                <p class="text-white/70 text-xs sm:text-sm mt-0.5">View, search, edit, and manage student accounts</p>
              </div>
              <button @click="refreshStudents" :disabled="isRefreshing" class="px-3 sm:px-4 py-2 rounded-xl text-white text-sm font-semibold bg-white/20 hover:bg-white/30 border border-white/20 transition flex items-center gap-2 disabled:opacity-60 flex-shrink-0">
                <svg :class="['w-4 h-4', isRefreshing ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                <span class="hidden sm:inline">{{ isRefreshing ? 'Refreshing...' : 'Refresh' }}</span>
              </button>
            </div>
          </div>
          <div class="p-3 sm:p-4 md:p-6">
          <div class="mb-4">
            <div class="flex flex-col sm:flex-row gap-3">
              <div class="flex-1 relative">
                <svg class="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <input v-model="searchQuery" @change="handleSearchChange" type="text" placeholder="Search by Name, Email, Student ID, or RFID Code..." class="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none text-sm" />
              </div>
              <div class="relative min-w-[140px]">
                <select v-model="filterProgram" @change="handleSearchChange" class="w-full appearance-none bg-white border border-gray-300 rounded-lg px-4 py-2 pr-8 focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none text-sm">
                  <option value="">All Programs</option>
                  <option value="BSCS">BSCS</option>
                  <option value="BSIS">BSIS</option>
                  <option value="BSIT">BSIT</option>
                </select>
                <svg class="absolute right-2 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-500 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>
              </div>
              <div class="relative min-w-[120px]">
                <select v-model="filterSchoolLevel" @change="handleSearchChange" class="w-full appearance-none bg-white border border-gray-300 rounded-lg px-4 py-2 pr-8 focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none text-sm">
                  <option value="">All Levels</option>
                  <option value="1st Year">1st Year</option>
                  <option value="2nd Year">2nd Year</option>
                  <option value="3rd Year">3rd Year</option>
                  <option value="4th Year">4th Year</option>
                </select>
                <svg class="absolute right-2 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-500 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>
              </div>
              <div class="relative min-w-[140px]">
                <select v-model="filterRfidStatus" @change="handleSearchChange" class="w-full appearance-none bg-white border border-gray-300 rounded-lg px-4 py-2 pr-8 focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none text-sm">
                  <option value="">All RFID Status</option>
                  <option value="verified">Verified</option>
                  <option value="unverified">Unverified</option>
                  <option value="Unreadable">Unreadable</option>
                </select>
                <svg class="absolute right-2 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-500 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>
              </div>
            </div>
          </div>

          <!-- Mobile Card List -->
          <div class="block sm:hidden divide-y divide-gray-100 -mx-3 sm:mx-0 mb-2">
            <div v-if="filteredUsers.length === 0" class="px-4 py-8 text-center text-gray-500 text-sm">No users found matching your search.</div>
            <div v-for="user in filteredUsers" :key="user.studentId || user.student_id" class="px-4 py-4 hover:bg-gray-50 transition">
              <div class="flex items-center gap-3 mb-3">
                <div :class="['w-10 h-10 rounded-full flex items-center justify-center text-white text-sm font-bold flex-shrink-0', isCOE ? 'bg-gradient-to-br from-orange-500 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-500 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-500 to-green-700' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                  {{ ((user.firstName || user.first_name || '?').charAt(0)).toUpperCase() }}
                </div>
                <div class="flex-1 min-w-0">
                  <p class="font-semibold text-gray-900 text-sm truncate">{{ (user.firstName || user.first_name) }} {{ (user.lastName || user.last_name) }}</p>
                  <p class="text-xs text-gray-500 font-mono truncate">{{ user.studentId || user.student_id }}</p>
                </div>
                <span :class="['px-2 py-1 rounded-full text-xs font-medium flex-shrink-0', (user.rfid_status === 'verified') ? 'bg-green-100 text-green-800' : (user.rfid_status === 'Unreadable') ? 'bg-gray-100 text-gray-800' : 'bg-yellow-100 text-yellow-800']">
                  {{ (user.rfid_status === 'verified') ? 'Verified' : (user.rfid_status === 'Unreadable') ? 'Unreadable' : 'Unverified' }}
                </span>
              </div>
              <div class="grid grid-cols-2 gap-1.5 text-xs text-gray-600 mb-3 bg-gray-50 rounded-lg p-2">
                <div><span class="text-gray-400">Program:</span> <span class="font-medium">{{ user.program || '—' }}</span></div>
                <div><span class="text-gray-400">Level:</span> <span class="font-medium">{{ user.yearLevel || user.year_level || '—' }}</span></div>
                <div class="col-span-2 truncate"><span class="text-gray-400">Email:</span> <span class="font-medium">{{ user.email || '—' }}</span></div>
                <div class="col-span-2 truncate"><span class="text-gray-400">RFID:</span> <span class="font-mono font-medium">{{ user.rfidCode || user.rfid_code || '—' }}</span></div>
              </div>
              <div class="flex gap-2">
                <button @click="editUser(user)" :class="['flex-1 py-2 rounded-lg transition flex items-center justify-center gap-2 text-sm font-medium text-white', isCOE ? 'bg-orange-500 hover:bg-orange-600' : 'bg-blue-500 hover:bg-blue-600']">
                  <img src="/edit.svg" alt="Edit" class="w-4 h-4" style="filter: brightness(0) invert(1);" />
                  Edit
                </button>
                <button @click="deleteUser(user.studentId || user.student_id)" class="flex-1 bg-red-500 text-white py-2 rounded-lg hover:bg-red-600 transition flex items-center justify-center gap-2 text-sm font-medium">
                  <img src="/delete.svg" alt="Delete" class="w-4 h-4" style="filter: brightness(0) invert(1);" />
                  Delete
                </button>
              </div>
            </div>
          </div>

          <!-- Desktop Table -->
          <div class="hidden sm:block overflow-x-auto">
            <table class="w-full border-collapse text-sm">
              <thead>
                <tr class="bg-blue-100">
                  <th class="border border-blue-300 px-4 py-3 text-left font-semibold text-blue-900">Name</th>
                  <th class="border border-blue-300 px-4 py-3 text-left font-semibold text-blue-900">Student ID</th>
                  <th class="border border-blue-300 px-4 py-3 text-left font-semibold text-blue-900">Email</th>
                  <th class="border border-blue-300 px-4 py-3 text-center font-semibold text-blue-900">RFID Code</th>
                  <th class="border border-blue-300 px-4 py-3 text-center font-semibold text-blue-900">RFID Status</th>
                  <th class="border border-blue-300 px-4 py-3 text-center font-semibold text-blue-900">Program</th>
                  <th class="border border-blue-300 px-4 py-3 text-center font-semibold text-blue-900">School Level</th>
                  <th class="border border-blue-300 px-4 py-3 text-center font-semibold text-blue-900">Actions</th>
                </tr>
              </thead>
              <tbody>
                <tr v-if="filteredUsers.length === 0" class="hover:bg-gray-50">
                  <td colspan="8" class="border border-blue-300 px-4 py-8 text-center text-gray-600">No users found matching your search.</td>
                </tr>
                <tr v-for="user in filteredUsers" :key="user.studentId || user.student_id" class="hover:bg-gray-50">
                  <td class="border border-blue-300 px-4 py-3 text-gray-700">{{ (user.firstName || user.first_name) }} {{ (user.lastName || user.last_name) }}</td>
                  <td class="border border-blue-300 px-4 py-3 text-gray-700 text-xs font-mono">{{ user.studentId || user.student_id }}</td>
                  <td class="border border-blue-300 px-4 py-3 text-gray-700">{{ user.email }}</td>
                  <td class="border border-blue-300 px-4 py-3 text-center text-gray-700">{{ user.rfidCode || user.rfid_code || '—' }}</td>
                  <td class="border border-blue-300 px-4 py-3 text-center">
                    <span :class="['px-2 py-1 rounded-full text-xs font-medium', (user.rfid_status === 'verified') ? 'bg-green-100 text-green-800' : (user.rfid_status === 'Unreadable') ? 'bg-gray-100 text-gray-800' : 'bg-yellow-100 text-yellow-800']">
                      {{ (user.rfid_status === 'verified') ? 'Verified' : (user.rfid_status === 'Unreadable') ? 'Unreadable' : 'Unverified' }}
                    </span>
                  </td>
                  <td class="border border-blue-300 px-4 py-3 text-center text-gray-700">{{ user.program }}</td>
                  <td class="border border-blue-300 px-4 py-3 text-center text-gray-700">{{ user.yearLevel || user.year_level }}</td>
                  <td class="border border-blue-300 px-4 py-3 text-center">
                    <div class="flex items-center justify-center gap-2 flex-nowrap">
                      <button @click="editUser(user)" class="bg-blue-500 text-white p-2 rounded-lg hover:bg-blue-600 transition-all duration-200 hover:scale-110 active:scale-95 flex-shrink-0" title="Edit User">
                        <img src="/edit.svg" alt="Edit" class="w-4 h-4 min-w-[16px] min-h-[16px]" style="filter: brightness(0) invert(1);" />
                      </button>
                      <button @click="deleteUser(user.studentId || user.student_id)" class="bg-red-500 text-white p-2 rounded-lg hover:bg-red-600 transition-all duration-200 hover:scale-110 active:scale-95 flex-shrink-0" title="Delete User">
                        <img src="/delete.svg" alt="Delete" class="w-4 h-4 min-w-[16px] min-h-[16px]" style="filter: brightness(0) invert(1);" />
                      </button>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <!-- Pagination Controls -->
          <div v-if="paginationTotal > 0" class="mt-6 pt-6 border-t border-gray-200">
            <div class="text-sm text-gray-600 mb-4">
              Showing page <span class="font-semibold text-blue-900">{{ currentPageNum }}</span> of <span class="font-semibold text-blue-900">{{ totalPages }}</span> ({{ paginationTotal }} total students)
            </div>
            <div class="flex flex-wrap gap-2 items-center justify-center md:justify-start">
              <div class="flex gap-1">
                <button @click="goToPreviousPage" :disabled="currentPageNum === 1" class="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed font-medium text-sm">
                  Previous
                </button>
                <button @click="goToNextPage" :disabled="currentPageNum >= totalPages" class="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed font-medium text-sm">
                  Next
                </button>
              </div>
              
              <div class="flex gap-1">
                <button v-for="page in visiblePages" :key="page" @click="goToPage(page)" :class="['px-3 py-2 rounded-lg font-medium text-sm transition-all duration-200', currentPageNum === page ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-800 hover:bg-gray-300']">
                  {{ page }}
                </button>
              </div>
              
              <div class="flex gap-1">
                <button @click="goToPage(1)" :disabled="currentPageNum === 1" class="bg-blue-600 text-white px-3 py-2 rounded-lg hover:bg-blue-700 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed font-medium text-sm">
                  ← First
                </button>
                <button @click="goToPage(totalPages)" :disabled="currentPageNum === totalPages" class="bg-blue-600 text-white px-3 py-2 rounded-lg hover:bg-blue-700 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed font-medium text-sm">
                  Last →
                </button>
              </div>
            </div>
          </div>
          </div>
        </div>

        <!-- Admin Contribution Panel - visible for admin/co-admin -->
        <AdminContributionPanel v-if="currentPage === 'contributions' && (isAdminLike)" />

        <!-- Admin Raffle Ticket Panel - visible for admin/co-admin -->
        <AdminRaffleTicketPanel v-if="currentPage === 'raffle-tickets' && (isAdminLike)" />

        <!-- Audit Trail - treasurer sees own logs, co-admin sees college-wide logs -->
        <AuditTrailPanel v-if="currentPage === 'audit-trail' && (isTreasurer || isCoAdmin)" :currentUser="currentUser" />

        <!-- Student Raffle Results - visible for students only -->
        <StudentRaffleResultsView v-if="currentPage === 'my-raffle' && currentUser.role !== 'admin' && !currentUser.isMaster" />

        <!-- Manage Page (Roles & Users) -->
        <Manage ref="manageComponent" v-if="currentPage === 'manage' && (isAdminLike)" />

        <!-- Admin / Co-Admin Profile Page -->
        <div v-if="false" class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden mb-8">
          <!-- Hidden file input for photo upload -->
          <input ref="adminPhotoFileRef" type="file" accept="image/*" class="hidden" @change="handleAdminPhotoUpload" />

          <!-- Profile Banner with college-aware gradient -->
          <div :class="['relative h-44 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 via-red-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 via-teal-600 to-teal-700' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 via-green-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
            <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
            <div :class="['absolute -top-20 -right-20 w-72 h-72 rounded-full blur-3xl animate-pulse', isCOE ? 'bg-red-400/20' : isSOM ? 'bg-teal-400/20' : isCNAHS ? 'bg-green-400/20' : 'bg-blue-500/20']"></div>
            <div :class="['absolute -bottom-20 -left-20 w-72 h-72 rounded-full blur-3xl animate-pulse-slow', isCOE ? 'bg-orange-400/20' : isSOM ? 'bg-green-400/20' : isCNAHS ? 'bg-emerald-400/20' : 'bg-blue-400/20']"></div>
            <div class="light-sweep"></div>
            <!-- Role badge in banner -->
            <div class="absolute top-4 right-4">
              <span class="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full text-xs font-bold shadow-lg" :class="currentUser.isMaster ? 'bg-gradient-to-r from-yellow-400 to-amber-500 text-white' : 'bg-white/20 text-white border border-white/30'">
                <img v-if="currentUser.isMaster" src="/crown.svg" alt="" class="w-3.5 h-3.5 brightness-0 invert" />
                {{ currentUser.role === 'co-admin' ? 'Co-Admin' : 'Admin' }}
                <span v-if="currentUser.role === 'co-admin' && currentUser.college" class="font-normal opacity-80">({{ currentUser.college }})</span>
              </span>
            </div>
          </div>

          <div v-if="adminProfileLoading" class="flex items-center justify-center py-16">
            <svg :class="['animate-spin w-10 h-10', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
          </div>

          <div v-else-if="adminProfile" class="px-6 md:px-8 pb-8">
            <!-- Avatar + Name Row -->
            <div class="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-4 -mt-16 mb-8">
              <div class="flex items-end gap-4">
                <!-- Avatar with upload overlay -->
                <div class="relative group flex-shrink-0">
                  <div :class="['w-28 h-28 rounded-3xl overflow-hidden ring-4 ring-white shadow-2xl flex items-center justify-center', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-400 to-green-600' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                    <img v-if="adminProfileForm.photo || adminProfile.photo" :src="adminProfileForm.photo || adminProfile.photo" alt="Profile Photo" class="w-full h-full object-cover" @error="(e) => e.target.style.display='none'" />
                    <span v-else class="text-4xl font-bold text-white">{{ (adminProfile.username || 'A').charAt(0).toUpperCase() }}</span>
                  </div>
                  <!-- Upload overlay -->
                  <button @click="adminPhotoFileRef && adminPhotoFileRef.click()" class="absolute inset-0 rounded-3xl bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center cursor-pointer" type="button">
                    <div class="text-center">
                      <svg class="w-6 h-6 text-white mx-auto mb-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                      <p class="text-white text-[10px] font-bold">Upload</p>
                    </div>
                  </button>
                </div>
                <div class="pb-1">
                  <h2 class="text-2xl font-extrabold text-gray-900 tracking-tight">{{ adminProfile.full_name || adminProfile.username }}</h2>
                  <p class="text-sm text-gray-500">@{{ adminProfile.username }}</p>
                  <p :class="['text-xs font-medium mt-1', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']">{{ adminProfile.college || currentUser.college || 'All Colleges' }}</p>
                </div>
              </div>
            </div>

            <!-- Info Cards Row -->
            <div class="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">
              <div class="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Email</p>
                <p v-if="adminProfile.email" class="text-gray-900 font-semibold text-sm truncate">{{ adminProfile.email }}</p>
                <p v-else class="text-gray-400 text-sm italic">No email set</p>
              </div>
              <div class="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Phone</p>
                <p v-if="adminProfile.phone" class="text-gray-900 font-semibold text-sm">{{ adminProfile.phone }}</p>
                <p v-else class="text-gray-400 text-sm italic">No phone set</p>
              </div>
              <div class="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">College</p>
                <p class="text-gray-900 font-semibold text-sm">{{ adminProfile.college || currentUser.college || 'All Colleges' }}</p>
              </div>
            </div>

            <!-- Bio Card -->
            <div v-if="adminProfile.bio || adminProfileForm.bio" class="mb-8 p-4 bg-blue-50/40 rounded-2xl border border-blue-100">
              <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">About</p>
              <p class="text-gray-700 text-sm leading-relaxed">{{ adminProfile.bio || '—' }}</p>
            </div>

            <!-- Edit Form -->
            <div class="space-y-6">
              <div>
                <div class="flex items-center gap-2 mb-4">
                  <div :class="['w-1 h-6 rounded-full', isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-600' : 'bg-blue-600']"></div>
                  <h3 :class="['text-sm font-bold uppercase tracking-widest', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : isCNAHS ? 'text-green-400' : 'text-gray-400']">Edit Profile</h3>
                </div>
                <!-- Photo Upload Section -->
                <div class="mb-4 p-4 bg-gray-50 rounded-2xl border border-gray-200">
                  <p class="text-xs font-semibold text-gray-600 mb-3">Profile Photo</p>
                  <div class="flex items-center gap-4">
                    <div :class="['w-16 h-16 rounded-2xl overflow-hidden ring-2 ring-white shadow-md flex items-center justify-center flex-shrink-0', isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-400 to-green-600' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
                      <img v-if="adminProfileForm.photo || adminProfile.photo" :src="adminProfileForm.photo || adminProfile.photo" alt="" class="w-full h-full object-cover" @error="(e) => e.target.style.display='none'" />
                      <svg v-else class="w-7 h-7 text-white/70" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
                    </div>
                    <div class="flex-1 min-w-0">
                      <button @click="adminPhotoFileRef && adminPhotoFileRef.click()" :class="['w-full py-2.5 px-4 border-2 border-dashed rounded-xl text-sm font-medium transition-all flex items-center justify-center gap-2', isCOE ? 'border-orange-300 text-orange-600 hover:bg-orange-50 hover:border-orange-400' : isSOM ? 'border-green-300 text-green-600 hover:bg-green-50 hover:border-green-400' : isCNAHS ? 'border-green-300 text-green-600 hover:bg-green-50 hover:border-green-400' : 'border-blue-300 text-blue-600 hover:bg-blue-50 hover:border-blue-400']" type="button">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"/></svg>
                        Choose Photo
                      </button>
                      <p v-if="adminProfileForm.photo && adminProfileForm.photo.startsWith('data:')" class="text-xs text-green-600 mt-1.5 font-medium text-center">✓ New photo selected — save to apply</p>
                      <p v-else class="text-xs text-gray-400 mt-1.5 text-center">JPG, PNG or GIF · Max 5MB</p>
                    </div>
                    <button v-if="adminProfileForm.photo" @click="adminProfileForm.photo = ''" type="button" class="p-1.5 text-gray-400 hover:text-red-500 transition flex-shrink-0" title="Remove photo">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                  </div>
                </div>
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label class="block text-xs font-semibold text-gray-600 mb-1">Full Name</label>
                    <input v-model="adminProfileForm.full_name" type="text" placeholder="Your full name" :class="['w-full px-3 py-2.5 border border-gray-200 rounded-xl focus:ring-2 outline-none text-sm bg-gray-50 focus:bg-white transition', isCOE ? 'focus:ring-orange-300 focus:border-orange-400' : isSOM ? 'focus:ring-green-300 focus:border-green-400' : isCNAHS ? 'focus:ring-green-300 focus:border-green-400' : 'focus:ring-blue-400']" />
                  </div>
                  <div>
                    <label class="block text-xs font-semibold text-gray-600 mb-1">Phone</label>
                    <input v-model="adminProfileForm.phone" type="text" placeholder="Contact number" :class="['w-full px-3 py-2.5 border border-gray-200 rounded-xl focus:ring-2 outline-none text-sm bg-gray-50 focus:bg-white transition', isCOE ? 'focus:ring-orange-300 focus:border-orange-400' : isSOM ? 'focus:ring-green-300 focus:border-green-400' : isCNAHS ? 'focus:ring-green-300 focus:border-green-400' : 'focus:ring-blue-400']" />
                  </div>
                </div>
                <div class="mt-4">
                  <label class="block text-xs font-semibold text-gray-600 mb-1">Bio</label>
                  <textarea v-model="adminProfileForm.bio" rows="3" placeholder="Brief description about yourself..." :class="['w-full px-3 py-2.5 border border-gray-200 rounded-xl focus:ring-2 outline-none text-sm resize-none bg-gray-50 focus:bg-white transition', isCOE ? 'focus:ring-orange-300 focus:border-orange-400' : isSOM ? 'focus:ring-green-300 focus:border-green-400' : isCNAHS ? 'focus:ring-green-300 focus:border-green-400' : 'focus:ring-blue-400']"></textarea>
                </div>
              </div>

              <div class="border-t border-gray-100 pt-6">
                <div class="flex items-center gap-2 mb-4">
                  <div class="w-1 h-6 rounded-full bg-blue-600"></div>
                  <h3 class="text-sm font-bold text-gray-400 uppercase tracking-widest">Security</h3>
                </div>
                <div class="p-5 bg-gray-50 rounded-2xl border border-gray-100">
                  <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label class="block text-xs font-semibold text-gray-600 mb-1">Current Password</label>
                      <input v-model="adminProfileForm.current_password" type="password" placeholder="Current password" class="w-full px-3 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-400 outline-none text-sm bg-white transition" />
                    </div>
                    <div>
                      <label class="block text-xs font-semibold text-gray-600 mb-1">New Password</label>
                      <input v-model="adminProfileForm.new_password" type="password" placeholder="New password (min 8 chars)" class="w-full px-3 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-400 outline-none text-sm bg-white transition" />
                    </div>
                  </div>
                </div>
              </div>

              <div class="flex flex-col sm:flex-row gap-3">
                <button @click="saveAdminProfile" :disabled="adminProfileSaving" :class="['flex-1 text-white py-2.5 px-6 rounded-xl font-bold transition-all hover:scale-[1.02] flex items-center justify-center gap-2 disabled:opacity-60 shadow-lg bg-gradient-to-r', isCOE ? 'from-orange-600 to-red-700 shadow-orange-200' : isSOM ? 'from-green-600 to-teal-700 shadow-green-200' : isCNAHS ? 'from-emerald-600 to-green-700 shadow-green-200' : 'from-ssaam-dark to-ssaam-light shadow-blue-200']">
                  <svg v-if="adminProfileSaving" class="animate-spin w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                  <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>
                  {{ adminProfileSaving ? 'Saving...' : 'Save Changes' }}
                </button>
              </div>

              <!-- Co-Admin Transfer Role Section -->
              <div v-if="currentUser.role === 'co-admin'" class="border-t border-gray-100 pt-6">
                <div class="flex items-center gap-2 mb-4">
                  <div class="w-1 h-6 rounded-full bg-orange-500"></div>
                  <h3 class="text-sm font-bold text-gray-400 uppercase tracking-widest">Transfer Role</h3>
                </div>
                <p class="text-xs text-gray-500 mb-3">Transfer your co-admin responsibilities to another account. You will be removed and the target account will take over.</p>
                <div class="flex gap-2">
                  <input v-model="transferTargetUsername" type="text" placeholder="Target username" class="flex-1 px-3 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-400 outline-none text-sm bg-gray-50" />
                  <button @click="requestTransferRole" :disabled="transferringRole" class="px-5 py-2.5 bg-orange-600 hover:bg-orange-700 text-white rounded-xl text-sm font-bold transition disabled:opacity-60">
                    {{ transferringRole ? 'Transferring...' : 'Transfer' }}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Student Location Section — mirrors the admin Scanner geofence preview -->
        <div v-if="currentPage === 'location' && currentUser.role !== 'admin' && !currentUser.isMaster" class="space-y-6">
          <div class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div :class="['relative h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
              <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
              <div class="light-sweep"></div>
              <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
                <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl flex items-center justify-center flex-shrink-0 bg-white/20">
                  <svg class="w-5 h-5 sm:w-6 sm:h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                </div>
                <div class="min-w-0">
                  <h2 class="text-white text-base sm:text-lg md:text-xl font-bold leading-tight">My Location</h2>
                  <p class="text-white/80 text-xs sm:text-sm">See where you are relative to today's check-in zones.</p>
                </div>
              </div>
            </div>

            <div class="p-3 sm:p-4 md:p-6 space-y-3 sm:space-y-4">
              <!-- Quick description: tells the student what these maps are for
                   so they understand the location pin isn't generic — it's the
                   exact area where face-scan attendance is allowed. -->
              <div :class="['flex items-start gap-3 px-4 py-3 rounded-2xl border', isCOE ? 'bg-orange-50 border-orange-200 text-orange-900' : isSOM ? 'bg-green-50 border-green-200 text-green-900' : isCNAHS ? 'bg-emerald-50 border-emerald-200 text-emerald-900' : 'bg-blue-50 border-blue-200 text-blue-900']">
                <div :class="['flex-shrink-0 w-9 h-9 rounded-xl flex items-center justify-center', isCOE ? 'bg-orange-100 text-orange-600' : isSOM ? 'bg-green-100 text-green-600' : isCNAHS ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600']">
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
                </div>
                <div class="flex-1 text-xs sm:text-sm leading-relaxed">
                  <p class="font-bold mb-0.5">What these locations show</p>
                  <p class="opacity-90">Each map below pins the exact area where you're eligible to record attendance for the event using a face scan. As long as your live location stays inside the highlighted circle, you can mark your own attendance — step outside it and the face scanner is disabled.</p>
                </div>
              </div>

              <div v-if="attendanceLoading" class="flex items-center justify-center py-12">
                <svg :class="['animate-spin h-8 w-8', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" fill="none" viewBox="0 0 24 24">
                  <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                  <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
                </svg>
              </div>
              <div v-else-if="locationEvents.length === 0" class="text-center py-12 text-gray-500">
                <svg class="w-14 h-14 mx-auto mb-3 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                <p class="text-sm">No active events with a check-in zone right now.</p>
                <p class="text-xs mt-1 text-gray-400">When an admin sets a geofence on an event, you'll see a live map here.</p>
              </div>
              <div v-else class="space-y-5">
                <div
                  v-for="(event, idx) in locationEvents"
                  :key="event._id || event.event_id"
                  class="ssaam-row-anim rounded-2xl border border-gray-100 bg-gradient-to-br from-white to-gray-50 p-4 shadow-sm"
                  :style="{ animationDelay: (idx * 60) + 'ms' }"
                >
                  <div class="flex items-start justify-between gap-3 mb-3">
                    <div class="min-w-0">
                      <h3 class="font-bold text-base text-gray-900 leading-tight">{{ event.title }}</h3>
                      <p v-if="event.location" class="text-xs text-gray-500 mt-0.5 truncate">{{ event.location }}</p>
                    </div>
                    <span class="flex-shrink-0 inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider bg-green-100 text-green-700">
                      <span class="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                      Active
                    </span>
                  </div>
                  <GeofenceMap
                    readonly
                    :enabled="true"
                    :latitude="Number(event.geofence_lat)"
                    :longitude="Number(event.geofence_lng)"
                    :radius="Number(event.geofence_radius_meters) || 80"
                    :isCOE="isCOE"
                    :isSOM="isSOM"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Admin: Student Requests Section -->
        <div v-if="currentPage === 'admin-requests' && isAdminLike" class="space-y-6">
          <!-- Header -->
          <div class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div :class="['relative h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
              <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
              <div class="light-sweep"></div>
              <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
                <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white/20 flex items-center justify-center flex-shrink-0">
                  <svg class="w-5 h-5 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
                </div>
                <div class="min-w-0">
                  <h2 class="text-xl sm:text-2xl font-extrabold text-white tracking-tight">Student Requests</h2>
                  <p class="text-white/70 text-xs sm:text-sm mt-0.5">Review name and college change requests from students.</p>
                </div>
              </div>
            </div>
          </div>

          <!-- Filters -->
          <div class="bg-white rounded-2xl shadow border border-gray-100 p-4 md:p-5 flex flex-wrap gap-3 items-end">
            <!-- College filter (super-admin only) -->
            <div v-if="isSuperAdmin" class="flex flex-col gap-1 min-w-[140px]">
              <label class="text-xs font-bold text-gray-500 uppercase tracking-widest">College</label>
              <select v-model="adminRequestCollegeFilter" @change="fetchAdminRequests()" class="px-3 py-2 border-2 border-gray-200 rounded-xl text-sm focus:outline-none focus:border-blue-400 bg-gray-50">
                <option value="">All Colleges</option>
                <option value="CCS">CCS</option>
                <option value="COE">COE</option>
                <option value="SOM">SOM</option>
                <option value="CNAHS">CNAHS</option>
              </select>
            </div>
            <!-- Status filter -->
            <div class="flex flex-col gap-1 min-w-[140px]">
              <label class="text-xs font-bold text-gray-500 uppercase tracking-widest">Status</label>
              <select v-model="adminRequestStatusFilter" @change="fetchAdminRequests()" class="px-3 py-2 border-2 border-gray-200 rounded-xl text-sm focus:outline-none focus:border-blue-400 bg-gray-50">
                <option value="">All Statuses</option>
                <option value="pending">Pending</option>
                <option value="approved">Approved</option>
                <option value="rejected">Rejected</option>
              </select>
            </div>
            <!-- Refresh -->
            <button @click="fetchAdminRequests()" :disabled="adminRequestsLoading" :class="['px-4 py-2 rounded-xl text-white text-sm font-bold transition flex items-center gap-2 bg-gradient-to-r', primaryButtonGradient, primaryButtonHover, 'disabled:opacity-60 disabled:cursor-not-allowed']">
              <svg :class="{'animate-spin': adminRequestsLoading}" class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
              Refresh
            </button>
          </div>

          <!-- Loading -->
          <div v-if="adminRequestsLoading" class="flex items-center justify-center py-16">
            <svg :class="['animate-spin h-10 w-10', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          </div>

          <!-- Empty state -->
          <div v-else-if="adminRequests.length === 0" class="bg-white rounded-3xl shadow border border-gray-100 flex flex-col items-center justify-center py-16 gap-3">
            <div class="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center">
              <svg class="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
            </div>
            <p class="text-gray-500 font-medium">No requests found.</p>
          </div>

          <!-- Request cards -->
          <div v-else class="space-y-3">
            <div v-for="req in adminRequests" :key="req._id" :class="['bg-white rounded-2xl shadow-sm border overflow-hidden transition hover:shadow-md', req.status === 'pending' ? 'border-amber-200' : req.status === 'approved' ? 'border-green-200' : 'border-red-200']">
              <!-- Card top color strip -->
              <div :class="['h-1 w-full', req.status === 'pending' ? 'bg-amber-400' : req.status === 'approved' ? 'bg-green-400' : 'bg-red-400']"></div>
              <div class="p-4 sm:p-5">
                <!-- Top row: student name + status badges -->
                <div class="flex flex-wrap items-start justify-between gap-2 mb-3">
                  <div class="flex-1 min-w-0">
                    <p class="font-bold text-gray-900 text-sm leading-tight">{{ req.student_name || req.student_id }}</p>
                    <p class="text-[11px] text-gray-400 font-mono mt-0.5">{{ req.student_id }}</p>
                  </div>
                  <div class="flex flex-wrap gap-1.5 flex-shrink-0">
                    <span :class="['px-2.5 py-1 rounded-full text-[11px] font-bold whitespace-nowrap', req.type === 'name' ? 'bg-blue-100 text-blue-700' : 'bg-purple-100 text-purple-700']">
                      {{ req.type === 'name' ? '✏️ Name Change' : '🏫 College Change' }}
                    </span>
                    <span :class="['px-2.5 py-1 rounded-full text-[11px] font-bold whitespace-nowrap', req.status === 'pending' ? 'bg-amber-100 text-amber-700' : req.status === 'approved' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700']">
                      {{ req.status === 'pending' ? '⏳ Pending' : req.status === 'approved' ? '✓ Approved' : '✕ Rejected' }}
                    </span>
                    <span v-if="isSuperAdmin && req.college" class="px-2.5 py-1 rounded-full text-[11px] font-bold bg-gray-100 text-gray-600">{{ req.college }}</span>
                  </div>
                </div>

                <!-- Detail grid -->
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 mb-3">
                  <div class="bg-gray-50 rounded-xl px-3 py-2.5">
                    <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-0.5">Requested Value</p>
                    <p class="text-sm font-bold text-gray-800 break-words">{{ req.new_value }}</p>
                  </div>
                  <div class="bg-gray-50 rounded-xl px-3 py-2.5">
                    <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-0.5">Submitted</p>
                    <p class="text-xs text-gray-700 font-medium">{{ new Date(req.created_at).toLocaleString('en-PH', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' }) }}</p>
                  </div>
                </div>

                <!-- Reason -->
                <div class="mb-3 bg-gray-50 rounded-xl px-3 py-2.5">
                  <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-0.5">Reason</p>
                  <p class="text-xs text-gray-700 leading-relaxed">{{ req.reason }}</p>
                </div>

                <div v-if="req.admin_note" class="mb-3 bg-red-50 border border-red-100 rounded-xl px-3 py-2.5">
                  <p class="text-[10px] font-bold text-red-400 uppercase tracking-wider mb-0.5">Admin Note</p>
                  <p class="text-xs text-red-700 italic">{{ req.admin_note }}</p>
                </div>
                <div v-if="req.reviewed_by" class="text-[10px] text-gray-400 mb-3">
                  Reviewed by <span class="font-semibold">{{ req.reviewed_by }}</span> · {{ new Date(req.reviewed_at).toLocaleString('en-PH', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) }}
                </div>
                <div v-if="req.status === 'approved' && req.type === 'department'" class="mb-3 text-xs text-amber-700 bg-amber-50 border border-amber-100 rounded-xl px-3 py-2.5">
                  ⚠️ Department changes require manually reassigning the student via Manage.
                </div>

                <!-- Action buttons (pending only) — full-width on mobile -->
                <div v-if="req.status === 'pending'" class="flex flex-col sm:flex-row gap-2 pt-1">
                  <button @click="approveAdminRequest(req._id)" :disabled="adminRequestActing === req._id" class="flex-1 py-2.5 px-4 rounded-xl text-white text-sm font-bold transition flex items-center justify-center gap-2 bg-green-500 hover:bg-green-600 active:scale-[0.98] disabled:opacity-60 disabled:cursor-not-allowed shadow-sm shadow-green-100">
                    <svg v-if="adminRequestActing === req._id" class="animate-spin w-4 h-4" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                    <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"></path></svg>
                    Approve
                  </button>
                  <button @click="openRejectAdminRequest(req)" :disabled="adminRequestActing === req._id" class="flex-1 py-2.5 px-4 rounded-xl text-white text-sm font-bold transition flex items-center justify-center gap-2 bg-red-500 hover:bg-red-600 active:scale-[0.98] disabled:opacity-60 disabled:cursor-not-allowed shadow-sm shadow-red-100">
                    <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"></path></svg>
                    Reject
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Reject Request Modal -->
        <div v-if="rejectAdminRequestModal.open" class="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm" @click.self="rejectAdminRequestModal.open = false">
          <div class="bg-white rounded-3xl shadow-2xl w-full max-w-md p-6 space-y-4">
            <h3 class="text-lg font-bold text-gray-900">Reject Request</h3>
            <p class="text-sm text-gray-600">Optionally add a note explaining why this request is being rejected. The student will see this note.</p>
            <textarea v-model="rejectAdminRequestModal.note" rows="3" placeholder="Reason for rejection (optional)..." class="w-full px-4 py-3 border-2 border-gray-200 rounded-2xl outline-none text-sm resize-none focus:border-red-400 bg-gray-50 focus:bg-white transition"></textarea>
            <div class="flex gap-3">
              <button @click="rejectAdminRequestModal.open = false" class="flex-1 py-2.5 rounded-xl border-2 border-gray-200 text-gray-700 font-bold text-sm hover:bg-gray-50 transition">Cancel</button>
              <button @click="confirmRejectAdminRequest()" :disabled="adminRequestActing === rejectAdminRequestModal.id" class="flex-1 py-2.5 rounded-xl bg-red-500 hover:bg-red-600 text-white font-bold text-sm transition disabled:opacity-60">
                {{ adminRequestActing === rejectAdminRequestModal.id ? 'Rejecting...' : 'Confirm Reject' }}
              </button>
            </div>
          </div>
        </div>

        <!-- Student Request Section -->
        <div v-if="currentPage === 'request' && currentUser.role !== 'admin' && !currentUser.isMaster" class="space-y-6">
          <!-- Header Banner -->
          <div class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div :class="['relative h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
              <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
              <div class="light-sweep"></div>
              <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
                <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl flex items-center justify-center flex-shrink-0 bg-white/20">
                  <svg class="w-5 h-5 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
                </div>
                <div class="min-w-0">
                  <h2 class="text-base sm:text-xl md:text-2xl font-extrabold text-white tracking-tight leading-tight">Submit a Request</h2>
                  <p class="text-white/70 text-xs sm:text-sm mt-0.5 line-clamp-1">Request changes to your name or college/department.</p>
                </div>
              </div>
            </div>
          </div>

          <!-- Past Requests -->
          <div v-if="studentRequests.length > 0" class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div class="px-4 sm:px-6 md:px-8 py-3.5 sm:py-5 border-b border-gray-100 flex items-center gap-2">
              <div :class="['w-1 h-5 rounded-full flex-shrink-0', isCOE ? 'bg-orange-500' : isSOM ? 'bg-green-500' : isCNAHS ? 'bg-emerald-500' : 'bg-blue-600']"></div>
              <h3 :class="['text-xs sm:text-sm font-bold uppercase tracking-widest', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-emerald-800' : 'text-blue-800']">Your Past Requests</h3>
            </div>
            <div class="p-3 sm:p-4 md:p-6 space-y-2.5 sm:space-y-3">
              <div v-for="req in studentRequests" :key="req._id" :class="['rounded-2xl border p-4 text-sm transition hover:shadow-sm', req.status === 'approved' ? 'bg-green-50 border-green-200' : req.status === 'rejected' ? 'bg-red-50 border-red-200' : 'bg-amber-50 border-amber-200']">
                <div class="flex items-start justify-between gap-3 flex-wrap">
                  <div class="flex-1">
                    <div class="flex items-center gap-2 mb-1">
                      <svg v-if="req.type === 'name'" class="w-4 h-4 text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg>
                      <svg v-else class="w-4 h-4 text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>
                      <span class="font-semibold text-gray-800">{{ req.type === 'name' ? 'Name Change' : 'Department Change' }}</span>
                    </div>
                    <p class="text-gray-500 text-xs leading-relaxed">{{ req.reason }}</p>
                    <p v-if="req.new_value" class="text-gray-500 text-xs mt-1.5">New value: <span class="font-semibold text-gray-700">{{ req.new_value }}</span></p>
                    <p v-if="req.admin_note" class="mt-1.5 text-xs text-gray-500 italic">Admin note: {{ req.admin_note }}</p>
                    <p class="text-[10px] text-gray-400 mt-2">{{ new Date(req.created_at).toLocaleString() }}</p>
                  </div>
                  <span :class="['px-3 py-1 rounded-full text-[11px] font-bold whitespace-nowrap flex-shrink-0', req.status === 'approved' ? 'bg-green-100 text-green-700' : req.status === 'rejected' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700']">
                    {{ req.status === 'approved' ? '✓ Approved' : req.status === 'rejected' ? '✕ Rejected' : '⏳ Pending' }}
                  </span>
                </div>
              </div>
            </div>
          </div>

          <!-- New Request Form -->
          <div class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div class="px-4 sm:px-6 md:px-8 py-3.5 sm:py-5 border-b border-gray-100 flex items-center gap-2">
              <div :class="['w-1 h-5 rounded-full flex-shrink-0', isCOE ? 'bg-orange-500' : isSOM ? 'bg-green-500' : isCNAHS ? 'bg-emerald-500' : 'bg-blue-600']"></div>
              <h3 :class="['text-xs sm:text-sm font-bold uppercase tracking-widest', isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : isCNAHS ? 'text-emerald-800' : 'text-blue-800']">New Request</h3>
            </div>

            <div class="p-4 sm:p-6 md:p-8 space-y-4 sm:space-y-6">
              <!-- Request Type Toggle -->
              <div>
                <label class="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-3">Request Type</label>
                <div class="grid grid-cols-2 gap-3">
                  <button @click="newRequest.type = 'name'" :class="['flex items-center gap-3 px-4 py-3 rounded-2xl border-2 transition-all text-sm font-semibold', newRequest.type === 'name' ? (isCOE ? 'bg-orange-50 border-orange-400 text-orange-700' : isSOM ? 'bg-green-50 border-green-400 text-green-700' : isCNAHS ? 'bg-emerald-50 border-emerald-400 text-emerald-700' : 'bg-blue-50 border-blue-500 text-blue-700') : 'bg-gray-50 border-gray-200 text-gray-500 hover:border-gray-300']">
                    <svg class="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg>
                    <span>Name Change</span>
                  </button>
                  <button @click="newRequest.type = 'department'" :class="['flex items-center gap-3 px-4 py-3 rounded-2xl border-2 transition-all text-sm font-semibold', newRequest.type === 'department' ? (isCOE ? 'bg-orange-50 border-orange-400 text-orange-700' : isSOM ? 'bg-green-50 border-green-400 text-green-700' : isCNAHS ? 'bg-emerald-50 border-emerald-400 text-emerald-700' : 'bg-blue-50 border-blue-500 text-blue-700') : 'bg-gray-50 border-gray-200 text-gray-500 hover:border-gray-300']">
                    <svg class="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"></path></svg>
                    <span>College Change</span>
                  </button>
                </div>
              </div>

              <!-- Name Change Fields -->
              <div v-if="newRequest.type === 'name'" class="space-y-4">
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label :class="['block text-xs font-bold mb-1.5', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-emerald-700' : 'text-blue-700']">First Name <span class="text-red-500">*</span></label>
                    <input v-model="newRequest.first_name" type="text" placeholder="e.g. Juan" :class="['w-full px-4 py-3 border-2 rounded-2xl outline-none text-sm font-medium transition bg-gray-50 focus:bg-white', isCOE ? 'focus:ring-0 focus:border-orange-400 border-gray-200' : isSOM ? 'focus:ring-0 focus:border-green-400 border-gray-200' : isCNAHS ? 'focus:ring-0 focus:border-emerald-400 border-gray-200' : 'focus:ring-0 focus:border-blue-400 border-gray-200']" />
                  </div>
                  <div>
                    <label class="block text-xs font-bold mb-1.5 text-gray-400">Middle Name <span class="font-normal">(optional)</span></label>
                    <input v-model="newRequest.middle_name" type="text" placeholder="e.g. Dela Cruz" :class="['w-full px-4 py-3 border-2 rounded-2xl outline-none text-sm font-medium transition bg-gray-50 focus:bg-white', isCOE ? 'focus:ring-0 focus:border-orange-400 border-gray-200' : isSOM ? 'focus:ring-0 focus:border-green-400 border-gray-200' : isCNAHS ? 'focus:ring-0 focus:border-emerald-400 border-gray-200' : 'focus:ring-0 focus:border-blue-400 border-gray-200']" />
                  </div>
                  <div>
                    <label :class="['block text-xs font-bold mb-1.5', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-emerald-700' : 'text-blue-700']">Last Name <span class="text-red-500">*</span></label>
                    <input v-model="newRequest.last_name" type="text" placeholder="e.g. Santos" :class="['w-full px-4 py-3 border-2 rounded-2xl outline-none text-sm font-medium transition bg-gray-50 focus:bg-white', isCOE ? 'focus:ring-0 focus:border-orange-400 border-gray-200' : isSOM ? 'focus:ring-0 focus:border-green-400 border-gray-200' : isCNAHS ? 'focus:ring-0 focus:border-emerald-400 border-gray-200' : 'focus:ring-0 focus:border-blue-400 border-gray-200']" />
                  </div>
                  <div>
                    <label class="block text-xs font-bold mb-1.5 text-gray-400">Suffix <span class="font-normal">(optional)</span></label>
                    <select v-model="newRequest.suffix" :class="['w-full px-4 py-3 border-2 rounded-2xl outline-none text-sm font-medium transition bg-gray-50 focus:bg-white', isCOE ? 'focus:ring-0 focus:border-orange-400 border-gray-200' : isSOM ? 'focus:ring-0 focus:border-green-400 border-gray-200' : isCNAHS ? 'focus:ring-0 focus:border-emerald-400 border-gray-200' : 'focus:ring-0 focus:border-blue-400 border-gray-200']">
                      <option value="">None</option>
                      <option>Jr.</option>
                      <option>Sr.</option>
                      <option>II</option>
                      <option>III</option>
                      <option>IV</option>
                      <option>V</option>
                    </select>
                  </div>
                </div>

                <!-- Live Preview -->
                <div v-if="newRequest.first_name || newRequest.last_name" :class="['p-4 rounded-2xl border-2 border-dashed', isCOE ? 'border-orange-200 bg-orange-50/50' : isSOM ? 'border-green-200 bg-green-50/50' : isCNAHS ? 'border-emerald-200 bg-emerald-50/50' : 'border-blue-200 bg-blue-50/50']">
                  <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Live Preview</p>
                  <p :class="['text-base font-bold', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-emerald-700' : 'text-blue-700']">
                    {{ [newRequest.first_name, newRequest.middle_name, newRequest.last_name, newRequest.suffix].filter(v => v && v.trim()).join(' ') }}
                  </p>
                  <p class="text-[10px] text-gray-400 mt-1">This is how your name will appear after the request is approved.</p>
                </div>
                <p class="text-xs text-gray-400">This request will be sent to your college admin for review.</p>
              </div>

              <!-- Department Change Field -->
              <div v-if="newRequest.type === 'department'" class="space-y-3">
                <label :class="['block text-xs font-bold mb-1.5 uppercase tracking-wider', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-emerald-700' : 'text-blue-700']">Select New College / Department</label>
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <button v-for="col in [{v:'CCS',label:'College of Computing Studies',color:'blue'},{v:'COE',label:'College of Engineering',color:'orange'},{v:'SOM',label:'School of Midwifery',color:'green'},{v:'CNAHS',label:'College of Nursing and Allied Health Sciences',color:'emerald'}]" :key="col.v" @click="newRequest.new_value = col.v" :class="['flex items-center gap-3 p-3 rounded-2xl border-2 transition-all text-left', newRequest.new_value === col.v ? `bg-${col.color}-50 border-${col.color}-400` : 'bg-gray-50 border-gray-200 hover:border-gray-300']">
                    <img :src="`/icons/${col.v.toLowerCase()}.svg`" :alt="col.v" class="w-9 h-9 object-contain flex-shrink-0" />
                    <div>
                      <p :class="['text-sm font-bold', newRequest.new_value === col.v ? `text-${col.color}-700` : 'text-gray-700']">{{ col.v }}</p>
                      <p :class="['text-[10px] leading-tight', newRequest.new_value === col.v ? `text-${col.color}-500` : 'text-gray-400']">{{ col.label }}</p>
                    </div>
                    <svg v-if="newRequest.new_value === col.v" :class="[`text-${col.color}-500`, 'w-5 h-5 ml-auto flex-shrink-0']" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"/></svg>
                  </button>
                </div>
                <p class="text-xs text-gray-400">Department change requests are reviewed by the co-admin of the target college.</p>
              </div>

              <!-- Reason -->
              <div>
                <label :class="['block text-xs font-bold mb-1.5 uppercase tracking-wider', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-emerald-700' : 'text-blue-700']">Reason <span class="text-red-500">*</span></label>
