                    <div class="flex-1 min-w-0">
                      <p class="font-semibold text-sm text-gray-900 truncate">{{ getCoAdminForCollege('CNAHS').full_name || getCoAdminForCollege('CNAHS').username }}</p>
                      <p class="text-xs text-gray-500 truncate">{{ getCoAdminForCollege('CNAHS').email }}</p>
                    </div>
                    <button @click="removeCoAdmin(getCoAdminForCollege('CNAHS')._id, 'CNAHS')" :disabled="coAdminActionLoading === 'CNAHS'" class="p-1.5 rounded-xl text-red-400 hover:bg-red-50 hover:text-red-600 transition flex-shrink-0" title="Remove">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                  </div>
                  <div v-else class="p-2.5 bg-gray-50 rounded-xl border border-dashed border-gray-200 text-center text-xs text-gray-400">No co-admin assigned</div>
                </div>
                <div class="space-y-1.5">
                  <p class="text-[10px] font-bold text-cyan-600 uppercase tracking-widest flex items-center gap-1.5"><span class="inline-block w-2 h-2 rounded-full bg-cyan-500"></span>Treasurer</p>
                  <div v-if="getTreasurerForCollege('CNAHS')" class="flex items-center gap-3 p-3 bg-cyan-50 rounded-2xl border border-cyan-100">
                    <div class="w-9 h-9 rounded-full flex items-center justify-center text-white font-bold text-xs flex-shrink-0 bg-gradient-to-br from-cyan-500 to-teal-600">
                      {{ (getTreasurerForCollege('CNAHS').full_name || getTreasurerForCollege('CNAHS').username || '?').charAt(0).toUpperCase() }}
                    </div>
                    <div class="flex-1 min-w-0">
                      <p class="font-semibold text-sm text-gray-900 truncate">{{ getTreasurerForCollege('CNAHS').full_name || getTreasurerForCollege('CNAHS').username }}</p>
                      <p class="text-xs text-gray-500 truncate">{{ getTreasurerForCollege('CNAHS').email }}</p>
                    </div>
                    <button @click="removeTreasurer(getTreasurerForCollege('CNAHS')._id, 'CNAHS')" :disabled="coAdminActionLoading === 'CNAHS-treasurer'" class="p-1.5 rounded-xl text-red-400 hover:bg-red-50 hover:text-red-600 transition flex-shrink-0" title="Remove">
                      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                  </div>
                  <div v-else class="p-2.5 bg-gray-50 rounded-xl border border-dashed border-gray-200 text-center text-xs text-gray-400">No treasurer assigned</div>
                </div>
                <div class="pt-1 border-t border-gray-100 space-y-2">
                  <input v-model="roleAssignInputs['CNAHS'].studentId" type="text" placeholder="Enter Student ID to assign" class="w-full px-3 py-2 border border-gray-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-emerald-400 bg-gray-50 focus:bg-white transition" @keyup.enter="assignAdminRole('CNAHS')" />
                  <div class="flex gap-2">
                    <select v-model="roleAssignInputs['CNAHS'].role" class="flex-1 px-3 py-2 border border-gray-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-emerald-400 bg-gray-50 focus:bg-white transition appearance-none">
                      <option value="co-admin">Co-Admin</option>
                      <option value="treasurer">Treasurer</option>
                    </select>
                    <button @click="assignAdminRole('CNAHS')" :disabled="coAdminActionLoading === 'CNAHS-co-admin' || coAdminActionLoading === 'CNAHS-treasurer' || !roleAssignInputs['CNAHS']?.studentId?.trim()" class="px-4 py-2 bg-gradient-to-r from-emerald-600 to-green-700 hover:from-emerald-700 hover:to-green-800 text-white rounded-xl text-sm font-semibold transition disabled:opacity-50 whitespace-nowrap">
                      {{ (coAdminActionLoading === 'CNAHS-co-admin' || coAdminActionLoading === 'CNAHS-treasurer') ? '...' : 'Assign' }}
                    </button>
                  </div>
                </div>
              </div>
            </div>

          </div>
        </div>

        <!-- Active Attendance Event Banner for Students -->
        <div v-if="currentPage === 'dashboard' && (!isAdminLike || inUserView) && activeUnattendedEvents.length > 0" class="mb-4 space-y-2">
          <div v-for="event in activeUnattendedEvents" :key="event._id" :class="['rounded-xl px-4 py-3 text-white flex items-center gap-3 shadow-md', isCOE ? 'bg-gradient-to-r from-orange-600 to-red-600' : isSOM ? 'bg-gradient-to-r from-green-700 to-teal-600' : isCNAHS ? 'bg-gradient-to-r from-green-700 to-green-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']" :style="{ background: profileGradient }">
            <div class="flex-shrink-0">
              <svg v-if="getAttendanceStatus(event._id || event.event_id) === 'incomplete'" class="w-4 h-4 text-yellow-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
              <svg v-else class="w-4 h-4 text-white/80" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
            </div>
            <div class="flex-1 min-w-0">
              <div class="flex flex-wrap items-baseline gap-x-1.5 gap-y-0.5">
                <span class="font-semibold text-sm">{{ event.title }}</span>
                <span class="text-white/50 text-xs">·</span>
                <span class="text-white/80 text-xs">
                  <template v-if="getAttendanceStatus(event._id || event.event_id) === 'incomplete'">Checked in — not yet checked out</template>
                  <template v-else-if="getAttendanceStatus(event._id || event.event_id) === 'ongoing'">Ongoing — check in with RFID</template>
                  <template v-else>Active — tap your RFID card</template>
                </span>
              </div>
              <div class="flex flex-wrap gap-x-3 mt-0.5 text-xs text-white/55">
                <span v-if="event.date || event.event_date">{{ formatEventDate(event.date || event.event_date) }}</span>
                <span v-if="event.startTime || event.start_time">{{ formatEventTime(event.startTime || event.start_time) }}–{{ formatEventTime(event.endTime || event.end_time) }}</span>
                <span v-if="event.location">{{ event.location }}</span>
              </div>
            </div>
            <button @click="currentPage = 'attendance'; fetchAttendanceData()" class="flex-shrink-0 bg-white/15 hover:bg-white/25 text-white text-xs font-semibold px-3 py-1.5 rounded-lg transition border border-white/20 flex items-center gap-1.5 whitespace-nowrap">
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
              Attendance
            </button>
          </div>
        </div>

        <!-- Dashboard Page -->
        <div v-if="currentPage === 'dashboard' && (!isAdminLike || inUserView)" class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden mb-8">
          <!-- Profile Header -->
          <div :class="['relative h-32 sm:h-36 md:h-40 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-900 via-orange-600 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-900 via-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-800 via-green-700 to-green-600' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light']">
            <!-- Artistic Blurred Background -->
            <div 
              v-if="currentUser.image || currentUser.photo"
              class="absolute inset-0 w-full h-full bg-cover bg-center transition-all duration-1000 scale-125"
              :style="{ 
                backgroundImage: `url(${currentUser.image || currentUser.photo})`,
                filter: 'blur(30px) saturate(1.8) brightness(0.8)'
              }"
            ></div>
            <div v-else :class="[isCOE ? 'bg-gradient-to-br from-orange-900 via-orange-600 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-900 via-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-800 via-green-700 to-green-600' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-dark', 'absolute inset-0 w-full h-full animate-gradient-slow']"></div>
            
            <!-- Artistic Overlays -->
            <div class="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-black/20"></div>
            <div class="absolute inset-0 opacity-30 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
            <div :class="[isCOE ? 'bg-orange-500/20' : isSOM ? 'bg-green-500/20' : isCNAHS ? 'bg-green-700/20' : 'bg-blue-500/20', 'absolute -top-20 -right-20 w-64 h-64 rounded-full blur-3xl animate-pulse']"></div>
            <div :class="[isCOE ? 'bg-red-500/20' : isSOM ? 'bg-teal-500/20' : isCNAHS ? 'bg-green-600/20' : 'bg-blue-500/20', 'absolute -bottom-20 -left-20 w-64 h-64 rounded-full blur-3xl animate-pulse-slow']"></div>
            
            <div class="light-sweep"></div>
            <button @click="refreshCurrentUser" :disabled="refreshingUserData" class="absolute top-4 right-4 p-2 bg-white/20 hover:bg-white/40 rounded-full text-white transition-all backdrop-blur-md z-10 border border-white/20 shadow-lg" title="Refresh Profile">
              <svg :class="['w-5 h-5', refreshingUserData ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
            </button>
          </div>

          <div class="px-4 sm:px-6 md:px-8 pb-4 sm:pb-6 md:pb-8">
            <div class="relative -mt-12 sm:-mt-14 md:-mt-16 mb-3 sm:mb-5 md:mb-6">
              <div class="inline-block relative">
                <div :class="[isCOE ? 'bg-gradient-to-br from-orange-400 to-red-600' : isSOM ? 'bg-gradient-to-br from-green-400 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-green-500 to-green-700' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light', 'w-20 h-20 sm:w-28 sm:h-28 md:w-32 md:h-32 rounded-2xl md:rounded-3xl overflow-hidden ring-4 ring-white shadow-2xl flex items-center justify-center']">
                  <div v-if="profileImageLoading && !profileImageFailed" class="w-full h-full flex items-center justify-center">
                    <svg class="animate-spin h-10 w-10 text-white/80" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                      <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                  </div>
                  <img 
                    v-else-if="!profileImageFailed && (currentUser.image || currentUser.photo)" 
                    :src="currentUser.image || currentUser.photo" 
                    alt="Profile Picture" 
                    class="w-full h-full object-cover" 
                    crossorigin="anonymous"
                    @load="onProfileImageLoad" 
                    @error="handleProfileImageError" 
                  />
                  <div v-else class="w-full h-full flex items-center justify-center text-4xl font-bold text-white">
                    {{ getInitials(currentUser?.full_name || displayName || '') }}
                  </div>
                </div>
                <button 
                  v-if="currentUser.role !== 'admin' && !currentUser.isMaster"
                  @click="$refs.studentPhotoInput.click()" 
                  :class="[isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-700' : 'text-blue-600', 'absolute -bottom-2 -right-2 p-2.5 bg-white rounded-2xl shadow-lg hover:scale-110 transition-transform border border-gray-100']"
                  title="Change Photo"
                >
                  <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                </button>
              </div>
              <input 
                ref="studentPhotoInput" 
                @change="handleStudentPhotoUpload"
                type="file" 
                accept="image/*" 
                class="hidden" 
              />
            </div>

            <div class="mb-4 sm:mb-6 md:mb-8">
              <h1 class="text-xl sm:text-2xl md:text-3xl font-extrabold text-gray-900 tracking-tight">{{ displayName }}</h1>
              <p :class="[isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-700' : 'text-blue-600', 'text-sm sm:text-base md:text-lg font-medium']">ID: {{ currentUser.studentId || currentUser.student_id }}</p>
              <p v-if="studentPhotoUploading" :class="[isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-700' : 'text-blue-600', 'text-xs mt-2 font-medium']">Uploading photo...</p>
            </div>

            <!-- Info Grid -->
            <div class="space-y-4 sm:space-y-6 md:space-y-8">
              <section>
                <div class="flex items-center gap-2 mb-2 sm:mb-3 md:mb-4">
                  <div :class="[isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600', 'w-1 h-5 rounded-full']"></div>
                  <h3 class="text-xs font-bold text-gray-400 uppercase tracking-widest">Personal Information</h3>
                </div>
                <div class="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3 md:gap-4">
                  <div v-for="(val, label) in { 'First Name': currentUser.firstName || currentUser.first_name, 'Middle Name': currentUser.middleName || currentUser.middle_name || 'N/A', 'Last Name': currentUser.lastName || currentUser.last_name, 'Suffix': currentUser.suffix || 'N/A' }" :key="label" 
                       :class="[isCOE ? 'hover:border-orange-200' : isSOM ? 'hover:border-green-200' : isCNAHS ? 'hover:border-green-200' : 'hover:border-blue-200', 'p-2.5 sm:p-3 md:p-4 bg-gray-50 rounded-xl md:rounded-2xl border border-gray-100 transition-colors']">
                    <p class="text-[9px] sm:text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-0.5 sm:mb-1">{{ label }}</p>
                    <p class="text-sm sm:text-base text-gray-900 font-semibold truncate">{{ val }}</p>
                  </div>
                </div>
                <p class="text-xs text-gray-500 mt-2">Account created on {{ formatDateTimeShort(currentUser.created_date) }}</p>
              </section>

              <section>
                <div class="flex items-center gap-2 mb-2 sm:mb-3 md:mb-4">
                  <div :class="[isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600', 'w-1 h-5 rounded-full']"></div>
                  <h3 class="text-xs font-bold text-gray-400 uppercase tracking-widest">Contact & Identification</h3>
                </div>
                <div class="grid grid-cols-1 md:grid-cols-2 gap-2 sm:gap-3 md:gap-4">
                  <div :class="[isCOE ? 'hover:border-orange-200' : isSOM ? 'hover:border-green-200' : isCNAHS ? 'hover:border-green-200' : 'hover:border-blue-200', 'p-2.5 sm:p-3 md:p-4 bg-gray-50 rounded-xl md:rounded-2xl border border-gray-100 transition-colors']">
                    <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Email Address</p>
                    <p class="text-gray-900 font-semibold truncate">{{ currentUser.email || 'Not provided' }}</p>
                  </div>
                  <div :class="['p-2.5 sm:p-3 md:p-4 bg-white rounded-xl md:rounded-2xl border-2 shadow-sm relative overflow-hidden group', currentUser.rfid_status === 'verified' ? 'border-green-100' : (currentUser.rfid_status === 'Unreadable' || (currentUser.rfid_code && currentUser.rfid_code.toUpperCase().startsWith('UNREADABLE'))) ? 'border-gray-200' : 'border-yellow-100']">
                    <div class="absolute top-0 right-0 p-2">
                      <span :class="['px-2 py-0.5 rounded-full text-[10px] font-bold', currentUser.rfid_status === 'verified' ? 'bg-green-100 text-green-700' : (currentUser.rfid_status === 'Unreadable' || (currentUser.rfid_code && currentUser.rfid_code.toUpperCase().startsWith('UNREADABLE'))) ? 'bg-gray-100 text-gray-700' : 'bg-yellow-100 text-yellow-700']">
                        {{ currentUser.rfid_status === 'verified' ? 'Verified' : (currentUser.rfid_status === 'Unreadable' || (currentUser.rfid_code && currentUser.rfid_code.toUpperCase().startsWith('UNREADABLE'))) ? 'Unreadable' : 'Pending' }}
                      </span>
                    </div>
                    <p class="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">RFID STATUS</p>
                    <div v-if="currentUser.rfid_status === 'verified'" class="flex items-center gap-2 mb-2">
                      <p :class="[isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900', 'text-lg font-mono font-bold tracking-tight']">{{ currentUser.rfidCode || currentUser.rfid_code }}</p>
                      <button @click="copyRfidToClipboard(currentUser.rfidCode || currentUser.rfid_code)" :class="[isCOE ? 'hover:bg-orange-50 text-orange-400' : isSOM ? 'hover:bg-green-50 text-green-400' : isCNAHS ? 'hover:bg-green-50 text-green-700' : 'hover:bg-blue-50 text-blue-400', 'p-1 rounded transition-colors']">
                        <svg v-if="!rfidCopied" class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"></path></svg>
                        <svg v-else class="w-4 h-4 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg>
                      </button>
                    </div>
                    <div v-else-if="currentUser.rfid_status === 'Unreadable' || (currentUser.rfid_code && currentUser.rfid_code.toUpperCase().startsWith('UNREADABLE'))">
                      <p class="text-base font-semibold text-gray-700">Card Damaged</p>
                    </div>
                    <div v-else>
                      <p class="text-base font-semibold text-gray-900">Not Yet Assigned</p>
                    </div>
                    <p v-if="currentUser.rfid_verified_at" class="text-[10px] text-gray-500 mt-2">Verified on: {{ formatDateTimeShort(currentUser.rfid_verified_at) }}</p>
                    <p v-else class="text-[10px] text-gray-500 mt-2 italic">{{ currentUser.rfid_status === 'verified' ? 'Active and ready for attendance logging.' : 'Please visit the CCS office for assistance.' }}</p>
                  </div>
                </div>
              </section>

              <section>
                <div class="flex items-center gap-2 mb-2 sm:mb-3 md:mb-4">
                  <div :class="[isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600', 'w-1 h-5 rounded-full']"></div>
                  <h3 class="text-xs font-bold text-gray-400 uppercase tracking-widest">Academic Information</h3>
                </div>
                <div class="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3 md:gap-4">
                  <div v-for="(val, label) in { 
                    'Program': currentUser.program || 'N/A', 
                    'Year': currentUser.yearLevel || currentUser.year_level || 'N/A', 
                    'Semester': appSettings.semester || 'N/A', 
                    'School Year': appSettings.schoolYear || 'N/A' 
                  }" :key="label" 
                       :class="[isCOE ? 'hover:border-orange-200' : isSOM ? 'hover:border-green-200' : isCNAHS ? 'hover:border-green-200' : 'hover:border-blue-200', 'p-2.5 sm:p-3 md:p-4 bg-gray-50 rounded-xl md:rounded-2xl border border-gray-100 transition-colors']">
                    <p class="text-[9px] sm:text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-0.5 sm:mb-1">{{ label }}</p>
                    <p class="text-sm sm:text-base text-gray-900 font-bold">{{ val }}</p>
                  </div>
                </div>
              </section>

              <!-- Face ID Section (sidebar-styled: deep navy + glass) -->
              <section>
                <div class="flex items-center gap-2 mb-2 sm:mb-3 md:mb-4">
                  <div :class="[faceAccentBar, 'w-1 h-5 rounded-full']"></div>
                  <h3 class="text-xs font-bold text-gray-400 uppercase tracking-widest">Face ID</h3>
                </div>
                <div class="face-id-card relative overflow-hidden rounded-xl sm:rounded-2xl p-3 sm:p-4 md:p-6 border border-white/10 shadow-2xl bg-gradient-to-b from-[#080e2e] to-[#0f1f6e] text-white">
                  <!-- Soft animated orbs (sidebar vibe) -->
                  <div class="absolute -top-16 -right-16 w-56 h-56 rounded-full blur-3xl opacity-30 animate-pulse-slow" :class="faceOrbA"></div>
                  <div class="absolute -bottom-20 -left-20 w-60 h-60 rounded-full blur-3xl opacity-20 animate-pulse-slower" :class="faceOrbB"></div>
                  <!-- subtle grid sheen -->
                  <div class="absolute inset-0 opacity-[0.07] pointer-events-none" style="background-image: radial-gradient(circle at 1px 1px, white 1px, transparent 0); background-size: 22px 22px;"></div>

                  <div class="relative z-10">
                    <!-- Top row: avatar + text (+ inline button on sm+) -->
                    <div class="flex items-start gap-3 sm:gap-5 sm:items-center">
                      <!-- Avatar / status circle -->
                      <div class="flex-shrink-0">
                        <div class="relative">
                          <span v-if="!faceLoading && !faceEnrolled" class="absolute inset-0 rounded-2xl animate-ping-slow opacity-40" :class="faceAccentRing"></span>
                          <div :class="['relative w-14 h-14 sm:w-20 sm:h-20 md:w-24 md:h-24 rounded-2xl md:rounded-3xl overflow-hidden flex items-center justify-center shadow-xl ring-2 ring-white/20 backdrop-blur-sm', faceEnrolled ? 'bg-emerald-500/20' : 'bg-white/10']">
                            <img v-if="faceEnrolled && faceData?.faces?.[0]?.photo" :src="faceData.faces[0].photo" class="w-full h-full object-cover" alt="Face ID preview" />
                            <svg v-else class="w-7 h-7 sm:w-10 sm:h-10 md:w-12 md:h-12 text-white/85" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 10h.01M15 10h.01M9.5 15a3.5 3.5 0 005 0M4 7v10a3 3 0 003 3h10a3 3 0 003-3V7a3 3 0 00-3-3H7a3 3 0 00-3 3z" />
                            </svg>
                          </div>
                          <span v-if="faceEnrolled" class="absolute -bottom-1 -right-1 w-5 h-5 sm:w-6 sm:h-6 md:w-7 md:h-7 rounded-full bg-emerald-400 ring-2 ring-[#0a1340] flex items-center justify-center shadow-lg">
                            <svg class="w-3 h-3 md:w-4 md:h-4 text-[#0a1340]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                          </span>
                        </div>
                      </div>

                      <!-- Status text -->
                      <div class="flex-1 min-w-0">
                        <div class="flex items-center gap-1.5 mb-1">
                          <h4 class="text-sm sm:text-base md:text-lg font-bold text-white leading-tight">Face Recognition</h4>
                          <span v-if="faceLoading" class="flex-shrink-0 px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-white/10 text-white/80 border border-white/15">Loading…</span>
                          <span v-else-if="faceEnrolled" class="flex-shrink-0 inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-bold bg-emerald-400/20 text-emerald-200 border border-emerald-300/40">
                            <svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                            Enrolled
                          </span>
                          <span v-else class="flex-shrink-0 px-2 py-0.5 rounded-full text-[9px] font-bold bg-white/10 text-white border border-white/20">Not set up</span>
                        </div>
                        <p v-if="faceLoading" class="text-xs text-white/70">Checking Face ID status…</p>
                        <template v-else-if="faceEnrolled">
                          <p class="text-xs sm:text-sm text-white/90 font-medium">Use your face to mark attendance during events.</p>
                          <p class="text-[10px] sm:text-xs text-white/60 mt-0.5 sm:mt-1">
                            Updated <span class="font-semibold text-white/80">{{ formatFaceDate(faceData.face_updated_at) }}</span>.
                            <template v-if="faceData.in_cooldown"> Next on <span class="font-semibold text-white/80">{{ formatFaceDate(faceData.next_update_allowed_at) }}</span>.</template>
                            <template v-else> Can update anytime.</template>
                          </p>
                        </template>
                        <template v-else>
                          <p class="text-xs sm:text-sm text-white/90 font-medium">Enroll your face to enable self check-in on events.</p>
                          <p class="text-[10px] sm:text-xs text-white/60 mt-0.5 sm:mt-1">Only takes a few seconds with your camera.</p>
                        </template>
                      </div>

                      <!-- Inline button — visible on sm+ only -->
                      <div class="hidden sm:block flex-shrink-0">
                        <button
                          @click="openFaceEnroll"
                          :disabled="faceLoading || (faceEnrolled && faceData?.in_cooldown)"
                          :class="['face-cta group relative px-5 py-2.5 rounded-xl font-bold text-sm flex items-center gap-2 overflow-hidden transition-all duration-300 ease-out border whitespace-nowrap', (faceEnrolled && faceData?.in_cooldown) ? 'bg-white/5 text-white/40 border-white/10 cursor-not-allowed' : 'text-white border-white/25 bg-white/10 hover:bg-white/20 hover:border-white/40 hover:-translate-y-0.5 active:translate-y-0 shadow-lg shadow-black/20 hover:shadow-xl']"
                          :title="faceEnrolled && faceData?.in_cooldown ? `Locked until ${formatFaceDate(faceData.next_update_allowed_at)}` : ''"
                        >
                          <span v-if="!(faceEnrolled && faceData?.in_cooldown)" class="absolute inset-0 -translate-x-full group-hover:translate-x-full transition-transform duration-700 ease-out bg-gradient-to-r from-transparent via-white/30 to-transparent pointer-events-none"></span>
                          <svg class="relative w-4 h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                          </svg>
                          <span class="relative">{{ faceEnrolled ? 'Update Face ID' : 'Set Up Face ID' }}</span>
                        </button>
                      </div>
                    </div>

                    <!-- Full-width button — mobile only -->
                    <div class="sm:hidden mt-3">
                      <button
                        @click="openFaceEnroll"
                        :disabled="faceLoading || (faceEnrolled && faceData?.in_cooldown)"
                        :class="['face-cta group relative w-full px-4 py-2 rounded-xl font-bold text-xs flex items-center justify-center gap-2 overflow-hidden transition-all duration-300 ease-out border', (faceEnrolled && faceData?.in_cooldown) ? 'bg-white/5 text-white/40 border-white/10 cursor-not-allowed' : 'text-white border-white/25 bg-white/10 hover:bg-white/20 hover:border-white/40 active:translate-y-0 shadow-lg shadow-black/20']"
                        :title="faceEnrolled && faceData?.in_cooldown ? `Locked until ${formatFaceDate(faceData.next_update_allowed_at)}` : ''"
                      >
                        <span v-if="!(faceEnrolled && faceData?.in_cooldown)" class="absolute inset-0 -translate-x-full group-hover:translate-x-full transition-transform duration-700 ease-out bg-gradient-to-r from-transparent via-white/30 to-transparent pointer-events-none"></span>
                        <svg class="relative w-3.5 h-3.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                        </svg>
                        <span class="relative">{{ faceEnrolled ? 'Update Face ID' : 'Set Up Face ID' }}</span>
                      </button>
                    </div>
                  </div>

                  <!-- tip strip -->
                  <div class="relative z-10 mt-3 sm:mt-5 pt-3 sm:pt-4 border-t border-white/10 grid grid-cols-3 gap-1.5 sm:gap-2 text-[10px] sm:text-xs text-white/80">
                    <div class="flex items-center gap-1.5 px-2 sm:px-3 py-1.5 sm:py-2 rounded-lg bg-white/5 border border-white/10 border-l-4" :class="faceAccentBorderL">
                      <span class="w-4 h-4 rounded-md flex items-center justify-center flex-shrink-0 bg-white/10">
                        <svg class="w-2.5 h-2.5 text-emerald-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                      </span>
                      <span class="leading-tight">Phone &amp; laptop</span>
                    </div>
                    <div class="flex items-center gap-1.5 px-2 sm:px-3 py-1.5 sm:py-2 rounded-lg bg-white/5 border border-white/10 border-l-4" :class="faceAccentBorderL">
                      <span class="w-4 h-4 rounded-md flex items-center justify-center flex-shrink-0 bg-white/10">
                        <svg class="w-2.5 h-2.5 text-emerald-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                      </span>
                      <span class="leading-tight">Unique to you</span>
                    </div>
                    <div class="flex items-center gap-1.5 px-2 sm:px-3 py-1.5 sm:py-2 rounded-lg bg-white/5 border border-white/10 border-l-4" :class="faceAccentBorderL">
                      <span class="w-4 h-4 rounded-md flex items-center justify-center flex-shrink-0 bg-white/10">
                        <svg class="w-2.5 h-2.5 text-emerald-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                      </span>
                      <span class="leading-tight">Every {{ (faceData && faceData.cooldown_days) || 7 }}d update</span>
                    </div>
                  </div>
                </div>
              </section>

              <section>
                <div class="flex items-center gap-2 mb-2 sm:mb-3 md:mb-4">
                  <div :class="[isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600', 'w-1 h-5 rounded-full']"></div>
                  <h3 class="text-xs font-bold text-gray-400 uppercase tracking-widest">Account Security</h3>
                </div>
                <div class="p-3 sm:p-4 md:p-6 bg-gray-50 rounded-xl md:rounded-2xl border border-gray-100 flex items-center justify-between gap-3">
                  <div class="flex-1 min-w-0">
                    <h4 class="font-bold text-sm text-gray-900 mb-0.5">Password</h4>
                    <p class="text-xs text-gray-500">Keep your account secure with a strong password.</p>
                  </div>
                  <button @click="showPasswordChangeModal = true" :class="[isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 shadow-lg shadow-orange-200 hover:from-orange-700 hover:to-red-600' : isSOM ? 'bg-gradient-to-r from-green-600 to-yellow-500 shadow-lg shadow-green-200 hover:from-green-700 hover:to-yellow-600' : isCNAHS ? 'bg-gradient-to-r from-green-700 to-green-600 shadow-lg shadow-green-300 hover:from-green-800 hover:to-green-700' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light shadow-lg shadow-blue-200 hover:from-ssaam-dark hover:to-ssaam-light', 'flex-shrink-0 px-3 sm:px-4 md:px-6 py-2 sm:py-2.5 text-white rounded-xl font-bold text-xs sm:text-sm hover:scale-105 transition-transform flex items-center gap-1.5 whitespace-nowrap']">
                    <svg class="w-3.5 h-3.5 sm:w-4 sm:h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z"></path></svg>
                    Change Password
                  </button>
                </div>
              </section>

            </div>
          </div>
        </div>

        <!-- My Contributions Page (Students) -->
        <div v-if="currentPage === 'my-contributions' && currentUser.role !== 'admin' && !currentUser.isMaster" class="space-y-6">
          <!-- Header Banner -->
          <div class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div :class="['relative h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
              <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
              <div class="light-sweep"></div>
              <div class="relative z-10 px-4 sm:p-6 flex items-center gap-3 sm:gap-4 h-full">
                <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white/20 backdrop-blur flex items-center justify-center flex-shrink-0">
                  <svg class="w-5 h-5 sm:w-6 sm:h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>
                </div>
                <div class="min-w-0">
                  <h2 class="text-base sm:text-xl font-bold text-white leading-tight">My Contributions</h2>
                  <p class="text-white/70 text-xs sm:text-sm mt-0.5">Track your contribution fees and payment status</p>
                </div>
              </div>
            </div>

            <!-- Summary Cards -->
            <div class="p-3 sm:p-6 grid grid-cols-3 gap-2 sm:gap-4">
              <div :class="['rounded-2xl p-2.5 sm:p-4 text-center', isCOE ? 'bg-orange-50' : isSOM ? 'bg-green-50' : isCNAHS ? 'bg-green-50' : 'bg-blue-50']">
                <p class="text-xl sm:text-2xl font-bold text-gray-800">{{ myPayments.length }}</p>
                <p class="text-[10px] sm:text-xs text-gray-500 mt-0.5 sm:mt-1 font-medium">Total</p>
              </div>
              <div class="rounded-2xl p-2.5 sm:p-4 text-center bg-green-50">
                <p class="text-xl sm:text-2xl font-bold text-green-700">{{ myPayments.filter(p => p.is_paid).length }}</p>
                <p class="text-[10px] sm:text-xs text-gray-500 mt-0.5 sm:mt-1 font-medium">Paid</p>
              </div>
              <div class="rounded-2xl p-2.5 sm:p-4 text-center bg-red-50">
                <p class="text-xl sm:text-2xl font-bold text-red-600">{{ myPayments.filter(p => !p.is_paid).length }}</p>
                <p class="text-[10px] sm:text-xs text-gray-500 mt-0.5 sm:mt-1 font-medium">Outstanding</p>
              </div>
            </div>
          </div>

          <!-- Records Card -->
          <div class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div class="flex items-center justify-between px-4 sm:px-6 py-3 sm:py-4 border-b border-gray-100">
              <div class="flex items-center gap-2">
                <div :class="[isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600', 'w-1 h-5 rounded-full flex-shrink-0']"></div>
                <h3 class="text-xs sm:text-sm font-bold text-gray-700 uppercase tracking-widest">Payment Records</h3>
              </div>
              <button @click="fetchMyPayments" :disabled="loadingMyPayments" :class="[isCOE ? 'text-orange-600 hover:bg-orange-50' : isSOM ? 'text-green-600 hover:bg-green-50' : isCNAHS ? 'text-green-700 hover:bg-green-50' : 'text-blue-600 hover:bg-blue-50', 'p-2 rounded-xl transition-colors flex items-center gap-1.5 text-xs font-medium']" title="Refresh">
                <svg :class="['w-4 h-4', loadingMyPayments ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                Refresh
              </button>
            </div>

            <!-- Loading -->
            <div v-if="loadingMyPayments" class="flex items-center justify-center py-16">
              <svg :class="['animate-spin h-10 w-10', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : isCNAHS ? 'text-green-500' : 'text-blue-400']" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
              </svg>
            </div>

            <!-- Empty -->
            <div v-else-if="myPayments.length === 0" class="p-12 text-center">
              <div :class="['w-16 h-16 mx-auto mb-4 rounded-full flex items-center justify-center', isCOE ? 'bg-orange-50' : isSOM ? 'bg-green-50' : isCNAHS ? 'bg-green-50' : 'bg-blue-50']">
                <svg :class="['w-8 h-8', isCOE ? 'text-orange-300' : isSOM ? 'text-green-300' : isCNAHS ? 'text-green-400' : 'text-blue-300']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>
              </div>
              <p class="text-base font-semibold text-gray-500">No contribution records yet</p>
              <p class="text-sm text-gray-400 mt-1">Your payment records will appear here once fees are assigned by your college admin.</p>
            </div>

            <!-- Table -->
            <div v-else>
              <!-- Mobile card list (xs only) -->
              <div class="block sm:hidden divide-y divide-gray-100">
                <div v-for="record in myPayments.slice(0, myPaymentsLimit)" :key="record._id + '-m'" class="px-4 py-3 hover:bg-gray-50 transition-colors">
                  <div class="flex items-start justify-between gap-2 mb-1.5">
                    <p class="font-semibold text-sm text-gray-900 leading-tight flex-1">{{ record.title }}</p>
                    <span :class="['inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-bold flex-shrink-0',
                      record.is_paid ? 'bg-green-100 text-green-700' :
                      record.payment_status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                      'bg-red-100 text-red-700']">
                      <svg v-if="record.is_paid" class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                      {{ record.is_paid ? 'Paid' : record.payment_status === 'pending' ? 'Pending' : 'Unpaid' }}
                    </span>
                  </div>
                  <div class="flex items-center justify-between gap-2">
                    <div class="flex items-center gap-3 min-w-0">
                      <span :class="['text-sm font-bold', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-800' : 'text-blue-700']">₱{{ Number(record.amount_due).toLocaleString('en-PH', { minimumFractionDigits: 2 }) }}</span>
                      <span v-if="record.is_paid && record.amount_paid" class="text-[10px] text-gray-400">Paid: ₱{{ Number(record.amount_paid).toLocaleString('en-PH', { minimumFractionDigits: 2 }) }}</span>
                    </div>
                    <span v-if="record.deadline" class="text-[10px] text-gray-400 flex-shrink-0">Due {{ new Date(record.deadline).toLocaleDateString('en-PH', { month: 'short', day: 'numeric' }) }}</span>
                  </div>
                  <p v-if="record.description" class="text-[11px] text-gray-400 mt-1 line-clamp-1">{{ record.description }}</p>
                </div>
              </div>
              <!-- Desktop table (sm+) -->
              <div class="hidden sm:block overflow-x-auto">
                <table class="w-full text-sm">
                  <thead>
                    <tr :class="[isCOE ? 'bg-orange-50' : isSOM ? 'bg-green-50' : isCNAHS ? 'bg-green-50' : 'bg-blue-50']">
                      <th :class="['text-left px-5 py-3 font-bold text-xs uppercase tracking-wider', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-800' : 'text-blue-700']">Description</th>
                      <th :class="['text-right px-5 py-3 font-bold text-xs uppercase tracking-wider', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-800' : 'text-blue-700']">Amount</th>
                      <th :class="['text-center px-5 py-3 font-bold text-xs uppercase tracking-wider', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-800' : 'text-blue-700']">Status</th>
                      <th :class="['text-right px-5 py-3 font-bold text-xs uppercase tracking-wider', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-800' : 'text-blue-700']">Deadline</th>
                    </tr>
                  </thead>
                  <tbody class="divide-y divide-gray-100">
                    <tr v-for="record in myPayments.slice(0, myPaymentsLimit)" :key="record._id" class="hover:bg-gray-50 transition-colors">
                      <td class="px-5 py-4">
                        <p class="font-semibold text-gray-900">{{ record.title }}</p>
                        <p v-if="record.description" class="text-xs text-gray-500 mt-0.5 line-clamp-2">{{ record.description }}</p>
                      </td>
                      <td class="px-5 py-4 text-right">
                        <span class="font-bold text-gray-900">₱{{ Number(record.amount_due).toLocaleString('en-PH', { minimumFractionDigits: 2 }) }}</span>
                        <p v-if="record.is_paid && record.amount_paid" class="text-xs text-gray-400 mt-0.5">Paid: ₱{{ Number(record.amount_paid).toLocaleString('en-PH', { minimumFractionDigits: 2 }) }}</p>
                      </td>
                      <td class="px-5 py-4 text-center">
                        <span :class="['inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold',
                          record.is_paid ? 'bg-green-100 text-green-700' :
                          record.payment_status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                          'bg-red-100 text-red-700']">
                          <svg v-if="record.is_paid" class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/></svg>
                          {{ record.is_paid ? 'Paid' : record.payment_status === 'pending' ? 'Pending' : 'Unpaid' }}
                        </span>
                        <p v-if="record.is_paid && record.paid_date" class="text-[10px] text-gray-400 mt-1">{{ new Date(record.paid_date).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }) }}</p>
                      </td>
                      <td class="px-5 py-4 text-right">
                        <span v-if="record.deadline" class="text-xs text-gray-600">{{ new Date(record.deadline).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }) }}</span>
                        <span v-else class="text-xs text-gray-400">—</span>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
              <!-- Load More -->
              <div v-if="myPayments.length > myPaymentsLimit" class="px-4 sm:px-5 py-3 border-t border-gray-100 text-center">
                <button @click="myPaymentsLimit += 10" :class="['px-5 py-2 rounded-xl text-sm font-semibold transition-all hover:scale-105 active:scale-95', isCOE ? 'bg-orange-50 text-orange-700 hover:bg-orange-100' : isSOM ? 'bg-green-50 text-green-700 hover:bg-green-100' : isCNAHS ? 'bg-green-50 text-green-700 hover:bg-green-100' : 'bg-blue-50 text-blue-700 hover:bg-blue-100']">
                  Load More ({{ myPayments.length - myPaymentsLimit }} remaining)
                </button>
              </div>
              <div :class="['px-4 sm:px-5 py-3 flex items-center justify-between border-t border-gray-100', isCOE ? 'bg-orange-50/50' : isSOM ? 'bg-green-50/50' : isCNAHS ? 'bg-green-50/50' : 'bg-blue-50/50']">
                <span class="text-xs text-gray-500">{{ myPayments.filter(p => p.is_paid).length }} of {{ myPayments.length }} paid</span>
                <span :class="['text-xs font-bold', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-800' : 'text-blue-700']">
                  Total: ₱{{ myPayments.reduce((s, p) => s + (p.amount_due || 0), 0).toLocaleString('en-PH', { minimumFractionDigits: 2 }) }}
                </span>
              </div>
            </div>
          </div>
        </div>

        <div v-if="currentPage === 'dashboard' && isAdminLike && inRoleView" class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden mb-8">
          <div :class="['relative h-24 sm:h-28 overflow-hidden', isCOE ? 'bg-gradient-to-br from-orange-600 to-red-700' : isSOM ? 'bg-gradient-to-br from-green-600 to-teal-600' : isCNAHS ? 'bg-gradient-to-br from-emerald-600 to-green-700' : 'bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light']">
            <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
            <div class="light-sweep"></div>
            <div class="absolute inset-0 flex items-center px-4 sm:px-6 md:px-8 gap-3 sm:gap-4">
              <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-white/20 flex items-center justify-center flex-shrink-0">
                <svg class="w-5 h-5 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>
              </div>
              <div class="flex-1 min-w-0">
                <h2 class="text-lg sm:text-xl font-extrabold text-white tracking-tight">Registered Students</h2>
                <p class="text-white/70 text-xs sm:text-sm mt-0.5">Overview of enrolled students by year level and program</p>
              </div>
              <button @click="handleStatsRefresh" :disabled="statsLoading" class="px-3 sm:px-4 py-2 rounded-xl text-white text-sm font-semibold bg-white/20 hover:bg-white/30 border border-white/20 transition flex items-center gap-2 disabled:opacity-60 flex-shrink-0">
                <svg :class="['w-4 h-4', statsLoading ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                <span class="hidden sm:inline">{{ statsLoading ? 'Refreshing...' : 'Refresh' }}</span>
              </button>
            </div>
          </div>
          <div class="p-3 sm:p-4 md:p-6 space-y-4 sm:space-y-6">

          <!-- College Tabs (Master Admin only) -->
          <div v-if="currentUser.isMaster && !isCoAdmin && !isTreasurer" class="flex flex-wrap gap-2 mb-5">
            <button @click="statsViewCollege = null" :class="['px-4 py-1.5 rounded-lg text-sm font-semibold transition-all border', statsViewCollege === null ? 'bg-gradient-to-r from-ssaam-dark to-ssaam-light text-white border-transparent shadow-md' : 'bg-white border-gray-200 text-gray-600 hover:border-blue-300']">All</button>
            <button @click="statsViewCollege = 'CCS'" :class="['px-4 py-1.5 rounded-lg text-sm font-semibold transition-all border', statsViewCollege === 'CCS' ? 'bg-blue-600 text-white border-transparent shadow-md' : 'bg-white border-gray-200 text-gray-600 hover:border-blue-300']">CCS</button>
            <button @click="statsViewCollege = 'COE'" :class="['px-4 py-1.5 rounded-lg text-sm font-semibold transition-all border', statsViewCollege === 'COE' ? 'bg-orange-500 text-white border-transparent shadow-md' : 'bg-white border-gray-200 text-gray-600 hover:border-orange-300']">COE</button>
            <button @click="statsViewCollege = 'SOM'" :class="['px-4 py-1.5 rounded-lg text-sm font-semibold transition-all border', statsViewCollege === 'SOM' ? 'bg-green-600 text-white border-transparent shadow-md' : 'bg-white border-gray-200 text-gray-600 hover:border-green-300']">SOM</button>
            <button @click="statsViewCollege = 'CNAHS'" :class="['px-4 py-1.5 rounded-lg text-sm font-semibold transition-all border', statsViewCollege === 'CNAHS' ? 'bg-teal-600 text-white border-transparent shadow-md' : 'bg-white border-gray-200 text-gray-600 hover:border-teal-300']">CNAHS</button>
          </div>

          <!-- Table: show when not "All" for isMaster, or always for regular admin / co-admin / treasurer -->
          <div v-if="!currentUser.isMaster || statsViewCollege !== null || isCoAdmin || isTreasurer" class="overflow-x-auto text-sm md:text-base rounded-xl">
            <p class="sm:hidden text-[10px] text-gray-400 mb-1 flex items-center justify-end gap-1">
              <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
              Swipe to see all columns
            </p>
            <table class="w-full border-collapse min-w-[360px]">
              <thead>
                <tr :class="themeColors.headerBg">
                  <th :class="['border px-2 sm:px-4 py-2 sm:py-3 text-left font-semibold text-xs sm:text-sm', themeColors.headerText]"></th>
                  <th v-for="prog in displayPrograms" :key="prog" :class="['border px-2 sm:px-4 py-2 sm:py-3 text-center font-semibold text-xs sm:text-sm', themeColors.headerText]">{{ prog }}</th>
                  <th :class="['border px-2 sm:px-4 py-2 sm:py-3 text-center font-semibold text-xs sm:text-sm', themeColors.headerText]">Total</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="year in ['1st Year', '2nd Year', '3rd Year', '4th Year']" :key="year" class="hover:bg-gray-50">
                  <td :class="['border px-2 sm:px-4 py-2 sm:py-4 font-medium text-gray-700 text-xs sm:text-sm', themeColors.rowBorder]">{{ year.toLowerCase().replace('year', 'years') }}</td>
                  <td v-for="prog in displayPrograms" :key="prog" :class="['border px-2 sm:px-4 py-2 sm:py-4 text-center text-xs sm:text-sm', themeColors.rowBorder]">{{ displayStats[prog]?.[year] || 0 }}</td>
                  <td :class="`border px-2 sm:px-4 py-2 sm:py-4 text-center font-bold text-xs sm:text-sm ${themeColors.rowBorder} ${isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-800' : 'text-blue-700'}`">{{ displayPrograms.reduce((sum, prog) => sum + (displayStats[prog]?.[year] || 0), 0) }}</td>
                </tr>
                <tr :class="`font-bold ${themeColors.rowBgAlt}`">
                  <td :class="['border px-2 sm:px-4 py-2 sm:py-4 font-bold text-gray-900 text-xs sm:text-sm', themeColors.rowBorder]">All year levels</td>
                  <td v-for="prog in displayPrograms" :key="prog" :class="['border px-2 sm:px-4 py-2 sm:py-4 text-center text-xs sm:text-sm', themeColors.rowBorder]">{{ displayStats[prog]?.total || 0 }}</td>
                  <td :class="`border px-2 sm:px-4 py-2 sm:py-4 text-center text-xs sm:text-sm ${themeColors.rowBgAltText}`">{{ displayTotal }}</td>
                </tr>
              </tbody>
            </table>
          </div>

          <div class="mt-6 text-center">
            <p :class="['text-lg font-semibold', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">
              Total Registered Students: <span class="text-2xl">{{ currentUser.isMaster && statsViewCollege ? displayTotal : totalStudents }}</span>
            </p>
          </div>
          
          <div class="mt-2 grid grid-cols-3 gap-2 sm:gap-4">
            <!-- RFID Verified -->
            <div :class="['relative rounded-lg p-3 sm:p-4 text-center cursor-pointer transition',
                          isCOE ? 'bg-orange-50 border border-orange-200 hover:bg-orange-100' :
                          isSOM ? 'bg-green-50 border border-green-200 hover:bg-green-100' :
                          isCNAHS ? 'bg-green-50 border border-green-200 hover:bg-green-100' :
                          'bg-green-50 border border-green-200 hover:bg-green-100']" @click="toggleRfidList('verified')">
              <button @click.stop="fetchStats" :class="['absolute top-1.5 right-1.5 p-1 rounded-full transition', isCOE ? 'hover:bg-orange-200' : isSOM ? 'hover:bg-green-200' : isCNAHS ? 'hover:bg-green-200' : 'hover:bg-green-200']" title="Refresh">
                <svg :class="['w-3 h-3', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : isCNAHS ? 'text-green-500' : 'text-green-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
              </button>
              <div class="flex flex-col items-center gap-1 mb-2">
                <svg :class="['w-5 h-5 sm:w-6 sm:h-6', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-green-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                <span :class="['text-[10px] sm:text-xs font-semibold leading-tight', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : isCNAHS ? 'text-green-700' : 'text-green-700']">RFID Verified</span>
              </div>
              <p :class="['text-xl sm:text-3xl font-bold', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-green-600']">{{ verifiedCount }}</p>
              <p :class="['text-[10px] sm:text-xs mt-1', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : isCNAHS ? 'text-green-500' : 'text-green-500']">tap to view</p>
            </div>
            <!-- RFID Unverified -->
            <div :class="['relative rounded-lg p-3 sm:p-4 text-center cursor-pointer transition',
                          isCOE ? 'bg-orange-50 border border-orange-200 hover:bg-orange-100' :
                          isSOM ? 'bg-yellow-50 border border-yellow-200 hover:bg-yellow-100' :
                          isCNAHS ? 'bg-yellow-50 border border-yellow-200 hover:bg-yellow-100' :
                          'bg-yellow-50 border border-yellow-200 hover:bg-yellow-100']" @click="toggleRfidList('unverified')">
              <button @click.stop="fetchStats" :class="['absolute top-1.5 right-1.5 p-1 rounded-full transition', isCOE ? 'hover:bg-orange-200' : isSOM ? 'hover:bg-yellow-200' : isCNAHS ? 'hover:bg-yellow-200' : 'hover:bg-yellow-200']" title="Refresh">
                <svg :class="['w-3 h-3', isCOE ? 'text-orange-500' : isSOM ? 'text-yellow-500' : isCNAHS ? 'text-yellow-500' : 'text-yellow-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
              </button>
              <div class="flex flex-col items-center gap-1 mb-2">
                <svg :class="['w-5 h-5 sm:w-6 sm:h-6', isCOE ? 'text-orange-600' : isSOM ? 'text-yellow-600' : isCNAHS ? 'text-yellow-600' : 'text-yellow-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                <span :class="['text-[10px] sm:text-xs font-semibold leading-tight', isCOE ? 'text-orange-700' : isSOM ? 'text-yellow-700' : isCNAHS ? 'text-yellow-700' : 'text-yellow-700']">Unverified</span>
              </div>
              <p :class="['text-xl sm:text-3xl font-bold', isCOE ? 'text-orange-600' : isSOM ? 'text-yellow-600' : isCNAHS ? 'text-yellow-600' : 'text-yellow-600']">{{ unverifiedCount }}</p>
              <p :class="['text-[10px] sm:text-xs mt-1', isCOE ? 'text-orange-500' : isSOM ? 'text-yellow-500' : isCNAHS ? 'text-yellow-500' : 'text-yellow-500']">tap to view</p>
            </div>
            <!-- RFID Unreadable -->
            <div :class="['relative rounded-lg p-3 sm:p-4 text-center cursor-pointer transition',
                          isCOE ? 'bg-orange-50 border border-orange-200 hover:bg-orange-100' :
                          isSOM ? 'bg-gray-50 border border-gray-200 hover:bg-gray-100' :
                          isCNAHS ? 'bg-gray-50 border border-gray-200 hover:bg-gray-100' :
                          'bg-gray-50 border border-gray-200 hover:bg-gray-100']" @click="toggleRfidList('unreadable')">
              <button @click.stop="fetchStats" :class="['absolute top-1.5 right-1.5 p-1 rounded-full transition', isCOE ? 'hover:bg-orange-200' : isSOM ? 'hover:bg-gray-200' : isCNAHS ? 'hover:bg-gray-200' : 'hover:bg-gray-200']" title="Refresh">
                <svg :class="['w-3 h-3', isCOE ? 'text-orange-500' : isSOM ? 'text-gray-500' : isCNAHS ? 'text-gray-500' : 'text-gray-500']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
              </button>
              <div class="flex flex-col items-center gap-1 mb-2">
                <svg :class="['w-5 h-5 sm:w-6 sm:h-6', isCOE ? 'text-orange-600' : isSOM ? 'text-gray-600' : isCNAHS ? 'text-gray-600' : 'text-gray-600']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                <span :class="['text-[10px] sm:text-xs font-semibold leading-tight', isCOE ? 'text-orange-700' : isSOM ? 'text-gray-700' : isCNAHS ? 'text-gray-700' : 'text-gray-700']">Unreadable</span>
              </div>
              <p :class="['text-xl sm:text-3xl font-bold', isCOE ? 'text-orange-600' : isSOM ? 'text-gray-600' : isCNAHS ? 'text-gray-600' : 'text-gray-600']">{{ unreadableCount }}</p>
              <p :class="['text-[10px] sm:text-xs mt-1', isCOE ? 'text-orange-500' : isSOM ? 'text-gray-500' : isCNAHS ? 'text-gray-500' : 'text-gray-500']">tap to view</p>
            </div>
          </div>
          
          <transition name="ssaam-rfid-list">
          <div v-if="showRfidList" :class="['mt-6 bg-white rounded-lg p-4 border', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : isCNAHS ? 'border-green-200' : 'border-blue-200']">
            <div class="flex items-center justify-between mb-4">
              <h4 :class="['text-lg font-semibold', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">
                {{ rfidListType === 'verified' ? 'Verified Users' : rfidListType === 'unverified' ? 'Unverified Users' : 'Unreadable Status Users' }}
                <span class="text-sm font-normal text-gray-500 ml-2">({{ rfidListDisplayUsers.length }} of {{ rfidListFilteredUsers.length }})</span>
              </h4>
              <button @click="showRfidList = false" class="text-gray-500 hover:text-gray-700">
                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            
            <!-- Filters -->
            <div class="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-4">
              <input v-model="rfidListSearch" type="text" placeholder="Search by name..." :class="['px-3 py-2 border rounded-lg text-sm focus:ring-2 outline-none', isCOE ? 'border-orange-300 focus:ring-orange-600' : isSOM ? 'border-green-300 focus:ring-green-600' : isCNAHS ? 'border-green-300 focus:ring-green-600' : 'border-gray-300 focus:ring-blue-600']" />
              <select v-model="rfidListFilterProgram" :class="['px-3 py-2 border rounded-lg text-sm focus:ring-2 outline-none', isCOE ? 'border-orange-300 focus:ring-orange-600' : isSOM ? 'border-green-300 focus:ring-green-600' : isCNAHS ? 'border-green-300 focus:ring-green-600' : 'border-gray-300 focus:ring-blue-600']">
                <option value="">All Programs</option>
                <option value="BSCS">BSCS</option>
                <option value="BSIS">BSIS</option>
                <option value="BSIT">BSIT</option>
              </select>
              <select v-model="rfidListFilterYear" :class="['px-3 py-2 border rounded-lg text-sm focus:ring-2 outline-none', isCOE ? 'border-orange-300 focus:ring-orange-600' : isSOM ? 'border-green-300 focus:ring-green-600' : isCNAHS ? 'border-green-300 focus:ring-green-600' : 'border-gray-300 focus:ring-blue-600']">
                <option value="">All Year Levels</option>
                <option value="1st Year">1st Year</option>
                <option value="2nd Year">2nd Year</option>
                <option value="3rd Year">3rd Year</option>
                <option value="4th Year">4th Year</option>
              </select>
            </div>
            
            <div v-if="rfidListLoading" class="flex items-center justify-center py-8">
              <svg :class="['animate-spin h-8 w-8', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : isCNAHS ? 'text-green-600' : 'text-blue-600']" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
              </svg>
            </div>
            <div v-else-if="rfidListFilteredUsers.length === 0" class="text-center text-gray-500 py-8">
              No users found in this category.
            </div>
            <div v-else class="max-h-96 overflow-x-auto overflow-y-auto">
              <table class="w-full text-sm min-w-[560px]">
                <thead :class="['sticky top-0', isCOE ? 'bg-orange-50' : isSOM ? 'bg-green-50' : isCNAHS ? 'bg-green-50' : 'bg-blue-50']">
                  <tr>
                    <th :class="['text-left px-3 py-2 font-medium', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">Student ID</th>
                    <th :class="['text-left px-3 py-2 font-medium cursor-pointer', isCOE ? 'text-orange-900 hover:text-orange-700' : isSOM ? 'text-green-900 hover:text-green-700' : isCNAHS ? 'text-green-900 hover:text-green-700' : 'text-blue-900 hover:text-blue-700']" @click="toggleRfidListSort">
                      Name
                      <span v-if="rfidListSortAsc">↑</span>
                      <span v-else>↓</span>
                    </th>
                    <th :class="['text-left px-3 py-2 font-medium', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">Program</th>
                    <th :class="['text-left px-3 py-2 font-medium', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">Year</th>
                    <th :class="['text-left px-3 py-2 font-medium', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">RFID Code</th>
                    <th :class="['text-left px-3 py-2 font-medium', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : isCNAHS ? 'text-green-900' : 'text-blue-900']">Status</th>
                  </tr>
                </thead>
                <tbody class="divide-y divide-gray-100">
                  <tr v-for="(user, idx) in rfidListDisplayUsers" :key="user.student_id"
                    class="hover:bg-gray-50 ssaam-row-anim"
                    :style="{ animationDelay: Math.min(idx * 30, 600) + 'ms' }">
                    <td class="px-3 py-2 text-gray-700">{{ user.student_id }}</td>
                    <td class="px-3 py-2 text-gray-700">{{ user.full_name || `${user.first_name} ${user.last_name}` }}</td>
                    <td class="px-3 py-2 text-gray-700">{{ user.program }}</td>
                    <td class="px-3 py-2 text-gray-700">{{ user.year_level }}</td>
                    <td class="px-3 py-2 text-gray-700">{{ user.rfid_code || 'N/A' }}</td>
                    <td class="px-3 py-2">
                      <span :class="['px-2 py-1 rounded-full text-xs font-medium', 
                        user.rfid_status === 'verified' ? 'bg-green-100 text-green-800' : 
                        user.rfid_status === 'unverified' ? 'bg-yellow-100 text-yellow-800' : 
                        'bg-gray-100 text-gray-800']">
                        {{ user.rfid_status === 'verified' ? 'Verified' : user.rfid_status === 'unverified' ? 'Unverified' : 'Unreadable' }}
                      </span>
                    </td>
                  </tr>
                </tbody>
              </table>
              
              <!-- Load More Button -->
              <div v-if="rfidListDisplayUsers.length < rfidListFilteredUsers.length" class="mt-4 text-center">
                <button @click="loadMoreRfidUsers" :class="['px-6 py-2 rounded-lg transition font-medium text-sm', isCOE ? 'bg-orange-100 text-orange-700 hover:bg-orange-200' : isSOM ? 'bg-green-100 text-green-700 hover:bg-green-200' : isCNAHS ? 'bg-green-100 text-green-700 hover:bg-green-200' : 'bg-blue-100 text-blue-700 hover:bg-blue-200']">
                  Load More ({{ rfidListFilteredUsers.length - rfidListDisplayUsers.length }} remaining)
                </button>
              </div>
            </div>
          </div>
          </transition>
          </div>

          <!-- Quick Actions: Create Event -->
          <div class="px-4 pb-4 sm:px-6 md:px-8 md:pb-6 border-t border-gray-100 pt-4">
            <div class="flex items-center gap-2 mb-4">
              <div :class="[isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600', 'w-1 h-6 rounded-full']"></div>
              <h3 class="text-sm font-bold text-gray-400 uppercase tracking-widest">Quick Actions</h3>
            </div>
            <div class="grid grid-cols-2 lg:grid-cols-3 gap-3">
              <!-- Create Event Card -->
              <button @click="openCreateEventModal" :class="['group relative overflow-hidden rounded-2xl border-2 p-5 text-left transition-all hover:shadow-lg hover:-translate-y-0.5 active:scale-95',
                isCOE ? 'border-orange-100 bg-orange-50 hover:border-orange-300' :
                isSOM ? 'border-green-100 bg-green-50 hover:border-green-300' :
                isCNAHS ? 'border-green-100 bg-green-50 hover:border-green-300' :
                'border-blue-100 bg-blue-50 hover:border-blue-300']">
                <div :class="['absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity', isCOE ? 'bg-gradient-to-br from-orange-100/60 to-transparent' : isSOM ? 'bg-gradient-to-br from-green-100/60 to-transparent' : isCNAHS ? 'bg-gradient-to-br from-green-100/60 to-transparent' : 'bg-gradient-to-br from-blue-100/60 to-transparent']"></div>
                <div class="relative">
                  <div :class="['w-10 h-10 rounded-xl flex items-center justify-center mb-3 shadow-sm', isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600']">
                    <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
                  </div>
                  <p :class="['font-bold text-gray-900 mb-0.5']">Create Event</p>
                  <p class="text-xs text-gray-500">Schedule a new attendance event with sessions</p>
                </div>
              </button>
              <!-- Go to Attendance -->
              <button @click="currentPage = 'attendance'; fetchAttendanceData()" :class="['group relative overflow-hidden rounded-2xl border-2 p-5 text-left transition-all hover:shadow-lg hover:-translate-y-0.5 active:scale-95',
                isCOE ? 'border-orange-100 bg-orange-50 hover:border-orange-300' :
                isSOM ? 'border-green-100 bg-green-50 hover:border-green-300' :
                isCNAHS ? 'border-green-100 bg-green-50 hover:border-green-300' :
                'border-blue-100 bg-blue-50 hover:border-blue-300']">
                <div :class="['absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity', isCOE ? 'bg-gradient-to-br from-orange-100/60 to-transparent' : isSOM ? 'bg-gradient-to-br from-green-100/60 to-transparent' : isCNAHS ? 'bg-gradient-to-br from-green-100/60 to-transparent' : 'bg-gradient-to-br from-blue-100/60 to-transparent']"></div>
                <div class="relative">
                  <div :class="['w-10 h-10 rounded-xl flex items-center justify-center mb-3 shadow-sm', isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600']">
                    <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
                  </div>
                  <p class="font-bold text-gray-900 mb-0.5">Manage Attendance</p>
                  <p class="text-xs text-gray-500">View events, sessions, and attendance logs</p>
                </div>
              </button>
              <!-- Go to Contributions -->
              <button @click="currentPage = 'contributions'" :class="['group relative overflow-hidden rounded-2xl border-2 p-5 text-left transition-all hover:shadow-lg hover:-translate-y-0.5 active:scale-95',
                isCOE ? 'border-orange-100 bg-orange-50 hover:border-orange-300' :
                isSOM ? 'border-green-100 bg-green-50 hover:border-green-300' :
                isCNAHS ? 'border-green-100 bg-green-50 hover:border-green-300' :
                'border-blue-100 bg-blue-50 hover:border-blue-300']">
                <div :class="['absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity', isCOE ? 'bg-gradient-to-br from-orange-100/60 to-transparent' : isSOM ? 'bg-gradient-to-br from-green-100/60 to-transparent' : isCNAHS ? 'bg-gradient-to-br from-green-100/60 to-transparent' : 'bg-gradient-to-br from-blue-100/60 to-transparent']"></div>
                <div class="relative">
                  <div :class="['w-10 h-10 rounded-xl flex items-center justify-center mb-3 shadow-sm', isCOE ? 'bg-orange-600' : isSOM ? 'bg-green-600' : isCNAHS ? 'bg-green-700' : 'bg-blue-600']">
                    <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
                  </div>
                  <p class="font-bold text-gray-900 mb-0.5">Contributions</p>
                  <p class="text-xs text-gray-500">Track and manage student payment records</p>
                </div>
              </button>
            </div>
          </div>
        </div>

        <!-- All Colleges Statistics (Master Admin Only) -->
        <div v-if="currentPage === 'dashboard' && currentUser.isMaster && !isCoAdmin && !isTreasurer" class="mt-6">
          <div class="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
            <div class="relative h-24 bg-gradient-to-br from-ssaam-dark via-blue-700 to-ssaam-light overflow-hidden">
              <div class="absolute inset-0 opacity-20 mix-blend-overlay bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>
              <div class="light-sweep"></div>
              <div class="absolute inset-0 flex items-center justify-between px-6 md:px-8">
                <div>
                  <h2 class="text-xl md:text-2xl font-extrabold text-white tracking-tight">All Colleges Overview</h2>
                  <p class="text-white/70 text-sm">Registered students across all departments</p>
                </div>
                <button @click="fetchAllCollegesStats" :disabled="allCollegesLoading" class="px-4 py-2 rounded-xl text-white text-sm font-semibold bg-white/20 hover:bg-white/30 border border-white/20 transition flex items-center gap-2 disabled:opacity-60">
                  <svg :class="['w-4 h-4', allCollegesLoading ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path></svg>
                  {{ allCollegesLoading ? 'Loading...' : 'Refresh' }}
                </button>
              </div>
            </div>

            <div class="p-4 md:p-6">
              <div v-if="allCollegesLoading" class="flex items-center justify-center py-12">
                <svg class="animate-spin h-10 w-10 text-blue-600" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
              </div>
              <div v-else class="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
                <!-- CCS -->
                <div class="rounded-2xl border border-blue-100 overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                  <div class="relative h-16 bg-gradient-to-br from-blue-700 to-ssaam-light overflow-hidden flex items-center gap-3 px-4">
                    <img src="/icons/ccs.svg" alt="CCS" class="h-10 w-10 object-contain opacity-90" />
                    <div>
                      <p class="text-white font-extrabold text-base">CCS</p>
                      <p class="text-white/70 text-[10px]">College of Computing Studies</p>
                    </div>
                  </div>
                  <div class="p-4 bg-blue-50/30">
                    <div v-if="allCollegesStats.CCS">
                      <p class="text-3xl font-extrabold text-blue-700">{{ allCollegesStats.CCS.total }}</p>
                      <p class="text-xs text-gray-500 mt-1">Registered Students</p>
                      <div class="mt-3 space-y-1">
                        <template v-for="(count, prog) in allCollegesStats.CCS.stats" :key="prog">
                          <div v-if="count.total > 0" class="flex justify-between text-xs text-gray-600">
                            <span>{{ prog }}</span><span class="font-semibold text-blue-700">{{ count.total || 0 }}</span>
                          </div>
                        </template>
                      </div>
                    </div>
                    <div v-else class="text-center py-4 text-gray-400 text-sm">No data</div>
                  </div>
                </div>

                <!-- COE -->
                <div class="rounded-2xl border border-orange-100 overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                  <div class="relative h-16 bg-gradient-to-br from-orange-600 to-red-600 overflow-hidden flex items-center gap-3 px-4">
                    <img src="/icons/coe.svg" alt="COE" class="h-10 w-10 object-contain opacity-90" />
                    <div>
                      <p class="text-white font-extrabold text-base">COE</p>
                      <p class="text-white/70 text-[10px]">College of Engineering</p>
                    </div>
                  </div>
                  <div class="p-4 bg-orange-50/30">
                    <div v-if="allCollegesStats.COE">
                      <p class="text-3xl font-extrabold text-orange-600">{{ allCollegesStats.COE.total }}</p>
                      <p class="text-xs text-gray-500 mt-1">Registered Students</p>
                      <div class="mt-3 space-y-1">
                        <template v-for="(count, prog) in allCollegesStats.COE.stats" :key="prog">
                          <div v-if="count.total > 0" class="flex justify-between text-xs text-gray-600">
                            <span>{{ prog }}</span><span class="font-semibold text-orange-600">{{ count.total || 0 }}</span>
                          </div>
                        </template>
                      </div>
                    </div>
                    <div v-else class="text-center py-4 text-gray-400 text-sm">No data</div>
                  </div>
                </div>

                <!-- SOM -->
                <div class="rounded-2xl border border-green-100 overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                  <div class="relative h-16 bg-gradient-to-br from-green-600 to-teal-600 overflow-hidden flex items-center gap-3 px-4">
                    <img src="/icons/som.svg" alt="SOM" class="h-10 w-10 object-contain opacity-90" />
                    <div>
                      <p class="text-white font-extrabold text-base">SOM</p>
                      <p class="text-white/70 text-[10px]">School of Midwifery</p>
                    </div>
                  </div>
                  <div class="p-4 bg-green-50/30">
                    <div v-if="allCollegesStats.SOM">
                      <p class="text-3xl font-extrabold text-green-600">{{ allCollegesStats.SOM.total }}</p>
                      <p class="text-xs text-gray-500 mt-1">Registered Students</p>
                      <div class="mt-3 space-y-1">
                        <template v-for="(count, prog) in allCollegesStats.SOM.stats" :key="prog">
                          <div v-if="count.total > 0" class="flex justify-between text-xs text-gray-600">
                            <span>{{ prog }}</span><span class="font-semibold text-green-600">{{ count.total || 0 }}</span>
                          </div>
                        </template>
                      </div>
                    </div>
                    <div v-else class="text-center py-4 text-gray-400 text-sm">No data</div>
                  </div>
                </div>

                <!-- CNAHS -->
                <div class="rounded-2xl border border-emerald-100 overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                  <div class="relative h-16 bg-gradient-to-br from-emerald-600 to-green-700 overflow-hidden flex items-center gap-3 px-4">
                    <img src="/icons/cnahs.svg" alt="CNAHS" class="h-10 w-10 object-contain opacity-90" />
                    <div>
                      <p class="text-white font-extrabold text-base">CNAHS</p>
                      <p class="text-white/70 text-[10px]">College of Nursing and Allied Health Sciences</p>
                    </div>
                  </div>
                  <div class="p-4 bg-emerald-50/30">
                    <div v-if="allCollegesStats.CNAHS">
                      <p class="text-3xl font-extrabold text-emerald-600">{{ allCollegesStats.CNAHS.total }}</p>
                      <p class="text-xs text-gray-500 mt-1">Registered Students</p>
                      <div class="mt-3 space-y-1">
                        <template v-for="(count, prog) in allCollegesStats.CNAHS.stats" :key="prog">
                          <div v-if="count.total > 0" class="flex justify-between text-xs text-gray-600">
                            <span>{{ prog }}</span><span class="font-semibold text-emerald-600">{{ count.total || 0 }}</span>
                          </div>
                        </template>
                      </div>
                    </div>
                    <div v-else class="text-center py-4 text-gray-400 text-sm">No data</div>
                  </div>
                </div>
              </div>

              <!-- Grand Total -->
              <div v-if="!allCollegesLoading && (allCollegesStats.CCS || allCollegesStats.COE || allCollegesStats.SOM || allCollegesStats.CNAHS)" class="mt-5 p-4 bg-gradient-to-r from-ssaam-dark to-ssaam-light rounded-2xl text-white text-center">
                <p class="text-sm font-medium text-white/80">Grand Total — All Colleges</p>
                <p class="text-4xl font-extrabold mt-1">
                  {{ (allCollegesStats.CCS?.total || 0) + (allCollegesStats.COE?.total || 0) + (allCollegesStats.SOM?.total || 0) + (allCollegesStats.CNAHS?.total || 0) }}
                </p>
                <p class="text-white/60 text-xs mt-1">Registered students across JRMSU</p>
              </div>
            </div>
          </div>
        </div>

        <div v-if="currentPage === 'dashboard'" class="mt-6 pb-2 flex items-center justify-center gap-3">
          <button
            type="button"
            @click="showTermsModal = true; tcOpenSection = 0"
            class="inline-flex items-center gap-1.5 text-[11px] text-gray-400 hover:text-gray-600 transition-colors group"
          >
            <svg class="w-3 h-3 opacity-60 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
            <span class="underline underline-offset-2">Terms &amp; Conditions</span>
          </button>
          <span class="text-gray-200 text-xs select-none">·</span>
          <button
            type="button"
            @click="showPrivacyModal = true; privacyOpenSection = 0"
            class="inline-flex items-center gap-1.5 text-[11px] text-gray-400 hover:text-gray-600 transition-colors group"
          >
            <svg class="w-3 h-3 opacity-60 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
            <span class="underline underline-offset-2">Privacy Policy</span>
          </button>
        </div>

      </div>
      </Transition>
    </div>
  </div>


  <!-- Privacy Policy Modal -->
  <Transition name="fade">
    <div
      v-if="showPrivacyModal"
      class="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4"
      style="background: rgba(5,30,30,0.65); backdrop-filter: blur(6px);"
      @click.self="showPrivacyModal = false"
    >
      <div class="bg-white w-full sm:max-w-2xl sm:rounded-3xl rounded-t-3xl overflow-hidden shadow-2xl flex flex-col" style="max-height: 92vh;">

        <!-- Header -->
        <div class="relative bg-gradient-to-br from-teal-700 via-cyan-700 to-emerald-700 px-5 pt-5 pb-4 flex-shrink-0 overflow-hidden">
          <div class="pointer-events-none absolute -top-8 -right-8 w-36 h-36 rounded-full bg-white/5"></div>
          <div class="pointer-events-none absolute -bottom-6 left-10 w-20 h-20 rounded-full bg-white/5"></div>
          <div class="pointer-events-none absolute top-1/2 left-1/3 w-10 h-10 rounded-full bg-white/5"></div>
          <div class="relative flex items-center gap-3">
            <div class="w-11 h-11 bg-white/15 backdrop-blur-sm rounded-2xl flex items-center justify-center flex-shrink-0 ring-1 ring-white/20">
              <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
            </div>
            <div class="flex-1 min-w-0">
              <h2 class="text-white text-base sm:text-lg font-black leading-tight tracking-tight">Privacy Policy</h2>
              <p class="text-white/60 text-[10px] sm:text-xs mt-0.5 truncate">SSAAM · CCS - Jose Rizal Memorial State University</p>
            </div>
            <button
              @click="showPrivacyModal = false"
              class="flex-shrink-0 w-9 h-9 rounded-full bg-white/15 hover:bg-white/25 flex items-center justify-center transition-all active:scale-90 ring-1 ring-white/20"
              aria-label="Close"
            >
              <svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
            </button>
          </div>
          <p class="relative text-white/65 text-[11px] mt-3 leading-relaxed">
            SSAAM is committed to protecting your personal data. This policy explains what we collect, how we use it, and your rights under the Philippine Data Privacy Act of 2012 (R.A. 10173).
          </p>
        </div>

        <!-- Accordion Body -->
        <div class="modal-inner-scroll flex-1 bg-gray-50/80">
          <div class="p-3 sm:p-4 space-y-2">
            <div
              v-for="(section, idx) in privacySections"
              :key="idx"
              class="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 transition-shadow hover:shadow-md"
            >
              <button
                @click="privacyOpenSection = privacyOpenSection === idx ? null : idx"
                class="w-full flex items-center gap-3 px-4 py-3 sm:py-3.5 text-left focus:outline-none"
              >
                <div :class="['w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 text-white text-xs font-black shadow-sm', section.color]">
                  {{ idx + 1 }}
                </div>
                <span class="flex-1 font-bold text-gray-800 text-sm leading-tight">{{ section.title }}</span>
                <svg
                  :class="['w-4 h-4 text-gray-400 transition-transform duration-300 flex-shrink-0', privacyOpenSection === idx ? 'rotate-180 text-teal-500' : '']"
                  fill="none" stroke="currentColor" viewBox="0 0 24 24"
                ><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M19 9l-7 7-7-7"/></svg>
              </button>
              <Transition name="tc-accordion">
                <div v-if="privacyOpenSection === idx" class="px-4 pb-4">
                  <div class="h-px bg-gray-100 mb-3"></div>
                  <ul class="space-y-2.5">
                    <li
                      v-for="(point, pi) in section.points"
                      :key="pi"
                      class="flex gap-2.5 text-xs text-gray-600 leading-relaxed"
                    >
                      <span :class="['flex-shrink-0 mt-1.5 w-1.5 h-1.5 rounded-full', section.dot]"></span>
                      <span>{{ point }}</span>
                    </li>
                  </ul>
                </div>
              </Transition>
            </div>
          </div>
        </div>

        <!-- Footer -->
        <div class="flex-shrink-0 bg-white border-t border-gray-100 px-4 py-3 space-y-2.5">
          <!-- Prev / dots / Next row -->
          <div class="flex items-center justify-between gap-2">
            <button
              @click="privacyOpenSection = privacyOpenSection > 0 ? privacyOpenSection - 1 : 0"
              :disabled="privacyOpenSection === 0 || privacyOpenSection === null"
              class="flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold text-gray-600 bg-gray-100 hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95"
            >
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              Prev
            </button>
            <div class="flex items-center gap-1">
              <button
                v-for="(_, i) in privacySections"
                :key="i"
                @click="privacyOpenSection = i"
                :class="['h-1.5 rounded-full transition-all duration-200', privacyOpenSection === i ? 'w-4 bg-teal-500' : 'w-1.5 bg-gray-300 hover:bg-gray-400']"
              ></button>
            </div>
            <button
              @click="privacyOpenSection = privacyOpenSection < privacySections.length - 1 ? privacyOpenSection + 1 : privacySections.length - 1"
              :disabled="privacyOpenSection === privacySections.length - 1"
              class="flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold text-gray-600 bg-gray-100 hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95"
            >
              Next
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
            </button>
          </div>
          <!-- Last updated + keyboard hint + close -->
          <div class="flex items-center justify-between gap-3">
            <div class="flex items-center gap-2 min-w-0">
              <p class="text-[10px] text-gray-400 whitespace-nowrap">Last updated: <span class="font-semibold text-gray-500">May 1, 2026</span></p>
              <span class="hidden sm:inline-flex items-center gap-0.5 text-[9px] text-gray-300 bg-gray-50 border border-gray-100 rounded-lg px-1.5 py-0.5 whitespace-nowrap">
                <svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/></svg>
                <svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                arrow keys
              </span>
            </div>
            <button
              @click="showPrivacyModal = false"
              :class="['flex-shrink-0 px-4 py-1.5 rounded-xl font-bold text-white text-xs tracking-wide transition-all hover:-translate-y-0.5 active:scale-95 shadow-sm bg-gradient-to-r',
                isCOE ? 'from-orange-600 to-amber-500'
                : isSOM ? 'from-green-600 to-emerald-500'
                : isCNAHS ? 'from-emerald-600 to-teal-500'
                : 'from-teal-600 to-emerald-600']"
            >Close</button>
          </div>
        </div>

      </div>
    </div>
  </Transition>

  <!-- Terms & Conditions Modal -->
  <Transition name="fade">
    <div
      v-if="showTermsModal"
      class="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4"
      style="background: rgba(15,10,40,0.65); backdrop-filter: blur(6px);"
      @click.self="showTermsModal = false"
    >
      <div class="bg-white w-full sm:max-w-2xl sm:rounded-3xl rounded-t-3xl overflow-hidden shadow-2xl flex flex-col" style="max-height: 92vh;">

        <!-- Header -->
        <div class="relative bg-gradient-to-br from-violet-700 via-indigo-700 to-blue-700 px-5 pt-5 pb-4 flex-shrink-0 overflow-hidden">
          <div class="pointer-events-none absolute -top-8 -right-8 w-36 h-36 rounded-full bg-white/5"></div>
          <div class="pointer-events-none absolute -bottom-6 left-10 w-20 h-20 rounded-full bg-white/5"></div>
          <div class="pointer-events-none absolute top-1/2 left-1/3 w-10 h-10 rounded-full bg-white/5"></div>
          <div class="relative flex items-center gap-3">
            <div class="w-11 h-11 bg-white/15 backdrop-blur-sm rounded-2xl flex items-center justify-center flex-shrink-0 ring-1 ring-white/20">
              <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
            </div>
            <div class="flex-1 min-w-0">
              <h2 class="text-white text-base sm:text-lg font-black leading-tight tracking-tight">Terms &amp; Conditions</h2>
              <p class="text-white/60 text-[10px] sm:text-xs mt-0.5 truncate">SSAAM · CCS - Jose Rizal Memorial State University</p>
            </div>
            <button
              @click="showTermsModal = false"
              class="flex-shrink-0 w-9 h-9 rounded-full bg-white/15 hover:bg-white/25 flex items-center justify-center transition-all active:scale-90 ring-1 ring-white/20"
              aria-label="Close"
            >
              <svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
            </button>
          </div>
          <p class="relative text-white/65 text-[11px] mt-3 leading-relaxed">
            By using SSAAM you agree to the following terms governing attendance, financial contributions, and your personal data within JRMSU.
          </p>
        </div>

        <!-- Accordion Body -->
        <div class="modal-inner-scroll flex-1 bg-gray-50/80">
          <div class="p-3 sm:p-4 space-y-2">
            <div
              v-for="(section, idx) in tcSections"
              :key="idx"
              class="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 transition-shadow hover:shadow-md"
            >
              <button
                @click="tcOpenSection = tcOpenSection === idx ? null : idx"
                class="w-full flex items-center gap-3 px-4 py-3 sm:py-3.5 text-left focus:outline-none"
              >
                <div :class="['w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 text-white text-xs font-black shadow-sm', section.color]">
                  {{ idx + 1 }}
                </div>
                <span class="flex-1 font-bold text-gray-800 text-sm leading-tight">{{ section.title }}</span>
                <svg
                  :class="['w-4 h-4 text-gray-400 transition-transform duration-300 flex-shrink-0', tcOpenSection === idx ? 'rotate-180 text-indigo-500' : '']"
                  fill="none" stroke="currentColor" viewBox="0 0 24 24"
                ><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M19 9l-7 7-7-7"/></svg>
              </button>
              <Transition name="tc-accordion">
                <div v-if="tcOpenSection === idx" class="px-4 pb-4">
                  <div class="h-px bg-gray-100 mb-3"></div>
                  <ul class="space-y-2.5">
                    <li
                      v-for="(point, pi) in section.points"
                      :key="pi"
                      class="flex gap-2.5 text-xs text-gray-600 leading-relaxed"
                    >
                      <span :class="['flex-shrink-0 mt-1.5 w-1.5 h-1.5 rounded-full', section.dot]"></span>
                      <span>{{ point }}</span>
                    </li>
                  </ul>
                </div>
              </Transition>
            </div>
          </div>
        </div>

        <!-- Footer -->
        <div class="flex-shrink-0 bg-white border-t border-gray-100 px-4 py-3 space-y-2.5">
          <div class="flex items-center justify-between gap-2">
            <button
              @click="tcOpenSection = tcOpenSection > 0 ? tcOpenSection - 1 : 0"
              :disabled="tcOpenSection === 0 || tcOpenSection === null"
              class="flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold text-gray-600 bg-gray-100 hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95"
            >
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M15 19l-7-7 7-7"/></svg>
              Prev
            </button>
            <div class="flex items-center gap-1">
              <button
                v-for="(_, i) in tcSections"
                :key="i"
                @click="tcOpenSection = i"
                :class="['h-1.5 rounded-full transition-all duration-200', tcOpenSection === i ? 'w-4 bg-indigo-500' : 'w-1.5 bg-gray-300 hover:bg-gray-400']"
              ></button>
            </div>
            <button
              @click="tcOpenSection = tcOpenSection < tcSections.length - 1 ? tcOpenSection + 1 : tcSections.length - 1"
              :disabled="tcOpenSection === tcSections.length - 1"
              class="flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold text-gray-600 bg-gray-100 hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed transition-all active:scale-95"
            >
              Next
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M9 5l7 7-7 7"/></svg>
            </button>
          </div>
          <div class="flex items-center justify-between gap-3">
            <div class="flex items-center gap-2 min-w-0">
              <p class="text-[10px] text-gray-400 whitespace-nowrap">Last updated: <span class="font-semibold text-gray-500">May 1, 2026</span></p>
              <span class="hidden sm:inline-flex items-center gap-0.5 text-[9px] text-gray-300 bg-gray-50 border border-gray-100 rounded-lg px-1.5 py-0.5 whitespace-nowrap">
                <svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"/></svg>
                <svg class="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>
                arrow keys
              </span>
            </div>
            <button
              @click="showTermsModal = false"
              :class="['flex-shrink-0 px-4 py-1.5 rounded-xl font-bold text-white text-xs tracking-wide transition-all hover:-translate-y-0.5 active:scale-95 shadow-sm bg-gradient-to-r',
                isCOE ? 'from-orange-600 to-amber-500'
                : isSOM ? 'from-green-600 to-emerald-500'
                : isCNAHS ? 'from-emerald-600 to-teal-500'
                : 'from-violet-600 to-indigo-600']"
            >Close</button>
          </div>
        </div>

      </div>
    </div>
  </Transition>

  <!-- Edit User Modal -->
  <div v-if="showEditModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
    <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-md w-full mx-4 max-h-[90vh] overflow-y-auto">
      <h3 class="text-2xl font-bold text-blue-900 mb-6">Edit User</h3>
      <div v-if="editingUser" class="space-y-4">
        <div class="flex flex-col items-center mb-6">
          <div class="relative">
            <div :class="['w-24 h-24 rounded-full overflow-hidden mb-3 shadow-lg flex items-center justify-center relative', isCOE ? 'bg-gradient-to-r from-orange-400 to-red-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']">
              <div v-if="editImageLoading" class="absolute inset-0 flex items-center justify-center bg-black bg-opacity-30">
                <svg class="animate-spin h-8 w-8 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                  <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              </div>
              <img v-if="editingUser.image || editingUser.photo" :src="editingUser.image || editingUser.photo" alt="User Photo" class="w-full h-full object-cover" @load="editImageLoading = false" @error="editImageLoading = false" />
              <img v-else src="/user.svg" alt="Profile" class="w-12 h-12" style="filter: brightness(0) invert(1);" />
            </div>
            <button 
              @click="$refs.photoInput.click()" 
              :class="['absolute bottom-0 right-0 w-8 h-8 rounded-full flex items-center justify-center shadow-lg transition-all duration-200 hover:scale-110', isCOE ? 'bg-gradient-to-br from-orange-500 to-red-500 hover:from-orange-600 hover:to-red-600' : 'bg-gradient-to-br from-ssaam-dark to-ssaam-light hover:from-ssaam-dark hover:to-ssaam-light']"
              title="Change Photo"
            >
              <img src="/change_photo.svg" alt="Change Photo" class="w-4 h-4" style="filter: brightness(0) invert(1);" />
            </button>
          </div>
          <input 
            ref="photoInput" 
            @change="handleEditImageUpload"
            type="file" 
            accept="image/*" 
            class="hidden" 
          />
          <p v-if="editImageUploading" class="text-xs text-blue-600 mt-3 font-medium">Uploading...</p>
          <div v-if="editingUser.image && editingUser.image.startsWith('http')" class="mt-3 p-3 bg-blue-50 rounded-lg border border-blue-200">
            <p class="text-xs font-medium text-gray-700 mb-1">Photo URL:</p>
            <a :href="editingUser.image" target="_blank" class="text-xs text-blue-600 hover:text-blue-800 underline break-all font-medium">{{ editingUser.image }}</a>
          </div>
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Student ID</label>
          <input v-model="editingUser.studentId" type="text" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none" />
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">First Name</label>
          <input v-model="editingUser.firstName" @input="editingUser.firstName = editingUser.firstName.toUpperCase()" type="text" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none uppercase" />
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Middle Name <span class="text-gray-400">(optional)</span></label>
          <input v-model="editingUser.middleName" @input="editingUser.middleName = editingUser.middleName.toUpperCase()" type="text" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none uppercase" />
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Last Name</label>
          <input v-model="editingUser.lastName" @input="editingUser.lastName = editingUser.lastName.toUpperCase()" type="text" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none uppercase" />
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Email</label>
          <input v-model="editingUser.email" type="email" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none" />
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Program</label>
          <select v-model="editingUser.program" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none">
            <option value="">Select Program</option>
            <option value="BSCS">BSCS</option>
            <option value="BSIS">BSIS</option>
            <option value="BSIT">BSIT</option>
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Year Level</label>
          <select v-model="editingUser.yearLevel" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none">
            <option value="">Select Year</option>
            <option value="1st Year">1st Year</option>
            <option value="2nd Year">2nd Year</option>
            <option value="3rd Year">3rd Year</option>
            <option value="4th Year">4th Year</option>
          </select>
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">RFID Code</label>
          <input v-model="editingUser.rfidCode" type="text" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none" :disabled="editingUser.rfidUnreadable" :class="{'bg-gray-100': editingUser.rfidUnreadable}" />
          <div class="flex items-center gap-2 mt-2">
            <input 
              type="checkbox" 
              id="rfidUnreadable" 
              v-model="editingUser.rfidUnreadable"
              @change="handleRfidUnreadableChange"
              class="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
            />
            <label for="rfidUnreadable" class="text-sm text-gray-600">Mark RFID as unreadable</label>
          </div>
          <p v-if="editingUser.rfidUnreadable" class="text-xs text-orange-600 mt-1">This RFID card cannot be read by the scanner and will be marked accordingly.</p>
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Role</label>
          <select v-model="editingUser.role" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 outline-none">
            <option value="student">Student</option>
          </select>
        </div>
        <div class="flex gap-3 mt-6">
          <div class="flex-1">
            <button @click="closeEditModal" :disabled="savingUser" class="w-full bg-gray-200 text-gray-800 py-2 px-4 rounded-lg font-medium hover:bg-gray-300 transition disabled:opacity-50 disabled:cursor-not-allowed">Cancel</button>
          </div>
          <div class="flex-1">
            <template v-if="editingUser && editingUser.isDuplicate">
              <div class="mb-2 flex items-center gap-2">
                <input id="confirmDuplicate" type="checkbox" v-model="confirmDuplicate" class="w-4 h-4 text-blue-600 rounded focus:ring-blue-500" />
                <label for="confirmDuplicate" class="text-sm text-gray-700">I confirm I want to duplicate this record</label>
              </div>
              <button @click="duplicateUser" :disabled="savingUser || !confirmDuplicate" class="w-full bg-gradient-to-r from-ssaam-dark to-ssaam-light text-white py-2 px-4 rounded-lg font-medium hover:from-ssaam-dark hover:to-ssaam-light transition flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed">
                <svg v-if="savingUser" class="animate-spin w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                {{ savingUser ? 'Duplicating...' : 'Duplicate' }}
              </button>
            </template>
            <template v-else>
              <button @click="saveUser" :disabled="savingUser" class="w-full bg-gradient-to-r from-ssaam-dark to-ssaam-light text-white py-2 px-4 rounded-lg font-medium hover:from-ssaam-dark hover:to-ssaam-light transition flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed">
                <svg v-if="savingUser" class="animate-spin w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                {{ savingUser ? 'Saving...' : 'Save' }}
              </button>
            </template>
          </div>
        </div>
      </div>
    </div>
  </div>


  <!-- Delete Confirmation Modal -->
  <div v-if="showDeleteConfirm" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
    <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-sm w-full mx-4">
      <h3 class="text-2xl font-bold text-red-600 mb-4">Delete User?</h3>
      <p class="text-gray-600 mb-6">Are you sure you want to delete this user? This action cannot be undone.</p>
      <div class="flex gap-3">
        <button @click="showDeleteConfirm = false" class="flex-1 bg-gray-200 text-gray-800 py-2 px-4 rounded-lg font-medium hover:bg-gray-300 transition">Cancel</button>
        <button @click="confirmDelete" class="flex-1 bg-red-600 text-white py-2 px-4 rounded-lg font-medium hover:bg-red-700 transition">Delete</button>
      </div>
    </div>
  </div>

  <!-- Delete Payment Record Modal -->
  <div v-if="deletePaymentConfirmation" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
    <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-sm w-full mx-4">
      <h3 class="text-2xl font-bold text-red-600 mb-4">Delete Payment Record?</h3>
      <div class="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
        <p class="text-sm text-gray-700 mb-3"><strong>Student:</strong> {{ deletePaymentConfirmation.name }}</p>
        <p class="text-sm text-gray-700 mb-3"><strong>Amount:</strong> ₱{{ parseFloat(deletePaymentConfirmation.amount || 0).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) }}</p>
        <p class="text-sm text-gray-700"><strong>Description:</strong> {{ deletePaymentConfirmation.description || '-' }}</p>
      </div>
      <p class="text-gray-600 mb-6">Are you sure you want to delete this payment record? This action cannot be undone.</p>
      <div class="flex gap-3">
        <button @click="deletePaymentConfirmation = null" :disabled="deletingPayment" class="flex-1 bg-gray-200 text-gray-800 py-2 px-4 rounded-lg font-medium hover:bg-gray-300 transition disabled:opacity-50">Cancel</button>
        <button @click="confirmDeletePaymentRecord" :disabled="deletingPayment" class="flex-1 bg-red-600 text-white py-2 px-4 rounded-lg font-medium hover:bg-red-700 transition disabled:opacity-50 flex items-center justify-center gap-2">
          <svg v-if="deletingPayment" class="animate-spin h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
          {{ deletingPayment ? 'Deleting...' : 'Delete' }}
        </button>
      </div>
    </div>
  </div>

  <!-- Delete Payment Campaign Modal -->
  <transition name="fadeBackground">
    <div v-if="deletePaymentCampaignConfirm.show" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50"></div>
  </transition>
  <transition name="modal-bounce" appear>
    <div v-if="deletePaymentCampaignConfirm.show" class="fixed inset-0 flex items-center justify-center z-50 pointer-events-none">
      <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-sm w-full mx-4 pointer-events-auto">
      <h3 class="text-2xl font-bold text-red-600 mb-4">Delete Payment Campaign?</h3>
      <div class="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
        <p class="text-sm text-gray-700 mb-3"><strong>Campaign:</strong> {{ deletePaymentCampaignConfirm.payment?.title }}</p>
        <p class="text-sm text-gray-700 mb-3"><strong>Type:</strong> {{ deletePaymentCampaignConfirm.payment?.type }}</p>
        <p class="text-sm text-gray-700"><strong>Total Records:</strong> {{ deletePaymentCampaignConfirm.payment?.payment_records?.length || 0 }} students</p>
      </div>
      <p class="mb-6 font-semibold text-red-600">⚠️ This will delete the entire payment campaign and all associated student records. This action cannot be undone.</p>
      
      <!-- Countdown Timer -->
      <div v-if="deletePaymentCampaignConfirm.countdownActive" class="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg text-center">
        <p class="text-sm text-yellow-800 font-semibold mb-2">Please wait before deleting</p>
        <p class="text-4xl font-bold text-yellow-600">{{ deletePaymentCampaignConfirm.countdown }}</p>
      </div>
      
      <div class="flex gap-3">
        <button @click="() => { deletePaymentCampaignConfirm.show = false; deletingPaymentCampaign = false; if (deletePaymentCountdownInterval) { clearInterval(deletePaymentCountdownInterval); deletePaymentCountdownInterval = null } }" :disabled="deletingPaymentCampaign" class="flex-1 bg-gray-200 text-gray-800 py-2 px-4 rounded-lg font-medium hover:bg-gray-300 transition disabled:opacity-50">Cancel</button>
        <button @click="deletePaymentCampaign" :disabled="deletingPaymentCampaign || deletePaymentCampaignConfirm.countdownActive" class="flex-1 bg-red-600 text-white py-2 px-4 rounded-lg font-medium hover:bg-red-700 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2">
          <svg v-if="deletingPaymentCampaign" class="animate-spin h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
          {{ deletingPaymentCampaign ? 'Deleting...' : 'Delete Campaign' }}
        </button>
      </div>
      </div>
    </div>
  </transition>

  <!-- Password Change Modal with Email Verification -->
  <transition name="fade">
    <div v-if="showPasswordChangeModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" @click.self="closePasswordChangeModal">
      <transition name="modal-bounce" appear>
        <div v-if="showPasswordChangeModal" class="bg-white rounded-2xl shadow-2xl overflow-hidden max-w-md w-full mx-4 max-h-[90vh] flex flex-col">
          <!-- Gradient Header -->
          <div :class="['flex justify-between items-center px-6 py-4 flex-shrink-0', isCOE ? 'bg-gradient-to-r from-orange-700 to-red-500' : isSOM ? 'bg-gradient-to-r from-green-700 to-teal-500' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']">
            <div class="flex items-center gap-3">
              <div class="bg-white/20 p-2 rounded-lg">
                <svg class="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path></svg>
              </div>
              <h3 class="text-xl font-bold text-white">Change Password</h3>
            </div>
            <button @click="closePasswordChangeModal" class="text-white/70 hover:text-white text-2xl leading-none">&times;</button>
          </div>
          <!-- Body -->
          <div class="p-6 overflow-y-auto flex-1">

          <!-- Step 1: Request Email Verification -->
          <div v-if="pwChangeStep === 1" class="space-y-4">
            <div class="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-4">
              <div class="flex items-start gap-3">
                <svg class="w-5 h-5 text-blue-500 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                <p class="text-sm text-blue-800">For your security, we'll send a verification code to your registered email address.</p>
              </div>
            </div>
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-2">Your Email Address</label>
              <input v-model="pwChangeEmail" type="email" :placeholder="currentUser.email || 'your.email@example.com'" :class="['w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 outline-none', isCOE ? 'focus:ring-orange-600' : isSOM ? 'focus:ring-green-600' : 'focus:ring-blue-600']" />
            </div>
            <button @click="requestPasswordChangeCode" :disabled="changingPassword || !pwChangeEmail.trim()" :class="[isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 hover:from-orange-700 hover:to-red-600' : isSOM ? 'bg-gradient-to-r from-green-600 to-teal-500 hover:from-green-700 hover:to-teal-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light hover:from-ssaam-dark hover:to-ssaam-light', 'w-full text-white py-3 px-6 rounded-lg font-medium transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center']">
              <svg v-if="changingPassword" class="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
              {{ changingPassword ? 'Sending...' : 'Send Verification Code' }}
            </button>
            <p v-if="pwChangeMessage" :class="['text-sm text-center', pwChangeSuccess ? 'text-green-600' : 'text-red-600']">{{ pwChangeMessage }}</p>
          </div>

          <!-- Step 2: Enter Verification Code -->
          <div v-if="pwChangeStep === 2" class="space-y-4">
            <div class="bg-green-50 border border-green-200 rounded-lg p-4 mb-4">
              <div class="flex items-start gap-3">
                <svg class="w-5 h-5 text-green-500 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"></path></svg>
                <p class="text-sm text-green-800">A 6-digit code has been sent to your email. Please check your inbox.</p>
              </div>
            </div>
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-2">Verification Code</label>
              <input v-model="pwChangeCode" type="text" placeholder="123456" maxlength="6" :class="['w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 outline-none text-center text-2xl tracking-widest', isCOE ? 'focus:ring-orange-600' : isSOM ? 'focus:ring-green-600' : 'focus:ring-blue-600']" />
            </div>
            <button @click="verifyPasswordChangeCode" :disabled="changingPassword || pwChangeCode.length !== 6" :class="[isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 hover:from-orange-700 hover:to-red-600' : isSOM ? 'bg-gradient-to-r from-green-600 to-teal-500 hover:from-green-700 hover:to-teal-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light hover:from-ssaam-dark hover:to-ssaam-light', 'w-full text-white py-3 px-6 rounded-lg font-medium transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center']">
              <svg v-if="changingPassword" class="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
              {{ changingPassword ? 'Verifying...' : 'Verify Code' }}
            </button>
            <button @click="pwChangeStep = 1" :class="[isCOE ? 'text-orange-600 hover:text-orange-700' : isSOM ? 'text-green-600 hover:text-green-700' : 'text-blue-600 hover:text-blue-700', 'w-full text-sm font-medium']">Back to Step 1</button>
            <p v-if="pwChangeMessage" :class="['text-sm text-center', pwChangeSuccess ? 'text-green-600' : 'text-red-600']">{{ pwChangeMessage }}</p>
          </div>

          <!-- Step 3: Enter New Password -->
          <div v-if="pwChangeStep === 3" class="space-y-4">
            <div :class="[isCOE ? 'bg-orange-50 border-orange-200' : isSOM ? 'bg-green-50 border-green-200' : 'bg-blue-50 border-blue-200', 'border rounded-lg p-4 mb-4']">
              <div class="flex items-start gap-3">
                <svg :class="[isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500', 'w-5 h-5 mt-0.5 flex-shrink-0']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                <p :class="[isCOE ? 'text-orange-800' : isSOM ? 'text-green-800' : 'text-blue-800', 'text-sm']">Email verified! Now create your new secure password.</p>
              </div>
            </div>
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-2">New Password</label>
              <div class="relative">
                <input v-model="passwordForm.newPassword" :type="showNewPassword ? 'text' : 'password'" placeholder="Enter new password (min 6 characters)" :class="['w-full px-4 py-3 pr-12 border border-gray-300 rounded-lg focus:ring-2 outline-none', isCOE ? 'focus:ring-orange-600' : isSOM ? 'focus:ring-green-600' : 'focus:ring-blue-600']" />
                <button type="button" @click="showNewPassword = !showNewPassword" :class="[isCOE ? 'hover:text-orange-600' : isSOM ? 'hover:text-green-600' : 'hover:text-blue-600', 'absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 transition']">
                  <svg v-if="showNewPassword" class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                  <svg v-else class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"></path></svg>
                </button>
              </div>
              <p v-if="passwordErrors.newPassword" class="text-red-500 text-xs mt-1">{{ passwordErrors.newPassword }}</p>
            </div>
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-2">Confirm New Password</label>
              <div class="relative">
                <input v-model="passwordForm.confirmPassword" :type="showConfirmPassword ? 'text' : 'password'" placeholder="Confirm new password" :class="['w-full px-4 py-3 pr-12 border border-gray-300 rounded-lg focus:ring-2 outline-none', isCOE ? 'focus:ring-orange-600' : isSOM ? 'focus:ring-green-600' : 'focus:ring-blue-600']" />
                <button type="button" @click="showConfirmPassword = !showConfirmPassword" :class="[isCOE ? 'hover:text-orange-600' : isSOM ? 'hover:text-green-600' : 'hover:text-blue-600', 'absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 transition']">
                  <svg v-if="showConfirmPassword" class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path></svg>
                  <svg v-else class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"></path></svg>
                </button>
              </div>
              <p v-if="passwordErrors.confirmPassword" class="text-red-500 text-xs mt-1">{{ passwordErrors.confirmPassword }}</p>
            </div>
            <button @click="completePasswordChange" :disabled="changingPassword || !passwordForm.newPassword || passwordForm.newPassword !== passwordForm.confirmPassword" :class="[isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 hover:from-orange-700 hover:to-red-600' : isSOM ? 'bg-gradient-to-r from-green-600 to-teal-500 hover:from-green-700 hover:to-teal-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light hover:from-ssaam-dark hover:to-ssaam-light', 'w-full text-white py-3 px-6 rounded-lg font-medium transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center']">
              <svg v-if="changingPassword" class="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
              {{ changingPassword ? 'Changing Password...' : 'Change Password' }}
            </button>
            <p v-if="passwordForm.newPassword && passwordForm.confirmPassword && passwordForm.newPassword !== passwordForm.confirmPassword" class="text-sm text-red-600 text-center">Passwords do not match</p>
            <p v-if="pwChangeMessage" :class="['text-sm text-center', pwChangeSuccess ? 'text-green-600' : 'text-red-600']">{{ pwChangeMessage }}</p>
          </div>
          </div>
        </div>
      </transition>
    </div>
  </transition>

  <!-- Custom Calendar Picker Modal -->
  <!-- Backdrop Fade Only -->
  <transition name="fade">
    <div v-if="showCalendarPicker" class="fixed inset-0 bg-black bg-opacity-50"></div>
  </transition>
  <!-- Modal Pop -->
  <transition name="fade-scale">
    <div v-if="showCalendarPicker" class="fixed inset-0 flex items-center justify-center z-[60] p-2 sm:p-4" @click.self="showCalendarPicker = false">
      <div class="bg-white rounded-2xl shadow-2xl p-4 sm:p-5 w-full max-w-sm">
      <div class="flex justify-between items-center mb-4">
        <h3 :class="['text-xl font-bold bg-gradient-to-r bg-clip-text text-transparent', isCOE ? 'from-orange-600 to-red-500' : isSOM ? 'from-green-600 to-teal-600' : 'from-ssaam-dark to-ssaam-light']">Select Date</h3>
        <button @click="showCalendarPicker = false" :class="['text-2xl transition', isCOE ? 'text-orange-500 hover:text-orange-700' : isSOM ? 'text-green-500 hover:text-green-700' : 'text-gray-500 hover:text-gray-700']">×</button>
      </div>
      
      <!-- Calendar Header -->
      <div class="flex items-center justify-between mb-3 sm:mb-4 gap-2">
        <button @click="changeCalendarMonth(-1)" :class="['w-8 h-8 sm:w-10 sm:h-10 flex-shrink-0 flex items-center justify-center rounded-full transition', isCOE ? 'bg-gradient-to-r from-orange-100 to-red-100 hover:from-orange-200 hover:to-red-200 text-orange-700' : isSOM ? 'bg-gradient-to-r from-green-100 to-teal-100 hover:from-green-200 hover:to-teal-200 text-green-700' : 'bg-gradient-to-r from-blue-100 to-blue-100 hover:from-blue-200 hover:to-blue-200 text-blue-700']">
          <svg class="w-4 h-4 sm:w-5 sm:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"></path></svg>
        </button>
        <div class="text-center flex-1 min-w-0">
          <span :class="['text-sm sm:text-lg font-bold bg-gradient-to-r bg-clip-text text-transparent', isCOE ? 'from-orange-600 to-red-500' : isSOM ? 'from-green-600 to-teal-600' : 'from-ssaam-dark to-ssaam-light']">{{ calendarMonthName }} {{ calendarYear }}</span>
        </div>
        <button @click="changeCalendarMonth(1)" :class="['w-8 h-8 sm:w-10 sm:h-10 flex-shrink-0 flex items-center justify-center rounded-full transition', isCOE ? 'bg-gradient-to-r from-orange-100 to-red-100 hover:from-orange-200 hover:to-red-200 text-orange-700' : isSOM ? 'bg-gradient-to-r from-green-100 to-teal-100 hover:from-green-200 hover:to-teal-200 text-green-700' : 'bg-gradient-to-r from-blue-100 to-blue-100 hover:from-blue-200 hover:to-blue-200 text-blue-700']">
          <svg class="w-4 h-4 sm:w-5 sm:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
        </button>
      </div>
      
      <!-- Day Headers -->
      <div class="grid grid-cols-7 gap-0.5 sm:gap-1 mb-1 sm:mb-2">
        <div v-for="day in ['S', 'M', 'T', 'W', 'T', 'F', 'S']" :key="day" :class="['text-center py-1 sm:py-2 text-[10px] sm:text-xs font-semibold', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']">{{ day }}</div>
      </div>
      
      <!-- Calendar Grid -->
      <div class="grid grid-cols-7 gap-0.5 sm:gap-1">
        <div v-for="(day, index) in calendarDays" :key="index" class="aspect-square">
          <button 
            v-if="day.date"
            @click="selectCalendarDate(day.date)"
            :class="[
              'w-full h-full rounded-lg sm:rounded-xl text-xs sm:text-sm font-medium transition-all duration-200 flex items-center justify-center',
              day.isToday && !day.isSelected ? (isCOE ? 'bg-gradient-to-r from-orange-100 to-red-100 text-orange-700 ring-1 sm:ring-2 ring-orange-400' : isSOM ? 'bg-gradient-to-r from-green-100 to-teal-100 text-green-700 ring-1 sm:ring-2 ring-green-400' : 'bg-gradient-to-r from-blue-100 to-blue-100 text-blue-700 ring-1 sm:ring-2 ring-blue-400') : '',
              day.isSelected ? (isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 text-white shadow-lg scale-105 sm:scale-110' : isSOM ? 'bg-gradient-to-r from-green-600 to-teal-600 text-white shadow-lg scale-105 sm:scale-110' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light text-white shadow-lg scale-105 sm:scale-110') : '',
              !day.isToday && !day.isSelected && day.isCurrentMonth ? (isCOE ? 'text-gray-700 hover:bg-gradient-to-r hover:from-orange-50 hover:to-red-50 hover:text-orange-700' : isSOM ? 'text-gray-700 hover:bg-gradient-to-r hover:from-green-50 hover:to-teal-50 hover:text-green-700' : 'text-gray-700 hover:bg-gradient-to-r hover:from-blue-50 hover:to-blue-50 hover:text-blue-700') : '',
              !day.isCurrentMonth ? 'text-gray-300' : ''
            ]"
          >
            {{ day.day }}
          </button>
        </div>
      </div>
      
      <!-- Quick Actions -->
      <div class="flex gap-2 mt-3 sm:mt-4 pt-3 sm:pt-4 border-t border-gray-100">
        <button @click="selectToday" :class="['flex-1 px-2 sm:px-3 py-2 text-xs sm:text-sm font-medium rounded-lg transition', isCOE ? 'text-orange-600 bg-orange-50 hover:bg-orange-100' : isSOM ? 'text-green-600 bg-green-50 hover:bg-green-100' : 'text-blue-600 bg-blue-50 hover:bg-blue-100']">Today</button>
        <button @click="clearCalendarDate" class="flex-1 px-2 sm:px-3 py-2 text-xs sm:text-sm font-medium text-gray-600 bg-gray-100 rounded-lg hover:bg-gray-200 transition">Clear</button>
      </div>
      
      <!-- Selected Date Display -->
      <div :class="['mt-3 sm:mt-4 p-2 sm:p-3 rounded-lg sm:rounded-xl bg-gradient-to-r', isCOE ? 'from-orange-50 to-red-50' : isSOM ? 'from-green-50 to-teal-50' : 'from-blue-50 to-blue-50']">
        <p class="text-xs sm:text-sm text-center">
          <span class="text-gray-500">Selected: </span>
          <span :class="['font-bold bg-gradient-to-r bg-clip-text text-transparent', isCOE ? 'from-orange-600 to-red-500' : isSOM ? 'from-green-600 to-teal-600' : 'from-ssaam-dark to-ssaam-light']">{{ selectedCalendarDateDisplay || 'No date selected' }}</span>
        </p>
      </div>
      
      <div class="flex gap-2 sm:gap-3 mt-3 sm:mt-4">
        <button @click="showCalendarPicker = false" class="flex-1 bg-gray-200 text-gray-800 py-2 sm:py-3 px-3 sm:px-4 rounded-lg text-sm sm:text-base font-medium hover:bg-gray-300 transition">Cancel</button>
        <button @click="confirmCalendarDate" :disabled="!calendarSelectedDate" :class="['flex-1 text-white py-2 sm:py-3 px-3 sm:px-4 rounded-lg text-sm sm:text-base font-medium transition shadow-lg disabled:opacity-50 disabled:cursor-not-allowed bg-gradient-to-r', isCOE ? 'from-orange-600 to-red-500 hover:from-orange-700 hover:to-red-600' : isSOM ? 'from-green-600 to-teal-600 hover:from-green-700 hover:to-teal-700' : 'from-ssaam-dark to-ssaam-light hover:from-ssaam-dark hover:to-ssaam-light']">Confirm</button>
      </div>
      </div>
    </div>
  </transition>

  <!-- Time Picker Modal - Clock Design -->
  <!-- Backdrop Fade Only -->
  <!-- z-[150] so this backdrop covers the Add Session modal (z-[80]) when the
       time picker is opened from inside that modal. -->
  <transition name="fade">
    <div v-if="showTimePicker" class="fixed inset-0 bg-black bg-opacity-50 z-[150]"></div>
  </transition>
  <!-- Modal Pop (z-[160] — above its own backdrop and above Add Session modal) -->
  <transition name="fade-scale">
    <div v-if="showTimePicker" class="fixed inset-0 flex items-center justify-center z-[160]" @click.self="showTimePicker = false">
      <div class="bg-white rounded-2xl shadow-2xl p-5 max-w-sm w-full mx-4">
      <div class="flex justify-between items-center mb-6">
        <h3 :class="['text-xl font-bold bg-gradient-to-r bg-clip-text text-transparent', isCOE ? 'from-orange-600 to-red-500' : isSOM ? 'from-green-600 to-teal-600' : 'from-ssaam-dark to-ssaam-light']">Select Time</h3>
        <button @click="showTimePicker = false" :class="['text-2xl transition', isCOE ? 'text-orange-500 hover:text-orange-700' : isSOM ? 'text-green-500 hover:text-green-700' : 'text-gray-500 hover:text-gray-700']">&times;</button>
      </div>
      
      <!-- Clock Face Design -->
      <div class="relative w-48 h-48 mx-auto mb-6">
        <div :class="['absolute inset-0 rounded-full bg-gradient-to-br shadow-inner', isCOE ? 'from-orange-100 to-red-100' : isSOM ? 'from-green-100 to-teal-100' : 'from-blue-100 to-blue-100']"></div>
        <div class="absolute inset-2 rounded-full bg-white shadow-lg flex items-center justify-center">
          <div class="text-center">
            <div :class="['text-4xl font-bold bg-gradient-to-r bg-clip-text text-transparent', isCOE ? 'from-orange-600 to-red-500' : isSOM ? 'from-green-600 to-teal-600' : 'from-ssaam-dark to-ssaam-light']">
              {{ timePickerHour.toString().padStart(2, '0') }}:{{ timePickerMinute.toString().padStart(2, '0') }}
            </div>
            <div :class="['text-lg font-semibold mt-1', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']">{{ timePickerPeriod }}</div>
          </div>
        </div>
        <!-- Clock hour markers -->
        <div v-for="i in 12" :key="i" :class="['absolute w-1.5 h-1.5 rounded-full', isCOE ? 'bg-orange-300' : isSOM ? 'bg-green-300' : 'bg-blue-300']" :style="{ top: `${50 - 42 * Math.cos((i * 30 - 90) * Math.PI / 180)}%`, left: `${50 + 42 * Math.sin((i * 30 - 90) * Math.PI / 180)}%` }"></div>
      </div>
      
      <!-- Time Input Controls -->
      <div class="flex items-center justify-center gap-4 mb-6">
        <!-- Hour Control -->
        <div class="flex flex-col items-center">
          <label class="text-xs text-gray-500 mb-1 font-medium">Hour</label>
          <div class="flex flex-col items-center">
            <button @click="timePickerHour = timePickerHour < 12 ? timePickerHour + 1 : 1" :class="['p-1 transition', isCOE ? 'text-orange-600 hover:text-red-500' : isSOM ? 'text-green-600 hover:text-teal-500' : 'text-blue-600 hover:text-blue-500']">
              <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 15l7-7 7 7"></path></svg>
            </button>
            <div :class="['w-16 h-16 flex items-center justify-center text-2xl font-bold text-white rounded-xl shadow-lg bg-gradient-to-br', isCOE ? 'from-orange-500 to-red-500' : isSOM ? 'from-green-500 to-teal-500' : 'from-ssaam-dark to-ssaam-light']">
              {{ timePickerHour.toString().padStart(2, '0') }}
            </div>
            <button @click="timePickerHour = timePickerHour > 1 ? timePickerHour - 1 : 12" :class="['p-1 transition', isCOE ? 'text-orange-600 hover:text-red-500' : isSOM ? 'text-green-600 hover:text-teal-500' : 'text-blue-600 hover:text-blue-500']">
              <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>
            </button>
          </div>
        </div>
        
        <span :class="['text-3xl font-bold bg-gradient-to-r bg-clip-text text-transparent mt-5', isCOE ? 'from-orange-600 to-red-500' : isSOM ? 'from-green-600 to-teal-600' : 'from-ssaam-dark to-ssaam-light']">:</span>
        
        <!-- Minute Control (any minute 0-59) -->
        <div class="flex flex-col items-center">
          <label class="text-xs text-gray-500 mb-1 font-medium">Minute</label>
          <div class="flex flex-col items-center">
            <button @click="timePickerMinute = timePickerMinute < 59 ? timePickerMinute + 1 : 0" :class="['p-1 transition', isCOE ? 'text-orange-600 hover:text-red-500' : isSOM ? 'text-green-600 hover:text-teal-500' : 'text-blue-600 hover:text-blue-500']">
              <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 15l7-7 7 7"></path></svg>
            </button>
            <div :class="['w-16 h-16 flex items-center justify-center text-2xl font-bold text-white rounded-xl shadow-lg bg-gradient-to-br', isCOE ? 'from-orange-500 to-red-500' : isSOM ? 'from-green-500 to-teal-500' : 'from-ssaam-dark to-ssaam-light']">
              {{ timePickerMinute.toString().padStart(2, '0') }}
            </div>
            <button @click="timePickerMinute = timePickerMinute > 0 ? timePickerMinute - 1 : 59" :class="['p-1 transition', isCOE ? 'text-orange-600 hover:text-red-500' : isSOM ? 'text-green-600 hover:text-teal-500' : 'text-blue-600 hover:text-blue-500']">
              <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>
            </button>
          </div>
        </div>
        
        <!-- Period Control -->
        <div class="flex flex-col items-center ml-2">
          <label class="text-xs text-gray-500 mb-1 font-medium">Period</label>
          <div class="flex flex-col gap-2 mt-1">
            <button @click="timePickerPeriod = 'AM'" :class="['px-4 py-3 rounded-xl text-sm font-bold transition shadow-md', timePickerPeriod === 'AM' ? (isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 text-white' : isSOM ? 'bg-gradient-to-r from-green-600 to-teal-600 text-white' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light text-white') : 'bg-gray-100 text-gray-600 hover:bg-gray-200']">AM</button>
            <button @click="timePickerPeriod = 'PM'" :class="['px-4 py-3 rounded-xl text-sm font-bold transition shadow-md', timePickerPeriod === 'PM' ? (isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 text-white' : isSOM ? 'bg-gradient-to-r from-green-600 to-teal-600 text-white' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light text-white') : 'bg-gray-100 text-gray-600 hover:bg-gray-200']">PM</button>
          </div>
        </div>
      </div>
      
      <div class="flex gap-3">
        <button @click="showTimePicker = false" class="flex-1 bg-gray-200 text-gray-800 py-3 px-4 rounded-lg font-medium hover:bg-gray-300 transition">Cancel</button>
        <button @click="confirmTimePicker" :class="['flex-1 text-white py-3 px-4 rounded-lg font-medium transition shadow-lg bg-gradient-to-r', isCOE ? 'from-orange-600 to-red-500 hover:from-orange-700 hover:to-red-600' : isSOM ? 'from-green-600 to-teal-600 hover:from-green-700 hover:to-teal-700' : 'from-ssaam-dark to-ssaam-light hover:from-ssaam-dark hover:to-ssaam-light']">Confirm</button>
      </div>
      </div>
    </div>
  </transition>

  <!-- Loading Screen Modal for Events (Both Create and Edit) -->
  <transition name="fade">
    <div v-if="loadingStudentsForEvent" class="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-[60]">
      <div :class="['rounded-2xl shadow-2xl p-8 max-w-sm w-full mx-4 text-center transform transition-all duration-300', isCOE ? 'bg-gradient-to-br from-orange-50 to-orange-100' : isSOM ? 'bg-gradient-to-br from-green-50 to-green-100' : 'bg-gradient-to-br from-blue-50 to-blue-100']">
        <!-- Animated Spinner -->
        <div class="flex justify-center mb-6">
          <div :class="['relative w-20 h-20 flex items-center justify-center', isCOE ? 'bg-orange-200 rounded-full' : isSOM ? 'bg-green-200 rounded-full' : 'bg-blue-200 rounded-full']">
            <svg :class="['w-12 h-12 animate-spin', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          </div>
        </div>
        
        <!-- Loading Text -->
        <h3 :class="['text-xl font-bold mb-2', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-blue-900']">Preparing Event</h3>
        <p :class="['text-sm mb-6', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">Loading students and data...</p>
        
        <!-- Progress Bar -->
        <div class="mb-4">
          <div :class="['w-full rounded-full h-2 overflow-hidden', isCOE ? 'bg-orange-300' : isSOM ? 'bg-green-300' : 'bg-blue-300']">
            <div :class="['h-full rounded-full transition-all duration-500 ease-out', isCOE ? 'bg-gradient-to-r from-orange-500 to-orange-600' : isSOM ? 'bg-gradient-to-r from-green-500 to-green-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']" :style="{ width: totalStudentCount > 0 ? (loadedStudentCount / totalStudentCount * 100) + '%' : '0%' }"></div>
          </div>
        </div>
        
        <!-- Progress Text -->
        <p :class="['text-xs font-medium', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']">{{ loadedStudentCount }} / {{ totalStudentCount }} students loaded</p>
      </div>
    </div>
  </transition>

  <!-- Create Attendance Event Modal -->
  <transition name="fade">
    <div v-if="showCreateEventModal" class="fixed inset-0 bg-black bg-opacity-50 z-40"></div>
  </transition>
  <transition name="fade-scale">
    <div v-if="showCreateEventModal" class="fixed inset-0 flex items-end sm:items-center justify-center z-50 p-0 sm:p-4 overflow-hidden" @click.self="showCreateEventModal = false">
      <div class="bg-white rounded-t-2xl sm:rounded-2xl shadow-2xl w-full sm:max-w-2xl max-h-[95vh] flex flex-col overflow-hidden">

        <!-- Sticky Header -->
        <div :class="['flex items-center justify-between px-4 py-3 sm:px-5 border-b flex-shrink-0', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
          <h3 :class="['text-base font-bold', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-blue-900']">Create Attendance Event</h3>
          <button @click="showCreateEventModal = false" class="w-8 h-8 flex items-center justify-center rounded-full text-gray-400 hover:text-gray-600 hover:bg-gray-100 transition text-xl leading-none">&times;</button>
        </div>

        <!-- Scrollable Body -->
        <div class="modal-body-scroll overscroll-contain flex-1 min-h-0 px-4 py-3 sm:px-5 space-y-3" style="-webkit-overflow-scrolling: touch; touch-action: pan-y;">

          <!-- Loading Progress -->
          <div v-if="loadingStudentsForEvent" class="p-3 bg-blue-50 border border-blue-200 rounded-lg">
            <div class="flex items-center justify-between mb-1.5">
              <p class="text-xs font-medium text-blue-900">Loading students...</p>
              <span class="text-xs text-blue-700">{{ loadedStudentCount }} / {{ totalStudentCount }}</span>
            </div>
            <div class="w-full bg-blue-200 rounded-full h-1.5">
              <div :style="{ width: totalStudentCount > 0 ? (loadedStudentCount / totalStudentCount * 100) + '%' : '0%' }" class="bg-blue-600 h-1.5 rounded-full transition-all duration-200"></div>
            </div>
          </div>

          <!-- Basic Information -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest mb-3', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Basic Information</p>
            <div class="space-y-2.5">
              <div>
                <label :class="['block text-xs font-semibold mb-1', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">Event Title *</label>
                <input ref="newEventTitleInput" v-model="newEvent.title" type="text" placeholder="e.g., CCS General Assembly" @keydown.enter.prevent="focusNewEventLocation" :class="['w-full px-3 py-2 border rounded-lg focus:ring-2 outline-none transition text-sm font-medium bg-white', isCOE ? 'border-orange-200 focus:ring-orange-400 focus:border-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400 focus:border-green-400' : 'border-blue-200 focus:ring-blue-400 focus:border-blue-400']" />
              </div>
              <div class="grid grid-cols-2 gap-2">
                <div>
                  <label :class="['block text-xs font-semibold mb-1', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">Location</label>
                  <input ref="newEventLocationInput" v-model="newEvent.location" type="text" placeholder="e.g., CCS AVR" @keydown.enter.prevent="focusNewEventDescription" :class="['w-full px-3 py-2 border rounded-lg focus:ring-2 outline-none transition text-sm bg-white', isCOE ? 'border-orange-200 focus:ring-orange-400 focus:border-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400 focus:border-green-400' : 'border-blue-200 focus:ring-blue-400 focus:border-blue-400']" />
                </div>
                <div>
                  <label :class="['block text-xs font-semibold mb-1', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">Description</label>
                  <input ref="newEventDescriptionInput" v-model="newEvent.description" type="text" placeholder="Short description..." :class="['w-full px-3 py-2 border rounded-lg focus:ring-2 outline-none transition text-sm bg-white', isCOE ? 'border-orange-200 focus:ring-orange-400 focus:border-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400 focus:border-green-400' : 'border-blue-200 focus:ring-blue-400 focus:border-blue-400']" />
                </div>
              </div>
            </div>
          </div>

          <!-- Schedule -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest mb-3', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Schedule</p>
            <div class="grid grid-cols-3 gap-2">
              <div class="col-span-3 sm:col-span-1">
                <label class="block text-xs font-semibold text-gray-600 mb-1">Date *</label>
                <button @click="openCalendarPicker('newEvent')" type="button" :class="['w-full px-3 py-2 border rounded-lg text-left flex items-center justify-between transition text-sm bg-white', isCOE ? 'border-orange-200 hover:border-orange-300' : isSOM ? 'border-green-200 hover:border-green-300' : 'border-gray-200 hover:border-gray-300']">
                  <span :class="newEvent.date ? 'text-gray-900 text-xs' : 'text-gray-400 text-xs'">{{ formatCalendarDisplayDate(newEvent.date) || 'Select date' }}</span>
                  <svg :class="['w-4 h-4 flex-shrink-0', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>
                </button>
              </div>
              <div>
                <label class="block text-xs font-semibold text-gray-600 mb-1">Start *</label>
                <button @click="openTimePicker('event_start_time')" type="button" :class="['w-full px-3 py-2 border rounded-lg text-left flex items-center justify-between transition bg-white', isCOE ? 'border-orange-200 hover:border-orange-300' : isSOM ? 'border-green-200 hover:border-green-300' : 'border-gray-200 hover:border-gray-300']">
                  <span :class="newEvent.start_time ? 'text-gray-900 text-xs' : 'text-gray-400 text-xs'">{{ formatDisplayTime(newEvent.start_time) || 'Time' }}</span>
                  <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                </button>
              </div>
              <div>
                <label class="block text-xs font-semibold text-gray-600 mb-1">End *</label>
                <button @click="openTimePicker('event_end_time')" type="button" :class="['w-full px-3 py-2 border rounded-lg text-left flex items-center justify-between transition bg-white', isCOE ? 'border-orange-200 hover:border-orange-300' : isSOM ? 'border-green-200 hover:border-green-300' : 'border-gray-200 hover:border-gray-300']">
                  <span :class="newEvent.end_time ? 'text-gray-900 text-xs' : 'text-gray-400 text-xs'">{{ formatDisplayTime(newEvent.end_time) || 'Time' }}</span>
                  <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                </button>
              </div>
            </div>
            <p :class="['text-[10px] mt-2 px-1', isCOE ? 'text-orange-500' : isSOM ? 'text-green-600' : 'text-blue-500']">Session times must fall within the event time range.</p>
          </div>

          <!-- Assign to Specific Students -->
          <div :class="['flex items-center gap-3 border rounded-xl p-3 cursor-pointer transition', isCOE ? 'bg-orange-50 border-orange-200 hover:bg-orange-100' : isSOM ? 'bg-green-50 border-green-200 hover:bg-green-100' : 'bg-blue-50 border-blue-200 hover:bg-blue-100']" @click="newEvent.is_custom = !newEvent.is_custom">
            <input type="checkbox" v-model="newEvent.is_custom" id="customEventToggle" @click.stop :class="['w-4 h-4 rounded cursor-pointer flex-shrink-0', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" />
            <div class="flex-1 min-w-0">
              <p :class="['text-sm font-semibold', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-blue-900']">Assign to Specific Students</p>
              <p :class="['text-xs', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']">Select individual students from the list</p>
            </div>
          </div>

          <!-- Student Selection -->
          <div v-if="newEvent.is_custom" :class="['border rounded-xl p-3 sm:p-4 space-y-3', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Select Students</p>
            <div :class="['bg-white border rounded-lg p-3 space-y-2', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : 'border-blue-200']">
              <input v-model="eventUserFilters.name" type="text" placeholder="Search name or student ID..." :class="['w-full px-3 py-1.5 border rounded-lg focus:ring-2 outline-none text-xs', isCOE ? 'border-orange-200 focus:ring-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400' : 'border-blue-200 focus:ring-blue-400']" />
              <div class="grid grid-cols-2 gap-2">
                <select v-model="eventUserFilters.program" :class="['w-full px-2 py-1.5 border rounded-lg focus:ring-2 outline-none text-xs', isCOE ? 'border-orange-200 focus:ring-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400' : 'border-blue-200 focus:ring-blue-400']">
                  <option value="">All Programs</option>
                  <option value="BSIT">BSIT</option>
                  <option value="BSCS">BSCS</option>
                  <option value="BSIS">BSIS</option>
                </select>
                <select v-model="eventUserFilters.yearLevel" :class="['w-full px-2 py-1.5 border rounded-lg focus:ring-2 outline-none text-xs', isCOE ? 'border-orange-200 focus:ring-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400' : 'border-blue-200 focus:ring-blue-400']">
                  <option value="">All Years</option>
                  <option value="1st Year">1st Year</option>
                  <option value="2nd Year">2nd Year</option>
                  <option value="3rd Year">3rd Year</option>
                  <option value="4th Year">4th Year</option>
                </select>
              </div>
              <div class="flex items-center gap-3">
                <button @click="eventUserFilters = { name: '', program: '', yearLevel: '' }" type="button" class="text-xs text-gray-500 hover:text-gray-700 font-medium">Clear</button>
                <button @click="newEvent.assigned_users = filteredEventUsers.map(u => u._id)" type="button" class="text-xs text-green-600 hover:text-green-800 font-medium">Select All</button>
                <button v-if="newEvent.assigned_users.length > 0" @click="newEvent.assigned_users = []" type="button" class="text-xs text-red-500 hover:text-red-700 font-medium">Deselect All</button>
              </div>
            </div>
            <div :class="['max-h-40 overflow-y-auto border rounded-lg bg-white divide-y divide-gray-50', isCOE ? 'border-orange-100' : isSOM ? 'border-green-100' : 'border-blue-100']">
              <div v-if="filteredEventUsers.length === 0" class="py-4 text-center text-xs text-gray-400">No students found</div>
              <label v-for="user in filteredEventUsers" :key="user._id" class="flex items-center gap-2.5 px-3 py-2 hover:bg-gray-50 cursor-pointer">
                <input type="checkbox" :checked="newEvent.assigned_users && (newEvent.assigned_users.includes(user._id) || newEvent.assigned_users.some(u => (typeof u === 'object' ? u._id : u) === user._id))" @change="toggleEventUser(user._id)" :class="['w-4 h-4 rounded flex-shrink-0', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" />
                <div class="min-w-0">
                  <p class="text-xs font-semibold text-gray-900 truncate">{{ getUserDisplayName(user) }}</p>
                  <p class="text-[10px] text-gray-500">{{ user.student_id }} · {{ user.program }} · {{ user.year_level }}</p>
                </div>
              </label>
            </div>
            <div v-if="newEvent.assigned_users && newEvent.assigned_users.length > 0">
              <p :class="['text-xs font-semibold mb-1.5', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">{{ newEvent.assigned_users.length }} selected</p>
              <div class="flex flex-wrap gap-1.5">
                <span v-for="userItem in newEventDisplayUsers" :key="typeof userItem === 'string' ? userItem : userItem._id" :class="['inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full', isCOE ? 'bg-orange-100 text-orange-800' : isSOM ? 'bg-green-100 text-green-800' : 'bg-blue-100 text-blue-800']">
                  {{ getSelectedEventUserName(userItem) }}
                  <button @click="newEvent.assigned_users = newEvent.assigned_users.filter(id => (typeof id === 'string' ? id : id._id) !== (typeof userItem === 'string' ? userItem : userItem._id))" type="button" class="hover:opacity-60 leading-none ml-0.5">×</button>
                </span>
              </div>
            </div>
          </div>

          <!-- GPS Geofence -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest mb-0.5', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">GPS Geofence</p>
            <p class="text-[10px] text-gray-500 mb-3">Optional — limits check-ins to devices near the venue.</p>
            <GeofenceMap
              :enabled="newEvent.geofence_enabled"
              :latitude="newEvent.geofence_lat"
              :longitude="newEvent.geofence_lng"
              :radius="newEvent.geofence_radius_meters"
              :isCOE="isCOE"
              :isSOM="isSOM"
              @update:enabled="newEvent.geofence_enabled = $event"
              @update:latitude="newEvent.geofence_lat = $event"
              @update:longitude="newEvent.geofence_lng = $event"
              @update:radius="newEvent.geofence_radius_meters = $event"
            />
          </div>

          <!-- Sessions -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <div class="flex items-center justify-between mb-3">
              <div>
                <p :class="['text-[10px] font-bold uppercase tracking-widest', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Sessions</p>
                <p class="text-[10px] text-gray-500 mt-0.5">Students can check in right after the event is created.</p>
              </div>
              <button @click="openAddSessionForNewEvent" type="button" :class="['text-xs px-2.5 py-1 rounded-lg flex items-center gap-1 font-semibold transition flex-shrink-0', isCOE ? 'bg-orange-200 text-orange-700 hover:bg-orange-300' : isSOM ? 'bg-green-200 text-green-700 hover:bg-green-300' : 'bg-blue-200 text-blue-700 hover:bg-blue-300']">
                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"></path></svg>
                Add
              </button>
            </div>
            <div v-if="newEventSessions.length === 0" class="text-center py-3 bg-white/60 rounded-lg border border-dashed border-gray-200">
              <p class="text-xs text-gray-400">No sessions yet — you can add them later too.</p>
            </div>
            <div v-else class="space-y-2">
              <div v-for="(session, idx) in newEventSessions" :key="'new-session-' + idx" class="flex items-center gap-2 p-2.5 bg-white rounded-lg border border-gray-100 shadow-sm">
                <div class="flex-1 min-w-0">
                  <div class="flex items-center gap-1.5 flex-wrap">
                    <span class="font-semibold text-gray-800 text-sm">{{ session.label }}</span>
                    <span v-if="session.check_in_only" class="px-1.5 py-0.5 rounded-full text-[10px] bg-blue-100 text-blue-700 font-medium">Check-In Only</span>
                  </div>
                  <p class="text-xs text-gray-500 mt-0.5">{{ formatDisplayTime(session.start_time) }} – {{ formatDisplayTime(session.end_time) }} · <span class="text-orange-500">Late after {{ session.late_timer_minutes || 60 }} min</span></p>
                </div>
                <div class="flex items-center gap-0.5 flex-shrink-0">
                  <button @click="openEditSessionForNewEvent(idx)" type="button" :class="['p-1.5 rounded-lg hover:bg-gray-100 transition', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg>
                  </button>
                  <button @click="deleteSessionForNewEvent(idx)" type="button" class="p-1.5 rounded-lg hover:bg-red-50 text-red-400 hover:text-red-600 transition">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>

        </div>

        <!-- Sticky Footer -->
        <div class="flex gap-2 px-4 py-3 sm:px-5 border-t border-gray-100 bg-white flex-shrink-0">
          <button @click="closeCreateEventModal" class="flex-1 bg-gray-100 text-gray-700 py-2.5 rounded-xl text-sm font-semibold hover:bg-gray-200 transition">Cancel</button>
          <button @click="createAttendanceEvent" :disabled="!newEvent.title || !newEvent.date || creatingEventInProgress" :class="['flex-1 text-white py-2.5 rounded-xl text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2', isCOE ? 'bg-gradient-to-r from-orange-600 to-red-500 hover:from-orange-700 hover:to-red-600' : isSOM ? 'bg-gradient-to-r from-green-600 to-teal-600 hover:from-green-700 hover:to-teal-700' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']">
            <svg v-if="creatingEventInProgress" class="animate-spin h-4 w-4" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
            <span>{{ creatingEventInProgress ? 'Creating...' : 'Create Event' }}</span>
          </button>
        </div>

      </div>
    </div>
  </transition>

  <!-- Edit Attendance Event Modal -->
  <transition name="fade">
    <div v-if="showEditEventModal && selectedEvent" class="fixed inset-0 bg-black bg-opacity-50 z-40"></div>
  </transition>
  <transition name="fade-scale">
    <div v-if="showEditEventModal && selectedEvent" class="fixed inset-0 flex items-end sm:items-center justify-center z-50 p-0 sm:p-4" @click.self="showEditEventModal = false">
      <div class="bg-white rounded-t-2xl sm:rounded-2xl shadow-2xl w-full sm:max-w-2xl max-h-[95vh] flex flex-col overflow-hidden">

        <!-- Sticky Header -->
        <div :class="['flex items-center justify-between px-4 py-3 sm:px-5 border-b flex-shrink-0', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
          <div class="flex items-center gap-2 min-w-0">
            <h3 :class="['text-base font-bold truncate', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-blue-900']">Edit Event</h3>
            <span v-if="selectedEvent.status" :class="['px-2 py-0.5 rounded-full text-[10px] font-semibold flex-shrink-0', selectedEvent.status === 'active' ? 'bg-green-100 text-green-700' : selectedEvent.status === 'draft' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-600']">
              {{ selectedEvent.status === 'active' ? 'Active' : selectedEvent.status === 'draft' ? 'Upcoming' : 'Closed' }}
            </span>
          </div>
          <button @click="showEditEventModal = false" class="w-8 h-8 flex items-center justify-center rounded-full text-gray-400 hover:text-gray-600 hover:bg-gray-100 transition text-xl leading-none flex-shrink-0">&times;</button>
        </div>

        <!-- Scrollable Body -->
        <div class="overflow-y-auto overscroll-contain flex-1 min-h-0 px-4 py-3 sm:px-5 space-y-3" style="-webkit-overflow-scrolling: touch; touch-action: pan-y;">

          <!-- Loading Progress -->
          <div v-if="loadingStudentsForEvent" class="p-3 bg-blue-50 border border-blue-200 rounded-lg">
            <div class="flex items-center justify-between mb-1.5">
              <p class="text-xs font-medium text-blue-900">Loading students...</p>
              <span class="text-xs text-blue-700">{{ loadedStudentCount }} / {{ totalStudentCount }}</span>
            </div>
            <div class="w-full bg-blue-200 rounded-full h-1.5">
              <div :style="{ width: totalStudentCount > 0 ? (loadedStudentCount / totalStudentCount * 100) + '%' : '0%' }" class="bg-blue-600 h-1.5 rounded-full transition-all duration-200"></div>
            </div>
          </div>

          <!-- Basic Information -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest mb-3', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Basic Information</p>
            <div class="space-y-2.5">
              <div>
                <label :class="['block text-xs font-semibold mb-1', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">Event Title *</label>
                <input v-model="selectedEvent.title" type="text" :class="['w-full px-3 py-2 border rounded-lg focus:ring-2 outline-none transition text-sm font-medium bg-white', isCOE ? 'border-orange-200 focus:ring-orange-400 focus:border-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400 focus:border-green-400' : 'border-blue-200 focus:ring-blue-400 focus:border-blue-400']" />
              </div>
              <div class="grid grid-cols-2 gap-2">
                <div>
                  <label :class="['block text-xs font-semibold mb-1', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">Location</label>
                  <input v-model="selectedEvent.location" type="text" :class="['w-full px-3 py-2 border rounded-lg focus:ring-2 outline-none transition text-sm bg-white', isCOE ? 'border-orange-200 focus:ring-orange-400 focus:border-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400 focus:border-green-400' : 'border-blue-200 focus:ring-blue-400 focus:border-blue-400']" />
                </div>
                <div>
                  <label :class="['block text-xs font-semibold mb-1', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">Description</label>
                  <input v-model="selectedEvent.description" type="text" :class="['w-full px-3 py-2 border rounded-lg focus:ring-2 outline-none transition text-sm bg-white', isCOE ? 'border-orange-200 focus:ring-orange-400 focus:border-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400 focus:border-green-400' : 'border-blue-200 focus:ring-blue-400 focus:border-blue-400']" />
                </div>
              </div>
            </div>
          </div>

          <!-- Schedule -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest mb-3', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Schedule</p>
            <div class="grid grid-cols-3 gap-2">
              <div class="col-span-3 sm:col-span-1">
                <label class="block text-xs font-semibold text-gray-600 mb-1">Date *</label>
                <button @click="openCalendarPicker('editEvent')" type="button" :class="['w-full px-3 py-2 border rounded-lg text-left flex items-center justify-between transition text-sm bg-white', isCOE ? 'border-orange-200 hover:border-orange-300' : isSOM ? 'border-green-200 hover:border-green-300' : 'border-gray-200 hover:border-gray-300']">
                  <span :class="selectedEvent.date ? 'text-gray-900 text-xs' : 'text-gray-400 text-xs'">{{ formatCalendarDisplayDate(selectedEvent.date) || 'Select date' }}</span>
                  <svg :class="['w-4 h-4 flex-shrink-0', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>
                </button>
              </div>
              <div>
                <label class="block text-xs font-semibold text-gray-600 mb-1">Start *</label>
                <button @click="openTimePicker('edit_start_time')" type="button" :class="['w-full px-3 py-2 border rounded-lg text-left flex items-center justify-between transition bg-white', isCOE ? 'border-orange-200 hover:border-orange-300' : isSOM ? 'border-green-200 hover:border-green-300' : 'border-gray-200 hover:border-gray-300']">
                  <span :class="(selectedEvent.start_time || selectedEvent.startTime) ? 'text-gray-900 text-xs' : 'text-gray-400 text-xs'">{{ formatDisplayTime(selectedEvent.start_time || selectedEvent.startTime) || 'Time' }}</span>
                  <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                </button>
              </div>
              <div>
                <label class="block text-xs font-semibold text-gray-600 mb-1">End *</label>
                <button @click="openTimePicker('edit_end_time')" type="button" :class="['w-full px-3 py-2 border rounded-lg text-left flex items-center justify-between transition bg-white', isCOE ? 'border-orange-200 hover:border-orange-300' : isSOM ? 'border-green-200 hover:border-green-300' : 'border-gray-200 hover:border-gray-300']">
                  <span :class="(selectedEvent.end_time || selectedEvent.endTime) ? 'text-gray-900 text-xs' : 'text-gray-400 text-xs'">{{ formatDisplayTime(selectedEvent.end_time || selectedEvent.endTime) || 'Time' }}</span>
                  <svg :class="['w-3.5 h-3.5 flex-shrink-0', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                </button>
              </div>
            </div>
            <p class="text-[10px] text-gray-400 mt-2 px-1">Status updates automatically based on date and session times.</p>
          </div>

          <!-- Assign to Specific Students -->
          <div :class="['flex items-center gap-3 border rounded-xl p-3 cursor-pointer transition', isCOE ? 'bg-orange-50 border-orange-200 hover:bg-orange-100' : isSOM ? 'bg-green-50 border-green-200 hover:bg-green-100' : 'bg-blue-50 border-blue-200 hover:bg-blue-100']" @click="selectedEvent.is_custom = !selectedEvent.is_custom">
            <input type="checkbox" v-model="selectedEvent.is_custom" id="editCustomEventToggle" @click.stop :class="['w-4 h-4 rounded cursor-pointer flex-shrink-0', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" />
            <div class="flex-1 min-w-0">
              <p :class="['text-sm font-semibold', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-blue-900']">Assign to Specific Students</p>
              <p :class="['text-xs', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']">Select individual students from the list</p>
            </div>
          </div>

          <!-- Student Selection (Edit) -->
          <div v-if="selectedEvent.is_custom" :class="['border rounded-xl p-3 sm:p-4 space-y-3', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Select Students</p>
            <div :class="['bg-white border rounded-lg p-3 space-y-2', isCOE ? 'border-orange-200' : isSOM ? 'border-green-200' : 'border-blue-200']">
              <input v-model="editEventUserFilters.name" type="text" placeholder="Search name or student ID..." :class="['w-full px-3 py-1.5 border rounded-lg focus:ring-2 outline-none text-xs', isCOE ? 'border-orange-200 focus:ring-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400' : 'border-blue-200 focus:ring-blue-400']" />
              <div class="grid grid-cols-2 gap-2">
                <select v-model="editEventUserFilters.program" :class="['w-full px-2 py-1.5 border rounded-lg focus:ring-2 outline-none text-xs', isCOE ? 'border-orange-200 focus:ring-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400' : 'border-blue-200 focus:ring-blue-400']">
                  <option value="">All Programs</option>
                  <option value="BSIT">BSIT</option>
                  <option value="BSCS">BSCS</option>
                  <option value="BSIS">BSIS</option>
                </select>
                <select v-model="editEventUserFilters.yearLevel" :class="['w-full px-2 py-1.5 border rounded-lg focus:ring-2 outline-none text-xs', isCOE ? 'border-orange-200 focus:ring-orange-400' : isSOM ? 'border-green-200 focus:ring-green-400' : 'border-blue-200 focus:ring-blue-400']">
                  <option value="">All Years</option>
                  <option value="1st Year">1st Year</option>
                  <option value="2nd Year">2nd Year</option>
                  <option value="3rd Year">3rd Year</option>
                  <option value="4th Year">4th Year</option>
                </select>
              </div>
              <div class="flex items-center gap-3">
                <button @click="editEventUserFilters = { name: '', program: '', yearLevel: '' }" type="button" class="text-xs text-gray-500 hover:text-gray-700 font-medium">Clear</button>
                <button @click="selectedEvent.assigned_users = filteredEditEventUsers.map(u => u._id)" type="button" class="text-xs text-green-600 hover:text-green-800 font-medium">Select All</button>
                <button v-if="selectedEvent.assigned_users && selectedEvent.assigned_users.length > 0" @click="selectedEvent.assigned_users = []" type="button" class="text-xs text-red-500 hover:text-red-700 font-medium">Deselect All</button>
              </div>
            </div>
            <div :class="['max-h-40 overflow-y-auto border rounded-lg bg-white divide-y divide-gray-50', isCOE ? 'border-orange-100' : isSOM ? 'border-green-100' : 'border-blue-100']">
              <div v-if="filteredEditEventUsers.length === 0" class="py-4 text-center text-xs text-gray-400">No students found</div>
              <label v-for="user in filteredEditEventUsers" :key="user._id" class="flex items-center gap-2.5 px-3 py-2 hover:bg-gray-50 cursor-pointer">
                <input type="checkbox" :checked="selectedEvent.assigned_users && (selectedEvent.assigned_users.includes(user._id) || selectedEvent.assigned_users.some(u => (typeof u === 'object' ? u._id : u) === user._id))" @change="toggleEditEventUser(user._id)" :class="['w-4 h-4 rounded flex-shrink-0', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" />
                <div class="min-w-0">
                  <p class="text-xs font-semibold text-gray-900 truncate">{{ getUserDisplayName(user) }}</p>
                  <p class="text-[10px] text-gray-500">{{ user.student_id }} · {{ user.program }} · {{ user.year_level }}</p>
                </div>
              </label>
            </div>
            <div v-if="selectedEvent.assigned_users && selectedEvent.assigned_users.length > 0">
              <p :class="['text-xs font-semibold mb-1.5', isCOE ? 'text-orange-700' : isSOM ? 'text-green-700' : 'text-blue-700']">{{ selectedEvent.assigned_users.length }} selected</p>
              <div class="flex flex-wrap gap-1.5">
                <span v-for="userItem in selectedEventDisplayUsers" :key="typeof userItem === 'string' ? userItem : userItem._id" :class="['inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full', isCOE ? 'bg-orange-100 text-orange-800' : isSOM ? 'bg-green-100 text-green-800' : 'bg-blue-100 text-blue-800']">
                  {{ getSelectedEventUserName(userItem) }}
                  <button @click="selectedEvent.assigned_users = selectedEvent.assigned_users.filter(id => (typeof id === 'string' ? id : id._id) !== (typeof userItem === 'string' ? userItem : userItem._id))" type="button" class="hover:opacity-60 leading-none ml-0.5">×</button>
                </span>
              </div>
            </div>
          </div>

          <!-- GPS Geofence (Edit) -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <p :class="['text-[10px] font-bold uppercase tracking-widest mb-0.5', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">GPS Geofence</p>
            <p class="text-[10px] text-gray-500 mb-3">Optional — limits check-ins to devices near the venue.</p>
            <GeofenceMap
              :enabled="!!selectedEvent.geofence_enabled"
              :latitude="Number.isFinite(selectedEvent.geofence_lat) ? selectedEvent.geofence_lat : null"
              :longitude="Number.isFinite(selectedEvent.geofence_lng) ? selectedEvent.geofence_lng : null"
              :radius="selectedEvent.geofence_radius_meters || 80"
              :isCOE="isCOE"
              :isSOM="isSOM"
              @update:enabled="selectedEvent.geofence_enabled = $event"
              @update:latitude="selectedEvent.geofence_lat = $event"
              @update:longitude="selectedEvent.geofence_lng = $event"
              @update:radius="selectedEvent.geofence_radius_meters = $event"
            />
          </div>

          <!-- Face ID Toggle (Edit) -->
          <div :class="['flex items-center gap-3 border rounded-xl p-3 cursor-pointer transition', isCOE ? 'bg-orange-50 border-orange-200 hover:bg-orange-100' : isSOM ? 'bg-green-50 border-green-200 hover:bg-green-100' : 'bg-blue-50 border-blue-200 hover:bg-blue-100']" @click="selectedEvent.face_id_enabled = selectedEvent.face_id_enabled === false ? true : false">
            <input type="checkbox" :checked="selectedEvent.face_id_enabled !== false" @change="selectedEvent.face_id_enabled = $event.target.checked" id="faceIdToggleEdit" @click.stop :class="['w-4 h-4 rounded cursor-pointer flex-shrink-0', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']" />
            <div class="flex-1 min-w-0">
              <p :class="['text-sm font-semibold flex items-center gap-1.5', isCOE ? 'text-orange-900' : isSOM ? 'text-green-900' : 'text-blue-900']">
                <svg class="w-3.5 h-3.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 8V6a2 2 0 012-2h2M4 16v2a2 2 0 002 2h2m8-16h2a2 2 0 012 2v2m-4 12h2a2 2 0 002-2v-2M9 10h.01M15 10h.01M9 16c.85.63 1.885 1 3 1s2.15-.37 3-1"/></svg>
                Allow Face ID Check-In
              </p>
              <p :class="['text-xs', isCOE ? 'text-orange-600' : isSOM ? 'text-green-600' : 'text-blue-600']">When off, students cannot use Face ID for this event.</p>
            </div>
          </div>

          <!-- Sessions (Edit) -->
          <div :class="['p-3 sm:p-4 rounded-xl border', isCOE ? 'bg-orange-50 border-orange-100' : isSOM ? 'bg-green-50 border-green-100' : 'bg-blue-50 border-blue-100']">
            <div class="flex items-center justify-between mb-3">
              <div>
                <p :class="['text-[10px] font-bold uppercase tracking-widest', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">Sessions</p>
              </div>
              <button @click="openAddSessionModal" type="button" :class="['text-xs px-2.5 py-1 rounded-lg flex items-center gap-1 font-semibold transition flex-shrink-0', addSessionButtonAnimating ? (isCOE ? 'bg-orange-500 text-white animate-pulse' : isSOM ? 'bg-green-500 text-white animate-pulse' : 'bg-blue-500 text-white animate-pulse') : (isCOE ? 'bg-orange-200 text-orange-700 hover:bg-orange-300' : isSOM ? 'bg-green-200 text-green-700 hover:bg-green-300' : 'bg-blue-200 text-blue-700 hover:bg-blue-300')]">
                <svg :class="['w-3.5 h-3.5', addSessionButtonAnimating ? 'animate-spin' : '']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"></path></svg>
                {{ addSessionButtonAnimating ? 'Opening...' : 'Add' }}
              </button>
            </div>
            <div v-if="eventSessions.length === 0" class="text-center py-3 bg-white/60 rounded-lg border border-dashed border-gray-200">
              <p class="text-xs text-gray-400">No sessions yet — add one to enable check-in.</p>
            </div>
            <div v-else class="space-y-2">
              <div v-for="session in eventSessions" :key="session._id" class="flex items-center gap-2 p-2.5 bg-white rounded-lg border border-gray-100 shadow-sm">
                <div class="flex-1 min-w-0">
                  <div class="flex items-center gap-1.5 flex-wrap">
                    <span class="font-semibold text-gray-800 text-sm">{{ session.label }}</span>
                    <span :class="['px-1.5 py-0.5 rounded-full text-[10px] font-medium', getSessionDisplayStatus(session, selectedEvent) === 'active' ? 'bg-green-100 text-green-700' : getSessionDisplayStatus(session, selectedEvent) === 'draft' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-600']">
                      {{ getSessionDisplayStatus(session, selectedEvent) === 'active' ? 'Active' : getSessionDisplayStatus(session, selectedEvent) === 'draft' ? 'Upcoming' : 'Closed' }}
                    </span>
                  </div>
                  <p class="text-xs text-gray-500 mt-0.5">{{ formatDisplayTime(session.start_time) }} – {{ formatDisplayTime(session.end_time) }} · <span class="text-orange-500">Late after {{ session.late_timer_minutes || 60 }} min</span></p>
                  <div class="flex gap-2 mt-0.5">
                    <span v-if="session.check_in_locked" class="text-[10px] text-red-500">Check-in locked</span>
                    <span v-if="session.check_out_locked" class="text-[10px] text-red-500">Check-out locked</span>
                  </div>
                </div>
                <div class="flex items-center gap-0.5 flex-shrink-0">
                  <button @click="openEditSessionModal(session)" type="button" :class="['p-1.5 rounded-lg hover:bg-gray-100 transition', isCOE ? 'text-orange-500' : isSOM ? 'text-green-500' : 'text-blue-500']">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg>
                  </button>
                  <button @click="deleteSession(session._id)" type="button" class="p-1.5 rounded-lg hover:bg-red-50 text-red-400 hover:text-red-600 transition">
                    <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>

        </div>

        <!-- Sticky Footer -->
        <div class="flex gap-2 px-4 py-3 sm:px-5 border-t border-gray-100 bg-white flex-shrink-0">
          <button @click="showEditEventModal = false" class="flex-1 bg-gray-100 text-gray-700 py-2.5 rounded-xl text-sm font-semibold hover:bg-gray-200 transition">Cancel</button>
          <button @click="updateAttendanceEvent" :disabled="!selectedEvent.title || !selectedEvent.date" :class="['flex-1 text-white py-2.5 rounded-xl text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed bg-gradient-to-r', primaryButtonGradient, primaryButtonHover]">Save Changes</button>
        </div>

      </div>
    </div>
  </transition>

  <!-- Add/Edit Session Modal -->
  <!-- Backdrop Fade Only -->
  <transition name="fade">
    <div v-if="showSessionModal" class="fixed inset-0 bg-black bg-opacity-50 z-50"></div>
  </transition>
  <!-- Modal Pop -->
  <transition name="fade-scale">
    <div v-if="showSessionModal" class="fixed inset-0 flex items-center justify-center z-[80]" @click.self="closeSessionModal">
      <div class="bg-white rounded-2xl shadow-2xl p-6 max-w-md w-full mx-4">
      <div class="flex justify-between items-center mb-4">
        <h3 :class="['text-xl font-bold', isCOE ? 'text-orange-900' : 'text-blue-900']">{{ (editingSession || editingNewEventSessionIdx !== null) ? 'Edit Session' : 'Add Session' }}</h3>
        <button @click="closeSessionModal" :class="['text-2xl transition', isCOE ? 'text-orange-500 hover:text-orange-700' : 'text-gray-500 hover:text-gray-700']">&times;</button>
      </div>
      <div class="space-y-4">
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Session Label *</label>
          <select v-model="newSession.label" :class="['w-full px-4 py-2 border rounded-lg focus:ring-2 outline-none transition', isCOE ? 'border-orange-300 focus:ring-orange-600' : isSOM ? 'border-green-300 focus:ring-green-600' : 'border-gray-300 focus:ring-blue-600']">
            <option v-for="label in sessionLabels" :key="label" :value="label">{{ label }}</option>
          </select>
        </div>
        <div class="grid grid-cols-2 gap-4">
          <div>
            <label class="block text-sm font-medium text-gray-700 mb-2">Start Time *</label>
            <button @click="openTimePicker('session_start_time')" type="button" :class="['w-full px-4 py-2 border rounded-lg focus:ring-2 outline-none text-left flex items-center justify-between hover:bg-opacity-50 transition', isCOE ? 'border-orange-300 focus:ring-orange-600' : isSOM ? 'border-green-300 focus:ring-green-600' : 'border-gray-300 focus:ring-blue-600']">
              <span :class="newSession.start_time ? 'text-gray-900' : 'text-gray-400'">{{ formatDisplayTime(newSession.start_time) || 'Select time' }}</span>
              <svg :class="['w-5 h-5', isCOE ? 'text-orange-400' : isSOM ? 'text-green-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            </button>
          </div>
          <div>
            <label class="block text-sm font-medium text-gray-700 mb-2">End Time *</label>
            <button @click="openTimePicker('session_end_time')" type="button" :class="['w-full px-4 py-2 border rounded-lg focus:ring-2 outline-none text-left flex items-center justify-between hover:bg-opacity-50 transition', isCOE ? 'border-orange-300 focus:ring-orange-600' : isSOM ? 'border-green-300 focus:ring-green-600' : 'border-gray-300 focus:ring-blue-600']">
              <span :class="newSession.end_time ? 'text-gray-900' : 'text-gray-400'">{{ formatDisplayTime(newSession.end_time) || 'Select time' }}</span>
              <svg :class="['w-5 h-5', isCOE ? 'text-orange-400' : 'text-gray-400']" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            </button>
          </div>
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Late Threshold (minutes after start)</label>
          <div class="flex items-center gap-2">
            <input 
              v-model.number="newSession.late_timer_minutes" 
              type="number" 
              min="0" 
              max="480"
              placeholder="60"
              :class="['w-full px-4 py-2 border rounded-lg focus:ring-2 outline-none transition', isCOE ? 'border-orange-300 focus:ring-orange-600' : isSOM ? 'border-green-300 focus:ring-green-600' : 'border-gray-300 focus:ring-blue-600']"
            />
            <span class="text-sm text-gray-500 whitespace-nowrap">minutes</span>
          </div>
          <p class="text-xs text-gray-500 mt-1">Check-ins after {{ newSession.late_timer_minutes || 60 }} minutes from session start will be marked as late</p>
        </div>
        <div :class="['flex items-center justify-between p-4 rounded-xl border-2 transition-all', newSession.check_in_only ? 'bg-blue-50 border-blue-300' : 'bg-gray-50 border-gray-200']">
          <div>
            <p class="text-sm font-semibold text-gray-800">Check-In Only Mode</p>
            <p class="text-xs text-gray-500 mt-0.5">Students scan once to check-in. No check-out required.</p>
          </div>
          <button type="button" @click="newSession.check_in_only = !newSession.check_in_only" :class="['relative inline-flex h-7 w-12 items-center rounded-full transition-colors duration-300 flex-shrink-0', newSession.check_in_only ? 'bg-blue-500' : 'bg-gray-300']">
            <span :class="['inline-block h-5 w-5 transform rounded-full bg-white shadow-lg transition-transform duration-300', newSession.check_in_only ? 'translate-x-6' : 'translate-x-1']"></span>
          </button>
        </div>
        <div v-if="sessionTimeError" class="bg-red-50 border border-red-200 rounded-lg p-3">
          <p class="text-sm text-red-700">{{ sessionTimeError }}</p>
        </div>
        <div class="flex gap-3 mt-6">
          <button @click="closeSessionModal" class="flex-1 bg-gray-200 text-gray-800 py-2 px-4 rounded-lg font-medium hover:bg-gray-300 transition" :disabled="savingSession">Cancel</button>
          <button @click="saveSession" :disabled="!newSession.label || !newSession.start_time || !newSession.end_time || savingSession || !!sessionTimeError" :class="['flex-1 text-white py-2 px-4 rounded-lg font-medium transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 bg-gradient-to-r', primaryButtonGradient, primaryButtonHover]">
            <svg v-if="savingSession" class="animate-spin h-5 w-5" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
            </svg>
            <span>{{ savingSession ? 'Saving...' : ((editingSession || editingNewEventSessionIdx !== null) ? 'Update' : 'Add') + ' Session' }}</span>
          </button>
        </div>
      </div>
      </div>
    </div>
  </transition>

  <!-- Event Attendance Logs Modal -->
  <!-- Backdrop Fade Only -->
  <transition name="fade">
    <div v-if="showEventLogsModal && selectedEvent" class="fixed inset-0 bg-black bg-opacity-50"></div>
  </transition>
  <!-- Modal Pop with fade-scale -->
  <transition name="fade-scale">
    <div v-if="showEventLogsModal && selectedEvent" class="fixed inset-0 flex items-center justify-center z-50 overflow-hidden" @click.self="showEventLogsModal = false">
      <div class="bg-white rounded-2xl shadow-2xl p-8 max-w-4xl w-full mx-4 max-h-[90vh] overflow-y-auto">
      <div class="flex justify-between items-center mb-6">
        <div>
          <h3 :class="['text-2xl font-bold', isCOE ? 'text-orange-900' : 'text-blue-900']">
            {{ selectedEvent.title }}
            <span v-if="selectedSessionForLogs" :class="['text-lg font-medium', isCOE ? 'text-orange-600' : 'text-blue-600']"> - {{ selectedSessionForLogs.label }} Session</span>
          </h3>
          <p class="text-gray-500 text-sm">
            Attendance Logs - {{ formatEventDate(selectedEvent.date || selectedEvent.event_date) }}
            <span v-if="selectedSessionForLogs"> ({{ formatDisplayTime(selectedSessionForLogs.start_time) }} - {{ formatDisplayTime(selectedSessionForLogs.end_time) }})</span>
          </p>
        </div>
        <button @click="showEventLogsModal = false" class="text-gray-500 hover:text-gray-700 text-2xl">&times;</button>
      </div>
      
      <div class="space-y-6">
        <!-- Panel switcher: Logs | Excused -->
        <div class="mb-4">
          <div class="inline-flex bg-gray-100 rounded-lg p-1">
            <button @click="selectedPanel = 'logs'" :class="['px-3 py-1 rounded-lg text-sm', selectedPanel === 'logs' ? 'bg-white shadow' : 'text-gray-600']">Logs</button>
            <button @click="selectedPanel = 'excused'" :class="['px-3 py-1 rounded-lg text-sm', selectedPanel === 'excused' ? 'bg-white shadow' : 'text-gray-600']">Excused</button>
          </div>
        </div>
        <!-- Left column: Filters, Stats, Logs -->
        <transition enter-active-class="transition-opacity duration-300" enter-from-class="opacity-0" enter-to-class="opacity-100" leave-active-class="transition-opacity duration-200" leave-from-class="opacity-100" leave-to-class="opacity-0">
          <div class="flex-1" v-if="selectedPanel === 'logs'">
      <!-- Filters -->
      <div class="mb-6">
        <input v-model="eventLogsFilter.search" type="text" placeholder="Search by name or ID..." :class="['w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 outline-none', isCOE ? 'focus:ring-orange-600' : 'focus:ring-blue-600']" @input="selectedSessionForLogs ? fetchSessionLogs(selectedSessionForLogs._id) : fetchEventLogs(selectedEvent._id)" />
      </div>

      <!-- Stats Summary (responsive) -->
      <div class="mb-6">
        <div v-if="attendanceLoading" class="grid grid-cols-2 sm:grid-cols-5 gap-3">
          <div v-for="n in 5" :key="n" class="p-3 sm:p-4 rounded-lg bg-gray-100 animate-pulse" style="height:64px"></div>
        </div>
        <div v-else class="grid grid-cols-2 sm:grid-cols-5 gap-3 mb-6">
          <div class="bg-green-50 p-3 sm:p-4 rounded-lg text-center">
            <p class="text-xl sm:text-2xl font-bold text-green-600">{{ dynamicSessionStats.present }}</p>
            <p class="text-xs sm:text-sm text-green-700">Present</p>
          </div>
          <div class="bg-yellow-50 p-3 sm:p-4 rounded-lg text-center">
            <p class="text-xl sm:text-2xl font-bold text-yellow-600">{{ dynamicSessionStats.incomplete }}</p>
            <p class="text-xs sm:text-sm text-yellow-700">Incomplete</p>
          </div>
          <div class="bg-orange-50 p-3 sm:p-4 rounded-lg text-center">
            <p class="text-xl sm:text-2xl font-bold text-orange-600">{{ dynamicSessionStats.late }}</p>
            <p class="text-xs sm:text-sm text-orange-700">Late</p>
          </div>
          <div class="bg-red-50 p-3 sm:p-4 rounded-lg text-center">
            <p class="text-xl sm:text-2xl font-bold text-red-600">{{ dynamicSessionStats.absent }}</p>
            <p class="text-xs sm:text-sm text-red-700">Absent</p>
          </div>
          <div :class="['p-3 sm:p-4 rounded-lg text-center', isCOE ? 'bg-orange-50' : 'bg-blue-50']">
            <p :class="['text-xl sm:text-2xl font-bold', isCOE ? 'text-orange-600' : 'text-blue-600']">{{ dynamicSessionStats.total }}<span v-if="dynamicSessionStats.totalStudents > 0" :class="['text-base sm:text-lg', isCOE ? 'text-orange-400' : 'text-blue-400']">/{{ dynamicSessionStats.totalStudents }}</span></p>
            <p :class="['text-xs sm:text-sm', isCOE ? 'text-orange-700' : 'text-blue-700']">Total<span v-if="dynamicSessionStats.totalStudents > 0"> Attended</span></p>
          </div>
        </div>
      </div>

      <!-- Late Threshold Editor -->
      <div v-if="selectedSessionForLogs" class="mb-6 p-4 bg-orange-50 border border-orange-200 rounded-lg">
        <div class="flex flex-wrap items-center gap-4">
          <div class="flex-1">
            <p class="text-sm font-medium text-orange-800 mb-1">Late Threshold Editor</p>
            <p class="text-xs text-orange-600">
              Session starts at <span class="font-semibold">{{ formatDisplayTime(selectedSessionForLogs.start_time) }}</span>.
              Check-ins after <span class="font-semibold">{{ calculateLateThreshold(selectedSessionForLogs.start_time, selectedLateThresholdMinutes) }}</span> will be marked as late.
            </p>
            <p class="text-xs text-orange-700 mt-1.5 p-2 bg-orange-50 rounded-md flex items-start gap-1.5">
              <svg class="w-4 h-4 mt-0.5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clip-rule="evenodd"></path></svg>
              <span><span class="font-semibold">Instant Preview:</span> Logs above update immediately. Click "Apply & Recalculate" to save changes permanently to database.</span>
            </p>
          </div>
          <div class="flex items-center gap-2">
            <select 
              v-model.number="selectedLateThresholdMinutes" 
              class="px-3 py-2 border border-orange-300 rounded-lg focus:ring-2 focus:ring-orange-500 outline-none text-sm"
              :disabled="applyingLateThreshold"
            >
              <option :value="30">30 min</option>
              <option :value="60">60 min</option>
              <option :value="90">90 min</option>
              <option :value="120">120 min</option>
              <option :value="180">180 min</option>
              <option :value="240">240 min</option>
            </select>
            <button 
              @click="applyLateThresholdByMinutes"
              :disabled="applyingLateThreshold || dynamicSessionStats.total === 0"
              class="px-4 py-2 bg-orange-500 text-white rounded-lg hover:bg-orange-600 transition text-sm flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <svg v-if="applyingLateThreshold" class="animate-spin h-4 w-4" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
              <svg v-else class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg>
              {{ applyingLateThreshold ? (recalculateProgress.isProcessing ? `Processing ${recalculateProgress.current}/${recalculateProgress.total}...` : 'Applying...') : 'Apply & Recalculate' }}
            </button>
          </div>
        </div>
      </div>

      <!-- Quick Download by Year Level -->
      <div class="mb-6 bg-gray-50 p-4 rounded-lg">
        <!-- Year Filter -->
        <div class="mb-4">
          <p class="text-sm font-medium text-gray-700 mb-2">Year Filter:</p>
          <div class="flex flex-wrap gap-2">
            <button @click="selectAllYears()" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', selectedYearFilters.length === 0 ? (isCOE ? 'bg-orange-600 text-white' : 'bg-blue-600 text-white') : 'bg-white border border-gray-200']">All</button>
            <button @click="toggleYearFilter('1st Year')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', yearFilterActive('1st Year') ? (isCOE ? 'bg-orange-600 text-white' : 'bg-blue-600 text-white') : 'bg-white border border-gray-200']">1st</button>
            <button @click="toggleYearFilter('2nd Year')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', yearFilterActive('2nd Year') ? 'bg-green-600 text-white' : 'bg-white border border-gray-200']">2nd</button>
            <button @click="toggleYearFilter('3rd Year')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', yearFilterActive('3rd Year') ? 'bg-yellow-600 text-white' : 'bg-white border border-gray-200']">3rd</button>
            <button @click="toggleYearFilter('4th Year')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', yearFilterActive('4th Year') ? (isCOE ? 'bg-orange-600 text-white' : 'bg-blue-600 text-white') : 'bg-white border border-gray-200']">4th</button>
          </div>
        </div>

        <!-- Status Filter -->
        <div class="mb-4">
          <p class="text-sm font-medium text-gray-700 mb-2">Status Filter:</p>
          <div class="flex flex-wrap gap-2">
            <button @click="selectAllStatuses()" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', selectedStatusFilters.length === 0 ? (isCOE ? 'bg-orange-600 text-white' : 'bg-blue-600 text-white') : 'bg-white border border-gray-200']">All</button>
            <button @click="toggleStatusFilter('Present')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', statusFilterActive('Present') ? 'bg-green-600 text-white' : 'bg-white border border-gray-200']">Present</button>
            <button @click="toggleStatusFilter('Incomplete')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', statusFilterActive('Incomplete') ? 'bg-orange-600 text-white' : 'bg-white border border-gray-200']">Incomplete</button>
            <button @click="toggleStatusFilter('Late')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', statusFilterActive('Late') ? 'bg-yellow-600 text-white' : 'bg-white border border-gray-200']">Late</button>
            <button @click="toggleStatusFilter('Absent')" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', statusFilterActive('Absent') ? 'bg-red-600 text-white' : 'bg-white border border-gray-200']">Absent</button>
          </div>
        </div>

        <!-- Program Filter -->
        <div class="mb-4">
          <p class="text-sm font-medium text-gray-700 mb-2">Program Filter:</p>
          <div class="flex flex-wrap gap-2">
            <button @click="selectAllPrograms()" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', selectedProgramFilters.length === 0 ? (isCOE ? 'bg-orange-600 text-white' : 'bg-blue-600 text-white') : 'bg-white border border-gray-200']">All</button>
            <button v-for="prog in availablePrograms" :key="prog" @click="toggleProgramFilter(prog)" :class="['text-xs sm:text-sm hover:shadow transition px-3 py-1 rounded-lg', programFilterActive(prog) ? (isCOE ? 'bg-orange-600 text-white' : 'bg-indigo-600 text-white') : 'bg-white border border-gray-200']">{{ prog }}</button>
          </div>
        </div>

        <!-- Download Excel -->
        <div>
          <p class="text-sm font-medium text-gray-700 mb-2">Download Excel:</p>
          <div class="relative inline-block w-full sm:w-auto">
            <button
              @click="showExportMenu = !showExportMenu"
              class="w-full sm:w-auto px-4 py-2 bg-gradient-to-r from-indigo-600 to-indigo-500 text-white rounded-lg hover:from-indigo-700 hover:to-indigo-600 transition inline-flex items-center justify-center sm:justify-start gap-2"
            >
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
              <span class="flex-1 sm:flex-none">Export</span>
              <svg class="w-3 h-3 opacity-80 transform" :class="showExportMenu ? 'rotate-180' : ''" viewBox="0 0 20 20" fill="currentColor"><path d="M5.23 7.21a.75.75 0 011.06.02L10 11.584l3.71-4.354a.75.75 0 111.14.976l-4.25 5a.75.75 0 01-1.14 0l-4.25-5a.75.75 0 01.02-1.06z"/></svg>
            </button>

            <transition name="fade-scale">
              <div v-if="showExportMenu" class="absolute z-40 mt-2 left-0 w-full sm:w-64 bg-white rounded-lg shadow-lg ring-1 ring-black ring-opacity-5 overflow-hidden">
                <button @click="(exportToExcel(selectedEvent), showExportMenu=false)" :disabled="exportingExcel || sessionStats.total === 0" class="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center justify-between disabled:opacity-50 disabled:cursor-not-allowed">
                  <span class="text-sm">Export All Years</span>
                  <span class="text-xs text-gray-500">{{ sessionStats.total }}</span>
                </button>
                <button @click="(exportFilteredToExcel(selectedEvent), showExportMenu=false)" :disabled="exportingFiltered || getFilteredLogsCount(selectedEvent) === 0" class="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center justify-between disabled:opacity-50 disabled:cursor-not-allowed border-t border-gray-100">
                  <span class="text-sm">Export Filtered</span>
                  <span class="text-xs text-gray-500">{{ getFilteredLogsCount(selectedEvent) }}</span>
                </button>
                <button @click="(exportAbsentToExcel(selectedEvent), showExportMenu=false)" :disabled="exportingAbsent || sessionStats.absent === 0" class="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center justify-between disabled:opacity-50 disabled:cursor-not-allowed border-t border-gray-100">
                  <span class="text-sm">Export Absent Only</span>
                  <span class="text-xs text-gray-500">{{ sessionStats.absent }}</span>
                </button>
              </div>
            </transition>
          </div>
        </div>
      </div>

      <!-- Logs Table -->
      <div class="overflow-x-auto">
        <table class="w-full border-collapse">
          <thead>
            <tr :class="isCOE ? 'bg-orange-100 text-orange-900' : 'bg-blue-100 text-blue-900'">
              <th :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-left']">Student</th>
              <th :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-left']">Program</th>
              <th :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-left']">Year</th>
              <th :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-center']">Check In</th>
              <th :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-center']">Check Out</th>
              <th :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-center']">Status</th>
            </tr>
          </thead>
          <tbody>
            <tr v-if="attendanceLoading" class="text-center">
              <td colspan="6" class="py-8 text-gray-500">
                <svg :class="['animate-spin h-8 w-8 mx-auto mb-2', isCOE ? 'text-orange-600' : 'text-blue-600']" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                  <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Loading logs...
              </td>
            </tr>
            <tr v-else-if="filteredAttendanceLogs.length === 0" class="text-center">
              <td colspan="6" class="py-8 text-gray-500">No attendance records found</td>
            </tr>
            <tr v-else v-for="log in filteredAttendanceLogs.slice(0, sessionLogsDisplayLimit)" :key="log.id" class="hover:shadow-md hover:rounded-lg transition-all duration-150">
              <td :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3']">
                <div class="flex items-center gap-3">
                  <div :class="['w-10 h-10 rounded-full overflow-hidden flex items-center justify-center text-white text-sm shrink-0', isCOE ? 'bg-gradient-to-r from-orange-400 to-red-600' : 'bg-gradient-to-r from-ssaam-dark to-ssaam-light']">
                    <img v-if="(log.student_image || log.student?.image || log.student?.photo || log.student?.avatar)" :src="log.student_image || log.student?.image || log.student?.photo || log.student?.avatar" class="w-full h-full object-cover" />
                    <span v-else>{{ ((log.student?.full_name || log.student_name || log.full_name || `${log.student?.first_name || ''} ${log.student?.last_name || ''}`).trim() || '?').charAt(0) }}</span>
                  </div>
                  <div>
                    <p class="font-medium text-gray-900">{{ (log.student?.full_name || log.student_name || log.full_name || `${log.student?.first_name || ''} ${log.student?.last_name || ''}`).trim() || 'N/A' }}</p>
                    <p class="text-xs text-gray-500">{{ log.student_id_number || log.student_id }}</p>
                    <p v-if="log.excused" class="text-xs text-gray-600 italic">Excused{{ (log.excused_by_name || log.excused_by) ? (' by ' + (log.excused_by_name || log.excused_by)) : '' }}{{ log.excuse_reason ? ' — ' + log.excuse_reason : '' }}</p>
                  </div>
                </div>
              </td>
              <td :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3']">{{ log.program || '-' }}</td>
              <td :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3']">{{ log.year_level || '-' }}</td>
              <td :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-center']">{{ (log.check_in_at || log.check_in_time) ? new Date(log.check_in_at || log.check_in_time).toLocaleTimeString() : '-' }}</td>
              <td :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-center']">{{ (log.check_out_at || log.check_out_time) ? new Date(log.check_out_at || log.check_out_time).toLocaleTimeString() : '-' }}</td>
              <td :class="[isCOE ? 'border-orange-300' : 'border-blue-300','px-4','py-3','text-center']">
                  <div class="flex items-center justify-center gap-2">
                  <span :class="getAttendanceLogStatusClass(log)" class="px-2 py-1 rounded-full text-xs font-semibold">{{ getAttendanceLogStatusLabel(log) }}</span>
                  <button
                    v-if="currentUser.value && (currentUser.value.role === 'admin' || currentUser.value.isMaster) && selectedEvent && selectedSessionForLogs && hasEventEndedPH(selectedEvent) && selectedSessionForLogs.status === 'closed'"
                    @click="openEditAttendanceModal(log)"
                    class="text-xs text-blue-600 hover:underline ml-2"
                  >
                    Edit
                  </button>
                  <!-- Excuse button for absent records -->
                  <button
                    v-if="getAttendanceLogStatusLabel(log) === 'Absent' && !log.excused && currentUser.value && (currentUser.value.role === 'admin' || currentUser.value.isMaster) && selectedEvent && selectedSessionForLogs && hasEventEndedPH(selectedEvent) && selectedSessionForLogs.status === 'closed'"
                    @click="openExcuseForLog(log)"
                    class="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded ml-2 hover:bg-yellow-200"
                  >
                    Excuse
                  </button>
                  <!-- Undo Excuse button when already excused -->
                  <button
                    v-if="log.excused && currentUser.value && (currentUser.value.role === 'admin' || currentUser.value.isMaster) && selectedEvent && selectedSessionForLogs && hasEventEndedPH(selectedEvent) && selectedSessionForLogs.status === 'closed'"
                    @click="undoExcuse(log)"
                    class="text-xs bg-red-100 text-red-800 px-2 py-1 rounded ml-2 hover:bg-red-200"
                  >
                    Undo
                  </button>
                  <!-- Details button for already-excused records -->
                  <button
                    v-if="log.excused && currentUser.value && (currentUser.value.role === 'admin' || currentUser.value.isMaster) && selectedEvent && selectedSessionForLogs && hasEventEndedPH(selectedEvent) && selectedSessionForLogs.status === 'closed'"
                    @click="openEditAttendanceModal(log)"
                    class="text-xs bg-indigo-100 text-indigo-800 px-2 py-1 rounded ml-2 hover:bg-indigo-200"
                    title="View / edit excuse details"
                  >
                    Details
                  </button>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
        </div>
      </transition>

          <!-- Excuse Management (separate panel) -->
