const newPaymentData = ref({
  title: '',
  description: '',
  type: 'fee',
  amount_due: 0,
  status: 'active'
})

// Get session token from localStorage
const getSessionToken = () => {
  return localStorage.getItem('authToken') || localStorage.getItem('adminToken') || ''
}

const fetchTransparencyBoard = async () => {
  transparencyLoading.value = true
  try {
    const response = await fetch(buildAPIUrl('/apis/contributions/transparency'), {
      headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
    })
    const result = await response.json()
    if (response.ok) {
      // Flatten the nested structure: each student has payments array
      // Transform into flat array with one row per payment
      const flatData = []
      const students = result.data || []
      
      students.forEach(student => {
        if (student.payments && Array.isArray(student.payments)) {
          student.payments.forEach(payment => {
            flatData.push({
              name: student.name,
              program: student.program,
              year_level: student.year_level,
              contribution_amount: payment.amount,
              contribution_description: payment.description,
              contribution_date: payment.date
            })
          })
        }
      })
      
      transparencyList.value = flatData
    }
  } catch (error) {
    console.error('Failed to fetch transparency board:', error)
  } finally {
    transparencyLoading.value = false
  }
}

// Fetch all payments
const fetchPayments = async (skipAutoSync = false) => {
  // Only admin/co-admin should fetch all payments; regular students should use fetchMyPayments
  if (currentUser.value.role !== 'admin' && !currentUser.value.isMaster) {
    // Skip payment list fetch for students - they use My Payments instead
    return
  }
  
  // Check cache first - only fetch if not already fetched or if forced refresh
  if (isSectionCached('contributions') && !skipAutoSync) {
    return
  }
  
  paymentsLoading.value = true
  try {
    const response = await Promise.race([
      fetch(buildAPIUrl('/apis/payments'), {
        headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
      }),
      new Promise((_, reject) => 
        setTimeout(() => reject(new Error('Fetch payments timeout')), 10000)
      )
    ])
    const result = await response.json()
    if (response.ok) {
      // Filter out invalid payments: those with no amount_due and empty/unknown title
      const validPayments = (result.data || []).filter(payment => 
        payment.amount_due > 0 && payment.title && payment.title.trim() && payment.title.toLowerCase() !== 'unknown payment'
      )
      paymentsList.value = validPayments
      
      // ensure stats align with dashboard total in case backend returned stale counts
      const expectedTotalLocal = totalStudents.value || 0
      paymentsList.value.forEach(p => {
        if (p.stats) {
          p.stats.total_students = expectedTotalLocal
          p.stats.unpaid_count = Math.max(0, expectedTotalLocal - (p.stats.paid_count || 0))
          p.stats.completion_percentage =
            expectedTotalLocal > 0 ? Math.round((p.stats.paid_count / expectedTotalLocal) * 100) : 0
        }
      })
      
      // If a payment is currently selected, update it with fresh data
      if (selectedPayment.value && selectedPayment.value._id) {
        const updatedPayment = paymentsList.value.find(p => p._id === selectedPayment.value._id)
        if (updatedPayment) {
          selectedPayment.value = updatedPayment
        }
      }
      
      // Mark section as cached
      markSectionAsCached('contributions')
      
      // Auto-sync all active payments (skip if explicitly requested to avoid recursion)
      if (!skipAutoSync) {
        // Don't await sync, let it run in background
        autoSyncPayments().catch(error => {
          console.error('Auto-sync failed in background:', error)
        })
      }
    }
  } catch (error) {
    console.error('Failed to fetch payments:', error)
    showNotification('Failed to load payments', 'error')
  } finally {
    paymentsLoading.value = false
  }
}

// Fetch student's payment records (contributions/receipts)
const fetchMyPayments = async () => {
  loadingMyPayments.value = true
  try {
    const response = await fetch(buildAPIUrl('/apis/my-payments'), {
      headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
    })
    const result = await response.json()
    
    // Check for token-related errors and auto-logout if needed
    if (handleTokenError(response, result)) {
      return
    }
    
    if (response.ok) {
      // Filter out invalid payments: those with no amount_due and empty/unknown title
      const validPayments = (result.data || []).filter(payment => 
        payment.amount_due > 0 && payment.title && payment.title.trim() && payment.title.toLowerCase() !== 'unknown payment'
      )
      myPayments.value = validPayments
    } else {
      console.error('Failed to fetch my payments:', result.message)
    }
  } catch (error) {
    console.error('Failed to fetch my payments:', error)
  } finally {
    loadingMyPayments.value = false
  }
}

// Comprehensive refresh - loads all user data and payments
const refreshAllData = async () => {
  paymentsLoading.value = true
  try {
    const isAdmin = currentUser.value.role === 'admin' || currentUser.value.isMaster
    
    if (isAdmin) {
      // ADMIN: Fetch all payments for management
      let refreshedPayment = null
      
      // If a payment is currently selected, prioritize fetching its details using the campaign-specific endpoint
      if (selectedPayment.value && selectedPayment.value._id) {
        try {
          const paymentResponse = await Promise.race([
            fetch(buildAPIUrl(`/apis/payments/${selectedPayment.value._id}`), {
              method: 'GET',
              headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
            }),
            new Promise((_, reject) => 
              setTimeout(() => reject(new Error('Payment fetch timeout')), 8000)
            )
          ])
          const paymentResult = await paymentResponse.json()
          if (paymentResponse.ok && paymentResult.data) {
            refreshedPayment = paymentResult.data
            selectedPayment.value = paymentResult.data
            // Update the payment in the list as well
            const paymentIndex = paymentsList.value.findIndex(p => p._id === selectedPayment.value._id)
            if (paymentIndex !== -1) {
              paymentsList.value[paymentIndex] = selectedPayment.value
            }
          }
        } catch (error) {
          console.error('Failed to fetch individual payment details:', error)
          // Don't fail here, try fetching all payments
        }
      }
      
      // If individual payment fetch failed or no payment selected, fetch all payments
      if (!refreshedPayment) {
        try {
          const paymentsResponse = await Promise.race([
            fetch(buildAPIUrl('/apis/payments'), {
              headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
            }),
            new Promise((_, reject) => 
              setTimeout(() => reject(new Error('Payments fetch timeout')), 8000)
            )
          ])
          const paymentsResult = await paymentsResponse.json()
          if (paymentsResponse.ok) {
            paymentsList.value = paymentsResult.data || []
            // Update selected payment if needed
            if (selectedPayment.value) {
              const updated = paymentsList.value.find(p => p._id === selectedPayment.value._id)
              if (updated) {
                selectedPayment.value = updated
              }
            }
          }
        } catch (error) {
          console.error('Failed to fetch payments:', error)
          // Continue anyway with existing data
        }
      }
    } else {
      // STUDENT: Fetch only their own payments
      await fetchMyPayments()
    }

    // Fetch students data (non-blocking)
    try {
      const studentsResponse = await Promise.race([
        fetch(buildAPIUrl(`/apis/students?page=${currentPageNum.value}&limit=${itemsPerPage.value}`), {
          method: 'GET',
          headers: getFetchHeaders({ 'Authorization': `Bearer SSAAMStudents` })
        }),
        new Promise((_, reject) => 
          setTimeout(() => reject(new Error('Students fetch timeout')), 8000)
        )
      ])
      const studentsResult = await studentsResponse.json()
      const pageData = studentsResult.data || studentsResult
      
      if (studentsResponse.ok && Array.isArray(pageData)) {
        if (studentsResult.pagination) {
          paginationTotal.value = studentsResult.pagination.total
          totalPages.value = studentsResult.pagination.totalPages
        }
        
        users.value = pageData.map(s => ({
          ...s,
          studentId: s.student_id,
          firstName: s.first_name,
          middleName: s.middle_name || '',
          lastName: s.last_name,
          yearLevel: s.year_level,
          rfidCode: s.rfid_code || 'N/A',
          schoolYear: s.school_year,
          image: s.photo || s.image || ''
        }))
      }
    } catch (error) {
      console.error('Failed to fetch students (non-blocking):', error)
      // Continue even if this fails
    }
    
    // Auto-sync payments in background without blocking
    autoSyncPayments().catch(error => {
      console.error('Auto-sync failed:', error)
    })
    
    showNotification('Data refreshed successfully', 'success')
  } catch (error) {
    console.error('Failed to refresh all data:', error)
    showNotification('Failed to refresh data', 'error')
  } finally {
    paymentsLoading.value = false
  }
}

// Create new payment
