// Search for student and show verification
const searchStudentForPayment = async () => {
  if (!paymentSearchQuery.value.trim()) {
    showNotification(`Enter ${paymentSearchMode.value === 'id' ? 'Student ID' : 'RFID code'}`, 'error')
    return
  }
  
  searchingPaymentStudent.value = true
  verifyingPaymentStudent.value = true
  
  try {
    // Build search params based on mode
    let searchParams
    if (paymentSearchMode.value === 'id') {
      // Search specifically by student ID
      searchParams = new URLSearchParams({
        search: paymentSearchQuery.value,
        limit: 1
      })
    } else {
      // Search specifically by RFID
      searchParams = new URLSearchParams({
        search: paymentSearchQuery.value,
        rfid_status: 'all',
        limit: 1
      })
    }
    
    const response = await fetch(buildAPIUrl(`/apis/students/search?${searchParams}`), {
      method: 'GET',
      headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
    })
    
    const result = await response.json()
    
    // Handle both response formats: data array or direct student object
    let student = null
    if (response.ok) {
      if (result.data && Array.isArray(result.data) && result.data.length > 0) {
        student = result.data[0]
      } else if (result.student) {
        student = result.student
      }
    }
    
    if (student) {
      selectedPaymentStudent.value = student
      showNotification('Student found! Please verify the information.', 'info')
    } else {
      selectedPaymentStudent.value = null
      showNotification(`Student not found. Make sure the ${paymentSearchMode.value === 'id' ? 'Student ID is correct' : 'RFID is registered'}.`, 'error')
    }
  } catch (error) {
    console.error('Error searching student:', error)
    selectedPaymentStudent.value = null
    showNotification('Error searching for student', 'error')
  } finally {
    searchingPaymentStudent.value = false
    verifyingPaymentStudent.value = false
  }
}

// Handle RFID input - auto-submit after scan completes
let rfidAutoSubmitTimer = null
const handleRfidInput = () => {
  // Clear any pending auto-submit
  if (rfidAutoSubmitTimer) {
    clearTimeout(rfidAutoSubmitTimer)
  }
  
  // Auto-submit RFID after 500ms of no input (RFID scanners typically finish scanning in 100-300ms)
  if (paymentSearchMode.value === 'rfid' && paymentSearchQuery.value.trim().length > 5) {
    rfidAutoSubmitTimer = setTimeout(() => {
      searchStudentForPayment()
    }, 500)
  }
}

// Clear the selected student and allow new search
const clearPaymentStudent = () => {
  selectedPaymentStudent.value = null
  paymentSearchQuery.value = ''
  paymentSearchMode.value = 'id' // Reset to Student ID mode
  markingPaymentAsPaid.value = false // Reset processing state
}

// Helper function to format the "Paid By" name
const formatPaidByName = (record) => {
  if (record.payment_status !== 'paid' || !record.paid_date) {
    return 'N/A'
  }
  
  const paidByName = record.marked_by_first_name || 
    (typeof record.paid_by_treasurer === 'string' ? record.paid_by_treasurer : record.paid_by_treasurer?.first_name)
  
  // If no name or it's empty, return "Treasurer" as fallback
  if (!paidByName || paidByName.trim() === '') {
    return 'Treasurer'
  }
  
  // Convert to uppercase
  return paidByName.toUpperCase()
}

