// Auto-sync all active payments with newly approved students
// This has been extended so the UI count always matches the dashboard's total
// registered students.  Whenever the overall student count changes we re-run
// the sync and, if necessary, refresh the payments list so the card numbers
// are kept in sync.
const autoSyncPayments = async () => {
  try {
    const activePayments = paymentsList.value.filter(p => p.status === 'active')
    if (activePayments.length === 0) return

    // compute expected total from dashboard stats (relying on computed property)
    const expectedTotal = totalStudents.value || 0

    // helper that will sync campaign stats to match dashboard totals.
    // we always recalc unpaid_count locally so the card never displays stale
    // numbers, then only contact the backend if the stored total_students
    // actually differs.  this ensures errors like "50 unpaid when students are
    // 769" cannot persist simply because a network call was skipped.
    const syncWithTimeout = (payment) => {
      if (payment.stats) {
        // recalc unpaid every time (paid_count may change independently);
        // clamp to zero in case dashboard total falls below paid count.
        payment.stats.unpaid_count = Math.max(0, expectedTotal - (payment.stats.paid_count || 0))
          expectedTotal > 0 ? Math.round((payment.stats.paid_count / expectedTotal) * 100) : 0
      }

      // if there is no stats object or totals already match, we don't need to
      // bother hitting the server; earlier recalculation is sufficient.  we
      // also ensure the local total_students is updated so UI reflects the
      // dashboard total immediately.
      if (!payment.stats || payment.stats.total_students === expectedTotal) {
        if (payment.stats) {
          payment.stats.total_students = expectedTotal
        }
        return Promise.resolve(null)
      }

      return new Promise((resolve) => {
        const timeout = setTimeout(() => {
          console.warn(`Sync timeout for payment ${payment._id}`)
          resolve(null)
        }, 5000)

        fetch(buildAPIUrl(`/apis/payments/${payment._id}/sync-students`), {
          method: 'POST',
          headers: getFetchHeaders({
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${getSessionToken()}`
          })
        })
        .then(res => res.json())
        .then(result => {
          clearTimeout(timeout)
          if (payment.stats) {
            const added = result && result.data ? result.data.added_count || 0 : 0
            payment.stats.total_students = expectedTotal
            payment.stats.unpaid_count = Math.max(0, expectedTotal - (payment.stats.paid_count || 0))
            payment.stats.completion_percentage =
              expectedTotal > 0 ? Math.round((payment.stats.paid_count / expectedTotal) * 100) : 0

            if (added > 0) {
              console.debug(`sync-students added ${added} records for payment ${payment._id}`)
            }
          }
          resolve(result)
        })
        .catch(err => {
          clearTimeout(timeout)
          console.warn('Sync request failed', err)
          resolve(null)
        })
      })
    }

    const syncPromises = activePayments.map(syncWithTimeout)
    const results = await Promise.all(syncPromises)

    // if any of the syncs actually added students we should force a refresh of
    // the payments list (bypassing cache) so that the backend-side stats are
    // in sync too.
    const addedSomething = results.some(r => r && r.data && r.data.added_count > 0)
    if (addedSomething) {
      await fetchPayments(true)
    }
  } catch (err) {
    console.error('autoSyncPayments error', err)
  }
}
// Filter payment records based on filters
const shouldShowRecord = (payment, record) => {
  // Filter by payment ID if selected
  if (paymentRecordsFilter.value.paymentId && payment._id !== paymentRecordsFilter.value.paymentId) {
    return false
  }

  // Filter by status
  if (paymentRecordsFilter.value.status === 'paid' && record.payment_status !== 'paid') {
    return false
  }
  if (paymentRecordsFilter.value.status === 'unpaid' && record.payment_status !== 'unpaid' && record.payment_status !== 'pending') {
    return false
  }

  // Filter by year level
  if (paymentRecordsFilter.value.yearLevel && record.year_level !== paymentRecordsFilter.value.yearLevel) {
    return false
  }

  // Filter by program
  if (paymentRecordsFilter.value.program && record.program !== paymentRecordsFilter.value.program) {
    return false
  }

  // Filter by search query (name or ID)
  if (paymentRecordsFilter.value.searchQuery.trim()) {
    const query = paymentRecordsFilter.value.searchQuery.toLowerCase()
    const name = (record.student_name || '').toLowerCase()
    const id = (record.student_id || '').toLowerCase()
    if (!name.includes(query) && !id.includes(query)) {
      return false
    }
  }

  return true
}

// Sort payment records - paid first when showing all, then by latest date paid
const getSortedPaymentRecords = (payment) => {
  if (!payment || !payment.payment_records) return []
  
  const records = [...(payment.payment_records || [])]
  
  // Sort by date paid (latest first) and status
  records.sort((a, b) => {
    // Paid records come first
    if (a.payment_status === 'paid' && b.payment_status !== 'paid') return -1
    if (a.payment_status !== 'paid' && b.payment_status === 'paid') return 1
    
    // If both are paid, sort by date (latest first)
    if (a.payment_status === 'paid' && b.payment_status === 'paid') {
      const dateA = new Date(a.paid_date || 0)
      const dateB = new Date(b.paid_date || 0)
      return dateB.getTime() - dateA.getTime() // Latest first
    }
    
    // Then unpaid, then pending
    if (a.payment_status === 'unpaid' && b.payment_status === 'pending') return -1
    if (a.payment_status === 'pending' && b.payment_status === 'unpaid') return 1
    
    // If same status (unpaid or pending), sort by record date (latest first)
    const dateA = new Date(a.date_submitted || a.created_at || 0)
    const dateB = new Date(b.date_submitted || b.created_at || 0)
    return dateB.getTime() - dateA.getTime() // Latest first
  })
  
  // Filter records before pagination
  const filteredRecords = records.filter(record => shouldShowRecord(payment, record))
  
  // Apply pagination
  const startIndex = (paymentRecordsFilter.value.currentPage - 1) * paymentRecordsFilter.value.recordsPerPage
  const endIndex = startIndex + paymentRecordsFilter.value.recordsPerPage
  
  return filteredRecords.slice(startIndex, endIndex)
}

// Get total pages for payment records
const getPaymentRecordsTotalPages = (payment) => {
  if (!payment || !payment.payment_records) return 0
  const filteredRecords = payment.payment_records.filter(record => shouldShowRecord(payment, record))
  return Math.ceil(filteredRecords.length / paymentRecordsFilter.value.recordsPerPage)
}

// Get filtered statistics
const getFilteredStats = () => {
  let paid = 0
  let unpaid = 0
  let total = 0

  // If a payment is selected, only count records from that payment
  if (selectedPayment.value) {
    (selectedPayment.value.payment_records || []).forEach(record => {
      if (shouldShowRecord(selectedPayment.value, record)) {
        total++
        if (record.is_paid) {
          paid++
        } else {
          unpaid++
        }
      }
    })
  } else {
    // Otherwise count from all payments
    paymentsList.value.forEach(payment => {
      (payment.payment_records || []).forEach(record => {
        if (shouldShowRecord(payment, record)) {
          total++
          if (record.is_paid) {
            paid++
          } else {
            unpaid++
          }
        }
      })
    })
  }

  const percentage = total > 0 ? Math.round((paid / total) * 100) : 0

  return { paid, unpaid, total, percentage }
}

// Fix old student IDs (ObjectId format) to proper student IDs
const autoFixStudentIds = async () => {
  try {
    const response = await fetch(buildAPIUrl('/apis/payments/migrate/fix-student-ids'), {
      method: 'POST',
      headers: getFetchHeaders({
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${getSessionToken()}`
      })
    })

    const result = await response.json()
    if (response.ok) {
      // Silent success - don't show notification for automatic fix
      if (result.fixed > 0) {
        console.log(`Fixed ${result.fixed} student IDs automatically`)
      }
    } else {
      console.error('Error auto-fixing student IDs:', result.message)
    }
  } catch (error) {
    console.error('Error auto-fixing student IDs:', error)
  }
}

// Delete payment record from transparency board
const deletePaymentRecordTransparency = (record) => {
  deletePaymentConfirmation.value = {
    name: record.name,
    amount: record.contribution_amount,
    description: record.contribution_description,
    record: record
  }
}

const confirmDeletePaymentRecord = async () => {
  if (!deletePaymentConfirmation.value) return
  
  deletingPayment.value = true
  try {
    // Find payment from the record and attempt to delete
    // Since we have student name but need ID, we'll search through our data
    const record = deletePaymentConfirmation.value.record
    
    // Try to find the payment ID from transparency list or payments list
    let deleted = false
    
    // First, try to find in the selected payment if one is selected
    if (selectedPayment.value && selectedPayment.value._id) {
      // Find the student ID from their full name
      const students = await fetch(buildAPIUrl('/apis/students'), {
        headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
      }).then(r => r.json())
      
      const student = students.data?.find(s => 
        (s.full_name || `${s.first_name} ${s.last_name}`).toLowerCase() === record.name.toLowerCase()
      )
      
      if (student) {
        const deleteResponse = await fetch(buildAPIUrl(`/apis/payments/${selectedPayment.value._id}/student/${student._id}`), {
          method: 'DELETE',
          headers: getFetchHeaders({ 'Authorization': `Bearer ${getSessionToken()}` })
        })
        
        if (deleteResponse.ok) {
          deleted = true
        }
      }
    }
    
    if (deleted) {
      showNotification(`Payment deleted for ${record.name}`, 'success')
      deletePaymentConfirmation.value = null
      await fetchTransparencyBoard()
      if (selectedPayment.value) await fetchPayments()
    } else {
      showNotification('Could not delete payment record', 'error')
    }
  } catch (error) {
    console.error('Error deleting payment:', error)
    showNotification('Error deleting payment record', 'error')
  } finally {
    deletingPayment.value = false
  }
}

const searchStudentForContribution = async () => {
  if (!contributionSearchQuery.value.trim()) return
  searchingStudent.value = true
  try {
    const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
    const queryParam = contributionScanMode.value === 'rfid' ? `rfid=${contributionSearchQuery.value}` : `search=${contributionSearchQuery.value}`
    const response = await fetch(buildAPIUrl(`/apis/students?${queryParam}`), {
      headers: getFetchHeaders({ 'Authorization': `Bearer ${token}` })
    })
    const result = await response.json()
    if (response.ok) {
      const students = result.data || result || []
      if (students.length > 0) {
        selectedStudentForContribution.value = students[0]
        showNotification('Student found!', 'success')
      } else {
        showNotification('Student not found', 'error')
        selectedStudentForContribution.value = null
      }
    }
    contributionSearchQuery.value = ''
    nextTick(() => contributionInputRef.value?.focus())
  } catch (error) {
    console.error('Search failed:', error)
  } finally {
    searchingStudent.value = false
  }
}

const recordContribution = async () => {
  if (!selectedStudentForContribution.value || !contributionAmount.value) return
  recordingContribution.value = true
  try {
    const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
    const response = await fetch(buildAPIUrl('/apis/admin/contributions'), {
      method: 'POST',
      headers: getFetchHeaders({ 'Authorization': `Bearer ${token}` }),
      body: JSON.stringify({
        student_id: selectedStudentForContribution.value.student_id,
        amount: contributionAmount.value,
        description: contributionDescription.value,
        admin_username: currentUser.value.username || 'admin'
      })
    })
    if (response.ok) {
      showNotification('Contribution recorded successfully', 'success')
      contributionAmount.value = ''
      contributionDescription.value = ''
      selectedStudentForContribution.value = null
      contributionSearchQuery.value = ''
    } else {
      const error = await response.json()
      showNotification(error.message || 'Failed to record contribution', 'error')
    }
  } catch (error) {
    console.error('Recording failed:', error)
    showNotification('Recording error', 'error')
  } finally {
    recordingContribution.value = false
  }
}

