// Notification state for the User > Attendance face/scanner card.
//   type: 'success' | 'error' | 'locked'  — drives color/icon
//   duration: ms used by the auto-dismiss progress bar so it stays in sync
//   key: bumped on every showDashNotif() call so the <Transition> re-mounts
//        and the intro animation + progress bar restart cleanly even when
//        the same message is fired twice in a row.
const dashFaceCheckInNotif = ref({ show: false, type: 'success', message: '', duration: 4000 })
const dashFaceCheckInNotifKey = ref(0)
let dashFaceCheckInNotifTimer = null
const showDashNotif = (type, message, duration = 4000) => {
  if (dashFaceCheckInNotifTimer) {
    clearTimeout(dashFaceCheckInNotifTimer)
    dashFaceCheckInNotifTimer = null
  }
  dashFaceCheckInNotifKey.value++
  dashFaceCheckInNotif.value = { show: true, type, message, duration }
  dashFaceCheckInNotifTimer = setTimeout(() => {
    dashFaceCheckInNotif.value.show = false
    dashFaceCheckInNotifTimer = null
  }, duration)
}
const dismissDashNotif = () => {
  if (dashFaceCheckInNotifTimer) {
    clearTimeout(dashFaceCheckInNotifTimer)
    dashFaceCheckInNotifTimer = null
  }
  dashFaceCheckInNotif.value.show = false
}

// Location Gate — appears BEFORE the Face ID modal whenever the event has
// `geofence_enabled`. It shows a live radar with the user's distance from
// the event center, blocks check-in when the user is outside the allowed
// radius, and (on pass) hands the captured GPS coords to the face scanner
// so the scanner doesn't need to re-request them.
const locationGateOpen = ref(false)
const locationGateEvent = ref(null)
const locationGateSession = ref(null)

const getSessionCheckAction = (session, event) => {
  const eventId = event._id || event.event_id
  const record = myAttendanceRecords.value.find(r => r.event_id === eventId)
  const sessionLog = record && (record.sessions || []).find(s => s.session_id === session._id || s.session?._id === session._id)
  const att = sessionLog?.attendance || {}
  if (att.check_in_at && att.check_out_at) return null
  if (att.check_in_at) return 'Check Out'
  return 'Check In'
}

// ── Per-event Face ID scanner button ────────────────────────────────────────
// Reads cascading rfidScanner toggles (session → event → defaults) so we can
// tell the user when check-in/check-out is currently open.
const isSessionCheckInAvailable = (session, event) => {
  const s = session?.rfidScanner
  if (s && typeof s.checkInEnabled === 'boolean') return s.checkInEnabled
  const e = event?.rfidScanner
  if (e && typeof e.checkInEnabled === 'boolean') return e.checkInEnabled
  return true
}
const isSessionCheckOutAvailable = (session, event) => {
  const s = session?.rfidScanner
  if (s && typeof s.checkOutEnabled === 'boolean') return s.checkOutEnabled
  const e = event?.rfidScanner
  if (e && typeof e.checkOutEnabled === 'boolean') return e.checkOutEnabled
  return false
}

// Lazy-load sessions for an event when the scanner button needs them. Returns
// the cached array (possibly empty if loading or fetch failed).
const ensureEventSessions = async (eventId) => {
  if (expandedEventSessions.value[eventId]) return expandedEventSessions.value[eventId]
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken') || localStorage.getItem('studentToken')
  try {
    const response = await fetch(buildAPIUrl(`/apis/attendance/events/${eventId}/sessions`), {
      headers: { 'Authorization': `Bearer ${token}`, 'X-SSAAM-TS': encodeTimestamp() }
    })
    if (response.ok) {
      const result = await response.json()
      expandedEventSessions.value[eventId] = result.data || result.sessions || []
    }
  } catch (e) {
    console.error('[EventScanner] Failed to load sessions for', eventId, e)
  }
  return expandedEventSessions.value[eventId] || []
}

// Compute the current state of the per-event scanner button.
//   loading    → sessions for this event are still being fetched
//   no_active  → no session is open right now
//   done       → all active sessions are complete (check-in + check-out done)
//   locked     → user is checked in but check-out isn't open yet
//   ready      → at least one actionable session (Check In or Check Out)
const getEventScannerInfo = (event) => {
  const eventId = event._id || event.event_id
  const sessions = expandedEventSessions.value[eventId]
  if (!sessions) return { state: 'loading', actionable: [], waiting: [] }
  const active = sessions.filter(s => getSessionDisplayStatus(s, event) === 'active')
  if (!active.length) return { state: 'no_active', actionable: [], waiting: [] }
  const actionable = []
  const waiting = []
  let anyOpen = false
  for (const s of active) {
    const a = getSessionCheckAction(s, event)
    if (a == null) continue
    anyOpen = true
    if (a === 'Check In') {
      if (isSessionCheckInAvailable(s, event)) actionable.push({ session: s, action: 'Check In' })
      else waiting.push({ session: s, action: 'Check In', reason: 'Check-in is not currently open for this session.' })
    } else if (a === 'Check Out') {
      if (isSessionCheckOutAvailable(s, event)) actionable.push({ session: s, action: 'Check Out' })
      else waiting.push({ session: s, action: 'Check Out', reason: "You're checked in. Please wait for check-out to be opened." })
    }
  }
  if (!anyOpen) return { state: 'done', actionable: [], waiting: [] }
  if (actionable.length === 0) return { state: 'locked', actionable: [], waiting }
  return { state: 'ready', actionable, waiting }
}

const getEventScannerBtnSize = 'w-20 h-20 sm:w-24 sm:h-24 text-xs'
const getEventScannerBtnClass = (event) => {
  // Face ID disabled by admin: render the button in a muted, "off" state.
  if (event && event.face_id_enabled === false) {
    return 'bg-gradient-to-br from-gray-400 to-gray-500 opacity-70 cursor-not-allowed'
  }
  const info = getEventScannerInfo(event)
  if (info.state === 'loading') return 'bg-gradient-to-br from-gray-300 to-gray-400 cursor-wait'
  if (info.state === 'no_active') return 'bg-gradient-to-br from-gray-400 to-gray-500 opacity-80'
  if (info.state === 'done') return 'bg-gradient-to-br from-emerald-500 to-emerald-600 cursor-default opacity-90'
  if (info.state === 'locked') return 'bg-gradient-to-br from-amber-500 to-orange-600 ring-2 ring-amber-300/60 hover:from-amber-600 hover:to-orange-700'
  // ready — any check-out actionable styles green, otherwise blue/college accent
  const hasCheckOut = info.actionable.some(a => a.action === 'Check Out')
  if (hasCheckOut) return 'bg-gradient-to-br from-emerald-500 to-green-600 hover:from-emerald-600 hover:to-green-700 shadow-lg shadow-emerald-500/30'
  if (isCOE.value) return 'bg-gradient-to-br from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 shadow-lg shadow-orange-500/30'
  if (isSOM.value) return 'bg-gradient-to-br from-green-500 to-green-600 hover:from-green-600 hover:to-green-700 shadow-lg shadow-green-500/30'
  if (isCNAHS.value) return 'bg-gradient-to-br from-emerald-500 to-emerald-600 hover:from-emerald-600 hover:to-emerald-700 shadow-lg shadow-emerald-500/30'
  return 'bg-gradient-to-br from-[#1e3bdb] to-[#4f62ff] hover:from-[#1730c0] hover:to-[#3d52e8] shadow-lg shadow-blue-600/30'
}
const getEventScannerLabel = (event) => {
  if (event && event.face_id_enabled === false) return 'Face ID Off'
  const info = getEventScannerInfo(event)
  if (info.state === 'loading') return 'Loading'
  if (info.state === 'no_active') return 'Closed'
  if (info.state === 'done') return 'Done'
  if (info.state === 'locked') return 'Locked'
  const hasCheckOut = info.actionable.some(a => a.action === 'Check Out')
  if (hasCheckOut && info.actionable.every(a => a.action === 'Check Out')) return 'Check Out'
  return 'Scan'
}
const getEventScannerTooltip = (event) => {
  if (event && event.face_id_enabled === false) return 'Face ID Recognition is disabled for this event by the admin.'
  const info = getEventScannerInfo(event)
  if (info.state === 'loading') return 'Loading sessions…'
  if (info.state === 'no_active') return 'No active session right now.'
  if (info.state === 'done') return 'You have completed attendance for this event.'
  if (info.state === 'locked') return info.waiting[0]?.reason || 'Waiting for check-out to be opened.'
  if (info.actionable.length === 1) return `${info.actionable[0].action} for ${info.actionable[0].session.label}`
  return 'Choose a session to scan'
}

// Session picker (shown only when 2+ actionable sessions exist).
const eventSessionPickerOpen = ref(false)
const eventSessionPickerEvent = ref(null)
const eventSessionPickerActions = ref([])
const dashFaceCheckInLoading = ref(false)

const openEventScanner = async (event) => {
  if (dashFaceCheckInLoading.value) return
  // Admins can disable Face ID Recognition for an event entirely; surface that to
  // the student instead of opening the camera so they know to use RFID/manual check-in.
  if (event && event.face_id_enabled === false) {
    showDashNotif('error', 'Face ID Recognition has been disabled for this event by the admin. Please use the RFID scanner or contact your administrator for manual check-in.', 6000)
    return
  }
  dashFaceCheckInLoading.value = true
  try {
    const eventId = event._id || event.event_id
    await ensureEventSessions(eventId)
    const info = getEventScannerInfo(event)
    if (info.state === 'no_active') {
      showDashNotif('error', 'There is no active session for this event right now.', 4000)
      return
    }
    if (info.state === 'done') {
      showDashNotif('success', "You've already completed attendance for this event.", 4000)
      return
    }
    if (info.state === 'locked') {
      const reason = info.waiting[0]?.reason || "You're checked in. Please wait for check-out to be opened."
      // 'locked' type renders amber + lock icon to clearly distinguish a
      // soft "wait" state from a hard error.
      showDashNotif('locked', reason, 4500)
      return
    }
    // state === 'ready'
    if (info.actionable.length === 1) {
      await openDashFaceCheckIn(info.actionable[0].session, event)
    } else {
      eventSessionPickerEvent.value = event
      eventSessionPickerActions.value = info.actionable
      eventSessionPickerOpen.value = true
    }
  } finally {
    dashFaceCheckInLoading.value = false
  }
}

const pickEventScannerSession = async (item) => {
  const event = eventSessionPickerEvent.value
  eventSessionPickerOpen.value = false
  if (event) await openDashFaceCheckIn(item.session, event)
}
const closeEventSessionPicker = () => {
  eventSessionPickerOpen.value = false
}

// Per-session lock reason (used by the inline session button inside the
// expanded panel). Returns a notification string when the action is Check In
// but check-in is closed, or Check Out but check-out isn't open yet.
const getSessionLockReason = (session, event) => {
  const action = getSessionCheckAction(session, event)
  if (action === 'Check In' && !isSessionCheckInAvailable(session, event)) {
    return 'Check-in is not currently open for this session.'
  }
  if (action === 'Check Out' && !isSessionCheckOutAvailable(session, event)) {
    return "You're checked in. Please wait for check-out to be opened."
  }
  return null
}
const handleSessionButtonClick = (session, event) => {
  const reason = getSessionLockReason(session, event)
  if (reason) {
    showDashNotif('locked', reason, 4500)
    return
  }
  openDashFaceCheckIn(session, event)
}

const openDashFaceCheckIn = async (session, event) => {
  dismissDashNotif()
  // Geofenced events go through the Location Gate first — it shows the user
  // a live radar, blocks if they're outside the allowed radius, and (on
  // pass) calls back into _openFaceScannerWithCoords with the GPS fix.
  // Non-geofenced events skip straight to the face scanner.
  if (event.geofence_enabled
      && Number.isFinite(Number(event.geofence_lat))
      && Number.isFinite(Number(event.geofence_lng))) {
    locationGateEvent.value = event
    locationGateSession.value = session
    locationGateOpen.value = true
    return
  }
  _openFaceScannerWithCoords(session, event, null)
}

// Internal: opens the Face ID scanner with optional pre-fetched GPS coords.
// Called either directly (no geofence) or from the Location Gate's @pass
// handler (geofence verified).
const _openFaceScannerWithCoords = (session, event, coords) => {
  const eventCopy = { ...event }
  if (coords && coords.lat != null && coords.lng != null) {
    eventCopy._pendingLat = coords.lat
    eventCopy._pendingLng = coords.lng
    eventCopy._pendingAccuracy = coords.accuracy
  }
  dashFaceCheckInEvent.value = eventCopy
  dashFaceCheckInSession.value = session
  dashFaceCheckInOpen.value = true
}

// Location Gate → Face ID handoff. Closes the gate, then opens the scanner
// with the verified coords on the next tick so the panel-leave animation
// doesn't visibly overlap the panel-enter animation.
const onLocationGatePass = (coords) => {
  const session = locationGateSession.value
  const event = locationGateEvent.value
  locationGateOpen.value = false
  if (!session || !event) return
  setTimeout(() => {
    _openFaceScannerWithCoords(session, event, coords)
    locationGateEvent.value = null
    locationGateSession.value = null
  }, 180)
}

const onLocationGateClose = () => {
  locationGateOpen.value = false
  locationGateEvent.value = null
  locationGateSession.value = null
}

const onDashFaceCheckInSuccess = async (data) => {
  dashFaceCheckInOpen.value = false
  const action = data.action === 'check_in' ? 'Check in' : data.action === 'check_out' ? 'Check out' : 'Attendance'
  showDashNotif('success', `${action} recorded successfully!`, 4000)
  try {
    const token = localStorage.getItem('authToken') || localStorage.getItem('studentToken')
    const res = await fetch(buildAPIUrl('/apis/attendance/my-records'), {
      headers: { 'Authorization': `Bearer ${token}`, 'X-SSAAM-TS': encodeTimestamp() }
    })
    if (res.ok) {
      const result = await res.json()
      const records = result.data || result || []
      myAttendanceRecords.value = records.map((r, idx) => {
        const eventId = r.event?._id || r.event_id || `record-${idx}`
        return {
          ...r,
          _id: eventId,
          event_id: eventId,
          event_title: r.event?.title,
          sessions: (r.sessions || []).map((s, sIdx) => ({
            ...s,
            session: s.session || {},
            session_id: s.session?._id || `session-${sIdx}`,
            attendance: s.attendance || { check_in_at: null, check_out_at: null, status: 'absent' }
          })),
          overall_status: r.overall_status || 'absent',
          check_in_at: r.attendance?.check_in_at,
          check_out_at: r.attendance?.check_out_at,
          status: r.attendance?.status || r.overall_status || 'absent'
        }
      })
    }
  } catch (_) {}
}
