  return 'linear-gradient(to bottom right, #1e3bdb, #4f62ff)' // ssaam blue
}

const applyPaletteToGradient = (palette) => {
  if (!palette || palette.length === 0) {
    profileGradient.value = getDefaultProfileGradient();
    return;
  }
  
  const isWhite = (rgba) => rgba[0] > 240 && rgba[1] > 240 && rgba[2] > 240;
  const isDark = (rgba) => (0.299 * rgba[0] + 0.587 * rgba[1] + 0.114 * rgba[2]) < 50;

  const getBrightness = (rgba) => (0.299 * rgba[0] + 0.587 * rgba[1] + 0.114 * rgba[2]);
  const getSaturation = (rgba) => {
    const max = Math.max(rgba[0], rgba[1], rgba[2]);
    const min = Math.min(rgba[0], rgba[1], rgba[2]);
    return max === 0 ? 0 : (max - min) / max;
  };

  // Find all valid colors
  const validColors = palette.filter(c => !isWhite(c.rgba) && !isDark(c.rgba));
  
  if (validColors.length === 0) {
    // If no valid colorful colors, use the dominant one even if it's white/dark
    const dominant = palette[0];
    profileGradient.value = `linear-gradient(to top, rgb(${dominant.rgba[0]},${dominant.rgba[1]},${dominant.rgba[2]}), rgb(${dominant.rgba[0]+20},${dominant.rgba[1]+20},${dominant.rgba[2]+20}))`;
    return;
  }

  // Sort by vibrant score (brightness + saturation)
  validColors.sort((a, b) => {
    const scoreA = (getBrightness(a.rgba) / 255) * 0.4 + getSaturation(a.rgba) * 0.6;
    const scoreB = (getBrightness(b.rgba) / 255) * 0.4 + getSaturation(b.rgba) * 0.6;
    return scoreB - scoreA;
  });

  const mainColor = validColors[0];
  const secondaryColor = validColors[1] || mainColor;

  const b1 = getBrightness(mainColor.rgba);
  const b2 = getBrightness(secondaryColor.rgba);

  let topColor, bottomColor;
  if (b1 > b2) {
    topColor = `rgb(${mainColor.rgba[0]}, ${mainColor.rgba[1]}, ${mainColor.rgba[2]})`;
    bottomColor = `rgb(${secondaryColor.rgba[0]}, ${secondaryColor.rgba[1]}, ${secondaryColor.rgba[2]})`;
  } else {
    topColor = `rgb(${secondaryColor.rgba[0]}, ${secondaryColor.rgba[1]}, ${secondaryColor.rgba[2]})`;
    bottomColor = `rgb(${mainColor.rgba[0]}, ${mainColor.rgba[1]}, ${mainColor.rgba[2]})`;
  }

  profileGradient.value = `linear-gradient(to top, ${bottomColor}, ${topColor})`;
};

const updateProfileGradient = async (url) => {
  if (!url) {
    profileGradient.value = getDefaultProfileGradient();
    return;
  }

  try {
    // Create an image element to extract colors from
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      try {
        const color = fac.getColor(img);
        if (color && color.rgba) {
          profileGradient.value = `linear-gradient(to top, rgb(${color.rgba[0]},${color.rgba[1]},${color.rgba[2]}), rgb(${Math.min(color.rgba[0]+30,255)},${Math.min(color.rgba[1]+30,255)},${Math.min(color.rgba[2]+30,255)}))`;
        } else {
          profileGradient.value = getDefaultProfileGradient();
        }
      } catch (e) {
        console.error('Color extraction failed:', e);
        profileGradient.value = getDefaultProfileGradient();
      }
    };
    img.onerror = () => {
      console.warn('Failed to load image for color extraction:', url);
      profileGradient.value = getDefaultProfileGradient();
    };
    img.src = url;
  } catch (e) {
    console.error('Error in updateProfileGradient:', e);
    profileGradient.value = getDefaultProfileGradient();
  }
};

watch(() => currentUser.value?.image || currentUser.value?.photo, (newUrl) => {
