// Database migration management
const migrationDestinationUri = ref('')
const migratingDatabase = ref(false)

// Duplicate search management
const duplicateSearchQuery = ref('')
const duplicateSearchLoading = ref(false)
const duplicateSearchResults = ref([])
const duplicateSearchPerformed = ref(false)
const duplicateSearchDebounceTimer = ref(null)

// Auto scan for all duplicates
const autoScanLoading = ref(false)
const autoScanResults = ref([])
const autoScanPerformed = ref(false)

// Auto-search for duplicates as user types (with 500ms debounce)
watch(duplicateSearchQuery, (newValue) => {
  // Clear previous timer
  if (duplicateSearchDebounceTimer.value) {
    clearTimeout(duplicateSearchDebounceTimer.value)
  }
  
  // Clear results if empty
  if (!newValue.trim()) {
    duplicateSearchResults.value = []
    duplicateSearchPerformed.value = false
    return
  }
  
  // Debounce: wait 500ms after user stops typing before searching
  duplicateSearchDebounceTimer.value = setTimeout(() => {
    searchForDuplicates()
  }, 500)
})

// RFID Fullscreen mode
const rfidFullscreenMode = ref(false)
const rfidFullscreenInputRef = ref(null)
const logoFlipping = ref(false)
const logoFlipInterval = ref(null)
const rfidFocusTimeout = ref(null)

// Particle animation for fullscreen RFID scanner
const particleCanvas = ref(null)
let particleAnimFrame = null
const particleList = []

const initParticles = (canvas) => {
  particleList.length = 0
  const count = Math.min(70, Math.floor((canvas.width * canvas.height) / 14000))
  for (let i = 0; i < count; i++) {
    const hue = Math.random() * 60 + 180
    particleList.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      radius: Math.random() * 2.5 + 0.8,
      vx: (Math.random() - 0.5) * 0.4,
      vy: (Math.random() - 0.5) * 0.4,
      opacity: Math.random() * 0.5 + 0.2,
      opacityDir: (Math.random() > 0.5 ? 1 : -1) * 0.004,
      color: `hsl(${hue}, 90%, 70%)`
    })
  }
}

const drawParticles = () => {
  const canvas = particleCanvas.value
  if (!canvas) return
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, canvas.width, canvas.height)
  for (const p of particleList) {
    p.x += p.vx
    p.y += p.vy
    if (p.x < 0) p.x = canvas.width
    if (p.x > canvas.width) p.x = 0
    if (p.y < 0) p.y = canvas.height
    if (p.y > canvas.height) p.y = 0
    p.opacity += p.opacityDir
    if (p.opacity > 0.85 || p.opacity < 0.1) p.opacityDir *= -1
    ctx.save()
    ctx.globalAlpha = p.opacity
    const grd = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.radius * 5)
    grd.addColorStop(0, p.color)
    grd.addColorStop(1, 'transparent')
    ctx.fillStyle = grd
    ctx.beginPath()
    ctx.arc(p.x, p.y, p.radius * 5, 0, Math.PI * 2)
    ctx.fill()
    ctx.restore()
    ctx.save()
    ctx.globalAlpha = p.opacity * 1.2
    ctx.fillStyle = '#fff'
    ctx.beginPath()
    ctx.arc(p.x, p.y, p.radius * 0.7, 0, Math.PI * 2)
    ctx.fill()
    ctx.restore()
  }
  // Draw faint connection lines
  for (let i = 0; i < particleList.length; i++) {
    for (let j = i + 1; j < particleList.length; j++) {
      const dx = particleList[i].x - particleList[j].x
      const dy = particleList[i].y - particleList[j].y
      const dist = Math.sqrt(dx * dx + dy * dy)
      if (dist < 100) {
        ctx.save()
        ctx.globalAlpha = (1 - dist / 100) * 0.12
        ctx.strokeStyle = particleList[i].color
        ctx.lineWidth = 0.6
        ctx.beginPath()
        ctx.moveTo(particleList[i].x, particleList[i].y)
        ctx.lineTo(particleList[j].x, particleList[j].y)
        ctx.stroke()
        ctx.restore()
      }
    }
  }
  particleAnimFrame = requestAnimationFrame(drawParticles)
}

const startParticles = () => {
  stopParticles()
  nextTick(() => {
    const canvas = particleCanvas.value
    if (!canvas) return
    canvas.width = canvas.offsetWidth
    canvas.height = canvas.offsetHeight
    initParticles(canvas)
    drawParticles()
  })
}

const stopParticles = () => {
  if (particleAnimFrame) {
    cancelAnimationFrame(particleAnimFrame)
    particleAnimFrame = null
  }
}

// Admin photo upload helper
const adminPhotoFileRef = ref(null)
const handleAdminPhotoUpload = (event) => {
  const file = event.target.files[0]
  if (!file) return
  if (!file.type.startsWith('image/')) {
    showNotification('Please select a valid image file', 'error')
    return
  }
  if (file.size > 5 * 1024 * 1024) {
    showNotification('Image must be smaller than 5MB', 'error')
    return
  }
  const reader = new FileReader()
  reader.onload = (e) => {
    adminProfileForm.value.photo = e.target.result
  }
  reader.readAsDataURL(file)
}

