const calculateEndTime = (startTimeStr) => {
  const [h, m] = startTimeStr.split(':').map(Number)
  let endMinute = m + 30
  let endHour = h
  if (endMinute >= 60) {
    endMinute = endMinute - 60
    endHour = endHour + 1
  }
  if (endHour >= 24) {
    endHour = 23
    endMinute = 59
  }
  return `${endHour.toString().padStart(2, '0')}:${endMinute.toString().padStart(2, '0')}`
}

const calculateEventStatus = (eventDate, startTime, endTime) => {
  if (!eventDate || !startTime || !endTime) return 'draft'
  
  const now = new Date()
  const [startH, startM] = startTime.split(':').map(Number)
  const [endH, endM] = endTime.split(':').map(Number)
  
  const eventStart = new Date(eventDate + 'T00:00:00')
  eventStart.setHours(startH, startM, 0, 0)
  
  const eventEnd = new Date(eventDate + 'T00:00:00')
  eventEnd.setHours(endH, endM, 0, 0)
  
  if (now < eventStart) {
    return 'draft'
  } else if (now >= eventStart && now <= eventEnd) {
    return 'active'
  } else {
    return 'closed'
  }
}

const getSessionDisplayStatus = (session, event) => {
  // If event is closed, always return 'closed' regardless of time
  if (event?.status === 'closed') {
    return 'closed'
  }
  
  if (!session || !session.start_time || !session.end_time) return session?.status || 'draft'
  
  const eventDate = event?.date || event?.event_date
  if (!eventDate) return session.status || 'draft'
  
  const [startH, startM] = session.start_time.split(':').map(Number)
  const [endH, endM] = session.end_time.split(':').map(Number)
  
  let eventDateStr
  if (typeof eventDate === 'string') {
    eventDateStr = eventDate.includes('T') ? eventDate.split('T')[0] : eventDate
  } else {
    const d = new Date(eventDate)
    eventDateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
  }
  
  const sessionStartPH = new Date(`${eventDateStr}T${String(startH).padStart(2, '0')}:${String(startM).padStart(2, '0')}:00+08:00`)
  const sessionEndPH = new Date(`${eventDateStr}T${String(endH).padStart(2, '0')}:${String(endM).padStart(2, '0')}:00+08:00`)
  
  const nowUTC = Date.now()
  const sessionStartUTC = sessionStartPH.getTime()
  const sessionEndUTC = sessionEndPH.getTime()
  
  if (nowUTC < sessionStartUTC) {
    return 'draft'
  } else if (nowUTC >= sessionStartUTC && nowUTC <= sessionEndUTC) {
    return 'active'
  } else {
    return 'closed'
  }
}

const openTimePicker = (target) => {
  timePickerTarget.value = target
  let currentTime = ''
  if (target === 'startTime' || target === 'endTime') {
    currentTime = newEvent.value[target]
  } else if (target === 'edit_start_time' || target === 'edit_end_time') {
    const field = target.replace('edit_', '')
    currentTime = selectedEvent.value?.[field] || ''
  } else if (target === 'afternoon_start') {
    currentTime = newEvent.value.afternoon_start_time || '13:00'
  } else if (target === 'edit_afternoon_start') {
    currentTime = selectedEvent.value?.afternoon_start_time || '13:00'
  } else if (target === 'session_start_time') {
    currentTime = newSession.value.start_time || '08:00'
  } else if (target === 'session_end_time') {
    currentTime = newSession.value.end_time || '17:00'
  } else if (target === 'event_start_time') {
    currentTime = newEvent.value.start_time || '07:00'
  } else if (target === 'event_end_time') {
    currentTime = newEvent.value.end_time || '17:00'
  }
  
  if (currentTime) {
    const [h, m] = currentTime.split(':').map(Number)
    timePickerHour.value = h > 12 ? h - 12 : (h === 0 ? 12 : h)
    timePickerMinute.value = m
    timePickerPeriod.value = h >= 12 ? 'PM' : 'AM'
  } else {
    timePickerHour.value = 8
    timePickerMinute.value = 0
    timePickerPeriod.value = 'AM'
  }
  showTimePicker.value = true
}

const isAmPm = (timeStr) => {
  if (!timeStr) return null
  const [h] = timeStr.split(':').map(Number)
  return h < 12 ? 'AM' : 'PM'
}

const autoAdjustEndTime = (startTime) => {
  const [h, m] = startTime.split(':').map(Number)
  return '17:00'
}

const validateDualEventTimes = (startTime, endTime) => {
  if (!startTime || !endTime) return { valid: true }
  const startPeriod = isAmPm(startTime)
  const endPeriod = isAmPm(endTime)
  if (startPeriod === 'PM') {
    return { valid: false, message: 'Dual events must start in the morning (AM). Start time should be before 12:00 PM.' }
  }
  if (endPeriod === 'AM') {
    return { valid: false, message: 'Dual events must end in the afternoon (PM). End time should be 12:00 PM or later.' }
  }
  if (startPeriod === endPeriod) {
    return { valid: false, message: 'Dual events require AM start and PM end time to span morning and afternoon sessions.' }
  }
  return { valid: true }
}

const confirmTimePicker = () => {
  let hour24 = timePickerHour.value
  if (timePickerPeriod.value === 'PM' && hour24 !== 12) hour24 += 12
  if (timePickerPeriod.value === 'AM' && hour24 === 12) hour24 = 0
  
  const timeStr = `${hour24.toString().padStart(2, '0')}:${timePickerMinute.value.toString().padStart(2, '0')}`
  const currentPeriod = hour24 >= 12 ? 'PM' : 'AM'
  
  if (timePickerTarget.value === 'startTime') {
    newEvent.value.startTime = timeStr
    if (!newEvent.value.endTime) {
      newEvent.value.endTime = calculateEndTime(timeStr)
    }
  } else if (timePickerTarget.value === 'endTime') {
    newEvent.value.endTime = timeStr
  } else if (timePickerTarget.value === 'edit_start_time') {
    selectedEvent.value.start_time = timeStr
    if (!selectedEvent.value.end_time) {
      selectedEvent.value.end_time = calculateEndTime(timeStr)
    }
  } else if (timePickerTarget.value === 'edit_end_time') {
    selectedEvent.value.end_time = timeStr
  } else if (timePickerTarget.value === 'session_start_time') {
    newSession.value.start_time = timeStr
  } else if (timePickerTarget.value === 'session_end_time') {
    newSession.value.end_time = timeStr
  } else if (timePickerTarget.value === 'event_start_time') {
    newEvent.value.start_time = timeStr
  } else if (timePickerTarget.value === 'event_end_time') {
    newEvent.value.end_time = timeStr
  }
  showTimePicker.value = false
}

const formatDisplayTime = (time) => {
  if (!time) return 'Select time'
  const [h, m] = time.split(':').map(Number)
  const hour12 = h > 12 ? h - 12 : (h === 0 ? 12 : h)
  const period = h >= 12 ? 'PM' : 'AM'
  return `${hour12.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')} ${period}`
}

const handlePosterImageError = async (notifId, imageUrl) => {
  const retries = posterImageRetries.value[notifId] || 0
  if (retries < MAX_POSTER_IMAGE_RETRIES && imageUrl) {
    posterImageRetries.value[notifId] = retries + 1
    await new Promise(resolve => setTimeout(resolve, 500))
    const imgElements = document.querySelectorAll(`img[src="${imageUrl}"]`)
    imgElements.forEach(img => {
      img.src = imageUrl + '?retry=' + Date.now()
    })
  } else {
    posterImageFailed.value[notifId] = true
  }
}


