onMounted(async () => {
  // Set up automatic logout callback for token errors
  setTokenExpiredCallback(() => {
    console.warn('Token expired, showing session expired modal')
    showSessionExpiredModal.value = true
  })
  
  // Add ESC key listener for fullscreen mode
  document.addEventListener('keydown', handleEscKey)

  // Focus main content on load so arrow-key scrolling works immediately
  nextTick(() => { mainContentEl.value?.focus() })
  
  // Set default profile gradient based on theme
  profileGradient.value = getDefaultProfileGradient()
  
  const user = JSON.parse(localStorage.getItem('currentUser') || '{}')
  if (!user.studentId && !user.student_id) {
    router.push('/')
    return
  }
  currentUser.value = user

  // Show welcome + T&C modal on every login until user explicitly agrees
  if (!localStorage.getItem('ssaam_tc_agreed')) {
    showWelcomeModal.value = true
  }

  // Check if user needs to update password (still using last name as password)
  if (user.requiresPasswordUpdate && !user.isMaster && user.role !== 'admin') {
    showPasswordUpdateWarning.value = true
  }
  
  // Initialize loading states
  profileImageLoading.value = false
  sidebarImageLoading.value = false
  
  // SECURITY: If user claims to be admin, verify via API using the JWT token
  // This prevents localStorage tampering - the server validates the actual JWT
  if (user.role === 'admin' || user.isMaster) {
    const token = localStorage.getItem('authToken')
    if (!token) {
      console.error('No auth token found for admin user')
      currentUser.value.isMaster = false
      currentUser.value.role = 'student'
      localStorage.setItem('currentUser', JSON.stringify(currentUser.value))
      router.push('/')
      return
    }
    
    try {
      const verifyResponse = await fetch(buildAPIUrl(`/apis/admin/verify`), {
        method: 'POST',
        headers: getFetchHeaders({
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        })
      })
      
      if (!verifyResponse.ok) {
        console.error('Admin verification failed - token is not a valid admin token')
        currentUser.value.isMaster = false
        currentUser.value.role = 'student'
        localStorage.setItem('currentUser', JSON.stringify(currentUser.value))
        localStorage.removeItem('authToken')
        router.push('/')
        return
      }
      
      const verifyData = await verifyResponse.json()
      if (!verifyData.isAdmin) {
        console.error('Token verified but user is not admin')
        currentUser.value.isMaster = false
        currentUser.value.role = 'student'
        localStorage.setItem('currentUser', JSON.stringify(currentUser.value))
        router.push('/')
        return
      }
      
      currentUser.value.isMaster = true
      currentUser.value.isPrimaryAdmin = verifyData.isPrimaryAdmin
      // Trigger face ID enrollment check for co-admin / treasurer
      checkFaceIdEnrollment()
    } catch (error) {
      console.error('Failed to verify admin status:', error)
      currentUser.value.isMaster = false
      currentUser.value.role = 'student'
      localStorage.setItem('currentUser', JSON.stringify(currentUser.value))
      router.push('/')
      return
    }
    
    try {
      // Fetch only current page (10-20 students)
      const response = await fetch(buildAPIUrl(`/apis/students?page=${currentPageNum.value}&limit=${itemsPerPage.value}`), {
        method: 'GET',
        headers: getFetchHeaders({ 'Authorization': `Bearer SSAAMStudents` })
      })
      const result = await response.json()
      const pageData = result.data || result
      
      if (response.ok && Array.isArray(pageData)) {
        // Get pagination info
        if (result.pagination) {
          paginationTotal.value = result.pagination.total
          totalPages.value = result.pagination.totalPages
        }
        
        // Normalize data
        users.value = pageData.map(s => ({
          ...s,
          studentId: s.student_id,
          firstName: s.first_name,
          middleName: s.middle_name || '',
          lastName: s.last_name,
          yearLevel: s.year_level,
          rfidCode: s.rfid_code || 'N/A',
          schoolYear: s.school_year,
          image: s.photo || s.image || ''
        }))
      } else {
        console.error('API returned error or invalid data:', pageData)
        users.value = []
      }
    } catch (error) {
      console.error('Failed to fetch students:', error)
      users.value = []
    }
    
    // Fetch statistics and pending count separately
    fetchStats()
    fetchPendingStudents()
    if (currentUser.value?.isMaster) fetchAllCollegesStats()
  } else {
    // Student path — do not auto-fetch attendance here. Attendance data
    // will be fetched when the user opens the Attendance view.
    // If we're coming from the login screen, we might already be "authenticating"
    // but we don't want a double loading screen. However, if the user refreshes,
    // we might need a small state check here.
    users.value = JSON.parse(localStorage.getItem('users') || '[]')
  }
  
  
  // [AI WARNING] checkAndShowAnnouncementPopup() removed — component was never in the template.
  
  // Fetch attendance data for students to show notification banner (already fetched earlier in student path)
  
  // Start auto-refresh for attendance and event timers
  startAttendanceAutoRefresh()
  
  // Start auto-refresh for stats (admin only) - REMOVED: Stats should not auto-refresh
  // if (user.role === 'admin' || user.isMaster) {
  //   startStatsAutoRefresh()
  //   // Start sidebar logo flip animation for admin users
  //   startSidebarLogoFlipAnimation()
  // }
  
  // Start sidebar logo flip animation for admin users
  if (user.role === 'admin' || user.isMaster) {
    startSidebarLogoFlipAnimation()
  }
  
  // Fetch settings for all users to ensure academic info is accurate
  await fetchSettings()
  
  // Fetch student's payment records if not admin
  if (!user.isMaster && user.role !== 'admin') {
    await fetchMyPayments()
    // Load Face ID enrollment status (students only)
    loadFaceStatus()
  }
  
  // Listen for user deletions from Manage component
  window.addEventListener('user-deleted', handleUserDeleted)

  // Restore the last visited page (persisted across browser refreshes)
  const savedPage = sessionStorage.getItem('ssaam_current_page')
  if (savedPage && savedPage !== 'dashboard') {
    const isAdmin = currentUser.value.isMaster || currentUser.value.role === 'admin'
    // Only restore pages the current role can actually access
    const adminPages = ['manage', 'pending', 'attendance', 'contributions', 'settings', 'co-admins', 'raffle-tickets']
    const studentPages = ['attendance', 'my-contributions', 'my-raffle', 'request']
    const allowed = isAdmin ? adminPages : studentPages
    if (allowed.includes(savedPage)) {
      currentPage.value = savedPage
      // Trigger fetches for pages that aren't child-component-driven
      if (savedPage === 'attendance') fetchAttendanceData()
      else if (savedPage === 'manage') handleManageClick()
      else if (savedPage === 'co-admins') fetchCoAdmins()
      else if (savedPage === 'request') fetchStudentRequests()
    }
  }

  isPageLoading.value = false
})

