  }
}

const handleStudentPhotoUpload = async (event) => {
  const file = event.target.files[0];
  if (!file) return;
  studentPhotoUploading.value = true;
  const maxUploadRetries = 3;
  let uploadSuccess = false;
  try {
    // Compress the image first
    showNotification('Compressing image...', 'info')
    const compressedBase64 = await compressImage(file);
    
    for (let attempt = 1; attempt <= maxUploadRetries; attempt++) {
      try {
        const res = await fetch(buildAPIUrl('/apis/upload-image'), {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ image: compressedBase64 })
        });
        const data = await res.json();
        if (data.success) {
          const photoUrl = data.url;
          const studentId = currentUser.value.studentId || currentUser.value.student_id;
          const token = localStorage.getItem('authToken') || localStorage.getItem('studentToken');
          const updateResponse = await fetch(buildAPIUrl(`/apis/students/${studentId}/photo`), {
            method: 'PUT',
            headers: { 
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`
            },
            body: JSON.stringify({
              photo: photoUrl
            })
          });
          if (updateResponse.ok) {
            // Cache-bust so the <img> reloads immediately even if the URL is the same shape
            const bust = `${photoUrl.includes('?') ? '&' : '?'}v=${Date.now()}`
            const displayUrl = photoUrl + bust
            currentUser.value.image = displayUrl;
            currentUser.value.photo = displayUrl;
            const updatedUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
            updatedUser.image = displayUrl;
            updatedUser.photo = displayUrl;
            localStorage.setItem('currentUser', JSON.stringify(updatedUser));
            // Invalidate the persistent photo cache for this student so the new photo is picked up everywhere
            try {
              if (studentId) localStorage.removeItem(`photo_${studentId}`);
              // Also drop in-memory cache entries for this student
              if (studentPhotoCache && studentPhotoCache.value && studentId) {
                delete studentPhotoCache.value[studentId];
              }
            } catch (_) {}
            profileImageFailed.value = false;
            sidebarImageFailed.value = false;
            uploadSuccess = true;
            showNotification('Photo updated successfully!', 'success');
            break;
          } else {
            const errorData = await updateResponse.json().catch(() => ({}));
            console.error('Photo update failed:', errorData);
            if (attempt < maxUploadRetries) {
              await new Promise(resolve => setTimeout(resolve, 1000));
            }
          }
        } else {
          if (attempt < maxUploadRetries) {
            await new Promise(resolve => setTimeout(resolve, 1000));
          }
        }
      } catch (error) {
        console.error('Photo upload attempt error:', error);
        if (attempt < maxUploadRetries) {
          await new Promise(resolve => setTimeout(resolve, 1000));
        }
      }
    }
    if (!uploadSuccess) {
      showNotification('Failed to update photo. Please try again.', 'error');
    }
  } catch (error) {
    console.error('Photo processing error:', error);
    showNotification('Image processing error. Please try again.', 'error');
  }
  studentPhotoUploading.value = false;
};

const saveUserImpl = async () => {
  if (!editingUser.value) return
  
  // Co-admins are explicitly permitted to edit users (matches backend
  // requireCoAdminOrAbove on PUT /apis/students/:student_id).
  if (!currentUser.value.isMaster && currentUser.value.role !== 'admin' && currentUser.value.role !== 'co-admin') {
    showNotification('Only administrators can edit users', 'error')
    closeEditModal()
    return
  }
  
  // Use original student ID to find the record (in case ID is being changed)
  const originalStudentId = editingUser.value.originalStudentId || editingUser.value.studentId || editingUser.value.student_id
  const newStudentId = editingUser.value.studentId || editingUser.value.student_id
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  
  if (!token) {
    showNotification('Admin authentication required', 'error')
    closeEditModal()
    return
  }
  
  savingUser.value = true
  
  try {
    // Determine rfid_status based on unreadable checkbox
    let rfidStatus = editingUser.value.rfid_status || 'unverified'
    if (editingUser.value.rfidUnreadable) {
      rfidStatus = 'Unreadable'
    }
    
    const updateData = {
      student_id: newStudentId,
      first_name: (editingUser.value.firstName || editingUser.value.first_name || '').toUpperCase(),
      middle_name: (editingUser.value.middleName || editingUser.value.middle_name || '').toUpperCase(),
      last_name: (editingUser.value.lastName || editingUser.value.last_name || '').toUpperCase(),
      email: editingUser.value.email,
      rfid_code: editingUser.value.rfidCode || editingUser.value.rfid_code || 'N/A',
      rfid_status: rfidStatus,
      year_level: editingUser.value.yearLevel || editingUser.value.year_level,
      program: editingUser.value.program,
      photo: editingUser.value.image || editingUser.value.photo || '',
      _ssaam_access_token: encodeTimestamp()
    }
    
    const response = await fetch(buildAPIUrl(`/apis/students/${originalStudentId}`), {
      method: 'PUT',
      headers: getFetchHeaders({
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp(),
        'X-SSAAM-Original-Student-Id': originalStudentId
      }),
      body: JSON.stringify(updateData)
    })
    
    if (response.ok) {
      // Also update role if it was changed (role is updated via separate endpoint)
      const newRole = editingUser.value.role
      const originalUser = users.value.find(u => (u.studentId || u.student_id) === originalStudentId)
      const originalRole = originalUser?.role
      
      if (newRole && newRole !== originalRole) {
        try {
          const roleResponse = await fetch(buildAPIUrl(`/apis/students/${originalStudentId}/role`), {
            method: 'PUT',
            headers: getFetchHeaders({
              'Authorization': `Bearer ${token}`,
              'X-SSAAM-TS': encodeTimestamp(),
              'X-SSAAM-Original-Student-Id': originalStudentId
            }),
            body: JSON.stringify({ 
              role: newRole.toLowerCase(),
              _ssaam_access_token: encodeTimestamp()
            })
          })
          
          if (!roleResponse.ok) {
            const roleError = await roleResponse.json()
            showNotification(roleError.message || 'Failed to update role', 'error')
          }
        } catch (roleErr) {
          console.error('Error updating role:', roleErr)
        }
      }
      
      // Also update RFID if it was changed (this auto-verifies the user)
      const newRfid = editingUser.value.rfidCode || editingUser.value.rfid_code
      const originalRfid = originalUser?.rfidCode || originalUser?.rfid_code
      
      if (newRfid && newRfid !== 'N/A' && newRfid !== originalRfid) {
        try {
          const rfidResponse = await fetch(buildAPIUrl(`/apis/students/${originalStudentId}/rfid`), {
            method: 'PUT',
            headers: getFetchHeaders({
              'Authorization': `Bearer ${token}`,
              'X-SSAAM-TS': encodeTimestamp(),
              'X-SSAAM-Original-Student-Id': originalStudentId
            }),
            body: JSON.stringify({ 
              rfid_code: newRfid,
              admin_verification_token: 'admin_update',
              _ssaam_access_token: encodeTimestamp()
            })
          })
          
          if (rfidResponse.ok) {
            // Update local user data to show verified status
            editingUser.value.rfid_status = 'verified'
          }
        } catch (rfidErr) {
          console.error('Error updating RFID:', rfidErr)
        }
      }
      
      const index = users.value.findIndex(u => (u.studentId || u.student_id) === originalStudentId)
      if (index !== -1) {
        users.value[index] = { ...editingUser.value, ...updateData, studentId: newStudentId, role: newRole, rfid_status: editingUser.value.rfid_status }
      }
      showNotification('User updated successfully', 'success')
      refreshStudents()
    } else {
      if (response.status === 403) {
        const errorData = await response.json()
        showNotification(errorData.message || 'Failed', 'error')
      } else {
        const errorData = await response.json()
        showNotification(errorData.message || 'Failed to update user', 'error')
      }
    }
  } catch (error) {
    console.error('Error updating user:', error)
    showNotification('Error updating user', 'error')
  } finally {
    savingUser.value = false
  }
  
  closeEditModal()
}

const duplicateUserImpl = async () => {
  if (!editingUser.value) return

  // Co-admins are explicitly permitted to duplicate users.
  if (!currentUser.value.isMaster && currentUser.value.role !== 'admin' && currentUser.value.role !== 'co-admin') {
    showNotification('Only administrators can duplicate users', 'error')
    closeEditModal()
    return
  }

  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  if (!token) {
    showNotification('Admin authentication required', 'error')
    closeEditModal()
    return
  }

  savingUser.value = true

  try {
    let rfidStatus = editingUser.value.rfid_status || 'unverified'
    if (editingUser.value.rfidUnreadable) {
      rfidStatus = 'Unreadable'
    }

    const createData = {
      student_id: editingUser.value.studentId || editingUser.value.student_id,
      first_name: (editingUser.value.firstName || editingUser.value.first_name || '').toUpperCase(),
      middle_name: (editingUser.value.middleName || editingUser.value.middle_name || '').toUpperCase(),
      last_name: (editingUser.value.lastName || editingUser.value.last_name || '').toUpperCase(),
      email: editingUser.value.email,
      rfid_code: editingUser.value.rfidCode || editingUser.value.rfid_code || 'N/A',
      rfid_status: rfidStatus,
      year_level: editingUser.value.yearLevel || editingUser.value.year_level,
      program: editingUser.value.program,
      photo: editingUser.value.image || editingUser.value.photo || '',
      _ssaam_access_token: encodeTimestamp()
    }

    const response = await fetch(buildAPIUrl('/apis/students'), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      },
      body: JSON.stringify(createData)
    })

    if (response.ok) {
      showNotification('Duplicate record created successfully', 'success')
      await scanAllForDuplicates()
      await fetchAllUsers()
    } else {
      const data = await response.json()
      showNotification(data.message || 'Failed to create duplicate', 'error')
    }
  } catch (error) {
    console.error('Error creating duplicate:', error)
    showNotification('Error creating duplicate', 'error')
  } finally {
    savingUser.value = false
  }

  closeEditModal()
}

const duplicateUser = () => withAdminAction(duplicateUserImpl)()

