const confirmDeleteImpl = async () => {
  // Check if user is admin (co-admins are also permitted).
  if (!currentUser.value.isMaster && currentUser.value.role !== 'admin' && currentUser.value.role !== 'co-admin') {
    showNotification('Only administrators can delete users', 'error')
    showDeleteConfirm.value = false
    userToDelete.value = null
    return
  }
  
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  
  if (!token) {
    showNotification('Admin authentication required', 'error')
    showDeleteConfirm.value = false
    userToDelete.value = null
    return
  }
  
  if (userToDelete.value) {
    try {
    const response = await fetch(buildAPIUrl(`/apis/students/${userToDelete.value}`), {
        method: 'DELETE',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
          'X-SSAAM-TS': encodeTimestamp()
        }
      })
      
      if (response.ok) {
        users.value = users.value.filter(u => (u.studentId || u.student_id) !== userToDelete.value)
        // Emit event to sync deletion with other components
        window.dispatchEvent(new CustomEvent('user-deleted', { detail: { userId: userToDelete.value.studentId || userToDelete.value.student_id } }))
        showNotification('User deleted successfully', 'success')
        fetchStats()
      } else {
        if (response.status === 403) {
          const errorData = await response.json()
          showNotification(errorData.message || 'Failed', 'error')
        } else {
          const errorData = await response.json()
          showNotification(errorData.message || 'Failed to delete user', 'error')
        }
      }
    } catch (error) {
      console.error('Error deleting user:', error)
      showNotification('Error deleting user', 'error')
    }
  }
  showDeleteConfirm.value = false
  userToDelete.value = null
}

const confirmDelete = () => withAdminAction(confirmDeleteImpl)()


const attendanceFetching = ref(false)

const fetchAttendanceData = async () => {
  // Check cache first - only fetch if not already fetched
  if (isSectionCached('attendance') && !attendanceFetching.value) {
    // Data already fetched, skip initial fetch
    // But still update event timers
    nextTick(() => {
      updateEventTimeRemaining()
      checkAndNotifyEndedEvents()
    })
    return
  }

  if (attendanceFetching.value) return
  attendanceFetching.value = true
  attendanceLoading.value = true
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  const u = currentUser.value || {}
  const isAdmin = (u.role === 'admin' || u.isMaster || u.role === 'co-admin' || u.role === 'treasurer') && inRoleView.value
  
  try {
    if (!token) {
      console.error('No authentication token found')
      showSessionExpiredModal.value = true
      return
    }

    if (isAdmin) {
      console.log('Fetching admin attendance events...')
      const response = await fetch(buildAPIUrl('/apis/attendance/events'), {
        method: 'GET',
        headers: getFetchHeaders({ 'Authorization': `Bearer ${token}`, 'X-SSAAM-TS': encodeTimestamp() })
      })
      console.log('Admin attendance events response status:', response.status)
      if (response.status === 401) {
        showSessionExpiredModal.value = true
        return
      }
      if (response.ok) {
        const result = await response.json()
        console.log('Admin attendance events data:', result)
        console.log('Events breakdown - custom:', result.data?.filter(e => e.is_custom).length, '| regular:', result.data?.filter(e => !e.is_custom).length)
        console.log('Sample events:', result.data?.slice(0, 3).map(e => ({ title: e.title, is_custom: e.is_custom, status: e.status })))
        attendanceEvents.value = result.data || result || []
        console.log('Attendance events loaded:', attendanceEvents.value.length)
        
        // Mark section as cached
        markSectionAsCached('attendance')
      } else {
        const errorText = await response.text()
        console.error('Admin attendance events fetch error:', response.status, errorText)
        showNotification(`Failed to load attendance events: ${response.status}`, 'error')
      }
    } else {
      console.log('Fetching student attendance records on first click...')
      // Fetch all three sections on initial load
      await fetchActiveEvents()
      await fetchUpcomingEvents()
      await fetchMyRecords()
      
      // Mark section as cached
      markSectionAsCached('attendance')
    }
  } catch (error) {
    console.error('Failed to fetch attendance data:', error)
    showNotification('Failed to load attendance data', 'error')
  } finally {
    attendanceLoading.value = false
    attendanceFetching.value = false
    // After data is loaded, check for ended events and notify user (only for students, only once per event)
    nextTick(() => {
      updateEventTimeRemaining()
      checkAndNotifyEndedEvents()
    })
  }
}

