const createAttendanceEvent = async () => {
  if (creatingEventInProgress.value) return
  creatingEventInProgress.value = true
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  try {
    const eventPayload = {
      title: newEvent.value.title,
      description: newEvent.value.description || '',
      location: newEvent.value.location || '',
      event_date: newEvent.value.date,
      year_level: newEvent.value.year_level || '',
      start_time: newEvent.value.start_time || '07:00',
      end_time: newEvent.value.end_time || '17:00',
      is_custom: newEvent.value.is_custom || false,
      // Extract IDs from assigned_users (can be objects or IDs)
      assigned_users: (newEvent.value.assigned_users || []).map(u => typeof u === 'string' ? u : u._id || u.id),
      // GPS geofence settings
      geofence_enabled: !!newEvent.value.geofence_enabled,
      geofence_lat: newEvent.value.geofence_lat,
      geofence_lng: newEvent.value.geofence_lng,
      geofence_radius_meters: newEvent.value.geofence_radius_meters || 80,
      // Face ID Recognition toggle
      face_id_enabled: newEvent.value.face_id_enabled !== false
    }
    const response = await fetch(buildAPIUrl('/apis/attendance/events'), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      },
      body: JSON.stringify(eventPayload)
    })
    
    if (response.ok) {
      const result = await response.json()

      // Snapshot data we need before we reset the form below.
      const createdEventStartTime = newEvent.value.start_time || '07:00'
      const createdEventEndTime = newEvent.value.end_time || '17:00'
      const createdEventDate = newEvent.value.date
      const stagedSessions = newEventSessions.value.slice()
      const newEventId = result.event?._id

      // POST staged sessions in sequence so we can report a single summary.
      let createdCount = 0
      let failedCount = 0
      if (newEventId && stagedSessions.length > 0) {
        for (const session of stagedSessions) {
          try {
            const sessionResp = await fetch(buildAPIUrl(`/apis/attendance/events/${newEventId}/sessions`), {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}`, 'X-SSAAM-TS': encodeTimestamp() },
              body: JSON.stringify(session)
            })
            if (sessionResp.ok) createdCount++
            else failedCount++
          } catch (_) {
            failedCount++
          }
        }
      }

      if (stagedSessions.length === 0) {
        showNotification('Event created successfully. Now add sessions to enable check-in.', 'success')
      } else if (failedCount === 0) {
        showNotification(`Event created with ${createdCount} session${createdCount === 1 ? '' : 's'}.`, 'success')
      } else {
        showNotification(`Event created. ${createdCount} session(s) added, ${failedCount} failed.`, 'error')
      }

      // Reset the form & close the create modal.
      newEvent.value = { title: '', description: '', location: '', date: '', year_level: '', start_time: '07:00', end_time: '17:00', assigned_users: [], is_custom: false, geofence_enabled: false, geofence_lat: null, geofence_lng: null, geofence_radius_meters: 80, face_id_enabled: true }
      newEventSessions.value = []
      eventUserSearch.value = ''
      eventUserFilters.value = { name: '', program: '', yearLevel: '' }
      showCreateEventModal.value = false

      // Refresh the events list — use refreshAttendanceSection so the
      // cached flag is cleared first; fetchAttendanceData alone short-
      // circuits when the section is already cached, which is why the
      // newly-created event would otherwise not appear until the user
      // clicked the Refresh button manually.
      await refreshAttendanceSection()

      // Only open the edit modal automatically if the user didn't add any
      // sessions in the create flow. Otherwise just stay on the events list —
      // their setup is already complete.
      if (result.event && stagedSessions.length === 0) {
        selectedEvent.value = {
          ...result.event,
          date: createdEventDate,
          start_time: createdEventStartTime,
          end_time: createdEventEndTime,
          assigned_users: Array.isArray(result.event.assigned_users) ? result.event.assigned_users.map(u => typeof u === 'string' ? u : u._id) : []
        }
        eventSessions.value = []
        fetchEventSessions(result.event._id)
        showEditEventModal.value = true
      }
    } else {
      if (response.status === 403) {
        const errorData = await response.json()
        showNotification(errorData.message || 'Failed', 'error')
      } else {
        const errorData = await response.json()
        showNotification(errorData.message || 'Failed to create event', 'error')
      }
    }
  } catch (error) {
    console.error('Error creating event:', error)
    showNotification('Error creating event', 'error')
  } finally {
    creatingEventInProgress.value = false
  }
}

const updateAttendanceEvent = async () => {
  if (!selectedEvent.value) return
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  try {
    const eventDate = selectedEvent.value.date || selectedEvent.value.event_date
    const eventPayload = {
      title: selectedEvent.value.title,
      description: selectedEvent.value.description || '',
      location: selectedEvent.value.location || '',
      event_date: eventDate,
      year_level: selectedEvent.value.year_level || '',
      start_time: selectedEvent.value.start_time || selectedEvent.value.startTime || '07:00',
      end_time: selectedEvent.value.end_time || selectedEvent.value.endTime || '17:00',
      is_custom: selectedEvent.value.is_custom || false,
      // Extract IDs from assigned_users (can be objects or IDs)
      assigned_users: (selectedEvent.value.assigned_users || []).map(u => typeof u === 'string' ? u : u._id || u.id),
      // GPS geofence settings — sent as a partial update; backend merges with existing values.
      geofence_enabled: !!selectedEvent.value.geofence_enabled,
      geofence_lat: (selectedEvent.value.geofence_lat === '' || selectedEvent.value.geofence_lat === undefined) ? null : selectedEvent.value.geofence_lat,
      geofence_lng: (selectedEvent.value.geofence_lng === '' || selectedEvent.value.geofence_lng === undefined) ? null : selectedEvent.value.geofence_lng,
      geofence_radius_meters: selectedEvent.value.geofence_radius_meters || 80,
      // Face ID Recognition toggle
      face_id_enabled: selectedEvent.value.face_id_enabled !== false
    }
    
    console.log('[Frontend Update] Sending event payload:', {
      id: selectedEvent.value._id,
      is_custom: eventPayload.is_custom,
      assigned_users: eventPayload.assigned_users,
      assigned_users_count: (eventPayload.assigned_users || []).length
    })
    
    const response = await fetch(buildAPIUrl(`/apis/attendance/events/${selectedEvent.value._id}`), {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      },
      body: JSON.stringify(eventPayload)
    })
    
    if (response.ok) {
      const responseData = await response.json()
      console.log('[Frontend Update] Response received:', {
        is_custom: responseData.event?.is_custom,
        assigned_users: responseData.event?.assigned_users,
        assigned_users_count: (responseData.event?.assigned_users || []).length
      })
      showNotification('Event updated successfully', 'success')
      showEditEventModal.value = false
      // Clear the section cache before refetching so the edited values
      // (title, sessions, RFID flags, etc.) replace the stale cached copy.
      await refreshAttendanceSection()
    } else {
      if (response.status === 403) {
        const errorData = await response.json()
        showNotification(errorData.message || 'Failed', 'error')
      } else {
        const errorData = await response.json()
        showNotification(errorData.message || 'Failed to update event', 'error')
      }
    }
  } catch (error) {
    console.error('Error updating event:', error)
    showNotification('Error updating event', 'error')
  }
}

const requestDeleteEvent = (event) => {
