  }
}

const fetchEventSessions = async (eventId) => {
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  sessionsLoading.value = true
  try {
    const response = await fetch(buildAPIUrl(`/apis/attendance/events/${eventId}/sessions`), {
      headers: { 'Authorization': `Bearer ${token}`, 'X-SSAAM-TS': encodeTimestamp() }
    })
    if (response.ok) {
      const result = await response.json()
      console.log('Fetched sessions for event:', eventId, 'Response:', result)
      eventSessions.value = result.data || result.sessions || []
      console.log('eventSessions.value set to:', eventSessions.value)
        // Auto-select session logic: if multiple active sessions, ask user; if 1, select it
        if (!selectedSession.value && Array.isArray(eventSessions.value) && eventSessions.value.length > 0) {
          const activeSessions = eventSessions.value.filter(s => getSessionDisplayStatus(s, selectedEvent.value) === 'active')
          let pick = null
          
          if (activeSessions.length === 1) {
            // Only one active session - auto-select it
            pick = activeSessions[0]
          } else if (activeSessions.length > 1) {
            // Multiple active sessions - don't auto-select, let user choose
            pick = null
            // The UI will show the session selection buttons automatically
          } else if (eventSessions.value.length === 1) {
            // No active sessions, but only 1 session total - select it anyway
            pick = eventSessions.value[0]
          }
          
          if (pick) {
            selectedSession.value = pick
            selectedSessionForLogs.value = pick
            showNotification(`Auto-selected session: ${pick.label}`, 'info')
            // If session-level rfidScanner flags exist, set operation mode accordingly
            try {
              const srf = (pick.rfidScanner && typeof pick.rfidScanner === 'object') ? pick.rfidScanner : null
              if (srf) {
                if (srf.checkOutEnabled) setRfidOperation('out')
                else if (srf.checkInEnabled) setRfidOperation('in')
              }
            } catch (e) {
              console.warn('Failed to apply session rfidScanner operation', e)
            }
            // focus scanner input shortly
            setTimeout(() => {
              try {
                if (rfidInputRef && rfidInputRef.value) rfidInputRef.value.focus()
                if (rfidFullscreenInputRef && rfidFullscreenInputRef.value) rfidFullscreenInputRef.value.focus()
              } catch (e) {}
            }, 120)
          }
        }
    } else {
      console.error('Failed to fetch sessions, status:', response.status)
    }
  } catch (error) {
    console.error('Error fetching sessions:', error)
  } finally {
    sessionsLoading.value = false
  }
}

const toggleEventExpansion = async (eventId) => {
  if (expandedEvents.value[eventId]) {
    expandedEvents.value[eventId] = false
  } else {
    expandedEvents.value[eventId] = true
    if (!expandedEventSessions.value[eventId]) {
      const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
