    for (const log of logsWithCheckIn) {
      const checkInTime = log.check_in_at || log.check_in_time
      const checkInDate = new Date(checkInTime)
      const checkInHourMin = checkInDate.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' })
      
      // Determine if this check-in should be marked as late
      const shouldBeLate = checkInHourMin > thresholdTime
      
      // Only update if the late status needs to change
      if (log.is_late !== shouldBeLate) {
        try {
          const response = await fetch(buildAPIUrl(`/apis/attendance/logs/${log._id || log.id}`), {
            method: 'PATCH',
            headers: {
              'Authorization': `Bearer ${token}`,
              'Content-Type': 'application/json',
              'X-SSAAM-TS': encodeTimestamp()
            },
            body: JSON.stringify({ is_late: shouldBeLate })
          })
          
          if (response.ok) {
            updatedCount++
          } else {
            errorCount++
          }
        } catch (err) {
          console.error('Error updating log:', err)
          errorCount++
        }
      }
    }
    
    if (updatedCount > 0) {
      showNotification(`Updated ${updatedCount} attendance records based on late threshold`, 'success')
      // Refresh the logs to show updated stats
      await fetchSessionLogs(sessionId)
    } else if (errorCount === 0) {
      showNotification('No changes needed - all records already match the threshold', 'info')
    } else {
      showNotification(`Failed to update ${errorCount} records`, 'error')
    }
  } catch (error) {
    console.error('Error applying late threshold:', error)
    showNotification('Failed to apply late threshold', 'error')
  } finally {
    applyingLateThreshold.value = false
  }
}

const fetchSessionLogs = async (sessionId, loadMore = false) => {
  console.log('[fetchSessionLogs] START - sessionId:', sessionId, 'loadMore:', loadMore)
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  
  if (!loadMore) {
    attendanceLoading.value = true
    attendanceLogs.value = []
    allSessionLogs.value = []
    attendanceLogsPagination.value.page = 1
    console.log('[fetchSessionLogs] Reset loading=true, logs=[]')
  } else {
    loadingMoreLogs.value = true
  }

  try {
    // Build query params
    const params = new URLSearchParams()
    params.append('limit', '10000')
    params.append('page', attendanceLogsPagination.value.page.toString())
    if (eventLogsFilter.value?.yearLevel) params.append('yearLevel', eventLogsFilter.value.yearLevel)
    if (eventLogsFilter.value?.program) params.append('program', eventLogsFilter.value.program)
    if (eventLogsFilter.value?.search) params.append('search', eventLogsFilter.value.search)

    const url = buildAPIUrl(`/apis/attendance/sessions/${sessionId}/logs?${params.toString()}`)
    console.log('[fetchSessionLogs] Fetching URL:', url)

    // SINGLE FETCH - get the logs
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      }
    })

    console.log('[fetchSessionLogs] Response status:', response.status)
    if (!response.ok) {
      console.error('[fetchSessionLogs] Failed. Status:', response.status)
      return
    }

    const result = await response.json()
    console.log('[fetchSessionLogs] Got result:', result)
    const logs = result.data || []
    console.log('[fetchSessionLogs] Logs array:', logs, 'Length:', logs.length)
    
    // ASSIGN DATA TO VIEW
    if (loadMore) {
      attendanceLogs.value.push(...logs)
      console.log('[fetchSessionLogs] Pushed logs, now total:', attendanceLogs.value.length)
    } else {
      // Enrich logs with absent entries if event has ended
      let mergedLogs = logs
      try {
        const event = selectedEvent.value || attendanceEvents.value.find(e => e._id === (selectedEvent.value?._id))
        const eventEnded = event ? hasEventEndedPH(event) : false
        if (eventEnded) {
          try {
            const studentsResponse = await fetch(buildAPIUrl(`/apis/students?limit=10000`), {
              method: 'GET',
              headers: {
                'Authorization': 'Bearer SSAAMStudents',
                'X-SSAAM-TS': encodeTimestamp()
              }
            })

              if (studentsResponse.ok) {
                const studentsResult = await studentsResponse.json()
                const allStudents = studentsResult.students || studentsResult.data || []

                const attendedStudentIds = new Set(logs.map(log => log.student_id_number || log.student?.student_id || log.student_id))

                // Infer the event's target cohort from the actual logs
                // Extract the program and year_level from logs (they should all be consistent for one event)
                let targetProgram = ''
                let targetYearLevel = ''
                if (logs.length > 0) {
                  targetProgram = logs[0].program || logs[0].student?.program || ''
                  targetYearLevel = logs[0].year_level || logs[0].student?.year_level || ''
                }

                // If this is a custom event and assigned_users is present, restrict absent synthesis
                // to only students who were assigned to this event. assigned_users may contain ids
                // or objects with `_id` properties depending on how the event was created.
                let studentsPool = allStudents
                if (selectedEvent.value && selectedEvent.value.is_custom && Array.isArray(selectedEvent.value.assigned_users) && selectedEvent.value.assigned_users.length > 0) {
                  const assignedSet = new Set(selectedEvent.value.assigned_users.map(u => (typeof u === 'string' ? u : (u._id || u))))
                  studentsPool = allStudents.filter(s => assignedSet.has(s._id) || assignedSet.has(s.student_id))
                } else {
                  // For non-custom events, filter students pool ONLY by the cohort inferred from logs
                  // This ensures we only synthesize absent for the actual target program/year
                  if (targetProgram) {
                    studentsPool = studentsPool.filter(s => s.program === targetProgram)
                  }
                  if (targetYearLevel) {
                    studentsPool = studentsPool.filter(s => s.year_level === targetYearLevel)
                  }
                }

                let absentStudents = studentsPool.filter(student => {
                  if (attendedStudentIds.has(student.student_id)) return false
                  // Apply UI search filter if present (doesn't restrict event pool, just display)
                  if (eventLogsFilter.value.search) {
                    const searchLower = eventLogsFilter.value.search.toLowerCase()
                    const nameMatch = (student.full_name || '').toLowerCase().includes(searchLower)
                    const idMatch = (student.student_id || '').toLowerCase().includes(searchLower)
                    if (!nameMatch && !idMatch) return false
                  }
                  return true
                })

                const absentLogs = absentStudents.map(student => ({
                  id: `absent_${student.student_id}`,
                  student_id: student._id,
                  student_id_number: student.student_id,
                  student_name: student.full_name,
                  student_image: student.photo,
                  program: student.program,
                  year_level: student.year_level,
                  check_in_at: null,
                  check_in_time: null,
                  check_out_at: null,
                  check_out_time: null,
                  is_late: false,
                  is_absent: true,
                  event_status: 'absent',
                  student: student
                }))

                // Merge and then enrich all logs with available student photos from allStudents
                mergedLogs = [...logs, ...absentLogs]

                const studentsMap = {}
                studentsPool.forEach(s => { if (s.student_id) studentsMap[s.student_id] = s })

                mergedLogs = mergedLogs.map(l => {
                  const sid = l.student_id_number || l.student?.student_id || l.student_id
                  // prefer existing student_image or nested student.photo
                  if (!l.student_image) {
                    if (l.student && (l.student.photo || l.student.image)) l.student_image = l.student.photo || l.student.image
                    else if (sid && studentsMap[sid]) l.student_image = studentsMap[sid].photo || studentsMap[sid].image || ''
                  }
                  // ensure student object exists for uniform access
                  if (!l.student && sid && studentsMap[sid]) l.student = studentsMap[sid]
                  return l
                })
                // cache a copy for exports and other operations
                allSessionLogs.value = mergedLogs
              }
          } catch (studentsError) {
            console.error('[fetchSessionLogs] Error fetching students for absent list:', studentsError)
          }
        }
      } catch (e) {
        console.error('[fetchSessionLogs] error determining eventEnded', e)
      }

      // Cache logs for exports and other global operations
      allSessionLogs.value = mergedLogs
      attendanceLogs.value = mergedLogs
      console.log('[fetchSessionLogs] Assigned logs to attendanceLogs (and allSessionLogs):', mergedLogs.length, 'items')

      // Calculate stats from merged logs
      let present = 0, incomplete = 0, late = 0, absent = 0
      mergedLogs.forEach(log => {
        const hasCheckIn = log.check_in_at || log.check_in_time
        const hasCheckOut = log.check_out_at || log.check_out_time
        if (hasCheckIn && hasCheckOut) {
          if (log.is_late) late++
          else present++
        } else if (hasCheckIn && !hasCheckOut) {
          incomplete++
        } else {
          absent++
        }
      })

      // The "total" shown should be total attended (present + incomplete + late)
      const totalAttended = present + incomplete + late

      // Fetch total assigned students based on whether event is custom
      let totalStudents = mergedLogs.length
      if (selectedEvent.value) {
        try {
          if (selectedEvent.value.is_custom) {
            const eventStatsResponse = await fetch(buildAPIUrl(`/apis/events/${selectedEvent.value._id}/stats`), {
              method: 'GET',
              headers: {
                'Authorization': `Bearer ${getSessionToken()}`,
                'X-SSAAM-TS': encodeTimestamp()
              }
            })
            if (eventStatsResponse.ok) {
              const eventStatsData = await eventStatsResponse.json()
              totalStudents = eventStatsData.totalAssignedStudents || mergedLogs.length
            }
          } else {
            const studentStatsResponse = await fetch(buildAPIUrl('/apis/students/stats'), {
              method: 'GET',
              headers: getFetchHeaders({ 'Authorization': 'Bearer SSAAMStudents', 'X-SSAAM-TS': encodeTimestamp() })
            })
            if (studentStatsResponse.ok) {
              const studentStatsData = await studentStatsResponse.json()
              totalStudents = studentStatsData.totalStudents || mergedLogs.length
            }
          }
        } catch (err) {
          console.log('[fetchSessionLogs] Could not fetch total students:', err.message)
        }
      }

      sessionStats.value = { present, incomplete, late, absent, total: totalAttended, totalStudents: totalStudents }
      console.log('[fetchSessionLogs] Stats calculated:', sessionStats.value)
    }

    console.log('[fetchSessionLogs] SUCCESS! Loaded', logs.length, 'logs. Total in view:', attendanceLogs.value.length)
  } catch (error) {
    console.error('[fetchSessionLogs] EXCEPTION:', error)
  } finally {
    // ALWAYS execute: stop loading
    console.log('[fetchSessionLogs] Finally block - setting loading=false')
    attendanceLoading.value = false
    loadingMoreLogs.value = false
    console.log('[fetchSessionLogs] COMPLETE - loading is now:', attendanceLoading.value)
  }
}

const loadMoreSessionLogs = () => {
  if (!loadingMoreLogs.value && attendanceLogsPagination.value.hasMore && selectedSessionForLogs.value) {
    attendanceLogsPagination.value.page++
    fetchSessionLogs(selectedSessionForLogs.value._id, true)
  }
}

const fetchEventLogs = async (eventId) => {
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  attendanceLoading.value = true
  try {
    const params = new URLSearchParams()
    params.append('limit', '10000')
    if (eventLogsFilter.value.yearLevel) params.append('yearLevel', eventLogsFilter.value.yearLevel)
    if (eventLogsFilter.value.program) params.append('program', eventLogsFilter.value.program)
    if (eventLogsFilter.value.search) params.append('search', eventLogsFilter.value.search)
    
    const response = await fetch(buildAPIUrl(`/apis/attendance/events/${eventId}/logs?${params.toString()}`), {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      }
    })
    
    if (response.ok) {
      const result = await response.json()
      // Enrich logs with cached photos (check localStorage first, then memory cache)
      let logs = (result.data || []).map(log => {
        const key = deriveStudentKey(log)
        // Priority: localStorage (persistent) → memory cache → API response
        let cachedPhoto = null
        const studentId = log.student_id || log.student?.student_id
        if (studentId) {
          cachedPhoto = getPhotoFromStorage(studentId) || (key ? studentPhotoCache.value[key] : null)
        } else {
          cachedPhoto = key ? studentPhotoCache.value[key] : null
        }
        const existingPhoto = log.student_image || log.student?.photo
        
        // Backfill cache if log has a photo we haven't cached yet
        if (existingPhoto && !cachedPhoto) {
          cacheStudentPhoto(log, existingPhoto)
        }
        
        return {
          ...log,
          student_image: log.student_image || cachedPhoto || log.student?.photo
        }
      })
      
      // Asynchronously fetch missing photos from public endpoint
      // Batch and limit concurrency to avoid flooding the API when many logs lack photos
      const missingStudentIds = []
      const missingMap = {} // studentId -> array of logs
      logs.forEach(log => {
        const studentId = log.student_id || log.student?.student_id
        if (!studentId || log.student_image || recentlyScannedStudents.value.has(studentId)) return

        // Check caches first (localStorage and memory)
        const cached = getPhotoFromStorage(studentId) || (studentPhotoCache.value ? studentPhotoCache.value[studentId] : null)
        if (cached) {
          log.student_image = cached
          return
        }

        // Skip if we recently determined this student has no photo
        if (noPhotoCache[studentId] && noPhotoCache[studentId] > Date.now()) return

        if (!missingMap[studentId]) {
          missingMap[studentId] = []
          missingStudentIds.push(studentId)
        }
        missingMap[studentId].push(log)
      })

      // Photo fetching disabled - use fallback images from cache or defaults
      // If missing photos in attendanceLogs, they will display fallback images
      
      // Check if event has ended - if so, fetch students matching event's target audience and add absent entries
      const event = selectedEvent.value || attendanceEvents.value.find(e => e._id === eventId)
      const eventEnded = event ? hasEventEndedPH(event) : false
      
      if (eventEnded) {
        try {
          // Fetch approved students
          const studentsResponse = await fetch(buildAPIUrl(`/apis/students?limit=10000`), {
            method: 'GET',
            headers: {
              'Authorization': 'Bearer SSAAMStudents',
              'X-SSAAM-TS': encodeTimestamp()
            }
          })
          
          if (studentsResponse.ok) {
            const studentsResult = await studentsResponse.json()
            const allStudents = studentsResult.students || studentsResult.data || []
            
            // Get set of student ID numbers who have attendance logs
            // Use student_id_number (string like "25-A-00546") not student_id (MongoDB ObjectId)
            const attendedStudentIds = new Set(logs.map(log => log.student_id_number || log.student?.student_id))
            
            // Check if event targets a specific year level
            const eventYearLevel = event?.year_level || ''
            const validYearLevels = ['1st Year', '2nd Year', '3rd Year', '4th Year']
            const hasSpecificYearLevel = validYearLevels.includes(eventYearLevel)
            
            // Filter students based on event's target audience
            let absentStudents = allStudents.filter(student => {
              // Skip students who already have attendance logs
              if (attendedStudentIds.has(student.student_id)) return false
              
              // If event targets a specific year level, only include those students
              if (hasSpecificYearLevel && student.year_level !== eventYearLevel) return false
              
              // Apply UI year level filter if set
              if (eventLogsFilter.value.yearLevel && student.year_level !== eventLogsFilter.value.yearLevel) return false
              
              // Apply program filter if set
              if (eventLogsFilter.value.program && student.program !== eventLogsFilter.value.program) return false
              
              // Apply search filter if set
              if (eventLogsFilter.value.search) {
                const searchLower = eventLogsFilter.value.search.toLowerCase()
                const nameMatch = (student.full_name || '').toLowerCase().includes(searchLower)
                const idMatch = (student.student_id || '').toLowerCase().includes(searchLower)
                if (!nameMatch && !idMatch) return false
              }
              
              return true
            })
            
            // Create absent log entries for students without attendance
            const absentLogs = absentStudents.map(student => ({
              id: `absent_${student.student_id}`,
              student_id: student._id,
              student_id_number: student.student_id,
              student_name: student.full_name,
              student_image: student.photo,
              program: student.program,
              year_level: student.year_level,
              check_in_at: null,
              check_in_time: null,
              check_out_at: null,
              check_out_time: null,
              is_late: false,
              is_absent: true,
              event_status: 'absent',
              student: student
            }))
            
            // Combine attendance logs with absent entries
            logs = [...logs, ...absentLogs]
          }
        } catch (studentsError) {
          console.error('Error fetching students for absent list:', studentsError)
        }
      }
      
      attendanceLogs.value = logs
    }
  } catch (error) {
    console.error('Error fetching event logs:', error)
  } finally {
    attendanceLoading.value = false
  }
}

// Export event attendance to Excel organized by year level
const exportEventAttendanceToExcel = async (event) => {
  exportingExcel.value = true
  try {
    const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
    
    // Fetch all logs for this event
    const response = await fetch(buildAPIUrl(`/apis/attendance/events/${event._id}/logs?limit=1000`), {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      }
    })
    
    if (!response.ok) {
      showNotification('Failed to fetch attendance data for export', 'error')
      return
    }
    
    const result = await response.json()
    const logs = result.data || []
    
    if (logs.length === 0) {
      showNotification('No attendance records to export', 'warning')
      return
    }
    
    // Create workbook
    const workbook = XLSX.utils.book_new()
    
    const eventDateFormatted = formatEventDate(event.date || event.event_date)
    const eventLocation = event.location || ''
    const uniqueSessions = [...new Set(logs.map(log => log.session_label || log.session?.label || 'Session').filter(Boolean))]
    const sessionsLabel = selectedSessionForLogs.value?.label || (uniqueSessions.length > 0 ? uniqueSessions.join(', ') : 'All Sessions')
    
    // Year level order for organization
    const yearLevels = ['1st Year', '2nd Year', '3rd Year', '4th Year']
    
    // Process data by year level
    yearLevels.forEach(yearLevel => {
      const yearLogs = logs.filter(log => {
        const studentYearLevel = log.student?.year_level || log.year_level || ''
        return studentYearLevel === yearLevel
      })
      
      if (yearLogs.length === 0) return
      
      // Sort by name alphabetically
      yearLogs.sort((a, b) => {
        const nameA = (a.student?.full_name || a.full_name || `${a.student?.first_name || ''} ${a.student?.last_name || ''}`).toLowerCase()
        const nameB = (b.student?.full_name || b.full_name || `${b.student?.first_name || ''} ${b.student?.last_name || ''}`).toLowerCase()
        return nameA.localeCompare(nameB)
      })
      
      // Create header rows with event information
      const headerRows = [
        { 'Event': event.title || 'Attendance Event' },
        { 'Event': `Date: ${eventDateFormatted}` },
        { 'Event': `Session: ${sessionsLabel}` },
        ...(eventLocation ? [{ 'Event': `Location: ${eventLocation}` }] : []),
        { 'Event': `Year Level: ${yearLevel}` },
        { 'Event': '' }
      ]
      
      // Prepare data for worksheet without session column (session is in header)
      const worksheetData = yearLogs.map((log, index) => {
        const checkIn = log.check_in_at || log.check_in_time
        const checkOut = log.check_out_at || log.check_out_time
        
        const studentName = log.student?.full_name || log.full_name || `${log.student?.first_name || ''} ${log.student?.last_name || ''}`.trim()
        const studentId = log.student_id_number || log.student?.student_id || log.student_id || ''
        const program = log.student?.program || log.program || ''
        
        let status = 'Absent'
        if (checkIn && checkOut) status = 'Present'
        else if (checkIn && !checkOut) status = 'Incomplete'
        
        return {
          '#': index + 1,
          'Student ID': studentId,
          'Name': studentName,
          'Program': program,
          'Year Level': yearLevel,
          'Check-In': checkIn ? new Date(checkIn).toLocaleString('en-PH') : '-',
          'Check-Out': checkOut ? new Date(checkOut).toLocaleString('en-PH') : '-',
          'Status': status
        }
      })
      
      // Create worksheet with headers first
      const headerSheet = XLSX.utils.json_to_sheet(headerRows)
      const dataStartRow = headerRows.length + 1
      XLSX.utils.sheet_add_json(headerSheet, worksheetData, { origin: `A${dataStartRow}` })
      
      const columnWidths = [
        { wch: 5 },   // #
        { wch: 15 },  // Student ID
        { wch: 30 },  // Name
        { wch: 10 },  // Program
        { wch: 12 },  // Year Level
        { wch: 20 },  // Check-In
        { wch: 20 },  // Check-Out
        { wch: 12 }   // Status
      ]
      headerSheet['!cols'] = columnWidths
      
      // Apply print formatting
      applyPrintFormatting(headerSheet, headerRows.length)
      
      // Add worksheet to workbook with year level as sheet name
      XLSX.utils.book_append_sheet(workbook, headerSheet, yearLevel.replace(' ', '_'))
    })
    
    // Create summary sheet
    const summaryData = yearLevels.map(yearLevel => {
      const yearLogs = logs.filter(log => {
        const studentYearLevel = log.student?.year_level || log.year_level || ''
        return studentYearLevel === yearLevel
      })
      
      const presentCount = yearLogs.filter(log => (log.check_in_at || log.check_in_time) && (log.check_out_at || log.check_out_time)).length
      const incompleteCount = yearLogs.filter(log => (log.check_in_at || log.check_in_time) && !(log.check_out_at || log.check_out_time)).length
      
      return {
        'Year Level': yearLevel,
        'Total Attendees': yearLogs.length,
        'Present (Complete)': presentCount,
        'Incomplete': incompleteCount
      }
    })
    
    // Add event header to summary sheet
    const summaryHeaderRows = [
      { 'Year Level': event.title || 'Attendance Event' },
      { 'Year Level': `Date: ${eventDateFormatted}` },
      { 'Year Level': `Session: ${sessionsLabel}` },
      ...(eventLocation ? [{ 'Year Level': `Location: ${eventLocation}` }] : []),
      { 'Year Level': '' },
      { 'Year Level': 'ATTENDANCE SUMMARY' },
      { 'Year Level': '' }
    ]
    
    const summaryHeaderSheet = XLSX.utils.json_to_sheet(summaryHeaderRows)
    const summaryDataStartRow = summaryHeaderRows.length + 1
    XLSX.utils.sheet_add_json(summaryHeaderSheet, summaryData, { origin: `A${summaryDataStartRow}` })
    summaryHeaderSheet['!cols'] = [{ wch: 15 }, { wch: 15 }, { wch: 18 }, { wch: 15 }, { wch: 12 }]
    
    // Apply print formatting
    applyPrintFormatting(summaryHeaderSheet, summaryHeaderRows.length)
    
    XLSX.utils.book_append_sheet(workbook, summaryHeaderSheet, 'Summary')
    
    // Generate filename with event title and date
    const eventDate = formatEventDate(event.date || event.event_date).replace(/[^a-zA-Z0-9]/g, '_')
    const eventTitle = (event.title || 'Event').replace(/[^a-zA-Z0-9]/g, '_').substring(0, 20)
    const filename = `Attendance_${eventTitle}_${eventDate}.xlsx`
    
    // Download the file
    XLSX.writeFile(workbook, filename)
    
    showNotification('Excel file exported successfully!', 'success')
  } catch (error) {
    console.error('Error exporting to Excel:', error)
    showNotification('Failed to export Excel file', 'error')
  } finally {
    exportingExcel.value = false
  }
}

const handleRfidKeydown = (event) => {
  const now = Date.now()
  const timeDiff = now - rfidLastKeyTime.value
  const SCANNER_THRESHOLD = 30
  
  if (timeDiff < SCANNER_THRESHOLD || rfidLastKeyTime.value === 0) {
    if (event.key !== 'Enter') {
      if (event.key && event.key.length === 1) {
        rfidInputBuffer.value += event.key.toUpperCase()
      } else {
        // ignore non-character keys
      }
    }
  } else {
    rfidInputBuffer.value = event.key === 'Enter' ? '' : (event.key && event.key.length === 1 ? event.key.toUpperCase() : '')
  }
  rfidLastKeyTime.value = now
  
  if (event.key === 'Enter' && rfidInputBuffer.value.length > 5) {
    event.preventDefault()
    processRfidScan(rfidInputBuffer.value)
    rfidInputBuffer.value = ''
    rfidInput.value = ''
  }
}

const switchToScannerTab = () => {
  rfidScannerVerified.value = true
  attendanceTab.value = 'scanner'
}

const launchFullscreenScanner = () => {
  if (!selectedEvent.value) {
    showNotification('Please select an event from the list before scanning.', 'error')
    return
  }
  
  if (rfidScannerVerified.value) {
    rfidScannerVerified.value = true
    rfidFullscreenMode.value = true
    nextTick(() => {
      if (rfidFullscreenInputRef.value) {
        rfidFullscreenInputRef.value.focus()
      }
    })
  }
}

const manualRfidSubmit = async () => {
  if (!rfidInput.value.trim() || rfidProcessing.value) return
  
  const input = rfidInput.value.trim()
  rfidInput.value = ''
  
  // Check if input contains multiple space-separated IDs
  const ids = input.split(/\s+/).filter(id => id.length > 0)
  
  if (ids.length > 1) {
    // Multiple IDs - add to queue and process
    bulkRfidQueue.value.push(...ids)
    showNotification(`Queued ${ids.length} ID(s) for processing...`, 'info')
    
    // Start processing the queue
    await processBulkRfidQueue()
  } else if (ids.length === 1) {
    // Single ID - process normally
    await processRfidScan(ids[0])
  }
}

const processBulkRfidQueue = async () => {
  while (bulkRfidQueue.value.length > 0) {
    const code = bulkRfidQueue.value.shift()
    await processRfidScan(code)
    // Add small delay between each scan to allow UI updates
    await new Promise(resolve => setTimeout(resolve, 500))
  }
}

// Fetch and cache student photo from public endpoint (disabled - use fallback images)
const fetchAndCacheStudentPhoto = async (studentId, fullName) => {
  // Photo fetching is disabled - fallback images will be used
  return null
}

const processRfidScan = async (inputCode) => {
  // If device is offline, queue the scan for later
  if (!navigator.onLine) {
    const normalized = (inputCode || '').toUpperCase().trim()
    if (normalized && !rfidOfflineQueue.value.includes(normalized)) {
      rfidOfflineQueue.value.push(normalized)
      showNotification(`Offline — scan queued (${rfidOfflineQueue.value.length} pending)`, 'warning')
    }
    return
  }

  // Check if user is still authenticated before processing scan
  const token = localStorage.getItem('authToken') || localStorage.getItem('adminToken')
  const currentUserData = localStorage.getItem('currentUser')
  
  if (!token || !currentUserData) {
    rfidResult.value = null
    rfidFullscreenMode.value = false
    rfidProcessing.value = false
    showNotification('Session expired. Please log in again.', 'error')
    router.push('/')
    return
  }
  
  if (!selectedSession.value || rfidProcessing.value) return
  
  rfidProcessing.value = true
  rfidResult.value = null
  
  // If there are queued items and this is the first one, show queue info
  if (bulkRfidQueue.value.length > 0) {
    showNotification(`Processing... (${bulkRfidQueue.value.length} remaining in queue)`, 'info')
  }
  
  try {
    // Normalize input and auto-detect student ID pattern
    const normalized = (inputCode || '').toUpperCase().trim()
    const isStudentId = studentIdPattern.test(normalized)

    // Backend expects concrete enum values for `source` and `identifier_type`.
    // Use 'manual' for student ID entries, 'rfid' for card scans.
    const requestBody = {
      rfid_code: normalized,
      student_id: normalized,
      identifier_type: isStudentId ? 'student_id' : 'rfid',
      source: isStudentId ? 'manual' : 'rfid',
      operation_type: rfidOperationType.value,
      force_mode: true
    }

    // === GEOFENCE: re-use the location captured during the one-time
    //              "Verify location" gate the admin completed when they
    //              opened the scanner. We deliberately DO NOT call
    //              getCurrentPosition here per-scan anymore — that was
    //              causing a GPS prompt / spinner on every single card
    //              tap. The backend still re-validates the coords.
    if (selectedEvent.value?.geofence_enabled) {
      const verified = scannerLocationVerified.value
      if (!verified || !Number.isFinite(verified.lat) || !Number.isFinite(verified.lng)) {
        rfidProcessing.value = false
        showNotification('Verify your location first to start scanning for this event.', 'error')
        // Re-open the gate so the admin can recover without hunting for the button.
        scannerLocationGateOpen.value = true
        return
      }
      requestBody.latitude = verified.lat
      requestBody.longitude = verified.lng
      requestBody.accuracy = verified.accuracy
    }

    const response = await fetch(buildAPIUrl(`/apis/attendance/sessions/${selectedSession.value._id}/check`), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      },
      body: JSON.stringify(requestBody)
    })
    
    const result = await response.json()
    if (response.ok && result.success !== false) {
      rfidResult.value = { success: true, ...result }

      // Ensure rfidResult includes a `student_image` so the UI avatar shows immediately.
      const studentPhoto = result.student_photo || result.student?.photo || null
      const studentId = result.student?.student_id || result.student_id || null
      if (studentPhoto) {
        rfidResult.value.student_image = studentPhoto
        cacheStudentPhoto(result.log, studentPhoto)
        cacheStudentPhoto(result.student, studentPhoto)
      } else {
        // try memory cache / localStorage as fallback
        try {
          const key = typeof deriveStudentKey === 'function' ? deriveStudentKey(result) : null
          const cached = (studentId ? getPhotoFromStorage(studentId) : null) || (key ? studentPhotoCache.value[key] : null)
          if (cached) rfidResult.value.student_image = cached
        } catch (e) {
          // silent
        }
      }

      const actionLabel = result.action === 'check_in' ? 'Check-in' : result.action === 'check_out' ? 'Check-out' : result.action === 'already_checked_in' ? 'Already checked in' : 'Success'
      showNotification(`${actionLabel}: ${result.student?.full_name || result.student_name || 'Student'}`, 'success')

      // Mark student as recently scanned to avoid re-fetching photo in fetchEventLogs
      if (studentId) {
        recentlyScannedStudents.value.add(studentId)
        // Remove from set after 10 seconds to avoid permanent blocking
        setTimeout(() => {
          recentlyScannedStudents.value.delete(studentId)
        }, 10000)
      }

      fetchEventLogs(selectedEvent.value._id)
    } else {
      // Classify responses:
      // - already completed/double-scan -> yellow warning
      // - user/student not found / not registered -> red error
      // - other failures -> yellow warning
      const msg = (result && result.message) || ''
      const alreadyCompleted = /already/i.test(msg) || result.action === 'already_checked_in'
      // Broaden user-not-found detection to match variations like:
      // "No verified student found with this RFID code", "student not found", "not registered", etc.
      const userNotFound = /(?:no\s+.*found|student\s+not\s+found|not\s+found|not\s+registered|user\s+not\s+found|not\s+verified|unknown)/i.test(msg) || ['user_not_found', 'not_registered'].includes(result.action)
      // Detect assignment-related messages and treat them as errors (red)
      const notAssigned = /not\s+assigned|only\s+assigned\s+students|not\s+assigned\s+to\s+this/i.test(msg)
      // VPN / proxy blocked by geofence security check
      const vpnBlocked = result.code === 'GEOFENCE_VPN_DETECTED'

      if (alreadyCompleted) {
        rfidResult.value = { success: false, warning: true, action: result.action || 'already_checked_in', ...result }
        showNotification(result.message || 'Student already completed session', 'warning')
      } else if (vpnBlocked) {
        rfidResult.value = { success: false, error: true, message: result.message }
        showNotification('VPN detected — disable your VPN to check in', 'error')
      } else if (userNotFound || notAssigned) {
        rfidResult.value = { success: false, error: true, message: result.message }
        showNotification(result.message || 'User not found', 'error')
      } else {
        rfidResult.value = { success: false, warning: true, message: result.message }
        showNotification(result.message || 'Warning: check input or try again', 'warning')
      }
    }
  } catch (error) {
    console.error('Attendance scan error:', error)
    rfidResult.value = { success: false, error: true, message: 'Error processing identifier' }
    showNotification('Error processing identifier', 'error')
  } finally {
    rfidProcessing.value = false
    setTimeout(() => { rfidResult.value = null }, 3000)
    // Keep input focused for continuous scanning - use correct ref based on mode
    setTimeout(() => {
      const inputRef = rfidFullscreenMode.value ? rfidFullscreenInputRef.value : rfidInputRef.value
      if (inputRef) {
        inputRef.focus()
      }
    }, 100)
  }
}

const flushOfflineRfidQueue = async () => {
  if (!navigator.onLine || rfidOfflineQueue.value.length === 0) return
  const queue = [...rfidOfflineQueue.value]
  rfidOfflineQueue.value = []
  showNotification(`Back online — processing ${queue.length} queued scan${queue.length > 1 ? 's' : ''}`, 'info')
  for (const code of queue) {
    await processRfidScan(code)
    await new Promise(r => setTimeout(r, 400))
  }
}

const openSessionLogs = (session, event) => {
  selectedEvent.value = event
  selectedSessionForLogs.value = session
  selectedLateThresholdMinutes.value = session.late_timer_minutes || 60
  showEventLogsModal.value = true
  sessionLogsDisplayLimit.value = 20
  fetchSessionLogs(session._id)
}

const selectSession = (session, event, ev) => {
  try {
    if (ev && ev.stopPropagation) ev.stopPropagation()
  } catch (e) {
    // ignore
  }
  // Set the selected event and session for scanner
  selectedEvent.value = event
  selectedSession.value = session
  // Also ensure session-for-logs is set for detail views
  selectedSessionForLogs.value = session
  // If session contains rfidScanner settings, apply them (check-in / check-out)
  try {
    const srf = (session && session.rfidScanner && typeof session.rfidScanner === 'object') ? session.rfidScanner : null
    if (srf) {
      if (srf.checkOutEnabled) setRfidOperation('out')
      else if (srf.checkInEnabled) setRfidOperation('in')
    }
    // prefer RFID scanning when selecting a session
    scanMode.value = 'rfid'
  } catch (ex) {
    console.warn('Failed to apply session-level RFID operation in selectSession', ex)
  }
  console.log('[UI] selectSession invoked', session._id, 'for event', event?._id)
  // brief UI notification so selection is obvious
  showNotification(`Selected session: ${session.label}`, 'info')
  // Focus the RFID input for quick scanning
  setTimeout(() => {
    try {
      if (rfidInputRef && rfidInputRef.value) rfidInputRef.value.focus()
      if (rfidFullscreenInputRef && rfidFullscreenInputRef.value) rfidFullscreenInputRef.value.focus()
    } catch (e) {
      // ignore
    }
  }, 80)
}

const openEditEvent = (event) => {
  // Fetch all registered students before opening edit modal
  const fetchStudentsForEdit = async () => {
    loadingStudentsForEvent.value = true
    loadedStudentCount.value = 0
    totalStudentCount.value = 0
    try {
      const response = await fetch(buildAPIUrl('/apis/students/list/all'), {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('authToken') || localStorage.getItem('adminToken')}`
        }
      })
      
      if (response.ok) {
        const result = await response.json()
        const allStudents = result.data || result
        totalStudentCount.value = allStudents.length
        
        if (Array.isArray(allStudents)) {
          // Load students progressively in batches of 50
          users.value = []
          const batchSize = 50
          
          for (let i = 0; i < allStudents.length; i += batchSize) {
            const batch = allStudents.slice(i, i + batchSize)
            const mappedBatch = batch.map(s => ({
              ...s,
              studentId: s.student_id,
              firstName: s.first_name,
              middleName: s.middle_name || '',
              lastName: s.last_name,
              yearLevel: s.year_level,
              rfidCode: s.rfid_code || 'N/A',
              image: s.photo || s.image || ''
            }))
            users.value.push(...mappedBatch)
            loadedStudentCount.value += mappedBatch.length
            // Allow UI to update between batches
            await new Promise(resolve => setTimeout(resolve, 10))
          }
          // Also populate allEventUsers with the mapped students
          allEventUsers.value = users.value
          
          // Now that students are loaded, enrich and set the event
          const enrichedAssignedUsers = enrichAssignedUsersWithNames(event.assigned_users)
          
          selectedEvent.value = { 
            ...event,
            date: event.event_date ? new Date(event.event_date).toISOString().split('T')[0] : event.date,
            start_time: event.start_time || event.startTime || '07:00',
            end_time: event.end_time || event.endTime || '17:00',
            assigned_users: enrichedAssignedUsers,
            is_custom: event.is_custom || false
          }
        }
      }
    } catch (error) {
      console.error('Error fetching students for edit:', error)
      showNotification('Failed to load student list', 'error')
    } finally {
      loadingStudentsForEvent.value = false
    }
  }
  
  // Fetch students then open modal
  fetchStudentsForEdit().then(() => {
    editEventUserFilters.value = { name: '', program: '', yearLevel: '' }
    eventSessions.value = []
    fetchEventSessions(event._id)
    showEditEventModal.value = true
  })
}

const formatEventDate = (dateStr) => {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  return date.toLocaleDateString('en-PH', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' })
}

const getCurrentSessionPeriod = (event) => {
  if (!event) return 'morning'
  const now = new Date()
  const afternoonStartTime = event.afternoon_start_time || '13:00'
  const [afternoonHour, afternoonMin] = afternoonStartTime.split(':').map(Number)
  const currentHour = now.getHours()
  const currentMin = now.getMinutes()
  
  if (currentHour < afternoonHour || (currentHour === afternoonHour && currentMin < afternoonMin)) {
    return 'morning'
  }
  return 'afternoon'
}

const formatEventTime = (timeStr) => {
  if (!timeStr) return ''
  const [hours, minutes] = timeStr.split(':')
  const hour = parseInt(hours)
  const ampm = hour >= 12 ? 'PM' : 'AM'
  const displayHour = hour % 12 || 12
  return `${displayHour}:${minutes} ${ampm}`
}

// Format attendance date for user logs
const formatAttendanceDate = (dateStr) => {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  return date.toLocaleDateString('en-PH', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })
}

// Refresh attendance data
const refreshAttendanceData = async () => {
  attendanceLoading.value = true
  try {
    await fetchAttendanceData()
    // If we're in admin view and have a session selected, refresh its logs too
    if ((currentUser.value.role === 'admin' || currentUser.value.isMaster) && selectedSessionForLogs.value) {
      await fetchSessionLogs(selectedSessionForLogs.value._id)
    }
    // If student, refresh their logs
    if (currentUser.value.role !== 'admin' && !currentUser.value.isMaster) {
      await fetchUserAttendanceLogs()
    }
    showNotification('Attendance data refreshed successfully!', 'success')
  } catch (error) {
    console.error('Attendance refresh error:', error)
    showNotification('Failed to refresh attendance data', 'error')
  } finally {
    attendanceLoading.value = false
  }
}

// Get user log attendance status based on check-in time vs event start time
const getUserLogStatus = (log) => {
  if (log && log.excused) return 'Excused'
  if (!log.check_in_time && !log.check_in_at) return 'Absent'

  const checkInTime = new Date(log.check_in_time || log.check_in_at)
  const eventStartTime = log.event_start_time || log.event?.start_time

  if (!eventStartTime) return 'Present'

  // Parse event start time (HH:MM format)
  const [startHours, startMinutes] = eventStartTime.split(':').map(Number)
  const eventDate = new Date(log.event_date || log.event?.event_date || checkInTime)
  eventDate.setHours(startHours, startMinutes, 0, 0)

  // Grace period of 15 minutes
  const graceMs = 15 * 60 * 1000

  if (checkInTime <= new Date(eventDate.getTime() + graceMs)) {
    return 'Present'
  }
  return 'Late'
}

// Get user log attendance status CSS class
const getUserLogStatusClass = (log) => {
  const status = getUserLogStatus(log)
  switch (status) {
    case 'Present':
      return 'bg-green-100 text-green-800'
    case 'Excused':
      return 'bg-green-100 text-green-800'
    case 'Late':
      return 'bg-yellow-100 text-yellow-800'
    case 'Absent':
      return 'bg-red-100 text-red-800'
    default:
      return 'bg-gray-100 text-gray-800'
  }
}

// Fetch user attendance logs
const fetchUserAttendanceLogs = async () => {
  if (currentUser.value.role === 'admin' || currentUser.value.isMaster) return
  
  userAttendanceLogsLoading.value = true
  try {
    const token = localStorage.getItem('authToken')
    
    const response = await fetch(buildAPIUrl('/apis/attendance/my-records'), {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'X-SSAAM-TS': encodeTimestamp()
      }
    })
    
    if (response.ok) {
      const result = await response.json()
      const records = result.data || []
      const flattenedLogs = []
      
      records.forEach(r => {
        if (r.sessions && r.sessions.length > 0) {
          r.sessions.forEach(sessionData => {
            if (sessionData.attendance && (sessionData.attendance.check_in_at || sessionData.attendance.check_out_at)) {
              flattenedLogs.push({
                id: `${r.event?._id}_${sessionData.session?._id}`,
                event_name: r.event?.title || 'Event',
                eventName: r.event?.title || 'Event',
                event_date: r.event?.event_date,
                session_label: sessionData.session?.label || 'Session',
                check_in_time: sessionData.attendance?.check_in_at,
                check_out_time: sessionData.attendance?.check_out_at,
                check_in_at: sessionData.attendance?.check_in_at,
                check_out_at: sessionData.attendance?.check_out_at,
                is_late: sessionData.attendance?.is_late || false,
                status: sessionData.attendance?.status || 'absent',
                created_at: sessionData.attendance?.check_in_at || r.event?.event_date
              })
            }
          })
        }
      })
      
      flattenedLogs.sort((a, b) => new Date(b.check_in_at || 0) - new Date(a.check_in_at || 0))
      userAttendanceLogs.value = flattenedLogs
    }
  } catch (error) {
    console.error('Failed to fetch user attendance logs:', error)
  } finally {
    userAttendanceLogsLoading.value = false
  }
}

