}

// Helper function to get current Philippine time (UTC+8)
const getPhilippineTime = () => {
  const now = new Date()
  // Get UTC time and add 8 hours for Philippine timezone
  const utcTime = now.getTime() + (now.getTimezoneOffset() * 60000)
  return new Date(utcTime + (8 * 60 * 60 * 1000))
}

// Helper function to create event end time in Philippine timezone
const getEventEndTimeInPH = (event) => {
  if (!event.end_time) return null
  
  // Parse the event date (YYYY-MM-DD format)
  const dateStr = event.event_date || event.date
  if (!dateStr) return null
  
  // Extract date parts
  const dateParts = dateStr.split('T')[0].split('-')
  const year = parseInt(dateParts[0])
  const month = parseInt(dateParts[1]) - 1 // Month is 0-indexed
  const day = parseInt(dateParts[2])
  
  // Parse end time (HH:MM format)
  const [hours, minutes] = event.end_time.split(':').map(Number)
  
  // Create date in Philippine timezone
  // We create a UTC date, then subtract 8 hours to account for PH being UTC+8
  // This way when we compare with getPhilippineTime(), the math works out
  const eventEndPH = new Date(Date.UTC(year, month, day, hours - 8, minutes, 0, 0))
  return eventEndPH
}

// Helper function to get event start time in Philippine timezone
const getEventStartTimeInPH = (event) => {
  if (!event.start_time) return null
  
  const dateStr = event.event_date || event.date
  if (!dateStr) return null
  
  const dateParts = dateStr.split('T')[0].split('-')
  const year = parseInt(dateParts[0])
  const month = parseInt(dateParts[1]) - 1
  const day = parseInt(dateParts[2])
  
  const [hours, minutes] = event.start_time.split(':').map(Number)
  const eventStartPH = new Date(Date.UTC(year, month, day, hours - 8, minutes, 0, 0))
  return eventStartPH
}

// Check if event has actually ended (using Philippine time)
const hasEventEndedPH = (event) => {
  const eventEnd = getEventEndTimeInPH(event)
  if (!eventEnd) return false
  const nowPH = getPhilippineTime()
  return nowPH >= eventEnd
}

// Check if event has started yet (using Philippine time)
const hasEventStartedPH = (event) => {
  const eventStart = getEventStartTimeInPH(event)
  if (!eventStart) return true  // If no start time, assume started
  const nowPH = getPhilippineTime()
  return nowPH >= eventStart
}

const getAttendanceStatus = (eventId) => {
  // PRIORITY: Use backend-provided overall_status from API response
  const record = myAttendanceRecords.value.find(r => r.event_id === eventId || r.event?._id === eventId)
  
  if (record && record.overall_status) {
    // Trust the backend's status calculation - it already handled closed events correctly
    return record.overall_status
  }
  
  // Fallback to time-based calculation if no record
  const event = attendanceEvents.value.find(e => e._id === eventId || e.event_id === eventId)
  
  // Check if event has actually ended using Philippine time
  const eventEnded = event ? hasEventEndedPH(event) : false
  
  // Check if event has started yet (for upcoming vs ongoing)
  const eventStarted = event ? hasEventStartedPH(event) : true
  
  if (!record) {
    // No attendance record - check event timing
    
    // If event hasn't started yet, show as upcoming (not absent)
    if (!eventStarted) {
      return 'upcoming'
    }
    
    // If event is ongoing (started but not ended), show as ongoing
    if (event && event.status === 'active' && !eventEnded) {
      return 'ongoing'
    }
    
    // Only mark absent if event has actually ended
    if (eventEnded) {
      return 'absent'
    }
    
    return 'ongoing'  // Default to ongoing if event status unclear
  }
  
  // Has a record but no overall_status field - shouldn't happen, default to ongoing
  return 'ongoing'
}

const getStatusBadgeClass = (status) => {
  switch (status) {
    case 'present': return 'bg-green-100 text-green-800'
    case 'late': return 'bg-orange-100 text-orange-800'
    case 'incomplete': return 'bg-yellow-100 text-yellow-800'
    case 'absent': return 'bg-red-100 text-red-800'
    case 'ongoing': return 'bg-blue-100 text-blue-800'
    case 'active': return 'bg-blue-100 text-blue-800'
    case 'upcoming': return 'bg-blue-100 text-blue-800'
    case 'draft': return 'bg-yellow-100 text-yellow-800'
    case 'closed': return isCOE ? 'bg-orange-100 text-orange-800' : isSOM ? 'bg-green-100 text-green-800' : isCNAHS ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-600'
    case 'ended': return isCOE ? 'bg-orange-100 text-orange-800' : isSOM ? 'bg-green-100 text-green-800' : isCNAHS ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-600'
    default: return 'bg-gray-100 text-gray-800'
  }
}

const getEventDisplayStatus = (event) => {
  if (!event) return { status: 'draft', label: 'Upcoming' }
  
  const eventDateRaw = event.event_date || event.date
  if (!eventDateRaw) return { status: 'draft', label: 'Upcoming' }
  
  const startTime = event.start_time || event.startTime || '07:00'
  const endTime = event.end_time || event.endTime || '17:00'
  
  const [startH, startM] = startTime.split(':').map(Number)
  const [endH, endM] = endTime.split(':').map(Number)
  
  let eventDateStr
  if (typeof eventDateRaw === 'string') {
    eventDateStr = eventDateRaw.includes('T') ? eventDateRaw.split('T')[0] : eventDateRaw
  } else {
    const d = new Date(eventDateRaw)
    eventDateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
  }
  
  const eventStartPH = new Date(`${eventDateStr}T${String(startH).padStart(2, '0')}:${String(startM).padStart(2, '0')}:00+08:00`)
  const eventEndPH = new Date(`${eventDateStr}T${String(endH).padStart(2, '0')}:${String(endM).padStart(2, '0')}:00+08:00`)
  
  const nowUTC = Date.now()
  const eventStartUTC = eventStartPH.getTime()
  const eventEndUTC = eventEndPH.getTime()
  
  if (nowUTC < eventStartUTC) {
    return { status: 'draft', label: 'Upcoming' }
  } else if (nowUTC >= eventStartUTC && nowUTC <= eventEndUTC) {
    return { status: 'active', label: 'Active' }
  } else {
    return { status: 'closed', label: 'Completed' }
  }
}

const getAttendanceLogStatusLabel = (log) => {
  if (log && log.excused) return 'Excused'
  const hasCheckIn = log.check_in_at || log.check_in_time
  const hasCheckOut = log.check_out_at || log.check_out_time
  
  // Dynamically calculate if should be late based on current threshold
  const shouldBeLate = calculateShouldBeLate(log)

  if (hasCheckIn && hasCheckOut) {
    return shouldBeLate ? 'Late' : 'Present'
  }
  if (hasCheckIn && !hasCheckOut) {
    return shouldBeLate ? 'Late (Incomplete)' : 'Incomplete'
  }
  return 'Absent'
}

// Helper function to dynamically calculate if a log should be late
const calculateShouldBeLate = (log) => {
  if (!selectedSessionForLogs.value) return log.is_late || false
  
  const checkInTime = log.check_in_at || log.check_in_time
  if (!checkInTime) return false
  
  try {
    const sessionStart = selectedSessionForLogs.value.start_time
    const [startHours, startMinutes] = sessionStart.split(':').map(Number)
    const thresholdMinutes = selectedLateThresholdMinutes.value || 60
    
    // Calculate threshold time
    const totalMinutes = startHours * 60 + startMinutes + thresholdMinutes
    const thresholdHours = Math.floor(totalMinutes / 60) % 24
    const thresholdMins = totalMinutes % 60
    const thresholdTime = `${thresholdHours.toString().padStart(2, '0')}:${thresholdMins.toString().padStart(2, '0')}`
    
    // Get check-in time
    const checkInDate = new Date(checkInTime)
    const checkInHourMin = checkInDate.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' })
    
    return checkInHourMin > thresholdTime
  } catch (e) {
    console.warn('Error calculating late status:', e)
    return log.is_late || false
  }
}

const getAttendanceLogStatusClass = (log) => {
  if (log && log.excused) return 'bg-green-100 text-green-800'
  const hasCheckIn = log.check_in_at || log.check_in_time
  const hasCheckOut = log.check_out_at || log.check_out_time
  const shouldBeLate = calculateShouldBeLate(log)

  if (hasCheckIn && hasCheckOut) {
    return shouldBeLate ? 'bg-orange-100 text-orange-800' : 'bg-green-100 text-green-800'
  }
  if (hasCheckIn && !hasCheckOut) {
    return shouldBeLate ? 'bg-orange-100 text-orange-800' : 'bg-yellow-100 text-yellow-800'
  }
  return 'bg-red-100 text-red-800'
}

const getRecordStatusLabel = (record) => {
  const hasCheckIn = record.check_in_at || record.check_in_time
  const hasCheckOut = record.check_out_at || record.check_out_time
  
  if (hasCheckIn && hasCheckOut) return 'Present'
  if (hasCheckIn && !hasCheckOut) {
    const event = record.event || attendanceEvents.value.find(e => e._id === record.event_id)
    const eventEnded = event ? hasEventEndedPH(event) : false
    return eventEnded ? 'Incomplete' : 'Incomplete'
  }
  if (!hasCheckIn && hasCheckOut) return 'Incomplete'
  
  const event = record.event || attendanceEvents.value.find(e => e._id === record.event_id)
  const eventEnded = event ? hasEventEndedPH(event) : true
  
  return eventEnded ? 'Absent' : 'Pending'
}

const getRecordStatusClass = (record) => {
  const label = getRecordStatusLabel(record)
  switch (label) {
    case 'Present': return 'bg-green-100 text-green-800'
    case 'Incomplete': return 'bg-yellow-100 text-yellow-800'
    case 'Absent': return 'bg-red-100 text-red-800'
    case 'Pending': return 'bg-blue-100 text-blue-800'
    default: return 'bg-gray-100 text-gray-800'
  }
}

const getOverallStatusLabel = (status) => {
  switch (status) {
    case 'present': return 'Present'
    case 'late': return 'Late'
    case 'incomplete': return 'Incomplete'
    case 'absent': return 'Absent'
    case 'upcoming': return 'Upcoming'
    case 'ongoing': return 'Ongoing'
    default: return status ? status.charAt(0).toUpperCase() + status.slice(1) : 'Unknown'
  }
}

const getOverallStatusClass = (status) => {
  switch (status) {
    case 'present': return 'bg-green-100 text-green-800'
    case 'late': return 'bg-yellow-100 text-yellow-800'
    case 'incomplete': return 'bg-orange-100 text-orange-800'
    case 'absent': return 'bg-red-100 text-red-800'
    case 'upcoming': return 'bg-blue-100 text-blue-800'
    case 'ongoing': return 'bg-blue-100 text-blue-800'
    default: return 'bg-gray-100 text-gray-800'
  }
}

// Smart status that considers event timing - for attendance history records
const getSmartRecordStatus = (record) => {
  const event = record.event || attendanceEvents.value.find(e => e._id === record.event_id)
  const originalStatus = record.overall_status || record.status
  
  // PRIORITY: If event is closed, always trust the backend status
  // Closed events can show absent, present, or late - don't recalculate
  if (event && event.status === 'closed') {
    return originalStatus || 'absent'
  }
  
  // If event exists, check if it has started yet (only for active/draft events)
  if (event) {
    const eventStarted = hasEventStartedPH(event)
    const eventEnded = hasEventEndedPH(event)
    
    // If event hasn't started yet, show "upcoming" instead of "absent"
    if (!eventStarted && (originalStatus === 'absent' || !originalStatus)) {
      return 'upcoming'
    }
    
    // If event is ongoing (started but not ended) and no attendance, show "ongoing"
    if (eventStarted && !eventEnded && (originalStatus === 'absent' || !originalStatus)) {
      return 'ongoing'
    }
  }
  
  // Otherwise return the original status
  return originalStatus || 'absent'
}

const getSessionAttendanceLabel = (attendance, session = null, event = null) => {
  // PRIORITY: If event is closed, show the actual status from attendance data
  if (event && event.status === 'closed') {
    if (!attendance || (!attendance.check_in_at && !attendance.check_in_time)) {
      return 'Absent'  // No check-in/out and event is closed = Absent
    }
    
    const status = attendance.status
    if (status === 'present') return 'Present'
    if (status === 'late') return 'Present (Late)'
    if (status === 'incomplete') return attendance.is_late ? 'Incomplete (Late)' : 'Incomplete'
    if (status === 'absent') return 'Absent'
    
    if (attendance.check_in_at && attendance.check_out_at) {
      return attendance.is_late ? 'Present (Late)' : 'Present'
    }
    if (attendance.check_in_at && !attendance.check_out_at) {
      return attendance.is_late ? 'Incomplete (Late)' : 'Incomplete'
    }
    return 'Absent'
  }
  
  // Check if the session/event hasn't started yet
  if (event && !hasEventStartedPH(event)) {
    return 'Upcoming'
  }
  
  // Check if event is ongoing (started but not ended)
  if (event && hasEventStartedPH(event) && !hasEventEndedPH(event)) {
    if (!attendance || (!attendance.check_in_at && !attendance.check_in_time)) {
      return 'Ongoing'
    }
  }
  
  if (!attendance) {
    // Only show Absent if event has ended
    if (event && hasEventEndedPH(event)) {
      return 'Absent'
    }
    return 'Upcoming'
  }
  
  const status = attendance.status
  if (status === 'present') return 'Present'
  if (status === 'late') return 'Present (Late)'
  if (status === 'incomplete') return attendance.is_late ? 'Incomplete (Late)' : 'Incomplete'
  if (status === 'absent') {
    // Double-check if event has actually ended
    if (event && !hasEventEndedPH(event)) {
      return hasEventStartedPH(event) ? 'Ongoing' : 'Upcoming'
    }
    return 'Absent'
  }
  if (attendance.check_in_at && attendance.check_out_at) {
    return attendance.is_late ? 'Present (Late)' : 'Present'
  }
  if (attendance.check_in_at && !attendance.check_out_at) {
    return attendance.is_late ? 'Incomplete (Late)' : 'Incomplete'
  }
  return 'Absent'
}

const calculateLateThreshold = (startTime, thresholdMinutes = 30) => {
  if (!startTime) return null
  const [hours, minutes] = startTime.split(':').map(Number)
  const totalMinutes = hours * 60 + minutes + thresholdMinutes
  const lateHours = Math.floor(totalMinutes / 60) % 24
  const lateMinutes = totalMinutes % 60
  const period = lateHours >= 12 ? 'PM' : 'AM'
  const displayHours = lateHours > 12 ? lateHours - 12 : (lateHours === 0 ? 12 : lateHours)
  return `${displayHours}:${lateMinutes.toString().padStart(2, '0')} ${period}`
}

// Apply print-ready formatting to worksheet
const applyPrintFormatting = (worksheet, headerRowCount) => {
  // Set page setup - landscape orientation for better fit
  worksheet['!pageSetup'] = {
    orientation: 'landscape'
  }
  
  // Set page margins (in inches)
  worksheet['!margins'] = {
    left: 0.5,
    right: 0.5,
    top: 0.75,
    bottom: 0.75,
    header: 0.3,
    footer: 0.3
  }
  
  // Freeze header rows for printing
  worksheet['!freeze'] = {
    xSplit: 0,
    ySplit: headerRowCount
  }
  
  // Apply borders and styling to all cells with content
  if (worksheet['!ref']) {
    const range = XLSX.utils.decode_range(worksheet['!ref'])
    
    for (let R = range.s.r; R <= range.e.r; R++) {
      for (let C = range.s.c; C <= range.e.c; C++) {
        const cellAddress = XLSX.utils.encode_cell({ r: R, c: C })
        let cell = worksheet[cellAddress]
        
        if (!cell) {
          cell = {}
          worksheet[cellAddress] = cell
        }
        
        // Add borders to all cells
        cell.border = {
          top: { style: 'thin' },
          bottom: { style: 'thin' },
          left: { style: 'thin' },
          right: { style: 'thin' }
        }
        
        // Style header rows
        if (R < headerRowCount) {
          if (!cell.font) cell.font = {}
          cell.font.bold = true
          cell.font.sz = 11
          
          if (!cell.fill) cell.fill = {}
          cell.fill.fgColor = { rgb: 'D9E8F5' } // Light blue background
          
          if (!cell.alignment) cell.alignment = {}
          cell.alignment.horizontal = 'center'
          cell.alignment.vertical = 'center'
          cell.alignment.wrapText = true
        } else {
          // Regular data rows
          if (!cell.font) cell.font = {}
          cell.font.sz = 10
          
          if (!cell.alignment) cell.alignment = {}
          cell.alignment.horizontal = 'left'
          cell.alignment.vertical = 'center'
          cell.alignment.wrapText = true
        }
      }
    }
  }
  
  return worksheet
}

const getSessionAttendanceClass = (attendance, session = null, event = null) => {
  // Get the label first for consistent styling
  const label = getSessionAttendanceLabel(attendance, session, event)
  
  if (label === 'Upcoming') return 'bg-blue-100 text-blue-800'
  if (label === 'Ongoing') return 'bg-blue-100 text-blue-800'
  if (label === 'Present' || label === 'Present (Late)') {
    return label.includes('Late') ? 'bg-yellow-100 text-yellow-800' : 'bg-green-100 text-green-800'
  }
  if (label.includes('Incomplete')) return 'bg-orange-100 text-orange-800'
  if (label === 'Absent') return 'bg-red-100 text-red-800'
  
  return 'bg-gray-100 text-gray-800'
}

// Get session badge styling based on session label (time-based colors)
const getSessionBadgeStyle = (sessionLabel) => {
  const label = (sessionLabel || '').toLowerCase().trim()
  
  if (label.includes('morning')) {
    return {
      bgGradient: 'bg-gradient-to-br from-yellow-400 to-orange-500',
      badge: 'bg-gradient-to-r from-yellow-100 to-orange-100 text-orange-800',
      displayText: 'Morning',
      icon: '/sessions/morning.svg'
    }
  } else if (label.includes('noon') || label.includes('lunch')) {
    return {
      bgGradient: 'bg-gradient-to-br from-ssaam-dark to-ssaam-light',
      badge: 'bg-gradient-to-r from-blue-100 to-cyan-100 text-blue-800',
      displayText: 'Noon',
      icon: '/sessions/noon.svg'
    }
  } else if (label.includes('afternoon')) {
    return {
      bgGradient: 'bg-gradient-to-br from-orange-400 to-red-500',
      badge: 'bg-gradient-to-r from-orange-100 to-red-100 text-red-800',
      displayText: 'Afternoon',
      icon: '/sessions/afternoon.svg'
    }
  } else if (label.includes('night') || label.includes('evening')) {
    return {
      bgGradient: 'bg-gradient-to-br from-ssaam-dark to-ssaam-light',
      badge: 'bg-gradient-to-r from-indigo-100 to-blue-100 text-blue-800',
      displayText: 'Night',
      icon: '/sessions/night.svg'
    }
  } else if (label.includes('dawn') || label.includes('morning twilight')) {
    return {
      bgGradient: 'bg-gradient-to-br from-ssaam-dark to-ssaam-light',
      badge: 'bg-gradient-to-r from-blue-100 to-rose-100 text-rose-800',
      displayText: 'Dawn',
      icon: '/sessions/dawn.svg'
    }
  } else if (label.includes('whole day') || label.includes('all day')) {
    return {
      bgGradient: 'bg-gradient-to-br from-green-400 to-emerald-500',
      badge: 'bg-gradient-to-r from-green-100 to-emerald-100 text-green-800',
      displayText: 'All Day',
      icon: '/sessions/whole_day.svg'
    }
  }
  
  // Default fallback
  return {
    bgGradient: 'bg-gradient-to-br from-gray-400 to-gray-600',
    badge: 'bg-gradient-to-r from-gray-100 to-gray-200 text-gray-800',
    displayText: sessionLabel || 'Session'
  }
}

const getInitials = (name) => {
  if (!name) return '?'
  const parts = name.trim().split(/\s+/)
  if (parts.length === 1) return parts[0].charAt(0).toUpperCase()
  return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
}

// Transparency board helper functions
const getTotalContributions = () => {
  return transparencyList.value.reduce((sum, record) => {
    return sum + (parseFloat(record.contribution_amount) || 0)
  }, 0).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

const getUniqueContributors = () => {
  const uniqueIds = new Set(transparencyList.value.map(record => record.student_id))
  return uniqueIds.size
}

const getAverageContribution = () => {
  if (transparencyList.value.length === 0) return '0.00'
  const total = transparencyList.value.reduce((sum, record) => {
    return sum + (parseFloat(record.contribution_amount) || 0)
  }, 0)
  return (total / transparencyList.value.length).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

const activeUnattendedEvents = computed(() => {
  if (currentUser.value.role === 'admin' || currentUser.value.isMaster) return []
  if (attendanceLoading.value) return []
  return attendanceEvents.value.filter(event => {
    const eventId = event._id || event.event_id
    const status = getAttendanceStatus(eventId)
    return event.status === 'active' && (status === 'active' || status === 'incomplete')
  })
})

// Sort attendance logs by most recent activity (check-out or check-in, whichever is more recent)
// Use filtered logs so UI filters apply
const sortedAttendanceLogs = computed(() => {
  return [...filteredAttendanceLogs.value].sort((a, b) => {
    // Get the most recent activity time for each log (check-out takes priority if it exists)
    const aCheckOut = a.check_out_at || a.check_out_time
    const aCheckIn = a.check_in_at || a.check_in_time || a.created_at
    const aTime = aCheckOut ? new Date(aCheckOut) : (aCheckIn ? new Date(aCheckIn) : new Date(0))
    
    const bCheckOut = b.check_out_at || b.check_out_time
    const bCheckIn = b.check_in_at || b.check_in_time || b.created_at
    const bTime = bCheckOut ? new Date(bCheckOut) : (bCheckIn ? new Date(bCheckIn) : new Date(0))
    
    return bTime - aTime
  })
})

// Check if a log entry is a recent activity (check-in or check-out within last 30 seconds)
const isRecentCheckIn = (log) => {
  const checkOutTime = log.check_out_at || log.check_out_time
  const checkInTime = log.check_in_at || log.check_in_time || log.created_at
  const now = new Date()
  
  // Check if checkout is recent
  if (checkOutTime) {
    const outTime = new Date(checkOutTime)
    if ((now - outTime) < 30000) return true
  }
  
  // Check if check-in is recent
  if (checkInTime) {
    const inTime = new Date(checkInTime)
    if ((now - inTime) < 30000) return true
  }
  
  return false
}


const closePasswordChangeModal = () => {
  showPasswordChangeModal.value = false
  pwChangeStep.value = 1
  pwChangeEmail.value = ''
  pwChangeCode.value = ''
  pwChangeToken.value = ''
  pwChangeMessage.value = ''
  pwChangeSuccess.value = false
  passwordForm.value = { currentPassword: '', newPassword: '', confirmPassword: '' }
  passwordErrors.value = {}
  showNewPassword.value = false
  showConfirmPassword.value = false
}

const requestPasswordChangeCode = async () => {
  changingPassword.value = true
  pwChangeMessage.value = ''
  try {
    const token = encodeTimestamp()
    const studentId = currentUser.value.studentId || currentUser.value.student_id
    
    const response = await fetch(buildAPIUrl(`/apis/password-reset/request`), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer SSAAMStudents',
        'X-SSAAM-TS': token
      },
      body: JSON.stringify({
        student_id: studentId,
        email: pwChangeEmail.value.trim(),
        _ssaam_access_token: token
      })
    })
    
    const data = await response.json()
    if (response.ok) {
      pwChangeSuccess.value = true
      pwChangeMessage.value = 'Verification code sent to your email!'
      pwChangeStep.value = 2
    } else {
      pwChangeSuccess.value = false
      pwChangeMessage.value = data.message || 'Failed to send verification code'
    }
  } catch (error) {
    pwChangeSuccess.value = false
    pwChangeMessage.value = 'Network error. Please try again.'
  } finally {
    changingPassword.value = false
  }
}

const verifyPasswordChangeCode = async () => {
  changingPassword.value = true
  pwChangeMessage.value = ''
  try {
    const token = encodeTimestamp()
    const studentId = currentUser.value.studentId || currentUser.value.student_id
    
    const response = await fetch(buildAPIUrl(`/apis/password-reset/verify`), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer SSAAMStudents',
        'X-SSAAM-TS': token
      },
      body: JSON.stringify({
        student_id: studentId,
        code: pwChangeCode.value.trim(),
        _ssaam_access_token: token
      })
    })
    
    const data = await response.json()
    if (response.ok) {
      pwChangeSuccess.value = true
      pwChangeMessage.value = 'Code verified!'
      pwChangeToken.value = data.reset_token
      pwChangeStep.value = 3
    } else {
      pwChangeSuccess.value = false
      pwChangeMessage.value = data.message || 'Invalid verification code'
    }
  } catch (error) {
    pwChangeSuccess.value = false
    pwChangeMessage.value = 'Verification failed. Please try again.'
  } finally {
    changingPassword.value = false
  }
}

const completePasswordChange = async () => {
  passwordErrors.value = {}
  
  if (!passwordForm.value.newPassword) {
    passwordErrors.value.newPassword = 'New password is required'
    return
  } else if (passwordForm.value.newPassword.length < 6) {
    passwordErrors.value.newPassword = 'Password must be at least 6 characters'
    return
  }
  if (passwordForm.value.newPassword !== passwordForm.value.confirmPassword) {
    passwordErrors.value.confirmPassword = 'Passwords do not match'
    return
  }
  
  changingPassword.value = true
  pwChangeMessage.value = ''
  try {
    const token = encodeTimestamp()
    const studentId = currentUser.value.studentId || currentUser.value.student_id
    
    const response = await fetch(buildAPIUrl(`/apis/password-reset/complete`), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer SSAAMStudents',
        'X-SSAAM-TS': token
      },
      body: JSON.stringify({
        student_id: studentId,
        reset_token: pwChangeToken.value,
        new_password: passwordForm.value.newPassword,
        _ssaam_access_token: token
      })
    })
    
    const data = await response.json()
    if (response.ok) {
      showNotification('Password changed successfully!', 'success')
      closePasswordChangeModal()
      showPasswordUpdateWarning.value = false
      const storedUser = JSON.parse(localStorage.getItem('currentUser') || '{}')
      storedUser.requiresPasswordUpdate = false
      localStorage.setItem('currentUser', JSON.stringify(storedUser))
      currentUser.value.requiresPasswordUpdate = false
    } else {
      pwChangeSuccess.value = false
      pwChangeMessage.value = data.message || 'Failed to change password'
    }
  } catch (error) {
    pwChangeSuccess.value = false
    pwChangeMessage.value = 'Password change failed. Please try again.'
  } finally {
    changingPassword.value = false
  }
}

// Permanent storage key for dismissed event ended notifications (per user)
const getDismissedEventsStorageKey = () => {
  const userId = currentUser.value.studentId || currentUser.value.student_id || 'unknown'
  return `ssaam_dismissed_ended_events_${userId}`
}

// Get dismissed event ended notifications from permanent localStorage
const getDismissedEndedEvents = () => {
  try {
    const stored = localStorage.getItem(getDismissedEventsStorageKey())
    return stored ? new Set(JSON.parse(stored)) : new Set()
  } catch {
    return new Set()
  }
}

// Save dismissed event ended notification to permanent localStorage
const dismissEndedEventNotification = (eventId) => {
  try {
    const dismissed = getDismissedEndedEvents()
    dismissed.add(eventId)
    localStorage.setItem(getDismissedEventsStorageKey(), JSON.stringify([...dismissed]))
  } catch (e) {
    console.error('Failed to save dismissed event:', e)
  }
}

// Track if we've shown the ended notification this session (to avoid showing multiple times in one session)
const shownEndedNotificationsThisSession = ref(new Set())

// Calculate time remaining for each active event (no automatic modal - only updates time display)
const updateEventTimeRemaining = () => {
  const nowPH = getPhilippineTime()
  const isAdmin = currentUser.value.role === 'admin' || currentUser.value.isMaster
  
  attendanceEvents.value.forEach(event => {
    if (event.status === 'active' && event.end_time) {
      const eventEnd = getEventEndTimeInPH(event)
      if (!eventEnd) return
      
      const diff = eventEnd - nowPH
      
      if (diff <= 0) {
        // Event has ended - just update the display, no automatic modal
        eventTimeRemaining.value[event._id] = 'Ended'
      } else {
        const hoursLeft = Math.floor(diff / (1000 * 60 * 60))
        const minutesLeft = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))
        const secondsLeft = Math.floor((diff % (1000 * 60)) / 1000)
        
        if (hoursLeft > 0) {
          eventTimeRemaining.value[event._id] = `${hoursLeft}h ${minutesLeft}m remaining`
        } else if (minutesLeft > 0) {
          eventTimeRemaining.value[event._id] = `${minutesLeft}m ${secondsLeft}s remaining`
        } else {
          eventTimeRemaining.value[event._id] = `${secondsLeft}s remaining`
        }
        
        // Warn admin when 5 minutes or less remaining
        if (isAdmin && diff <= 5 * 60 * 1000 && diff > 4 * 60 * 1000) {
          showNotification(`Event "${event.title}" ends in 5 minutes!`, 'warning')
        }
      }
    }
  })
}

// Check for ended events and show notification (called when opening attendance section)
const checkAndNotifyEndedEvents = () => {
  const isAdmin = currentUser.value.role === 'admin' || currentUser.value.isMaster
  if (isAdmin) return // Only for students
  
  const dismissedEvents = getDismissedEndedEvents()
  const nowPH = getPhilippineTime()
  
  attendanceEvents.value.forEach(event => {
    if (event.status === 'active' && event.end_time) {
      const eventEnd = getEventEndTimeInPH(event)
      if (!eventEnd) return
      
      const diff = eventEnd - nowPH
      
      // If event has ended and not previously dismissed or shown this session
      if (diff <= 0 && !dismissedEvents.has(event._id) && !shownEndedNotificationsThisSession.value.has(event._id)) {
        shownEndedNotificationsThisSession.value.add(event._id)
        showEventEndedModal(event)
        return // Only show one at a time
      }
    }
  })
}

// Show event ended modal with dismiss option
const eventEndedModalVisible = ref(false)
const eventEndedModalEvent = ref(null)

const showEventEndedModal = (event) => {
  eventEndedModalEvent.value = event
  eventEndedModalVisible.value = true
}

const closeEventEndedModal = () => {
  if (eventEndedModalEvent.value) {
    // Permanently dismiss this notification
    dismissEndedEventNotification(eventEndedModalEvent.value._id)
  }
  eventEndedModalVisible.value = false
  eventEndedModalEvent.value = null
}

// Get time remaining for a specific event
const getEventTimeRemaining = (eventId) => {
  return eventTimeRemaining.value[eventId] || ''
}

// Start auto-refresh for attendance data (for students)
// Note: Automatic refresh removed - users can manually refresh using the Refresh button
const startAttendanceAutoRefresh = () => {
  // Update event time remaining every second
  eventTimeInterval.value = setInterval(() => {
    updateEventTimeRemaining()
  }, 1000)
}

onUnmounted(() => {
  // Remove ESC key listener
  document.removeEventListener('keydown', handleEscKey)
  
  if (attendanceRefreshInterval.value) {
    clearInterval(attendanceRefreshInterval.value)
  }
  if (eventTimeInterval.value) {
    clearInterval(eventTimeInterval.value)
  }
})
</script>

